# ========== SECURITY CONFIGURATION ==========
# SECURITY: Use stable JWT secret from env, fallback to fixed secret for consistency
JWT_SECRET_KEY = os.environ.get('JWT_SECRET_KEY')
if not JWT_SECRET_KEY:
    raise RuntimeError(
        "JWT_SECRET_KEY env var is required. Refusing to start with a "
        "predictable fallback — that would let anyone forge admin tokens. "
        "Set a strong random secret in .env (dev) or Emergent System Keys (prod)."
    )
JWT_ALGORITHM = "HS256"
JWT_ACCESS_TOKEN_EXPIRE_MINUTES = 60  # 1 hour
JWT_REFRESH_TOKEN_EXPIRE_DAYS = 7

# Admin operation PINs — used for sensitive admin actions (bulk fail, force
# activate, admin credit etc). Loaded from env so prod/dev can rotate without
# code change. Fall back to historical values for dev parity; prod MUST set
# explicit env values.
ADMIN_OPERATION_PIN = os.environ.get("ADMIN_OPERATION_PIN", "123456")
ADMIN_OVERRIDE_PIN_ENV = os.environ.get("ADMIN_OVERRIDE_PIN", "153759")

# Rate limiting configuration
RATE_LIMIT_LOGIN_ATTEMPTS = 5  # Max login attempts before final lockout
RATE_LIMIT_API_CALLS = 100  # Max API calls per minute for admin
RATE_LIMIT_WINDOW_SECONDS = 3600  # 1 hour window for tracking attempts

# Progressive lockout durations (in seconds)
LOCKOUT_DURATION_FIRST = 300      # 5 minutes after 3 failed attempts
LOCKOUT_DURATION_SECOND = 900     # 15 minutes after 4 failed attempts  
LOCKOUT_DURATION_FINAL = 7200     # 2 hours after 5 failed attempts (changed from 24 hours)

# Session timeout (30 minutes)
SESSION_TIMEOUT_MINUTES = 30

# Rate limiting storage (in-memory, per-process)
rate_limit_storage = defaultdict(lambda: {"count": 0, "reset_time": time.time()})
login_attempt_storage = defaultdict(lambda: {"count": 0, "reset_time": time.time(), "locked_until": 0, "lockout_level": 0})

# Security bearer
security = HTTPBearer(auto_error=False)

# ========== USER-FRIENDLY ERROR HANDLER ==========
def get_user_friendly_error(error: Exception) -> str:
    """Convert technical errors to user-friendly messages"""
    error_str = str(error).lower()
    
    # Database errors
    if "e11000" in error_str or "duplicate key" in error_str:
        if "pan_number" in error_str:
            return "This PAN number is already registered with another account."
        if "aadhaar" in error_str:
            return "This Aadhaar number is already registered with another account."
        if "mobile" in error_str:
            return "This mobile number is already registered."
        if "email" in error_str:
            return "This email is already registered."
        return "This information is already registered with another account."
    
    # Motor/pymongo timeouts bubble up as NetworkTimeout, ServerSelectionTimeoutError,
    # ExecutionTimeout etc. All of these include "timeout" / "timed out" in their
    # string. Treat them as transient and ask user to retry — their action IS safe
    # to retry (backends are idempotent for approve/reject/pay flows).
    if "timeout" in error_str or "timed out" in error_str or "serverselectiontimeouterror" in error_str or "networktimeout" in error_str:
        return "Database is slow right now. Please try again — your action will work next time."
    
    if "connection" in error_str or "network" in error_str:
        return "Connection error. Please check your internet and try again."
    
    if "not found" in error_str:
        return "The requested information was not found."
    
    if "insufficient" in error_str:
        return "Insufficient balance. Please check your available balance."
    
    if "unauthorized" in error_str or "authentication" in error_str:
        return "Session expired. Please login again."
    
    if "invalid" in error_str:
        return "Invalid input. Please check your information and try again."
    
    if "rate limit" in error_str or "too many" in error_str:
        return "Too many requests. Please wait a moment and try again."
    
    # Default message (hide technical details)
    return "Something went wrong. Please try again. If the problem persists, contact support."

def raise_friendly_error(status_code: int, error: Exception, context: str = ""):
    """Raise HTTPException with user-friendly message"""
    message = get_user_friendly_error(error)
    if context:
        logging.error(f"[{context}] {str(error)}")
    raise HTTPException(status_code=status_code, detail=message)

# ========== JWT UTILITIES ==========
def create_access_token(data: dict, expires_delta: timedelta = None) -> str:
    """Create JWT access token"""
    to_encode = data.copy()
    expire = datetime.now(timezone.utc) + (expires_delta or timedelta(minutes=JWT_ACCESS_TOKEN_EXPIRE_MINUTES))
    to_encode.update({
        "exp": expire,
        "iat": datetime.now(timezone.utc),
        "type": "access"
    })
    return jwt.encode(to_encode, JWT_SECRET_KEY, algorithm=JWT_ALGORITHM)

def create_refresh_token(data: dict) -> str:
    """Create JWT refresh token"""
    to_encode = data.copy()
    expire = datetime.now(timezone.utc) + timedelta(days=JWT_REFRESH_TOKEN_EXPIRE_DAYS)
    to_encode.update({
        "exp": expire,
        "iat": datetime.now(timezone.utc),
        "type": "refresh"
    })
    return jwt.encode(to_encode, JWT_SECRET_KEY, algorithm=JWT_ALGORITHM)

def verify_token(token: str, token_type: str = "access") -> dict:
    """Verify JWT token and return payload"""
    try:
        payload = jwt.decode(token, JWT_SECRET_KEY, algorithms=[JWT_ALGORITHM])
        if payload.get("type") != token_type:
            raise HTTPException(status_code=401, detail=f"Invalid token type. Expected {token_type}")
        return payload
    except jwt.ExpiredSignatureError:
        raise HTTPException(status_code=401, detail="Token has expired")
    except jwt.InvalidTokenError:
        raise HTTPException(status_code=401, detail="Invalid token")

async def get_current_user(credentials: HTTPAuthorizationCredentials = Depends(security)) -> dict:
    """Get current user from JWT token"""
    if not credentials:
        raise HTTPException(status_code=401, detail="Not authenticated")
    
    payload = verify_token(credentials.credentials)
    uid = payload.get("uid")
    if not uid:
        raise HTTPException(status_code=401, detail="Invalid token payload")
    
    user = await db.users.find_one({"uid": uid}, {"_id": 0, "password_hash": 0})
    if not user:
        raise HTTPException(status_code=401, detail="User not found")
    
    # Check if session is still valid (not logged out)
    active_session = await db.admin_sessions.find_one({
        "uid": uid,
        "token_id": payload.get("token_id"),
        "is_active": True
    })
    
    if user.get("role") in ["admin", "sub_admin"] and not active_session:
        raise HTTPException(status_code=401, detail="Session expired or logged out")
    
    return user

async def get_current_admin(user: dict = Depends(get_current_user)) -> dict:
    """Verify current user is admin"""
    if user.get("role") not in ["admin", "sub_admin"]:
        raise HTTPException(status_code=403, detail="Admin access required")
    return user

# ========== RATE LIMITING ==========
def check_rate_limit(key: str, max_requests: int, window_seconds: int = RATE_LIMIT_WINDOW_SECONDS) -> bool:
    """Check if rate limit exceeded. Returns True if allowed, False if blocked."""
    current_time = time.time()
    
    if current_time > rate_limit_storage[key]["reset_time"]:
        rate_limit_storage[key] = {"count": 1, "reset_time": current_time + window_seconds}
        return True
    
    if rate_limit_storage[key]["count"] >= max_requests:
        return False
    
    rate_limit_storage[key]["count"] += 1
    return True


async def check_login_rate_limit_db(db, identifier: str) -> Tuple[bool, int, str]:
    """Check if user is locked out in DATABASE (persistent across server restarts).

    Uses sequential index-backed lookups instead of a $or query because $or
    queries don't use index intersections reliably on Atlas → occasional
    full collection scans causing 30s proxy timeouts during login.
    """
    ident_lc = identifier.lower() if '@' in identifier else identifier
    # Email first (most common), mobile, then uid — each uses its own index
    user = await db.users.find_one(
        {"email": ident_lc},
        {"_id": 0, "failed_login_attempts": 1, "locked_until": 1, "email": 1}
    )
    if not user:
        user = await db.users.find_one(
            {"mobile": identifier},
            {"_id": 0, "failed_login_attempts": 1, "locked_until": 1, "email": 1}
        )
    if not user:
        user = await db.users.find_one(
            {"uid": identifier},
            {"_id": 0, "failed_login_attempts": 1, "locked_until": 1, "email": 1}
        )
    
    if not user:
        return True, 0, ""  # User not found, let login flow handle it
    
    locked_until = user.get("locked_until")
    if locked_until:
        try:
            # Parse locked_until timestamp
            if isinstance(locked_until, str):
                lock_time = datetime.fromisoformat(locked_until.replace('Z', '+00:00'))
            else:
                lock_time = locked_until
            
            now = datetime.now(timezone.utc)
            if lock_time > now:
                remaining = int((lock_time - now).total_seconds())
                if remaining >= 3600:
                    hours = remaining // 3600
                    mins = (remaining % 3600) // 60
                    time_msg = f"{hours}h {mins}m"
                else:
                    mins = remaining // 60
                    time_msg = f"{mins} minute{'s' if mins > 1 else ''}"
                
                return False, remaining, f"🔒 Account locked. Try again in {time_msg}. Contact admin if you need immediate access."
        except Exception as e:
            logging.error(f"Error parsing locked_until for {identifier}: {e}")
    
    return True, 0, ""


def check_login_rate_limit(identifier: str) -> tuple:
    """Check login rate limit with progressive lockout. Returns (allowed: bool, locked_until: int, attempts_left: int, lockout_message: str)"""
    current_time = time.time()
    key = f"login:{identifier}"
    
    # Check if locked
    if login_attempt_storage[key]["locked_until"] > current_time:
        remaining_seconds = int(login_attempt_storage[key]["locked_until"] - current_time)
        lockout_level = login_attempt_storage[key].get("lockout_level", 1)
        
        # Format time remaining
        if remaining_seconds >= 3600:
            hours = remaining_seconds // 3600
            minutes = (remaining_seconds % 3600) // 60
            time_msg = f"{hours} hour{'s' if hours > 1 else ''} {minutes} minute{'s' if minutes > 1 else ''}"
        elif remaining_seconds >= 60:
            minutes = remaining_seconds // 60
            time_msg = f"{minutes} minute{'s' if minutes > 1 else ''}"
        else:
            time_msg = f"{remaining_seconds} second{'s' if remaining_seconds > 1 else ''}"
        
        if lockout_level >= 3:
            message = f"🔒 Account locked for 24 hours due to multiple failed attempts. Try again in {time_msg}."
        elif lockout_level == 2:
            message = f"⚠️ Account temporarily locked (15 min). Try again in {time_msg}."
        else:
            message = f"⏳ Too many attempts. Try again in {time_msg}."
            
        return False, remaining_seconds, 0, message
    
    # Reset if window expired
    if current_time > login_attempt_storage[key]["reset_time"]:
        login_attempt_storage[key] = {"count": 0, "reset_time": current_time + RATE_LIMIT_WINDOW_SECONDS, "locked_until": 0, "lockout_level": 0}
    
    attempts_left = RATE_LIMIT_LOGIN_ATTEMPTS - login_attempt_storage[key]["count"]
    return True, 0, attempts_left, ""

async def record_login_attempt_db(db, identifier: str, success: bool, ip_address: str = None):
    """Record login attempt in database for persistent tracking"""
    try:
        await db.login_attempts.insert_one({
            "identifier": identifier,
            "ip_address": ip_address,
            "success": success,
            "timestamp": datetime.now(timezone.utc).isoformat()
        })
    except Exception as e:
        logging.error(f"Failed to record login attempt: {e}")


def record_login_attempt(identifier: str, success: bool):
    """Record login attempt with progressive lockout (in-memory for speed)"""
    key = f"login:{identifier}"
    current_time = time.time()
    
    if success:
        # Reset everything on successful login
        login_attempt_storage[key] = {"count": 0, "reset_time": current_time + RATE_LIMIT_WINDOW_SECONDS, "locked_until": 0, "lockout_level": 0}
    else:
        login_attempt_storage[key]["count"] += 1
        failed_count = login_attempt_storage[key]["count"]
        
        # Progressive lockout based on failed attempts
        if failed_count >= 5:
            # 5+ attempts: 24 hour lockout
            login_attempt_storage[key]["locked_until"] = current_time + LOCKOUT_DURATION_FINAL
            login_attempt_storage[key]["lockout_level"] = 3
        elif failed_count >= 4:
            # 4 attempts: 15 minute lockout
            login_attempt_storage[key]["locked_until"] = current_time + LOCKOUT_DURATION_SECOND
            login_attempt_storage[key]["lockout_level"] = 2
        elif failed_count >= 3:
            # 3 attempts: 5 minute lockout
            login_attempt_storage[key]["locked_until"] = current_time + LOCKOUT_DURATION_FIRST
            login_attempt_storage[key]["lockout_level"] = 1

# ========== ADMIN AUDIT LOGGING ==========
async def log_admin_action(
    admin_uid: str,
    action: str,
    entity_type: str,
    entity_id: str = None,
    details: dict = None,
    ip_address: str = None,
    user_agent: str = None,
    before_data: dict = None,
    after_data: dict = None
):
    """Log admin action for audit trail"""
    audit_entry = {
        "audit_id": str(uuid.uuid4()),
        "admin_uid": admin_uid,
        "action": action,
        "entity_type": entity_type,
        "entity_id": entity_id,
        "details": details or {},
        "ip_address": ip_address,
        "user_agent": user_agent,
        "before_data": before_data,
        "after_data": after_data,
        "timestamp": datetime.now(timezone.utc).isoformat(),
        "created_at": datetime.now(timezone.utc).isoformat()
    }
    
    await db.admin_audit_logs.insert_one(audit_entry)
    return audit_entry


# ========== IDOR PROTECTION HELPER ==========
def verify_user_access_sync(request: Request, target_uid: str) -> bool:
    """
    SECURITY: Verify user can access the requested resource
    Returns True if allowed, raises HTTPException if not
    Non-admins can only access their own data
    """
    auth_header = request.headers.get("Authorization", "")
    if not auth_header.startswith("Bearer "):
        return True  # Allow anonymous for backwards compatibility, endpoint should handle
    
    token = auth_header.replace("Bearer ", "")
    try:
        payload = jwt.decode(token, JWT_SECRET_KEY, algorithms=[JWT_ALGORITHM])
        requesting_uid = payload.get("uid")
        requesting_role = payload.get("role", "user")
        
        # Admins can access any user's data
        if requesting_role in ["admin", "sub_admin"]:
            return True
        
        # Non-admins can only access their own data
        if requesting_uid != target_uid:
            raise HTTPException(
                status_code=403,
                detail="Access denied. You can only access your own data."
            )
        return True
    except jwt.InvalidTokenError:
        return True  # Let endpoint handle invalid token


# ========== SENSITIVE OPERATION AUDIT LOGGING ==========
async def log_sensitive_operation(
    operation_type: str,
    user_uid: str = None,
    target_uid: str = None,
    ip_address: str = None,
    user_agent: str = None,
    details: dict = None,
    success: bool = True,
    error_message: str = None
):
    """
    Log sensitive operations for security audit trail
    Types: login_attempt, password_reset, otp_request, data_access, profile_update, admin_action
    """
    audit_entry = {
        "audit_id": str(uuid.uuid4()),
        "operation_type": operation_type,
        "user_uid": user_uid,
        "target_uid": target_uid,
        "ip_address": ip_address,
        "user_agent": user_agent,
        "details": details or {},
        "success": success,
        "error_message": error_message,
        "timestamp": datetime.now(timezone.utc).isoformat()
    }
    
    # Fire and forget - don't block the request
    try:
        await db.security_audit_logs.insert_one(audit_entry)
    except Exception as e:
        logging.error(f"[AUDIT] Failed to log operation: {e}")
    
    return audit_entry


# ========== RATE LIMITING FOR SENSITIVE ENDPOINTS ==========
# In-memory rate limit for OTP/reset requests (stricter than login)
otp_rate_limit_storage = defaultdict(lambda: {"count": 0, "reset_time": time.time()})

def check_otp_rate_limit(identifier: str, ip_address: str = None) -> Tuple[bool, str]:
    """
    Strict rate limiting for OTP/password reset requests
    - 3 requests per 10 minutes per identifier
    - 10 requests per hour per IP
    Returns (allowed: bool, message: str)
    """
    current_time = time.time()
    
    # Per-identifier limit (3 per 10 min)
    id_key = f"otp:{identifier}"
    if current_time > otp_rate_limit_storage[id_key]["reset_time"]:
        otp_rate_limit_storage[id_key] = {"count": 1, "reset_time": current_time + 600}
    elif otp_rate_limit_storage[id_key]["count"] >= 3:
        return False, "Too many OTP requests. Please wait 10 minutes before trying again."
    else:
        otp_rate_limit_storage[id_key]["count"] += 1
    
    # Per-IP limit (10 per hour)
    if ip_address:
        ip_key = f"otp_ip:{ip_address}"
        if current_time > otp_rate_limit_storage[ip_key]["reset_time"]:
            otp_rate_limit_storage[ip_key] = {"count": 1, "reset_time": current_time + 3600}
        elif otp_rate_limit_storage[ip_key]["count"] >= 10:
            return False, "Too many requests from this IP. Please try again later."
        else:
            otp_rate_limit_storage[ip_key]["count"] += 1
    
    return True, ""

