# ========== ERROR SANITIZATION HANDLER ==========
# Strip MongoDB internals (shard hostnames, connection URLs, raw timeout phrases)
# from any error response body so they never reach end-user toasts.
import re as _err_re

_MONGO_INTERNALS_PATTERNS = [
    _err_re.compile(r"[a-z0-9-]+-shard-\d+-\d+\.[a-z0-9]+\.mongodb\.net:\d+", _err_re.I),
    _err_re.compile(r"mongodb\.net:\d+", _err_re.I),
    _err_re.compile(r"mongodb://[^\s]+", _err_re.I),
    _err_re.compile(r"the read operation timed out", _err_re.I),
    _err_re.compile(r"server selection timeout error", _err_re.I),
    _err_re.compile(r"connection.*\(closed\)", _err_re.I),
]

_FRIENDLY_DB_MSG = "Database is busy right now. Please try again in a few seconds."


def _sanitize_error_text(text: str) -> str:
    """Replace any MongoDB internals with a generic friendly message."""
    if not text or not isinstance(text, str):
        return text
    needs_replace = any(p.search(text) for p in _MONGO_INTERNALS_PATTERNS)
    if needs_replace:
        return _FRIENDLY_DB_MSG
    return text


@app.exception_handler(Exception)
async def _sanitize_unhandled_errors(request, exc):
    """Catch un-mapped exceptions, sanitize MongoDB internals, return 500."""
    from starlette.responses import JSONResponse
    raw = str(exc)
    safe = _sanitize_error_text(raw)
    return JSONResponse(status_code=500, content={"detail": safe})


@app.exception_handler(HTTPException)
async def _sanitize_http_exceptions(request, exc: HTTPException):
    """Sanitize HTTPException detail before responding."""
    from starlette.responses import JSONResponse
    detail = exc.detail
    if isinstance(detail, str):
        detail = _sanitize_error_text(detail)
    return JSONResponse(status_code=exc.status_code, content={"detail": detail})

# ========== ADMIN AUTHENTICATION MIDDLEWARE ==========
class AdminAuthMiddleware(BaseHTTPMiddleware):
    """
    SECURITY: Middleware to protect all /admin/ routes
    Requires valid JWT token with admin role
    """
    # Routes that should be excluded from auth check (public endpoints under /admin)
    EXCLUDED_ROUTES = [
        "/api/admin/payment-gateways-status",  # Public payment gateway status
        "/api/admin/popup/active",  # Public popup for user dashboard
        # Read-only feature flags consumed by the user dashboard. These must be
        # readable by ANY authenticated user (and even unauthenticated callers,
        # since the dashboard fetches them before auth state is resolved).
        # Toggling endpoints (POST) remain admin-only via inner role check.
        "/api/admin/failed-transactions/quick-recharge-status",
        "/api/admin/failed-transactions/refund-modal-status",
    ]
    
    async def dispatch(self, request, call_next):
        path = request.url.path
        
        # Only check routes under /api/admin/
        if not path.startswith("/api/admin/"):
            return await call_next(request)
        
        # Skip excluded routes
        if any(path.startswith(excluded) for excluded in self.EXCLUDED_ROUTES):
            return await call_next(request)
        
        # Extract Authorization header
        auth_header = request.headers.get("Authorization", "")
        
        if not auth_header.startswith("Bearer "):
            return JSONResponse(
                status_code=401,
                content={"detail": "Authentication required. Please provide a valid token."}
            )
        
        token = auth_header.replace("Bearer ", "")
        
        try:
            # Verify JWT token
            payload = jwt.decode(token, JWT_SECRET_KEY, algorithms=[JWT_ALGORITHM])
            
            # Check if user is admin
            role = payload.get("role", "user")
            is_admin = payload.get("is_admin", False)
            
            if role not in ["admin", "sub_admin"] and not is_admin:
                return JSONResponse(
                    status_code=403,
                    content={"detail": "Admin access required. Insufficient permissions."}
                )
            
            # Attach user info to request state for downstream use
            request.state.admin_user = payload
            
            # AUDIT: Log admin API access for sensitive endpoints
            admin_uid = payload.get("uid")
            client_ip = request.headers.get("X-Forwarded-For", "").split(",")[0].strip()
            if not client_ip:
                client_ip = request.headers.get("X-Real-IP", "")
            
            # Log write operations (POST, PUT, DELETE)
            if request.method in ["POST", "PUT", "DELETE", "PATCH"]:
                asyncio.create_task(log_sensitive_operation(
                    operation_type="admin_write_operation",
                    user_uid=admin_uid,
                    ip_address=client_ip,
                    details={
                        "method": request.method,
                        "path": path,
                        "role": role
                    },
                    success=True
                ))
            
        except jwt.ExpiredSignatureError:
            return JSONResponse(
                status_code=401,
                content={"detail": "Token expired. Please login again."}
            )
        except jwt.InvalidTokenError as e:
            logging.warning(f"[ADMIN AUTH] Invalid token attempt: {e}")
            return JSONResponse(
                status_code=401,
                content={"detail": "Invalid token. Please login again."}
            )
        
        return await call_next(request)

app.add_middleware(AdminAuthMiddleware)

# Health check endpoint for Kubernetes deployment
# This must return 200 even if DB is not fully connected
db_ready = False

async def retry_db_connection():
    """Background task to retry database connection"""
    global db_ready
    max_attempts = 30  # Try for up to 5 minutes (30 * 10 seconds)
    retry_delay = 10
    
    for attempt in range(max_attempts):
        if db_ready:
            return
        try:
            await asyncio.sleep(retry_delay)
            await client.admin.command('ping')
            db_ready = True
            print(f"✅ MongoDB connection established in background (attempt {attempt + 1})")
            # Now initialize database
            try:
                await initialize_database_indexes()
                print("✅ Database indexes initialized (background)")
            except Exception as e:
                print(f"⚠️ Error initializing indexes: {e}")
            return
        except Exception as e:
            print(f"⚠️ Background DB connection attempt {attempt + 1} failed: {str(e)[:100]}")
    
    print("❌ Failed to establish database connection after all background retries")

