@api_router.post("/admin/ensure-critical-indexes")
async def ensure_critical_indexes_now(request: Request):
    """One-shot endpoint to force-create critical Mongo indexes on a running
    production server WITHOUT a redeploy. Idempotent (safe to call repeatedly).

    Specifically targets the missing `vip_payments.payment_id` unique index
    that caused 6s+ COLLSCAN timeouts on approve/reject in May 2026. Also
    creates compound index for fraud-prevention check.

    Auth: Admin OPERATION_PIN required (header: X-Admin-Pin or body field
    `admin_pin`).
    """
    try:
        data = await request.json()
        admin_pin = (data.get("admin_pin") or request.headers.get("X-Admin-Pin") or "")
        if admin_pin != ADMIN_OPERATION_PIN:
            raise HTTPException(status_code=403, detail="Invalid admin PIN")

        results: list[dict] = []

        async def safe_create(collection_name: str, keys, **opts):
            try:
                col = db[collection_name]
                existing = await col.index_information()
                # Build the auto-generated index name pattern Mongo uses
                if isinstance(keys, str):
                    name = f"{keys}_1"
                    create_keys = keys
                else:
                    name = "_".join(f"{k}_{d}" for k, d in keys)
                    create_keys = keys
                if name in existing:
                    results.append({"collection": collection_name, "name": name, "status": "exists"})
                    return
                try:
                    await col.create_index(create_keys, **opts)
                    results.append({"collection": collection_name, "name": name, "status": "created"})
                except Exception as create_err:
                    err_str = str(create_err).lower()
                    # Unique constraint failed because of legacy duplicates —
                    # fall back to a NON-UNIQUE index. This still fixes the
                    # COLLSCAN performance issue while preserving the
                    # duplicates for separate cleanup.
                    if "duplicate key" in err_str and opts.get("unique"):
                        non_unique_opts = {k: v for k, v in opts.items() if k != "unique"}
                        try:
                            await col.create_index(create_keys, **non_unique_opts)
                            results.append({
                                "collection": collection_name,
                                "name": name,
                                "status": "created_non_unique",
                                "note": "Duplicates exist — created non-unique index (still fixes COLLSCAN). Run cleanup separately.",
                            })
                            return
                        except Exception as e2:
                            results.append({"collection": collection_name, "name": name, "status": "error", "error": str(e2)[:300]})
                            return
                    results.append({"collection": collection_name, "name": name, "status": "error", "error": str(create_err)[:300]})
            except Exception as e:
                results.append({"collection": collection_name, "name": str(keys), "status": "error", "error": str(e)[:300]})

        # The critical missing index — payment_id unique
        await safe_create("vip_payments", "payment_id", unique=True)
        # Fraud-prevention compound index used by approve flow
        await safe_create("vip_payments", [("user_id", 1), ("status", 1), ("approved_at", -1)])
        # Belt & suspenders: ensure existing recommended indexes are present
        await safe_create("vip_payments", [("status", 1), ("submitted_at", -1)])
        await safe_create("vip_payments", "user_id")

        # Also ensure subscription_payments has payment_id index (PRC flow)
        await safe_create("subscription_payments", "payment_id")
        await safe_create("subscription_payments", "user_id")

        # ✅ User-360 search indexes — fixes "Search failed: ... timed out" toast
        # Without these, every admin user-search did a COLLSCAN on the users
        # collection. Index lookups bring search latency from 8s timeout to <50ms.
        await safe_create("users", "uid")
        await safe_create("users", "mobile")
        await safe_create("users", "email")
        await safe_create("users", "referral_code")
        await safe_create("users", "pan_number")
        await safe_create("users", "aadhaar_number")

        # Also ensure idempotency_keys TTL/unique indexes (race-guard support)
        try:
            await db.idempotency_keys.create_index("expires_at", expireAfterSeconds=0)
        except Exception:
            pass
        try:
            await db.idempotency_keys.create_index([("scope", 1), ("key", 1)], unique=True)
        except Exception:
            pass

        return {
            "success": True,
            "message": "Indexes ensured. Approve/Reject latency should drop from 6s+ COLLSCAN to <100ms.",
            "results": results,
        }
    except HTTPException:
        raise
    except Exception as e:
        raise HTTPException(status_code=500, detail=str(e))


@api_router.post("/admin/clear-all-lockouts")
async def clear_all_login_lockouts():
    """
    Emergency API to clear ALL login lockouts from database and memory.
    Use when multiple users report lockout issues.
    """
    try:
        # Clear in-memory lockouts
        global login_attempt_storage
        login_attempt_storage.clear()
        
        # Clear database login_attempts
        db_result = await db.login_attempts.delete_many({})
        
        # Also clear any user-level lock flags
        await db.users.update_many(
            {"$or": [
                {"failed_login_attempts": {"$gt": 0}},
                {"locked_until": {"$ne": None}}
            ]},
            {
                "$set": {
                    "failed_login_attempts": 0,
                    "locked_until": None,
                    "failed_pin_attempts": 0,
                    "pin_locked_until": None
                }
            }
        )
        
        return {
            "success": True,
            "message": "All login lockouts cleared",
            "memory_cleared": True,
            "db_records_deleted": db_result.deleted_count,
            "timestamp": datetime.now(timezone.utc).isoformat()
        }
    except Exception as e:
        raise HTTPException(status_code=500, detail=get_user_friendly_error(e))


async def diagnose_user_login(identifier: str):
    """
    Diagnose why a specific user cannot login.
    Returns all relevant fields that could block login.
    """
    # Find user
    user = await db.users.find_one({
        "$or": [
            {"email": {"$regex": f"^{identifier}$", "$options": "i"}},
            {"mobile": identifier},
            {"uid": identifier}
        ]
    })
    
    if not user:
        return {
            "found": False,
            "error": "User NOT found in database",
            "identifier_searched": identifier,
            "possible_issues": [
                "Email/mobile might be different",
                "User may not be registered",
                "Check for typos in email"
            ]
        }
    
    # Check all possible blocking conditions
    diagnosis = {
        "found": True,
        "user_info": {
            "uid": user.get("uid"),
            "email": user.get("email"),
            "mobile": user.get("mobile"),
            "name": user.get("name"),
            "created_at": user.get("created_at")
        },
        "lockout_status": {
            "failed_login_attempts": user.get("failed_login_attempts", 0),
            "locked_until": user.get("locked_until"),
            "failed_pin_attempts": user.get("failed_pin_attempts", 0),
            "pin_locked_until": user.get("pin_locked_until"),
            "lockout_level": user.get("lockout_level", 0)
        },
        "account_status": {
            "is_blocked": user.get("is_blocked", False),
            "account_locked": user.get("account_locked", False),
            "is_suspended": user.get("is_suspended", False),
            "suspension_reason": user.get("suspension_reason"),
            "kyc_status": user.get("kyc_status"),
            "status": user.get("status")
        },
        "password_info": {
            "has_password": bool(user.get("password")),
            "has_password_hash": bool(user.get("password_hash")),
            "has_pin_hash": bool(user.get("pin_hash")),
            "password_reset_required": user.get("password_reset_required", False),
            "pin_reset_required": user.get("pin_reset_required", False)
        },
        "possible_issues": []
    }
    
    # Analyze issues
    issues = []
    
    if user.get("locked_until"):
        issues.append(f"LOCKED_UNTIL is set: {user.get('locked_until')}")
    
    if user.get("pin_locked_until"):
        issues.append(f"PIN_LOCKED_UNTIL is set: {user.get('pin_locked_until')}")
    
    if user.get("failed_login_attempts", 0) >= 3:
        issues.append(f"HIGH failed_login_attempts: {user.get('failed_login_attempts')}")
    
    if user.get("is_blocked"):
        issues.append("Account is BLOCKED (is_blocked=true)")
    
    if user.get("account_locked"):
        issues.append("Account is LOCKED (account_locked=true)")
    
    if user.get("is_suspended"):
        issues.append(f"Account is SUSPENDED: {user.get('suspension_reason')}")
    
    if not user.get("password") and not user.get("password_hash") and not user.get("pin_hash"):
        issues.append("NO PASSWORD/PIN SET - User cannot login!")
    
    if not issues:
        issues.append("No obvious issues found. User should be able to login.")
    
    diagnosis["possible_issues"] = issues
    
    # Check login_attempts collection
    login_attempts = await db.login_attempts.find({
        "$or": [
            {"identifier": user.get("email")},
            {"identifier": user.get("mobile")},
            {"identifier": user.get("uid")}
        ]
    }).sort("timestamp", -1).limit(10).to_list(10)
    
    diagnosis["recent_login_attempts"] = [
        {
            "timestamp": a.get("timestamp"),
            "success": a.get("success"),
            "ip": a.get("ip_address")
        }
        for a in login_attempts
    ]
    
    # Check in-memory lockout
    identifiers = [user.get("email"), user.get("mobile"), user.get("uid")]
    in_memory_status = {}
    for ident in identifiers:
        if ident:
            key = f"login:{ident}"
            if key in login_attempt_storage:
                in_memory_status[ident] = login_attempt_storage[key]
    
    diagnosis["in_memory_lockout"] = in_memory_status if in_memory_status else "No in-memory lockout found"
    
    return diagnosis


async def force_fix_user(identifier: str):
    """
    Force fix a user's account - clears ALL possible blocking conditions.
    Use this when a user cannot login despite clear_lockout.
    """
    # Find user
    user = await db.users.find_one({
        "$or": [
            {"email": {"$regex": f"^{identifier}$", "$options": "i"}},
            {"mobile": identifier},
            {"uid": identifier}
        ]
    })
    
    if not user:
        raise HTTPException(status_code=404, detail="User not found")
    
    user_id = user.get("uid")
    
    # Clear EVERYTHING that could possibly block login
    await db.users.update_one(
        {"uid": user_id},
        {
            "$set": {
                "failed_login_attempts": 0,
                "locked_until": None,
                "failed_pin_attempts": 0,
                "pin_locked_until": None,
                "lockout_level": 0,
                "is_blocked": False,
                "account_locked": False,
                "is_suspended": False,
                "suspension_reason": None,
                "password_reset_required": False,
                "pin_reset_required": False
            }
        }
    )
    
    # Clear from login_attempts collection
    delete_result = await db.login_attempts.delete_many({
        "$or": [
            {"identifier": user.get("email")},
            {"identifier": user.get("mobile")},
            {"identifier": user_id}
        ]
    })
    
    # Clear from in-memory storage
    identifiers = [user.get("email"), user.get("mobile"), user_id]
    cleared_memory = []
    for ident in identifiers:
        if ident:
            key = f"login:{ident}"
            if key in login_attempt_storage:
                login_attempt_storage[key] = {"count": 0, "reset_time": time.time() + RATE_LIMIT_WINDOW_SECONDS, "locked_until": 0, "lockout_level": 0}
                cleared_memory.append(ident)
    
    return {
        "success": True,
        "user_id": user_id,
        "email": user.get("email"),
        "message": "All blocking conditions cleared",
        "db_fields_reset": True,
        "login_attempts_deleted": delete_result.deleted_count,
        "memory_cleared_for": cleared_memory
    }


async def migrate_user_to_pin(identifier: str, new_pin: str = None):
    """
    Migrate a user from password to PIN system.
    If no PIN provided, generates a random 6-digit PIN.
    Use this for users who have password but no PIN.
    """
    
    # Find user
    user = await db.users.find_one({
        "$or": [
            {"email": {"$regex": f"^{identifier}$", "$options": "i"}},
            {"mobile": identifier},
            {"uid": identifier}
        ]
    })
    
    if not user:
        raise HTTPException(status_code=404, detail="User not found")
    
    # Generate PIN if not provided
    if not new_pin:
        new_pin = str(secrets.randbelow(900000) + 100000)
    
    # Validate PIN
    if not new_pin.isdigit() or len(new_pin) != 6:
        raise HTTPException(status_code=400, detail="PIN must be exactly 6 digits")
    
    # Hash the PIN
    pin_hash = pwd_context.hash(new_pin)
    
    # Update user
    await db.users.update_one(
        {"uid": user.get("uid")},
        {
            "$set": {
                "pin_hash": pin_hash,
                "pin_migrated": True,
                "password_hash": pin_hash,  # Also set password_hash for backward compatibility
                "password": pin_hash,       # Legacy field
                "failed_login_attempts": 0,
                "locked_until": None,
                "failed_pin_attempts": 0,
                "pin_locked_until": None
            }
        }
    )
    
    return {
        "success": True,
        "user_id": user.get("uid"),
        "email": user.get("email"),
        "mobile": user.get("mobile"),
        "new_pin": new_pin,
        "message": f"User migrated to PIN. New PIN: {new_pin}. Please share this securely with the user."
    }


