# Create scheduler for automated tasks (explicit UTC timezone for deterministic cron math)
import pytz
scheduler = AsyncIOScheduler(timezone=pytz.utc)

# ========== AUTO SYNC RAZORPAY PAYMENTS FUNCTION ==========
async def auto_sync_razorpay_payments():
    """
    Automatically sync pending Razorpay payments every 10 minutes.
    Checks Razorpay API and activates subscriptions for captured payments.
    """
    print(f"[AUTO-SYNC] ⏰ Auto-sync triggered at {datetime.now(timezone.utc).isoformat()}")
    
    try:
        import razorpay
        
        RAZORPAY_KEY_ID = os.environ.get("RAZORPAY_KEY_ID")
        RAZORPAY_KEY_SECRET = os.environ.get("RAZORPAY_KEY_SECRET")
        
        if not RAZORPAY_KEY_ID or not RAZORPAY_KEY_SECRET:
            print("[AUTO-SYNC] ❌ Razorpay not configured, skipping...")
            return
        
        print("[AUTO-SYNC] ✅ Razorpay configured, starting sync...")
        
        razorpay_client = razorpay.Client(auth=(RAZORPAY_KEY_ID, RAZORPAY_KEY_SECRET))
        
        # Plan durations (28 days per month)
        PLAN_DURATIONS = {
            "monthly": 28,
            "quarterly": 84,
            "half_yearly": 168,
            "yearly": 336
        }
        
        # Get all pending orders - REDUCED limit to prevent event loop blocking
        # CRITICAL FIX (Feb 2026): The previous version had a duplicate `status`
        # key in the dict literal — the second `$nin` clause silently OVERRODE
        # the first `$in` clause, causing the query to pull every order except
        # cancelled/failed instead of only pending ones. Merged into a single
        # `status: {$in: [...]}` clause. Cancelled/failed orders remain excluded.
        pending_orders = await db.razorpay_orders.find({
            "status": {"$in": ["created", "pending", "attempted"]},
        }).to_list(20)  # Reduced from 200 to 20 to minimize blocking time
        
        if not pending_orders:
            print("[AUTO-SYNC] No pending orders to sync")
            return
        
        print(f"[AUTO-SYNC] Found {len(pending_orders)} pending orders to sync")
        
        synced_count = 0
        
        for order in pending_orders:
            order_id = order.get("order_id")
            user_id = order.get("user_id")
            
            try:
                # FIXED: Use asyncio.to_thread() to prevent blocking the event loop
                # Razorpay SDK uses synchronous requests library
                razorpay_order = await asyncio.to_thread(razorpay_client.order.fetch, order_id)
                razorpay_status = razorpay_order.get("status")
                
                if razorpay_status == "paid":
                    # Order is paid - fetch payment details
                    # FIXED: Use asyncio.to_thread() for async-safe call
                    payments = await asyncio.to_thread(razorpay_client.order.payments, order_id)
                    
                    # Find captured payment
                    captured_payment = None
                    for payment in payments.get("items", []):
                        if payment.get("status") == "captured":
                            captured_payment = payment
                            break
                    
                    if captured_payment:
                        payment_id = captured_payment.get("id")
                        amount = captured_payment.get("amount", 0) / 100
                        
                        # CRITICAL CHECK 1: Check if this payment was already used in vip_payments
                        existing_vip = await db.vip_payments.find_one({"payment_id": payment_id})
                        if existing_vip:
                            print(f"[AUTO-SYNC] ⚠️ Payment {payment_id} already in vip_payments, skipping")
                            # Mark order as paid anyway to prevent future attempts
                            await db.razorpay_orders.update_one(
                                {"order_id": order_id},
                                {"$set": {"status": "paid", "skipped_reason": "already_in_vip_payments"}}
                            )
                            continue
                        
                        # CRITICAL CHECK 2: Check if user already has this payment_id
                        user_with_payment = await db.users.find_one({"last_payment_id": payment_id})
                        if user_with_payment:
                            print(f"[AUTO-SYNC] ⚠️ Payment {payment_id} already activated for user {user_with_payment.get('uid')}, skipping")
                            await db.razorpay_orders.update_one(
                                {"order_id": order_id},
                                {"$set": {"status": "paid", "skipped_reason": "user_has_payment"}}
                            )
                            continue
                        
                        # ATOMIC CLAIM: Mark order as processing to prevent race condition
                        # Feb 2026: also exclude cancelled/failed/etc. to prevent
                        # the auto-sync from over-riding a user-initiated cancel.
                        claim_result = await db.razorpay_orders.find_one_and_update(
                            {
                                "order_id": order_id,
                                "status": {"$nin": [
                                    "paid", "processing",
                                    "cancelled", "failed", "error", "timeout", "dismissed",
                                ]}
                            },
                            {
                                "$set": {
                                    "status": "processing",
                                    "payment_id": payment_id,
                                    "processing_by": "auto_sync",
                                    "processing_at": datetime.now(timezone.utc).isoformat()
                                }
                            }
                        )
                        
                        if not claim_result:
                            print(f"[AUTO-SYNC] Order {order_id} already being processed, skipping")
                            continue
                        
                        # ACTIVATE SUBSCRIPTION
                        plan_type = order.get("plan_type", "monthly")
                        plan_name = order.get("plan_name", "startup")
                        duration_days = PLAN_DURATIONS.get(plan_type, 28)  # Default 28 days
                        
                        now = datetime.now(timezone.utc)
                        
                        # Atomic claim on user to prevent double activation
                        user = await db.users.find_one_and_update(
                            {
                                "uid": user_id,
                                "last_payment_id": {"$ne": payment_id}
                            },
                            {"$set": {"_auto_sync_claiming": payment_id}}
                        )
                        
                        if not user:
                            print(f"[AUTO-SYNC] User {user_id} already has payment {payment_id}, skipping")
                            await db.razorpay_orders.update_one(
                                {"order_id": order_id},
                                {"$set": {"status": "paid", "skipped_reason": "user_claim_failed"}}
                            )
                            continue
                        
                        remaining_days = 0
                        old_plan = user.get("subscription_plan")
                        
                        # Check BOTH field names
                        existing_expiry = get_user_expiry(user)
                        if existing_expiry:
                            if isinstance(existing_expiry, str):
                                try:
                                    existing_expiry = datetime.fromisoformat(existing_expiry.replace('Z', '+00:00'))
                                except:
                                    existing_expiry = None
                            
                            if existing_expiry:
                                if existing_expiry.tzinfo is None:
                                    existing_expiry = existing_expiry.replace(tzinfo=timezone.utc)
                                if existing_expiry > now:
                                    remaining_days = (existing_expiry - now).days
                        
                        total_days = duration_days + remaining_days
                        expiry_date = now + timedelta(days=total_days)
                        
                        # Update user subscription (set BOTH expiry fields)
                        # Preserve existing subscription_payment_type if user has active PRC subscription
                        existing_payment_type = user.get("subscription_payment_type", "cash")
                        new_payment_type = "cash"  # Razorpay = cash
                        # If user already has active subscription (remaining_days > 0) and paid via PRC, preserve it
                        if remaining_days > 0 and existing_payment_type == "prc":
                            new_payment_type = "prc"
                        
                        await db.users.update_one(
                            {"uid": user_id},
                            {
                                "$set": {
                                    "subscription_plan": plan_name,
                                    "subscription_start": now,
                                    "subscription_expiry": expiry_date.isoformat(),
                                    "membership_type": "vip",
                                    "subscription_status": "active",
                                    "last_payment_id": payment_id,
                                    "last_payment_date": now,
                                    "previous_plan": old_plan,
                                    "previous_remaining_days_added": remaining_days,
                                    "activated_via": "auto_sync",
                                    "subscription_payment_type": new_payment_type
                                },
                                "$unset": {"_auto_sync_claiming": ""}
                            }
                        )
                        
                        # Assign subscription position for mining network
                        try:
                            await assign_subscription_position(user_id)
                        except Exception as pos_err:
                            logging.warning(f"[AUTO-SYNC] Sub position error: {pos_err}")
                        
                        # Update order status to paid
                        await db.razorpay_orders.update_one(
                            {"order_id": order_id},
                            {
                                "$set": {
                                    "status": "paid",
                                    "payment_captured": True,
                                    "verified_amount": amount,
                                    "synced_at": datetime.now(timezone.utc).isoformat(),
                                    "synced_via": "auto_sync"
                                }
                            }
                        )
                        
                        # Check if transaction already exists
                        existing_txn = await db.transactions.find_one({
                            "payment_id": payment_id,
                            "type": "subscription_payment"
                        })
                        
                        if not existing_txn:
                            # Log transaction
                            await db.transactions.insert_one({
                                "user_id": user_id,
                                "type": "subscription_payment",
                                "amount": amount,
                                "payment_id": payment_id,
                                "order_id": order_id,
                                "plan_name": plan_name,
                                "plan_type": plan_type,
                                "duration_days": duration_days,
                                "remaining_days_added": remaining_days,
                                "total_days": total_days,
                                "activated_via": "auto_sync",
                                "timestamp": now
                            })
                        
                        # Check if vip_payment already exists
                        existing_vip = await db.vip_payments.find_one({"payment_id": payment_id})
                        if not existing_vip:
                            # CRITICAL: Also log to vip_payments to prevent double activation
                            await db.vip_payments.insert_one({
                                "user_id": user_id,
                                "order_id": order_id,
                                "payment_id": payment_id,
                                "amount": amount,
                                "subscription_plan": plan_name.lower(),
                                "plan_type": plan_type,
                                "status": "approved",
                                "payment_method": "razorpay",
                                "payment_captured": True,
                                "new_expiry": expiry_date.isoformat(),
                                "duration_days": total_days,
                                "remaining_days_added": remaining_days,
                                "approved_at": now.isoformat(),
                                "created_at": now.isoformat(),
                                "auto_activated": True,
                                "activation_source": "auto_sync"
                            })
                        
                        synced_count += 1
                        print(f"[AUTO-SYNC] ✅ Activated subscription for user {user_id}, plan: {plan_name}")
                        
            except Exception as e:
                print(f"[AUTO-SYNC] Error syncing order {order_id}: {e}")
        
        if synced_count > 0:
            print(f"[AUTO-SYNC] ✅ Completed - Activated {synced_count} subscriptions")
        else:
            print("[AUTO-SYNC] No new payments to activate")
            
    except Exception as e:
        print(f"[AUTO-SYNC] ❌ Error: {e}")


async def auto_sync_captured_from_razorpay():
    """
    ADDITIONAL SYNC: Fetch recent captured payments directly from Razorpay API
    and activate any that have orders in our DB but are not yet activated.
    This catches payments where webhook failed or user closed modal early.
    """
    print(f"[RAZORPAY-CAPTURED-SYNC] ⏰ Triggered at {datetime.now(timezone.utc).isoformat()}")
    
    try:
        import razorpay
        
        RAZORPAY_KEY_ID = os.environ.get("RAZORPAY_KEY_ID")
        RAZORPAY_KEY_SECRET = os.environ.get("RAZORPAY_KEY_SECRET")
        
        if not RAZORPAY_KEY_ID or not RAZORPAY_KEY_SECRET:
            return
        
        razorpay_client = razorpay.Client(auth=(RAZORPAY_KEY_ID, RAZORPAY_KEY_SECRET))
        
        PLAN_DURATIONS = {
            "monthly": 28,
            "quarterly": 84,
            "half_yearly": 168,
            "yearly": 336
        }
        
        # Fetch recent captured payments (last 24 hours)
        from_timestamp = int((datetime.now(timezone.utc) - timedelta(hours=24)).timestamp())
        
        # FIXED: Use asyncio.to_thread() to prevent blocking the event loop
        payments_response = await asyncio.to_thread(
            razorpay_client.payment.all,
            {"count": 50, "from": from_timestamp}
        )
        
        all_payments = payments_response.get("items", [])
        captured_payments = [p for p in all_payments if p.get("status") == "captured"]
        
        if not captured_payments:
            print("[RAZORPAY-CAPTURED-SYNC] No recent captured payments")
            return
        
        print(f"[RAZORPAY-CAPTURED-SYNC] Found {len(captured_payments)} captured payments in last 24 hours")
        
        activated_count = 0
        
        for payment in captured_payments:
            payment_id = payment.get("id")
            order_id = payment.get("order_id")
            amount = payment.get("amount", 0) / 100
            
            if not order_id:
                continue
            
            try:
                # Check if order exists and is not yet paid
                order = await db.razorpay_orders.find_one({"order_id": order_id})
                
                if not order:
                    continue
                
                # CRITICAL CHECK 1: If order is already paid/processing, skip completely
                if order.get("status") in ["paid", "processing"]:
                    continue  # Already processed - skip to prevent double activation

                # CRITICAL CHECK 1b (Feb 2026 revenue-leak fix): if the frontend
                # already marked this order as cancelled / failed / errored /
                # timed-out / dismissed, DO NOT activate the subscription even
                # if a captured payment matches. This mirrors the same gate in
                # the /webhook and /verify-payment endpoints. Preserves user
                # intent — a cancelled order stays cancelled. If the user was
                # actually charged (rare async-UPI edge case), support can
                # manually reconcile via /admin/fix-subscription. Silent
                # auto-activation of cancelled orders was the reported bug.
                if order.get("status") in ["cancelled", "failed", "error", "timeout", "dismissed"]:
                    print(f"[RAZORPAY-CAPTURED-SYNC] Order {order_id} is {order.get('status')} - NOT activating (respecting user cancel)")
                    # Tag the order so support can find these easily
                    await db.razorpay_orders.update_one(
                        {"order_id": order_id},
                        {"$set": {
                            "captured_sync_skipped_reason": f"order_status_was_{order.get('status')}",
                            "captured_sync_skipped_at": datetime.now(timezone.utc).isoformat(),
                            "captured_payment_id_seen": payment_id,
                        }}
                    )
                    continue
                
                # CRITICAL CHECK 2: Check if this specific payment was already used in vip_payments
                existing_vip = await db.vip_payments.find_one({"payment_id": payment_id})
                if existing_vip:
                    # Mark order as paid to prevent future attempts
                    await db.razorpay_orders.update_one(
                        {"order_id": order_id},
                        {"$set": {"status": "paid", "skipped_reason": "already_in_vip_payments"}}
                    )
                    continue  # This payment already activated a subscription
                
                # CRITICAL CHECK 3: Check if any user already has this payment_id
                user_with_payment = await db.users.find_one({"last_payment_id": payment_id})
                if user_with_payment:
                    await db.razorpay_orders.update_one(
                        {"order_id": order_id},
                        {"$set": {"status": "paid", "skipped_reason": "user_has_payment"}}
                    )
                    continue
                
                # Need to activate!
                user_id = order.get("user_id")
                plan_type = order.get("plan_type", "monthly")
                plan_name = order.get("plan_name", "startup")
                duration_days = PLAN_DURATIONS.get(plan_type, 28)
                
                now = datetime.now(timezone.utc)
                
                # ATOMIC CLAIM ORDER: Mark as processing to prevent race condition
                # Feb 2026: also exclude cancelled/failed/etc. so this claim
                # cannot race with a user cancel that landed a microsecond ago.
                claim_order = await db.razorpay_orders.find_one_and_update(
                    {
                        "order_id": order_id,
                        "status": {"$nin": [
                            "paid", "processing",
                            "cancelled", "failed", "error", "timeout", "dismissed",
                        ]}
                    },
                    {
                        "$set": {
                            "status": "processing",
                            "payment_id": payment_id,
                            "processing_by": "captured_sync"
                        }
                    }
                )
                
                if not claim_order:
                    print(f"[RAZORPAY-CAPTURED-SYNC] Order {order_id} already being processed, skipping")
                    continue
                
                # ATOMIC CLAIM USER: Try to claim this payment for user
                user = await db.users.find_one_and_update(
                    {
                        "uid": user_id,
                        "last_payment_id": {"$ne": payment_id}
                    },
                    {"$set": {"_captured_sync_claiming": payment_id}}
                )
                
                if not user:
                    print(f"[RAZORPAY-CAPTURED-SYNC] User {user_id} already has payment {payment_id}, skipping")
                    await db.razorpay_orders.update_one(
                        {"order_id": order_id},
                        {"$set": {"status": "paid", "skipped_reason": "user_claim_failed"}}
                    )
                    continue
                
                remaining_days = 0
                user_name = user.get("name", "Unknown")
                
                expiry = get_user_expiry(user)
                if expiry:
                    try:
                        if isinstance(expiry, str):
                            exp_date = datetime.fromisoformat(expiry.replace('Z', '+00:00'))
                        else:
                            exp_date = expiry
                        if exp_date.tzinfo is None:
                            exp_date = exp_date.replace(tzinfo=timezone.utc)
                        if exp_date > now:
                            remaining_days = (exp_date - now).days
                    except:
                        pass
                
                total_days = duration_days + remaining_days
                new_expiry = now + timedelta(days=total_days)
                
                # Update order to paid
                await db.razorpay_orders.update_one(
                    {"order_id": order_id},
                    {"$set": {
                        "status": "paid",
                        "payment_captured": True,
                        "verified_amount": amount,
                        "synced_at": now.isoformat(),
                        "synced_via": "captured_sync"
                    }}
                )
                
                # Update user
                # Preserve existing subscription_payment_type if user has active PRC subscription
                existing_ptype = user.get("subscription_payment_type", "cash")
                captured_payment_type = "cash"
                if remaining_days > 0 and existing_ptype == "prc":
                    captured_payment_type = "prc"
                
                await db.users.update_one(
                    {"uid": user_id},
                    {
                        "$set": {
                            "subscription_plan": plan_name.lower(),
                            "subscription_type": plan_type,
                            "subscription_status": "active",
                            "subscription_start": now.isoformat(),
                            "subscription_expiry": new_expiry.isoformat(),
                            "membership_type": "vip",
                            "last_payment_id": payment_id,
                            "last_payment_amount": amount,
                            "last_payment_date": now.isoformat(),
                            "activated_via": "captured_sync",
                            "subscription_payment_type": captured_payment_type
                        },
                        "$unset": {"_captured_sync_claiming": ""}
                    }
                )
                
                # Assign subscription position for mining network
                try:
                    await assign_subscription_position(user_id)
                except Exception as pos_err:
                    logging.warning(f"[CAPTURED-SYNC] Sub position error: {pos_err}")
                
                # Check if vip_payment already exists
                existing_vip_check = await db.vip_payments.find_one({"payment_id": payment_id})
                if not existing_vip_check:
                    await db.vip_payments.insert_one({
                        "user_id": user_id,
                        "order_id": order_id,
                        "payment_id": payment_id,
                        "amount": amount,
                        "subscription_plan": plan_name.lower(),
                        "plan_type": plan_type,
                        "status": "approved",
                        "payment_method": "razorpay",
                        "payment_captured": True,
                        "new_expiry": new_expiry.isoformat(),
                        "duration_days": total_days,
                        "remaining_days_added": remaining_days,
                        "approved_at": now.isoformat(),
                        "created_at": now.isoformat(),
                        "auto_activated": True,
                        "activation_source": "captured_sync"
                    })
                
                activated_count += 1
                print(f"[RAZORPAY-CAPTURED-SYNC] ✅ Activated: {user_name}, Plan: {plan_name}")
                
            except Exception as e:
                print(f"[RAZORPAY-CAPTURED-SYNC] Error for {order_id}: {e}")
        
        if activated_count > 0:
            print(f"[RAZORPAY-CAPTURED-SYNC] ✅ Activated {activated_count} subscriptions")
        else:
            print("[RAZORPAY-CAPTURED-SYNC] No new activations needed")
            
    except Exception as e:
        print(f"[RAZORPAY-CAPTURED-SYNC] ❌ Error: {e}")


# ========== AUTO LOCKOUT CLEAR FUNCTION ==========
async def auto_clear_all_lockouts():
    """
    Automatically clear all login lockouts.
    Runs at 12 PM (noon) and 12 AM (midnight) daily.
    """
    try:
        global login_attempt_storage
        login_attempt_storage.clear()
        
        # Clear database login_attempts
        db_result = await db.login_attempts.delete_many({})
        
        # Clear user-level lock flags
        user_result = await db.users.update_many(
            {"$or": [
                {"failed_login_attempts": {"$gt": 0}},
                {"locked_until": {"$ne": None}},
                {"failed_pin_attempts": {"$gt": 0}},
                {"pin_locked_until": {"$ne": None}}
            ]},
            {
                "$set": {
                    "failed_login_attempts": 0,
                    "locked_until": None,
                    "failed_pin_attempts": 0,
                    "pin_locked_until": None
                }
            }
        )
        
        print(f"[AUTO LOCKOUT CLEAR] {datetime.now(timezone.utc).isoformat()} - Cleared {db_result.deleted_count} login attempts, {user_result.modified_count} users unlocked")
    except Exception as e:
        print(f"[AUTO LOCKOUT CLEAR ERROR] {e}")


# ========== DAILY WALLET RECONCILIATION ==========
async def daily_wallet_reconciliation():
    """
    Daily wallet reconciliation and profit calculation.
    Runs at 3 AM daily.
    """
    try:
        now = datetime.now(timezone.utc)
        today = now.strftime("%Y-%m-%d")
        
        # Calculate today's transactions
        today_start = now.replace(hour=0, minute=0, second=0, microsecond=0).isoformat()
        
        # Get subscription payments
        subscription_revenue = await db.subscription_orders.aggregate([
            {"$match": {"status": "paid", "created_at": {"$gte": today_start}}},
            {"$group": {"_id": None, "total": {"$sum": "$amount"}}}
        ]).to_list(1)
        
        # Get bill payments
        bill_payments = await db.bill_payment_requests.aggregate([
            {"$match": {"status": "completed", "created_at": {"$gte": today_start}}},
            {"$group": {"_id": None, "total": {"$sum": "$total_inr"}, "count": {"$sum": 1}}}
        ]).to_list(1)
        
        # Get bank redeems
        bank_redeems = await db.bank_withdrawal_requests.aggregate([
            {"$match": {"status": "completed", "created_at": {"$gte": today_start}}},
            {"$group": {"_id": None, "total": {"$sum": "$amount_inr"}, "count": {"$sum": 1}}}
        ]).to_list(1)
        
        # Save daily summary
        summary = {
            "date": today,
            "subscription_revenue": subscription_revenue[0]["total"] if subscription_revenue else 0,
            "bill_payments_total": bill_payments[0]["total"] if bill_payments else 0,
            "bill_payments_count": bill_payments[0]["count"] if bill_payments else 0,
            "bank_redeems_total": bank_redeems[0]["total"] if bank_redeems else 0,
            "bank_redeems_count": bank_redeems[0]["count"] if bank_redeems else 0,
            "generated_at": now.isoformat()
        }
        
        await db.daily_reconciliation.update_one(
            {"date": today},
            {"$set": summary},
            upsert=True
        )
        
        print(f"[WALLET RECONCILIATION] {today} - Revenue: ₹{summary['subscription_revenue']}, Bills: {summary['bill_payments_count']}, Redeems: {summary['bank_redeems_count']}")
    except Exception as e:
        print(f"[WALLET RECONCILIATION ERROR] {e}")


# ========== DATABASE KEEP-ALIVE PING ==========
_last_successful_ping = None
_consecutive_failures = 0


# ==================== EMERGENCY AUTO-PAUSE JOB (REMOVED) ====================
# The dynamic-rate emergency pause feature was removed in the June 2026
# fixed-rate cleanup (10 PRC = ₹1). The check_emergency_auto_pause_job and
# associated scheduler invocation are no longer needed.


async def auto_expire_subscriptions():
    """
    Background cron job: Automatically downgrade expired subscriptions to Explorer.
    Runs every 30 minutes to catch expired plans promptly.
    
    Two cases handled:
    1. Has expiry date → check if passed → downgrade
    2. No expiry date + no subscription_status=active → check payment records → downgrade if no valid payment
    """
    try:
        now = datetime.now(timezone.utc)
        now_iso = now.isoformat()
        
        # Find all users with paid plans (not explorer/free) that are not already expired
        paid_users = await db.users.find(
            {
                "subscription_plan": {"$nin": ["explorer", "free", "", None]},
                "subscription_expired": {"$ne": True}
            },
            {"_id": 0, "uid": 1, "subscription_plan": 1, "subscription_expiry": 1,
             "subscription_status": 1}
        ).to_list(500)
        
        if not paid_users:
            return
        
        expired_count = 0
        for user in paid_users:
            uid = user.get("uid")
            if not uid:
                continue
            
            # Check ALL expiry fields
            expiry_val = get_user_expiry(user)
            
            if expiry_val:
                # CASE 1: Has expiry date - check if expired
                try:
                    if isinstance(expiry_val, str):
                        expiry_dt = datetime.fromisoformat(str(expiry_val).replace('Z', '+00:00'))
                    elif isinstance(expiry_val, datetime):
                        expiry_dt = expiry_val
                    else:
                        continue
                    
                    if expiry_dt.tzinfo is None:
                        expiry_dt = expiry_dt.replace(tzinfo=timezone.utc)
                    
                    if now > expiry_dt:
                        old_plan = user.get("subscription_plan", "unknown")
                        await db.users.update_one(
                            {"uid": uid},
                            {"$set": {
                                "subscription_plan": "explorer",
                                "subscription_expired": True,
                                "subscription_expired_at": now_iso,
                                "subscription_status": "expired"
                            }}
                        )
                        expired_count += 1
                        logging.info(f"[AUTO-EXPIRE] User {uid} plan '{old_plan}' expired (expiry passed) → explorer")
                        
                        # Check for upcoming plan to auto-activate
                        try:
                            from routes.admin_subscription import check_and_activate_upcoming
                            activation = await check_and_activate_upcoming(uid)
                            if activation:
                                expired_count -= 1  # Not really expired, upcoming activated
                                logging.info(f"[AUTO-EXPIRE] User {uid} upcoming plan auto-activated: {activation.get('plan_name')}")
                        except Exception as upcoming_err:
                            logging.error(f"[AUTO-EXPIRE] Error activating upcoming for {uid}: {upcoming_err}")
                        
                        if cache:
                            await cache.delete(f"user_data:{uid}")
                            await cache.delete(f"user:dashboard:{uid}")
                except Exception as e:
                    logging.error(f"[AUTO-EXPIRE] Error processing user {uid}: {e}")
            else:
                # CASE 2: No expiry date at all
                # If subscription_status is explicitly "active", skip (admin-activated)
                if user.get("subscription_status") == "active":
                    continue
                
                # No expiry + no active status → check for valid payment records
                has_valid_payment = False
                try:
                    # Check razorpay_orders for paid/captured orders
                    razorpay_order = await db.razorpay_orders.find_one(
                        {"uid": uid, "payment_status": {"$in": ["captured", "paid"]}},
                        {"_id": 1}
                    )
                    if razorpay_order:
                        has_valid_payment = True
                    
                    if not has_valid_payment:
                        # Check vip_payments for approved payments
                        vip_payment = await db.vip_payments.find_one(
                            {"user_id": uid, "status": "approved"},
                            {"_id": 1}
                        )
                        if vip_payment:
                            has_valid_payment = True
                except Exception:
                    pass
                
                if not has_valid_payment:
                    # No expiry, no active status, no valid payment → downgrade
                    old_plan = user.get("subscription_plan", "unknown")
                    await db.users.update_one(
                        {"uid": uid},
                        {"$set": {
                            "subscription_plan": "explorer",
                            "subscription_expired": True,
                            "subscription_expired_at": now_iso,
                            "subscription_status": "expired",
                            "downgrade_reason": "no_expiry_no_payment"
                        }}
                    )
                    expired_count += 1
                    logging.info(f"[AUTO-EXPIRE] User {uid} plan '{old_plan}' no expiry + no payment → explorer")
                    if cache:
                        await cache.delete(f"user_data:{uid}")
                        await cache.delete(f"user:dashboard:{uid}")
        
        if expired_count > 0:
            logging.info(f"[AUTO-EXPIRE] Downgraded {expired_count} expired subscriptions to explorer")
        
        # ========== SECONDARY SWEEP: Activate stuck upcoming plans ==========
        # Edge case: Users already on explorer/free with an "upcoming" paid plan
        # (they could have been manually downgraded, or plan expired before this cron caught them).
        # Directly activate their upcoming plan so they don't lose paid-for days.
        try:
            stuck_upcomings = await db.subscription_payments.find(
                {"status": "upcoming"},
                {"_id": 0, "user_id": 1, "scheduled_start": 1, "plan_name": 1}
            ).to_list(500)
            
            activated_count = 0
            for up in stuck_upcomings:
                uid = up.get("user_id")
                if not uid:
                    continue
                
                # Check if scheduled_start has passed
                sched_start = up.get("scheduled_start")
                if sched_start:
                    try:
                        if isinstance(sched_start, str):
                            sched_dt = datetime.fromisoformat(sched_start.replace('Z', '+00:00'))
                        elif isinstance(sched_start, datetime):
                            sched_dt = sched_start
                        else:
                            continue
                        if sched_dt.tzinfo is None:
                            sched_dt = sched_dt.replace(tzinfo=timezone.utc)
                        if sched_dt > now:
                            continue  # Not yet due to start
                    except Exception:
                        pass
                
                # Check user state: is it safe to activate?
                u = await db.users.find_one({"uid": uid}, {"_id": 0, "subscription_plan": 1, "subscription_expiry": 1, "subscription_expired": 1})
                if not u:
                    continue
                
                u_plan = u.get("subscription_plan")
                u_exp_val = u.get("subscription_expiry")
                u_exp_dt = None
                if u_exp_val:
                    try:
                        if isinstance(u_exp_val, str):
                            u_exp_dt = datetime.fromisoformat(u_exp_val.replace('Z', '+00:00'))
                        elif isinstance(u_exp_val, datetime):
                            u_exp_dt = u_exp_val
                        if u_exp_dt and u_exp_dt.tzinfo is None:
                            u_exp_dt = u_exp_dt.replace(tzinfo=timezone.utc)
                    except Exception:
                        u_exp_dt = None
                
                # Safe to activate if: on explorer/free OR current expiry already passed OR explicitly expired
                is_on_free = u_plan in ["explorer", "free", "", None]
                is_past_expiry = u_exp_dt and u_exp_dt <= now
                is_expired_flag = u.get("subscription_expired") == True
                
                if is_on_free or is_past_expiry or is_expired_flag:
                    try:
                        from routes.admin_subscription import check_and_activate_upcoming
                        activation = await check_and_activate_upcoming(uid)
                        if activation:
                            activated_count += 1
                            logging.info(f"[AUTO-EXPIRE sweep] Stuck upcoming activated for {uid}: {activation.get('plan_name')}")
                            if cache:
                                await cache.delete(f"user_data:{uid}")
                                await cache.delete(f"user:dashboard:{uid}")
                    except Exception as sweep_err:
                        logging.error(f"[AUTO-EXPIRE sweep] Error for {uid}: {sweep_err}")
            
            if activated_count > 0:
                logging.info(f"[AUTO-EXPIRE sweep] Activated {activated_count} stuck upcoming plans")
        except Exception as sweep_outer:
            logging.error(f"[AUTO-EXPIRE sweep] Outer error: {sweep_outer}")
    except Exception as e:
        logging.error(f"[AUTO-EXPIRE] Job error: {e}")


async def notify_upcoming_subscription_starts():
    """
    Daily cron: Send reminder notifications for users with upcoming subscription plans.
    - 3 days before activation
    - 1 day before activation
    Prevents duplicate notifications via `upcoming_notify_sent` field on payment record.
    """
    try:
        now = datetime.now(timezone.utc)
        upcomings = await db.subscription_payments.find(
            {"status": "upcoming"},
            {"_id": 0, "payment_id": 1, "user_id": 1, "plan_name": 1,
             "scheduled_start": 1, "upcoming_notify_sent": 1}
        ).to_list(1000)

        if not upcomings:
            return

        sent_count = 0
        for up in upcomings:
            uid = up.get("user_id")
            pid = up.get("payment_id")
            sched_start = up.get("scheduled_start")
            if not uid or not pid or not sched_start:
                continue

            try:
                if isinstance(sched_start, str):
                    sched_dt = datetime.fromisoformat(sched_start.replace('Z', '+00:00'))
                elif isinstance(sched_start, datetime):
                    sched_dt = sched_start
                else:
                    continue
                if sched_dt.tzinfo is None:
                    sched_dt = sched_dt.replace(tzinfo=timezone.utc)
            except Exception:
                continue

            days_until = (sched_dt - now).total_seconds() / 86400
            sent_flags = up.get("upcoming_notify_sent") or {}

            # 3-day reminder
            if 2.5 <= days_until <= 3.5 and not sent_flags.get("d3"):
                try:
                    sched_display = sched_dt.strftime("%d %b %Y")
                    notif_id = await create_notification(
                        user_id=uid,
                        title="Your new plan starts in 3 days",
                        message=f"Your queued {up.get('plan_name','Elite')} subscription will activate on {sched_display}.",
                        notification_type="subscription"
                    )
                    if notif_id:
                        await db.subscription_payments.update_one(
                            {"payment_id": pid},
                            {"$set": {"upcoming_notify_sent.d3": now.isoformat()}}
                        )
                        sent_count += 1
                except Exception as n_err:
                    logging.error(f"[UPCOMING-NOTIFY] d3 error for {uid}: {n_err}")

            # 1-day reminder
            elif 0.5 <= days_until <= 1.5 and not sent_flags.get("d1"):
                try:
                    sched_display = sched_dt.strftime("%d %b %Y")
                    notif_id = await create_notification(
                        user_id=uid,
                        title="Your new plan starts tomorrow",
                        message=f"Your queued {up.get('plan_name','Elite')} subscription will activate on {sched_display}.",
                        notification_type="subscription"
                    )
                    if notif_id:
                        await db.subscription_payments.update_one(
                            {"payment_id": pid},
                            {"$set": {"upcoming_notify_sent.d1": now.isoformat()}}
                        )
                        sent_count += 1
                except Exception as n_err:
                    logging.error(f"[UPCOMING-NOTIFY] d1 error for {uid}: {n_err}")

        if sent_count > 0:
            logging.info(f"[UPCOMING-NOTIFY] Sent {sent_count} reminder notifications")
    except Exception as e:
        logging.error(f"[UPCOMING-NOTIFY] Job error: {e}")



async def database_keep_alive_ping():
    """
    Keep MongoDB connection pool warm by sending periodic pings.
    Runs every 2 minutes to prevent cold start delays.
    
    Cold start issue: First request after idle period can take 15-60 seconds
    because MongoDB Atlas closes idle connections.
    
    This function:
    1. Pings the database to keep connections alive
    2. Performs a lightweight read to warm the connection pool
    3. Auto-reconnects if connection is lost
    4. Logs the ping status for monitoring
    """
    global _last_successful_ping, _consecutive_failures, client, db
    
    try:
        start = datetime.now(timezone.utc)
        
        # Ping MongoDB
        await db.command('ping')
        
        # Lightweight read to warm connection pool
        await db.users.find_one({}, {"_id": 1})
        
        elapsed = (datetime.now(timezone.utc) - start).total_seconds() * 1000
        
        # Reset failure counter on success
        _consecutive_failures = 0
        _last_successful_ping = datetime.now(timezone.utc).isoformat()
        
        # Only log if ping is slow (> 500ms) to reduce log noise
        if elapsed > 500:
            print(f"[DB KEEP-ALIVE] Ping completed in {elapsed:.0f}ms (slow)")
        
    except Exception as e:
        _consecutive_failures += 1
        print(f"[DB KEEP-ALIVE ERROR #{_consecutive_failures}] {e}")
        
        # If 3+ consecutive failures, try to reconnect
        if _consecutive_failures >= 3:
            print("[DB KEEP-ALIVE] Multiple failures detected, attempting reconnect...")
            try:
                # Close existing connection
                client.close()
                # Create new connection
                client = AsyncIOMotorClient(mongo_url, **connection_options)
                db = client[os.environ.get('DB_NAME', 'paras_reward_db')]
                # Test new connection
                await client.admin.command('ping')
                print("[DB KEEP-ALIVE] ✅ Reconnected successfully!")
                _consecutive_failures = 0
            except Exception as reconnect_error:
                print(f"[DB KEEP-ALIVE] ❌ Reconnect failed: {reconnect_error}")


# ========== EKO TRANSACTION STATUS UPDATE FUNCTION ==========
async def eko_update_pending_transactions():
    """
    Automatically update pending Eko DMT transaction statuses.
    Runs every 5 minutes to check status of initiated transfers.
    
    Eko Transaction Status:
    - 0: Success (Final)
    - 1: Failed (Final)
    - 2: Initiated/Response Awaited (Needs check)
    - 3: Refund Pending
    - 4: Refunded (Final)
    - 5: Hold (Needs inquiry)
    """
    try:
        from services.eko_service import EkoService, EkoStatusUpdater
        
        eko_service = EkoService(db)
        status_updater = EkoStatusUpdater(db, eko_service)
        
        # Update bank withdrawal requests
        bank_result = await status_updater.update_pending_transactions("bank_withdrawal_requests")
        
        # Update bill payment requests (for DMT type)
        bill_result = await status_updater.update_pending_transactions("bill_payment_requests")
        
        total_updated = bank_result.get("updated", 0) + bill_result.get("updated", 0)
        total_checked = bank_result.get("checked", 0) + bill_result.get("checked", 0)
        
        if total_updated > 0:
            print(f"[EKO-SYNC] ✅ Updated {total_updated}/{total_checked} transactions")
        elif total_checked > 0:
            print(f"[EKO-SYNC] Checked {total_checked} transactions - no updates needed")
            
    except ImportError:
        print("[EKO-SYNC] ⚠️ Eko service not available")
    except Exception as e:
        print(f"[EKO-SYNC] ❌ Error: {e}")

