@api_router.get("/subscription/prc-eligibility/{uid}")
async def get_prc_subscription_eligibility(uid: str):
    """Check whether a user is eligible to avail PRC subscription.
    
    UPDATED (May 2026): The lifetime 3-time PRC subscription cap has been
    REMOVED. PRC subscriptions are now unlimited — users can subscribe as
    many times as they like as long as they have:
      - sufficient PRC balance
      - 7-day cooldown elapsed since last subscription
    
    Returns: {eligible: bool, used_count: int, max_allowed: int, remaining: int, last_used_at?, last_plan?}
    NOTE: `max_allowed` and `remaining` are kept for backward-compatible response
    shape (frontend reads them) but effectively report unlimited.
    """
    try:
        COUNTING_STATUSES = ["paid", "upcoming", "active", "completed", "expired"]

        used_count = await db.subscription_payments.count_documents({
            "user_id": uid,
            "payment_method": "prc",
            "status": {"$in": COUNTING_STATUSES},
        })

        # Fetch latest prior payment for context (if any)
        prior = await db.subscription_payments.find_one(
            {
                "user_id": uid,
                "payment_method": "prc",
                "status": {"$in": COUNTING_STATUSES},
            },
            sort=[("created_at", -1)],
            projection={"_id": 0, "created_at": 1, "plan_name": 1, "plan_type": 1, "status": 1},
        )
        return {
            "eligible": True,  # Always eligible (cap removed)
            "used_count": used_count,
            "max_allowed": None,  # Unlimited
            "remaining": None,    # Unlimited
            "unlimited": True,
            "last_used_at": prior.get("created_at") if prior else None,
            "last_plan": (prior.get("plan_name") if prior else None) or ("elite" if prior else None),
            "last_plan_type": prior.get("plan_type") if prior else None,
            "last_status": prior.get("status") if prior else None,
        }
    except Exception as e:
        logging.error(f"prc-eligibility error for {uid}: {e}")
        # Fail open — don't block user if DB hiccup
        return {"eligible": True, "used_count": 0, "max_allowed": None, "remaining": None, "unlimited": True, "error": str(e)}


# ==================== NEW ELITE PRICING (Active - 29 March 2026) ====================
# Formula: (₹999 + 18% GST) × PRC Rate + ₹10 Processing + 20% Admin Charges

ELITE_BASE_PRICE = 999  # Base price in INR
GST_RATE = 0.18  # 18% GST
PROCESSING_FEE_INR = 10  # ₹10 flat processing fee
ADMIN_CHARGE_RATE = 0.20  # 20% admin charges

async def calculate_elite_prc_price(prc_rate: float = None) -> dict:
    """
    Calculate Elite subscription PRC price (April 2026 - burn removed)
    
    Formula:
    1. Base + GST = ₹999 + 18% = ₹1178.82
    2. Convert to PRC = ₹1178.82 × PRC_RATE
    3. Processing Fee = ₹10 × PRC_RATE
    4. Admin Charges = 20% of (Base PRC + Processing)
    
    Total PRC = Base PRC + Processing PRC + Admin PRC
    """
    if prc_rate is None:
        prc_rate = await get_dynamic_prc_rate()
    
    # Step 1: Base + GST
    base_inr = ELITE_BASE_PRICE
    gst_inr = base_inr * GST_RATE
    base_with_gst_inr = base_inr + gst_inr  # ₹1178.82
    
    # Step 2: Convert to PRC
    base_prc = base_with_gst_inr * prc_rate
    
    # Step 3: Processing Fee (₹10)
    processing_fee_prc = PROCESSING_FEE_INR * prc_rate
    
    # Step 4: Admin Charges (20% of base + processing)
    subtotal_prc = base_prc + processing_fee_prc
    admin_charges_prc = subtotal_prc * ADMIN_CHARGE_RATE
    
    # Total (no burn)
    total_prc = base_prc + processing_fee_prc + admin_charges_prc
    
    # Admin charges in INR (20% of base + processing fee)
    admin_charges_inr = (base_inr + PROCESSING_FEE_INR) * ADMIN_CHARGE_RATE

    return {
        "base_inr": base_inr,
        "gst_inr": round(gst_inr, 2),
        "gst_rate": GST_RATE * 100,
        "base_with_gst_inr": round(base_with_gst_inr, 2),
        "processing_fee_inr": PROCESSING_FEE_INR,
        "admin_charge_rate": ADMIN_CHARGE_RATE * 100,
        "admin_charges_inr": round(admin_charges_inr, 2),
        "prc_rate": prc_rate,
        # PRC Breakdown (what user pays)
        "base_prc": round(base_prc, 2),
        "gst_prc": round(gst_inr * prc_rate, 2),
        "processing_fee_prc": round(processing_fee_prc, 2),
        "admin_charges_prc": round(admin_charges_prc, 2),
        "burn_prc": 0,
        "burn_rate_percent": 0,
        "subtotal_before_burn_prc": round(total_prc, 2),
        "total_prc": round(total_prc, 2),
        # For Company Wallet — always stored in INR so totals match UI labels (₹).
        # Unit alignment with manual/Razorpay subscription credits which are already INR.
        "company_wallet_breakdown": {
            "gst_collection": round(gst_inr, 2),
            "processing_fees": round(PROCESSING_FEE_INR, 2),
            "admin_charges": round(admin_charges_inr, 2),
            "burn_amount": 0,
            "subscription_revenue": round(base_inr, 2)
        }
    }


async def credit_company_wallets_for_subscription(user_id: str, pricing: dict, user_name: str = "User"):
    """
    Credit company wallets with subscription fees breakdown
    Called after successful PRC subscription payment
    """
    now = datetime.now(timezone.utc)
    breakdown = pricing.get("company_wallet_breakdown", {})
    prc_rate_used = pricing.get("prc_rate")
    
    wallet_credits = [
        ("gst_collection", breakdown.get("gst_collection", 0), "GST (18%)"),
        ("processing_fees", breakdown.get("processing_fees", 0), "Processing Fee (₹10)"),
        ("admin_charges", breakdown.get("admin_charges", 0), "Admin Charges (20%)"),
        ("subscription", breakdown.get("subscription_revenue", 0), "Subscription Revenue")
    ]
    
    for wallet_type, amount, description in wallet_credits:
        if amount > 0:
            # Update wallet balance (INR)
            await db.company_wallets.update_one(
                {"wallet_type": wallet_type},
                {
                    "$inc": {"balance": amount, "total_credit": amount},
                    "$set": {"last_updated": now.isoformat()}
                },
                upsert=True
            )
            
            # Record transaction — amount is in INR (aligned with manual subs)
            await db.company_wallet_transactions.insert_one({
                "txn_id": str(uuid.uuid4()),
                "wallet_type": wallet_type,
                "type": "credit",
                "amount": amount,
                "currency": "INR",
                "prc_rate_at_txn": prc_rate_used,
                "description": f"{description} from {user_name} Elite subscription",
                "source": "prc_subscription",
                "user_id": user_id,
                "timestamp": now.isoformat()
            })
    
    logging.info(f"[COMPANY-WALLET] Credited wallets for {user_name}: GST={breakdown.get('gst_collection')}, Processing={breakdown.get('processing_fees')}, Admin={breakdown.get('admin_charges')}, Sub={breakdown.get('subscription_revenue')}")


# ==================== MANUAL/VIP SUBSCRIPTION PRICING (March 2026) ====================
# Formula: ₹999 + 18% GST = ₹1178.82 (for Manual and Razorpay payments)
# Note: PRC has additional charges (Processing + Admin) handled in calculate_elite_prc_price()

MANUAL_SUBSCRIPTION_BASE = 999  # Base price in INR
MANUAL_GST_RATE = 0.18  # 18% GST

def calculate_manual_subscription_price(base_price: float = MANUAL_SUBSCRIPTION_BASE) -> dict:
    """
    Calculate Manual/Razorpay subscription price with GST
    
    Formula: ₹999 + 18% GST = ₹1178.82
    
    Returns breakdown for display and company wallet routing
    """
    gst_amount = round(base_price * MANUAL_GST_RATE, 2)
    total_price = round(base_price + gst_amount, 2)
    
    return {
        "base_price": base_price,
        "gst_rate": MANUAL_GST_RATE * 100,
        "gst_amount": gst_amount,
        "total_price": total_price,
        "formula": f"₹{base_price} + 18% GST = ₹{total_price}",
        # For company wallet routing
        "company_wallet_breakdown": {
            "gst_collection": gst_amount,
            "subscription_revenue": base_price
        }
    }


async def get_vip_plan_pricing(plan_type: str) -> dict:
    """
    Get pricing for a specific VIP/Manual subscription plan
    All plans now use ₹999 + 18% GST formula
    """
    pricing = calculate_manual_subscription_price()
    
    # Duration mapping (28 days per month)
    duration_mapping = {
        "monthly": {"days": 28, "label": "Monthly Plan", "multiplier": 1},
        "quarterly": {"days": 84, "label": "Quarterly Plan", "multiplier": 3},
        "half_yearly": {"days": 168, "label": "Half-Yearly Plan", "multiplier": 6},
        "yearly": {"days": 336, "label": "Yearly Plan", "multiplier": 12}
    }
    
    plan_info = duration_mapping.get(plan_type, duration_mapping["monthly"])
    multiplier = plan_info["multiplier"]
    
    return {
        "plan_type": plan_type,
        "label": plan_info["label"],
        "duration_days": plan_info["days"],
        "base_price": round(pricing["base_price"] * multiplier, 2),
        "gst_rate": pricing["gst_rate"],
        "gst_amount": round(pricing["gst_amount"] * multiplier, 2),
        "total_price": round(pricing["total_price"] * multiplier, 2),
        "formula": f"₹{round(pricing['base_price'] * multiplier, 2)} + 18% GST = ₹{round(pricing['total_price'] * multiplier, 2)}"
    }


async def get_all_vip_plans() -> list:
    """
    Get all VIP/Manual subscription plans with new pricing
    Formula: ₹999 + 18% GST = ₹1178.82 per month
    """
    plans = []
    plan_types = ["monthly", "quarterly", "half_yearly", "yearly"]
    
    for plan_type in plan_types:
        plan = await get_vip_plan_pricing(plan_type)
        plans.append(plan)
    
    return plans


async def credit_company_wallets_for_manual_subscription(user_id: str, amount_paid: float, user_name: str = "User"):
    """
    Credit company wallets when a manual subscription is approved
    Splits payment into: GST Collection + Subscription Revenue
    
    Formula: Total = Base + GST
    ₹1178.82 = ₹999 (subscription_revenue) + ₹179.82 (gst_collection)
    """
    now = datetime.now(timezone.utc)
    
    # Calculate breakdown from total paid amount
    # Total = Base + 18% GST = Base × 1.18
    # Base = Total / 1.18
    base_amount = round(amount_paid / 1.18, 2)
    gst_amount = round(amount_paid - base_amount, 2)
    
    wallet_credits = [
        ("gst_collection", gst_amount, "GST (18%)"),
        ("subscription", base_amount, "Subscription Revenue")
    ]
    
    for wallet_type, amount, description in wallet_credits:
        if amount > 0:
            # Update wallet balance
            await db.company_wallets.update_one(
                {"wallet_type": wallet_type},
                {
                    "$inc": {"balance": amount, "total_credit": amount},
                    "$set": {"last_updated": now.isoformat()}
                },
                upsert=True
            )
            
            # Record transaction
            await db.company_wallet_transactions.insert_one({
                "txn_id": str(uuid.uuid4()),
                "wallet_type": wallet_type,
                "type": "credit",
                "amount": amount,
                "description": f"{description} from {user_name} Manual subscription",
                "source": "manual_subscription",
                "user_id": user_id,
                "timestamp": now.isoformat()
            })
    
    logging.info(f"[COMPANY-WALLET] Manual Sub credited for {user_name}: GST={gst_amount}, Subscription={base_amount}")
    
    return {
        "gst_credited": gst_amount,
        "subscription_credited": base_amount,
        "total": amount_paid
    }


def get_effective_plan(user: dict) -> str:
    """
    Get the effective plan for a user.
    Legacy plans (startup, growth, vip) are treated as Elite.
    """
    plan = user.get("subscription_plan", "explorer").lower()
    
    # Legacy plans → Elite
    if plan in ["startup", "growth", "vip", "pro"]:
        return "elite"
    
    # Legacy membership_type → Elite
    if user.get("membership_type") == "vip":
        return "elite"
    
    # Default to explorer if unknown
    if plan not in ["explorer", "elite"]:
        return "explorer"
    
    return plan

async def get_user_subscription_info(user: dict) -> dict:
    """Get user's current subscription status and benefits"""
    now = datetime.now(timezone.utc)
    
    # Use subscription_plan only (no legacy VIP support)
    subscription_plan = user.get("subscription_plan", "explorer")
    subscription_expiry_str = user.get("subscription_expiry")
    
    is_expired = False
    days_remaining = 0
    
    if subscription_expiry_str and subscription_plan != "explorer":
        try:
            expiry = datetime.fromisoformat(subscription_expiry_str.replace('Z', '+00:00'))
            if expiry.tzinfo is None:
                expiry = expiry.replace(tzinfo=timezone.utc)
            
            if expiry < now:
                is_expired = True
                subscription_plan = "explorer"  # Downgrade to explorer
            else:
                days_remaining = (expiry - now).days
        except:
            pass
    
    plan_config = SUBSCRIPTION_PLANS.get(subscription_plan, SUBSCRIPTION_PLANS["explorer"])
    
    return {
        "plan": subscription_plan,
        "plan_name": plan_config["name"],
        "multiplier": plan_config["multiplier"],
        "referral_weight": plan_config["referral_weight"],
        "tap_limit": plan_config["tap_limit"],
        "can_redeem": plan_config["can_redeem"],
        "is_expired": is_expired,
        "days_remaining": days_remaining,
        "start_date": user.get("subscription_start"),
        "expiry_date": subscription_expiry_str
    }

