async def check_unique_fields(field_name: str, value: str, exclude_uid: Optional[str] = None):
    """Check if field value is unique"""
    if not value:
        return True
    
    # Clean the value (remove spaces for Aadhaar/PAN)
    if field_name in ["aadhaar_number", "pan_number"]:
        value = value.replace(" ", "").strip().upper() if field_name == "pan_number" else value.replace(" ", "").strip()
    
    query = {field_name: value}
    if exclude_uid:
        query["uid"] = {"$ne": exclude_uid}
    
    existing = await db.users.find_one(query)
    return existing is None

async def check_unique_utr(utr_number: str, exclude_id: Optional[str] = None, collection_type: str = "all"):
    """
    Check if UTR number is unique across all payment collections.
    IMPORTANT: Only APPROVED/PENDING UTRs are considered "used".
    REJECTED UTRs can be reused by the user.
    
    collection_type: 'all', 'subscription', 'bill_payment', 'gift_voucher'
    """
    if not utr_number:
        return True
    
    utr_number = utr_number.strip().upper()
    
    collections_to_check = []
    
    if collection_type in ["all", "subscription"]:
        collections_to_check.extend([
            ("subscriptions", "subscription_id"),
            ("vip_subscriptions", "subscription_id"),
            ("vip_payments", "payment_id")  # Added vip_payments collection
        ])
    
    if collection_type in ["all", "bill_payment"]:
        collections_to_check.append(("bill_payment_requests", "request_id"))
    
    if collection_type in ["all", "gift_voucher"]:
        collections_to_check.append(("gift_voucher_requests", "request_id"))
    
    for coll_name, id_field in collections_to_check:
        # Only check for APPROVED or PENDING status
        # REJECTED UTRs should be allowed to be reused
        query = {
            "utr_number": utr_number,
            "status": {"$nin": ["rejected", "cancelled", "failed"]}  # Exclude rejected/cancelled/failed
        }
        if exclude_id:
            query[id_field] = {"$ne": exclude_id}
        
        existing = await db[coll_name].find_one(query)
        if existing:
            return False
    
    return True


async def get_utr_usage_info(utr_number: str):
    """Get info about where UTR is already used (only for non-rejected entries)"""
    if not utr_number:
        return None
    
    utr_number = utr_number.strip().upper()
    
    # Only return info for APPROVED or PENDING (not rejected)
    valid_statuses = {"$nin": ["rejected", "cancelled", "failed"]}
    
    # Check vip_payments first (most common)
    vip_pay = await db.vip_payments.find_one({"utr_number": utr_number, "status": valid_statuses})
    if vip_pay:
        return {"type": "Subscription Payment", "id": vip_pay.get("payment_id"), "status": vip_pay.get("status")}
    
    # Check subscriptions
    sub = await db.subscriptions.find_one({"utr_number": utr_number, "status": valid_statuses})
    if sub:
        return {"type": "Subscription", "id": sub.get("subscription_id"), "status": sub.get("status")}
    
    vip_sub = await db.vip_subscriptions.find_one({"utr_number": utr_number, "status": valid_statuses})
    if vip_sub:
        return {"type": "VIP Subscription", "id": vip_sub.get("subscription_id"), "status": vip_sub.get("status")}
    
    # Check bill payments
    bill = await db.bill_payment_requests.find_one({"utr_number": utr_number, "status": valid_statuses})
    if bill:
        return {"type": "Bill Payment", "id": bill.get("request_id"), "status": bill.get("status")}
    
    # Check gift vouchers
    gift = await db.gift_voucher_requests.find_one({"utr_number": utr_number, "status": valid_statuses})
    if gift:
        return {"type": "Gift Voucher", "id": gift.get("request_id"), "status": gift.get("status")}
    
    return None


# ==================== UTR VALIDATION API ====================

@api_router.get("/utr/validate/{utr_number}")
async def validate_utr_number(utr_number: str):
    """
    Real-time UTR validation endpoint
    - Checks if UTR is exactly 12 digits
    - Checks if UTR is already used (duplicate check)
    Returns validation result for frontend to show immediate feedback
    """
    # Clean the UTR - remove non-digits
    cleaned_utr = ''.join(filter(str.isdigit, utr_number))
    
    # Validate format: must be exactly 12 digits
    if len(cleaned_utr) != 12:
        return {
            "valid": False,
            "error": "UTR_FORMAT_INVALID",
            "message": "UTR number फक्त 12 अंकी असावा",
            "details": f"Current: {len(cleaned_utr)} digits, Required: 12 digits"
        }
    
    # Check for duplicates across all collections
    is_unique = await check_unique_utr(cleaned_utr)
    
    if not is_unique:
        # Get details about where it's used
        usage_info = await get_utr_usage_info(cleaned_utr)
        return {
            "valid": False,
            "error": "UTR_ALREADY_USED",
            "message": "UTR ALREADY IN USE",
            "message_mr": "हा UTR आधीच वापरला गेला आहे!",
            "details": usage_info
        }
    
    return {
        "valid": True,
        "cleaned": cleaned_utr,
        "message": "UTR number valid",
        "message_mr": "UTR number योग्य आहे ✓"
    }


@api_router.post("/utr/check-bulk")
async def check_bulk_utr(request: Request):
    """
    Bulk UTR check for admin - check multiple UTRs at once
    Useful for fraud detection
    """
    data = await request.json()
    utr_list = data.get("utr_numbers", [])
    
    results = []
    for utr in utr_list:
        cleaned = ''.join(filter(str.isdigit, str(utr)))
        is_unique = await check_unique_utr(cleaned) if len(cleaned) == 12 else True
        usage = await get_utr_usage_info(cleaned) if not is_unique else None
        results.append({
            "utr": utr,
            "cleaned": cleaned,
            "valid_format": len(cleaned) == 12,
            "is_unique": is_unique,
            "usage_info": usage
        })
    
    return {"results": results}


