async def check_auth_type(identifier: str):
    """Check if user should use PIN or Password login - PIN ONLY MODE (password disabled)"""
    normalized_identifier = identifier.lower().strip()
    
    # Find user - OPTIMIZED: case-insensitive email match
    # Try email match first (most common), then mobile, then uid
    user = await db.users.find_one(
        {"email": {"$regex": f"^{normalized_identifier}$", "$options": "i"}},
        {"_id": 0, "pin_migrated": 1, "email": 1, "pin": 1}
    )
    
    if not user:
        # Try mobile number
        user = await db.users.find_one(
            {"mobile": normalized_identifier},
            {"_id": 0, "pin_migrated": 1, "email": 1, "pin": 1}
        )
    
    if not user:
        # Try UID
        user = await db.users.find_one(
            {"uid": normalized_identifier},
            {"_id": 0, "pin_migrated": 1, "email": 1, "pin": 1}
        )
    
    if not user:
        # User not found - new user will use PIN
        return {"auth_type": "pin", "user_exists": False}
    
    # PASSWORD DISABLED - All users use PIN now
    # If user doesn't have a PIN set, they need to set one
    has_pin = bool(user.get("pin"))
    
    if has_pin:
        return {"auth_type": "pin", "user_exists": True}
    else:
        # User exists but no PIN - needs to set PIN (migration)
        return {
            "auth_type": "pin", 
            "user_exists": True, 
            "needs_pin_setup": True,
            "message": "Please set your 6-digit PIN to continue"
        }

async def set_new_pin(request: Request):
    """Set new PIN for existing users (migration from password to PIN)"""
    try:
        body = await request.json()
        user_id = body.get('user_id')
        new_pin = body.get('new_pin')
        
        if not user_id or not new_pin:
            raise HTTPException(status_code=400, detail="User ID and new PIN are required")
        
        # Validate PIN format
        if not new_pin.isdigit() or len(new_pin) != 6:
            raise HTTPException(status_code=400, detail="PIN must be exactly 6 digits")
        
        # Check for weak PINs
        if len(set(new_pin)) == 1:  # All same digits
            raise HTTPException(status_code=400, detail="PIN cannot be all same digits")
        
        sequential = ['012345', '123456', '234567', '345678', '456789', '567890', 
                      '987654', '876543', '765432', '654321', '543210']
        if new_pin in sequential:
            raise HTTPException(status_code=400, detail="PIN cannot be sequential numbers")
        
        # Find user
        user = await db.users.find_one({
            "$or": [
                {"uid": user_id},
                {"email": {"$regex": f"^{user_id}$", "$options": "i"}}
            ]
        })
        
        if not user:
            raise HTTPException(status_code=404, detail="User not found")
        
        # Hash and save new PIN
        hashed_pin = pwd_context.hash(new_pin)
        
        await db.users.update_one(
            {"_id": user["_id"]},
            {
                "$set": {
                    "password": hashed_pin,
                    "password_hash": hashed_pin,
                    "pin_migrated": True,
                    "pin_migrated_at": datetime.now(timezone.utc).isoformat()
                }
            }
        )
        
        return {"success": True, "message": "PIN set successfully"}
        
    except HTTPException:
        raise
    except Exception as e:
        raise HTTPException(status_code=500, detail=get_user_friendly_error(e))

async def login(
    request: Request,
    identifier: str,
    password: str,
    device_id: Optional[str] = None,
    ip_address: Optional[str] = None
):
    """User login with email/mobile and password"""
    # Get real IP address
    real_ip = get_client_ip(request) or ip_address or "unknown"
    user_agent = request.headers.get("user-agent", "unknown")
    
    # DEBUG: Log login attempt details
    logging.info(f"[LOGIN DEBUG] Attempt for: {identifier}, IP: {real_ip}")
    
    # ========== FRAUD DETECTION: IP Login Limit ==========
    ip_ok, ip_msg = await fraud_detector.check_ip_login_limit(real_ip)
    if not ip_ok:
        logging.warning(f"[LOGIN DEBUG] IP BLOCKED for {identifier}: {ip_msg}")
        raise HTTPException(status_code=429, detail=ip_msg)
    
    # Check rate limit for login attempts (Progressive lockout)
    allowed, locked_seconds, attempts_left, lockout_message = check_login_rate_limit(identifier)
    
    # DEBUG: Log rate limit status
    logging.info(f"[LOGIN DEBUG] Rate limit check for {identifier}: allowed={allowed}, locked_seconds={locked_seconds}, attempts_left={attempts_left}")
    
    if not allowed:
        logging.warning(f"[LOGIN DEBUG] USER RATE LIMITED: {identifier}, message: {lockout_message}")
        raise HTTPException(
            status_code=429, 
            detail=lockout_message
        )
    
    # ========== DATABASE-BASED LOCKOUT CHECK (Persistent) ==========
    db_allowed, db_locked_seconds, db_lockout_msg = await check_login_rate_limit_db(db, identifier)
    if not db_allowed:
        logging.warning(f"[LOGIN DEBUG] USER DB LOCKED: {identifier}, message: {db_lockout_msg}")
        raise HTTPException(status_code=429, detail=db_lockout_msg)
    
    # Normalize email to lowercase for case-insensitive matching
    normalized_identifier = identifier.lower() if '@' in identifier else identifier
    
    # Find user by email (case-insensitive), phone, mobile, or UID
    # Sequential lookup: try phone first (some users have phone instead of mobile)
    user = None
    if '@' in identifier:
        user = await db.users.find_one({"email": {"$regex": f"^{normalized_identifier}$", "$options": "i"}}, {"_id": 0})
    else:
        # Try phone first, then mobile, then uid
        user = await db.users.find_one({"phone": identifier}, {"_id": 0})
        if not user:
            user = await db.users.find_one({"mobile": identifier}, {"_id": 0})
        if not user:
            user = await db.users.find_one({"uid": identifier}, {"_id": 0})
    
    # If PIN doesn't match first found user, check alternate user with same number
    if user:
        stored_pw = user.get("pin_hash") or user.get("password_hash") or user.get("password")
        if stored_pw and not verify_password(password, stored_pw):
            # Try alternate lookup (phone vs mobile collision)
            alt_query = {"$or": [{"mobile": identifier}, {"phone": identifier}], "uid": {"$ne": user.get("uid")}}
            alt_user = await db.users.find_one(alt_query, {"_id": 0})
            if alt_user:
                alt_pw = alt_user.get("pin_hash") or alt_user.get("password_hash") or alt_user.get("password")
                if alt_pw and verify_password(password, alt_pw):
                    user = alt_user  # Switch to the correct user
    
    if not user:
        record_login_attempt(identifier, False)
        await record_login_attempt_db(db, identifier, False, real_ip)
        # Create security alert for failed login
        await create_security_alert(
            alert_type="failed_login",
            severity="low",
            title="Failed Login Attempt",
            message=f"Login attempt with non-existent user: {identifier}",
            details={"identifier": identifier, "reason": "user_not_found"},
            ip_address=real_ip,
            user_identifier=identifier
        )
        raise HTTPException(
            status_code=404, 
            detail="Account not found. This email/mobile is not registered. Please Sign Up to create a new account."
        )
    
    # Verify password - check password_hash, pin_hash (new format), and password (legacy format)
    # Priority: pin_hash > password_hash > password (legacy)
    stored_password = user.get("pin_hash") or user.get("password_hash") or user.get("password")
    if stored_password:
        if not verify_password(password, stored_password):
            record_login_attempt(identifier, False)
            await record_login_attempt_db(db, identifier, False, real_ip)
            # Create security alert for failed password
            alert_severity = "medium" if attempts_left <= 2 else "low"
            await create_security_alert(
                alert_type="failed_login",
                severity=alert_severity,
                title="Failed Password Attempt",
                message=f"Invalid password for user: {user.get('email', identifier)}. {attempts_left - 1} attempts remaining.",
                details={"identifier": identifier, "email": user.get('email'), "attempts_left": attempts_left - 1},
                ip_address=real_ip,
                user_identifier=identifier
            )
            # Create brute force alert if locked out
            if attempts_left <= 1:
                await create_security_alert(
                    alert_type="brute_force",
                    severity="critical",
                    title="🚨 Account Locked - 24 Hour Lockout",
                    message=f"Account {user.get('email', identifier)} has been locked for 24 hours due to 5 failed login attempts. Possible brute force attack.",
                    details={"identifier": identifier, "email": user.get('email'), "lockout_hours": 24, "ip": real_ip},
                    ip_address=real_ip,
                    user_identifier=identifier
                )
            elif attempts_left <= 2:
                await create_security_alert(
                    alert_type="suspicious_login",
                    severity="high",
                    title="⚠️ Account Temporarily Locked",
                    message=f"Account {user.get('email', identifier)} temporarily locked (15 min) after 4 failed attempts.",
                    details={"identifier": identifier, "email": user.get('email'), "lockout_minutes": 15},
                    ip_address=real_ip,
                    user_identifier=identifier
                )
            raise HTTPException(status_code=401, detail=f"Invalid PIN. {attempts_left - 1} attempts remaining.")
    else:
        # No password/PIN stored - reject login for security
        record_login_attempt(identifier, False)
        await record_login_attempt_db(db, identifier, False, real_ip)
        logging.warning(f"[LOGIN DEBUG] No password/PIN found for user: {identifier}")
        raise HTTPException(status_code=401, detail="Account has no PIN set. Please contact support.")
    
    if user.get("is_banned"):
        raise HTTPException(status_code=403, detail=f"Account suspended: {user.get('suspension_reason', 'Contact support')}")
    
    # Check system lockdown for admin users
    if user.get("role") in ["admin", "sub_admin"]:
        # Check IP whitelist for admin
        ip_allowed = await check_ip_whitelist(real_ip, user["uid"])
        if not ip_allowed:
            await log_admin_action(
                admin_uid=user["uid"],
                action="login_blocked_ip",
                entity_type="security",
                details={"reason": "IP not whitelisted", "ip": real_ip},
                ip_address=real_ip,
                user_agent=user_agent
            )
            # Create high severity alert for blocked IP
            await create_security_alert(
                alert_type="ip_blocked",
                severity="high",
                title="🚫 Admin Login Blocked - IP Not Whitelisted",
                message=f"Admin {user.get('email')} attempted login from non-whitelisted IP: {real_ip}",
                details={"email": user.get('email'), "ip": real_ip, "uid": user.get('uid')},
                ip_address=real_ip,
                user_identifier=user.get('email')
            )
            raise HTTPException(status_code=403, detail="Access denied. IP not whitelisted for admin access.")
    
    # Record successful login
    record_login_attempt(identifier, True)
    await record_login_attempt_db(db, identifier, True, real_ip)
    
    # Save login history for user
    login_history_entry = {
        "user_id": user["uid"],
        "login_time": datetime.now(timezone.utc).isoformat(),
        "ip_address": real_ip,
        "device_id": device_id or "unknown",
        "user_agent": user_agent[:200] if user_agent else "unknown",
        "device_info": parse_user_agent(user_agent) if user_agent else {},
        "login_type": "pin",
        "success": True
    }
    
    # Insert login history
    await db.login_history.insert_one(login_history_entry)
    
    # Update user's last login info
    await db.users.update_one(
        {"uid": user["uid"]},
        {
            "$set": {
                "last_login": datetime.now(timezone.utc).isoformat(),
                "last_login_ip": real_ip,
                "last_login_device": device_id or "unknown"
            }
        }
    )
    
    # Check subscription expiry and add renewal message
    subscription_expiry_message = None
    if is_paid_subscriber(user):
        expiry_date = get_user_expiry(user)
        if expiry_date:
            try:
                now = datetime.now(timezone.utc)
                if expiry_date < now:
                    days_expired = (now - expiry_date).days
                    subscription_expiry_message = f"⚠️ Your Elite subscription expired {days_expired} days ago! Please renew to continue using marketplace, gift vouchers, and bill payment services. PRC mined after expiry will be burned after 5 days."
                    user["subscription_expired"] = True
                    user["subscription_days_expired"] = days_expired
                    user["subscription_expiry_message"] = subscription_expiry_message
            except:
                pass
    
    # ========== SIMPLIFIED PRC CHECK using helper function ==========
    # Use is_free_user() helper - subscription_plan is the single source of truth
    user_is_free = is_free_user(user)
    user_plan = get_user_plan(user)
    
    # DEBUG LOG
    print(f"[LOGIN PRC CHECK] User: {user.get('email')}, plan: {user_plan}, is_free: {user_is_free}, prc_balance: {user.get('prc_balance', 0)}")
    
    # ========== PRC RESET DISABLED ==========
    # CRITICAL FIX: DO NOT reset PRC on login anymore
    # This was causing paid users to lose their balance due to incorrect plan detection
    # PRC expiry/burn is handled separately by scheduled tasks, NOT on login
    # 
    # OLD CODE (DISABLED):
    # if user_is_free and user.get("prc_balance", 0) > 0:
    #     print(f"[LOGIN PRC RESET] Resetting PRC for free user: {user.get('email')}")
    #     await db.users.update_one({"uid": user["uid"]}, {"$set": {"prc_balance": 0}})
    #     user["prc_balance"] = 0
    #
    # =========================================
    
    # Generate JWT tokens for admin users
    token_id = str(uuid.uuid4())
    access_token = None
    refresh_token = None
    
    # ========== SINGLE SESSION ENFORCEMENT ==========
    # Generate unique session token for this login
    session_token = str(uuid.uuid4())
    
    # Invalidate any existing sessions by updating user's session_token
    # This ensures only ONE active session per user
    await db.users.update_one(
        {"uid": user["uid"]},
        {"$set": {"session_token": session_token, "session_created_at": datetime.now(timezone.utc).isoformat()}}
    )
    
    if user.get("role") in ["admin", "sub_admin"]:
        token_data = {
            "uid": user["uid"],
            "email": user.get("email"),
            "role": user.get("role"),
            "token_id": token_id
        }
        access_token = create_access_token(token_data)
        refresh_token = create_refresh_token(token_data)
        
        # Create admin session
        session_data = {
            "session_id": str(uuid.uuid4()),
            "uid": user["uid"],
            "token_id": token_id,
            "is_active": True,
            "ip_address": real_ip,
            "user_agent": user_agent,
            "device_id": device_id,
            "created_at": datetime.now(timezone.utc).isoformat(),
            "last_activity": datetime.now(timezone.utc).isoformat(),
            "expires_at": (datetime.now(timezone.utc) + timedelta(minutes=JWT_ACCESS_TOKEN_EXPIRE_MINUTES)).isoformat()
        }
        await db.admin_sessions.insert_one(session_data)
        
        # Log admin login
        await log_admin_action(
            admin_uid=user["uid"],
            action="login",
            entity_type="auth",
            details={"device_id": device_id, "identifier": identifier},
            ip_address=real_ip,
            user_agent=user_agent
        )
    
    # Update last login and device info
    update_data = {
        "last_login": datetime.now(timezone.utc).isoformat(),
    }
    
    if device_id:
        update_data["device_id"] = device_id
    if ip_address:
        update_data["ip_address"] = ip_address
    
    await db.users.update_one(
        {"uid": user["uid"]},
        {
            "$set": update_data,
            "$inc": {"login_count": 1}
        }
    )
    
    # Log activity
    await log_activity(
        user_id=user["uid"],
        action_type="login",
        description=f"User logged in from {real_ip}",
        metadata={"device_id": device_id, "identifier": identifier},
        ip_address=real_ip
    )
    
    # Convert datetime strings
    for field in ["created_at", "updated_at", "last_login", "membership_expiry"]:
        if user.get(field) and isinstance(user[field], str):
            try:
                user[field] = datetime.fromisoformat(user[field])
            except:
                pass
    
    # Remove sensitive/large fields from response
    if "password_hash" in user:
        del user["password_hash"]
    
    # PERFORMANCE FIX: Remove profile_picture from login response
    # Profile pictures can be very large (base64 encoded images)
    # This was causing 28+ second login times in production
    # Profile picture should be fetched separately via /api/users/{uid}/profile-picture
    if "profile_picture" in user:
        del user["profile_picture"]
    
    # Build response with tokens
    response_data = User(**user).model_dump()
    
    # Add session token for single-session enforcement
    response_data["session_token"] = session_token
    
    # Check if user needs PIN migration (old password users)
    if not user.get("pin_migrated", False):
        response_data["needs_pin_migration"] = True
    
    if access_token:
        response_data["access_token"] = access_token
        response_data["refresh_token"] = refresh_token
        response_data["token_type"] = "bearer"
        response_data["expires_in"] = JWT_ACCESS_TOKEN_EXPIRE_MINUTES * 60
    
    return response_data

async def forgot_password(email: str):
    """Request password reset"""
    user = await db.users.find_one({"email": email})
    if not user:
        # Don't reveal if email exists
        return {"message": "If the email exists, a reset link has been sent"}
    
    # Generate reset token
    reset_token = generate_reset_token()
    reset_expiry = datetime.now(timezone.utc) + timedelta(hours=1)
    
    await db.users.update_one(
        {"email": email},
        {
            "$set": {
                "reset_token": reset_token,
                "reset_token_expiry": reset_expiry.isoformat()
            }
        }
    )
    
    # In production, send email here
    # For now, return token (remove in production)
    return {
        "message": "Reset token generated",
        "reset_token": reset_token  # Remove in production
    }

# ========== FORGOT PIN WITH MSG91 OTP ==========

class ForgotPinRequest(BaseModel):
    mobile: str

class VerifyOTPRequest(BaseModel):
    mobile: str
    otp: str

class ResetPinRequest(BaseModel):
    mobile: str
    new_pin: str
    reset_token: str

async def forgot_pin_check_mobile(request: ForgotPinRequest):
    """Check if mobile number exists and return widget ID for OTP"""
    mobile = request.mobile.strip()
    
    # Normalize mobile - add 91 if not present
    if not mobile.startswith("91") and not mobile.startswith("+91"):
        mobile = "91" + mobile
    mobile = mobile.replace("+", "")
    
    # Check if user exists with this mobile
    user = await db.users.find_one({
        "$or": [
            {"mobile": mobile},
            {"mobile": mobile[-10:]},  # Last 10 digits
            {"mobile_number": mobile},
            {"mobile_number": mobile[-10:]}
        ]
    })
    
    if not user:
        raise HTTPException(status_code=404, detail="Mobile number not registered")
    
    # Send OTP via MSG91 API
    auth_key = os.environ.get("MSG91_AUTH_KEY", "")
    template_id = os.environ.get("MSG91_TEMPLATE_ID", "")
    
    if not auth_key:
        raise HTTPException(status_code=500, detail="MSG91 not configured")
    
    try:
        import httpx
        async with httpx.AsyncClient() as client:
            # Send OTP using MSG91 API
            response = await client.post(
                f"https://control.msg91.com/api/v5/otp?template_id={template_id}&mobile={mobile}",
                headers={
                    "authkey": auth_key,
                    "Content-Type": "application/json"
                }
            )
            result = response.json()
            
            if result.get("type") == "error":
                raise HTTPException(status_code=400, detail=result.get("message", "Failed to send OTP"))
                
    except httpx.RequestError as e:
        raise HTTPException(status_code=500, detail="Failed to send OTP. Please try again.")
    
    return {
        "success": True,
        "message": "OTP sent successfully",
        "mobile": mobile[-4:]  # Return last 4 digits for display
    }

async def forgot_pin_verify_otp(request: VerifyOTPRequest):
    """Verify OTP and generate reset token"""
    import httpx
    
    mobile = request.mobile.strip().replace("+", "")
    if not mobile.startswith("91"):
        mobile = "91" + mobile
    
    otp = request.otp.strip()
    if not otp or len(otp) < 4:
        raise HTTPException(status_code=400, detail="Invalid OTP")
    
    auth_key = os.environ.get("MSG91_AUTH_KEY", "")
    
    if not auth_key:
        raise HTTPException(status_code=500, detail="MSG91 not configured")
    
    # Verify OTP with MSG91
    try:
        async with httpx.AsyncClient() as client:
            response = await client.get(
                f"https://control.msg91.com/api/v5/otp/verify?mobile={mobile}&otp={otp}",
                headers={"authkey": auth_key}
            )
            
            result = response.json()
            
            if result.get("type") == "error" or result.get("message") != "OTP verified successfully":
                raise HTTPException(status_code=400, detail=result.get("message", "Invalid OTP"))
            
    except httpx.RequestError as e:
        raise HTTPException(status_code=500, detail=f"MSG91 API error: {str(e)}")
    
    # Find user by mobile
    user = await db.users.find_one({
        "$or": [
            {"mobile": mobile},
            {"mobile": mobile[-10:]},
            {"mobile_number": mobile},
            {"mobile_number": mobile[-10:]}
        ]
    })
    
    if not user:
        raise HTTPException(status_code=404, detail="User not found")
    
    # Generate PIN reset token
    reset_token = secrets.token_urlsafe(32)
    reset_expiry = datetime.now(timezone.utc) + timedelta(minutes=10)
    
    await db.users.update_one(
        {"_id": user["_id"]},
        {
            "$set": {
                "pin_reset_token": reset_token,
                "pin_reset_expiry": reset_expiry.isoformat()
            }
        }
    )
    
    return {
        "success": True,
        "message": "OTP verified successfully",
        "reset_token": reset_token,
        "mobile": mobile[-4:]  # Last 4 digits for display
    }

async def forgot_pin_reset(request: ResetPinRequest):
    """Reset PIN after OTP verification"""
    mobile = request.mobile.strip().replace("+", "")
    if not mobile.startswith("91"):
        mobile = "91" + mobile
    
    new_pin = request.new_pin.strip()
    
    # Validate PIN format
    if not new_pin or len(new_pin) != 6 or not new_pin.isdigit():
        raise HTTPException(status_code=400, detail="PIN must be 6 digits")
    
    # Check for weak PINs
    if len(set(new_pin)) == 1:  # All same digits
        raise HTTPException(status_code=400, detail="PIN cannot be all same digits")
    
    sequential = ["012345", "123456", "234567", "345678", "456789", "567890", 
                  "987654", "876543", "765432", "654321", "543210"]
    if new_pin in sequential:
        raise HTTPException(status_code=400, detail="PIN cannot be sequential numbers")
    
    # Find user with valid reset token
    user = await db.users.find_one({
        "$or": [
            {"mobile": mobile},
            {"mobile": mobile[-10:]},
            {"mobile_number": mobile},
            {"mobile_number": mobile[-10:]}
        ],
        "pin_reset_token": request.reset_token
    })
    
    if not user:
        raise HTTPException(status_code=400, detail="Invalid or expired reset token")
    
    # Check token expiry
    expiry_str = user.get("pin_reset_expiry", "")
    if expiry_str:
        try:
            expiry = datetime.fromisoformat(expiry_str.replace("Z", "+00:00"))
            if datetime.now(timezone.utc) > expiry:
                raise HTTPException(status_code=400, detail="Reset token expired")
        except:
            pass
    
    # Hash new PIN and update
    hashed_pin = hash_password(new_pin)
    
    await db.users.update_one(
        {"_id": user["_id"]},
        {
            "$set": {
                "password": hashed_pin,
                "pin_migrated": True
            },
            "$unset": {
                "pin_reset_token": "",
                "pin_reset_expiry": ""
            }
        }
    )
    
    # Clear any login attempts/lockouts
    await db.login_attempts.delete_many({
        "$or": [
            {"identifier": mobile},
            {"identifier": mobile[-10:]},
            {"identifier": user.get("email", "")}
        ]
    })
    
    return {
        "success": True,
        "message": "PIN reset successfully. Please login with your new PIN."
    }


# ========== FORGOT PIN - FIELD BASED VERIFICATION ==========

@api_router.post("/auth/forgot-pin/verify-email")
async def forgot_pin_verify_email(request: Request):
    """Step 1: Verify email exists and return user info"""
    data = await request.json()
    email = data.get("email", "").strip().lower()
    
    if not email or "@" not in email:
        raise HTTPException(status_code=400, detail="Valid email required")
    
    # Find user by email
    user = await db.users.find_one({
        "email": {"$regex": f"^{email}$", "$options": "i"}
    }, {"_id": 0, "uid": 1, "name": 1, "email": 1, "mobile": 1})
    
    if not user:
        raise HTTPException(status_code=404, detail="Email not found in our records")
    
    # Generate verification token
    verify_token = secrets.token_urlsafe(32)
    
    # Store token temporarily
    await db.users.update_one(
        {"email": {"$regex": f"^{email}$", "$options": "i"}},
        {"$set": {
            "pin_reset_verify_token": verify_token,
            "pin_reset_verify_email": email,
            "pin_reset_verify_step": 1,
            "pin_reset_verify_started": datetime.now(timezone.utc).isoformat()
        }}
    )
    
    return {
        "success": True,
        "user_name": user.get("name", "User"),
        "token": verify_token
    }


@api_router.post("/auth/forgot-pin/verify-mobile")
async def forgot_pin_verify_mobile(request: Request):
    """Step 2: Verify mobile number matches"""
    data = await request.json()
    email = data.get("email", "").strip().lower()
    mobile = data.get("mobile", "").strip()
    token = data.get("token", "")
    
    if not email or not mobile or not token:
        raise HTTPException(status_code=400, detail="Email, mobile and token required")
    
    # Normalize mobile
    mobile_clean = mobile[-10:] if len(mobile) >= 10 else mobile
    
    # Find user with valid token
    user = await db.users.find_one({
        "email": {"$regex": f"^{email}$", "$options": "i"},
        "pin_reset_verify_token": token
    })
    
    if not user:
        raise HTTPException(status_code=400, detail="Invalid session. Please start again.")
    
    # Check mobile matches
    user_mobile = user.get("mobile", "") or user.get("mobile_number", "")
    user_mobile_clean = user_mobile[-10:] if len(user_mobile) >= 10 else user_mobile
    
    if user_mobile_clean != mobile_clean:
        raise HTTPException(status_code=400, detail="Mobile number does not match our records")
    
    # Update verification step
    await db.users.update_one(
        {"email": {"$regex": f"^{email}$", "$options": "i"}},
        {"$set": {
            "pin_reset_verify_step": 2,
            "pin_reset_verify_mobile": mobile_clean
        }}
    )
    
    return {
        "success": True,
        "token": token
    }


@api_router.post("/auth/forgot-pin/verify-document")
async def forgot_pin_verify_document(request: Request):
    """Step 3: Verify Aadhaar or PAN number"""
    data = await request.json()
    email = data.get("email", "").strip().lower()
    doc_type = data.get("document_type", "").strip().lower()  # aadhaar or pan
    doc_number = data.get("document_number", "").strip().upper().replace(" ", "")
    token = data.get("token", "")
    
    if not email or not doc_type or not doc_number or not token:
        raise HTTPException(status_code=400, detail="All fields required")
    
    if doc_type not in ["aadhaar", "pan"]:
        raise HTTPException(status_code=400, detail="Invalid document type")
    
    # Find user with valid token at step 2
    user = await db.users.find_one({
        "email": {"$regex": f"^{email}$", "$options": "i"},
        "pin_reset_verify_token": token,
        "pin_reset_verify_step": 2
    })
    
    if not user:
        raise HTTPException(status_code=400, detail="Invalid session. Please start again.")
    
    # Get user's KYC data
    kyc = await db.kyc_documents.find_one({"user_id": user["uid"]})
    
    if not kyc:
        # Try checking user document directly
        user_aadhaar = user.get("aadhaar", "") or user.get("aadhaar_number", "")
        user_pan = user.get("pan", "") or user.get("pan_number", "")
        
        if doc_type == "aadhaar":
            # Match last 4 digits of Aadhaar
            user_aadhaar_clean = user_aadhaar.replace(" ", "")[-4:]
            if doc_number[-4:] != user_aadhaar_clean:
                raise HTTPException(status_code=400, detail="Aadhaar number does not match our records")
        else:
            # Match PAN
            user_pan_clean = user_pan.replace(" ", "").upper()
            if doc_number != user_pan_clean and doc_number[-4:] != user_pan_clean[-4:]:
                raise HTTPException(status_code=400, detail="PAN number does not match our records")
    else:
        # Check against KYC data
        if doc_type == "aadhaar":
            kyc_aadhaar = kyc.get("aadhaar_number", "") or kyc.get("aadhaar", "")
            kyc_aadhaar_clean = kyc_aadhaar.replace(" ", "")
            # Match last 4 digits for security
            if doc_number[-4:] != kyc_aadhaar_clean[-4:]:
                raise HTTPException(status_code=400, detail="Aadhaar number does not match our KYC records")
        else:
            kyc_pan = kyc.get("pan_number", "") or kyc.get("pan", "")
            kyc_pan_clean = kyc_pan.replace(" ", "").upper()
            if doc_number != kyc_pan_clean and doc_number[-4:] != kyc_pan_clean[-4:]:
                raise HTTPException(status_code=400, detail="PAN number does not match our KYC records")
    
    # Generate reset token
    reset_token = secrets.token_urlsafe(32)
    reset_expiry = datetime.now(timezone.utc) + timedelta(minutes=15)
    
    # Security PIN is always required — every user has a default (mobile last 4 digits)
    # Even if security_pin_hash is not in DB, verify-security endpoint generates it on-the-fly
    
    # Update with reset token - always require security PIN (step 3)
    await db.users.update_one(
        {"email": {"$regex": f"^{email}$", "$options": "i"}},
        {"$set": {
            "pin_reset_verify_step": 3,
            "pin_reset_token": reset_token,
            "pin_reset_expiry": reset_expiry.isoformat(),
            "pin_reset_verify_document": doc_type
        }}
    )
    
    return {
        "success": True,
        "reset_token": reset_token,
        "has_security_pin": True
    }


# ==================== SECURITY PIN APIs ====================

@api_router.post("/auth/security-pin/change")
async def change_security_pin(request: Request):
    """Change security PIN for a user (requires current PIN or login PIN)"""
    data = await request.json()
    user_id = data.get("user_id", "").strip()
    current_pin = data.get("current_security_pin", "").strip()
    new_pin = data.get("new_security_pin", "").strip()
    login_pin = data.get("login_pin", "").strip()
    
    if not user_id:
        raise HTTPException(status_code=400, detail="User ID required")
    
    if not new_pin or len(new_pin) != 4 or not new_pin.isdigit():
        raise HTTPException(status_code=400, detail="New Security PIN must be exactly 4 digits")
    
    # Weak PIN check
    if len(set(new_pin)) == 1:
        raise HTTPException(status_code=400, detail="Security PIN cannot be all same digits")
    
    # Find user
    user = await db.users.find_one({"uid": user_id})
    if not user:
        raise HTTPException(status_code=404, detail="User not found")
    
    # Verify identity: either current security PIN or login PIN
    verified = False
    
    if current_pin:
        stored_hash = user.get("security_pin_hash")
        if stored_hash:
            if hashlib.sha256(current_pin.encode()).hexdigest() == stored_hash:
                verified = True
        else:
            # No security PIN set, accept any current_pin as first-time setup
            verified = True
    
    if not verified and login_pin:
        # Verify login PIN
        stored_password = user.get("password") or user.get("password_hash") or user.get("pin_hash")
        if stored_password and verify_password(login_pin, stored_password):
            verified = True
    
    if not verified:
        raise HTTPException(status_code=400, detail="Incorrect PIN. Please enter correct current Security PIN or Login PIN.")
    
    # Hash and save new security PIN
    new_hash = hashlib.sha256(new_pin.encode()).hexdigest()
    
    await db.users.update_one(
        {"uid": user_id},
        {"$set": {
            "security_pin_hash": new_hash,
            "security_pin_updated_at": datetime.now(timezone.utc).isoformat()
        }}
    )
    
    return {
        "success": True,
        "message": "Security PIN changed successfully"
    }

@api_router.get("/auth/security-pin/check/{user_id}")
async def check_security_pin_status(user_id: str):
    """Check if user has security PIN set (never reveals the PIN)"""
    user = await db.users.find_one({"uid": user_id})
    if not user:
        raise HTTPException(status_code=404, detail="User not found")
    
    has_pin = bool(user.get("security_pin_hash"))
    
    return {
        "has_security_pin": has_pin,
        "is_default": not bool(user.get("security_pin_updated_at"))
    }

@api_router.post("/auth/forgot-pin/verify-security")
async def forgot_pin_verify_security_pin(request: Request):
    """Step 3.5: Verify 4-digit Security PIN during PIN reset"""
    data = await request.json()
    email = data.get("email", "").strip().lower()
    security_pin = data.get("security_pin", "").strip()
    reset_token = data.get("reset_token", "")
    
    if not email or not security_pin or not reset_token:
        raise HTTPException(status_code=400, detail="All fields required")
    
    if len(security_pin) != 4 or not security_pin.isdigit():
        raise HTTPException(status_code=400, detail="Security PIN must be 4 digits")
    
    # Find user with valid reset token
    user = await db.users.find_one({
        "email": {"$regex": f"^{email}$", "$options": "i"},
        "pin_reset_token": reset_token,
        "pin_reset_verify_step": 3
    })
    
    if not user:
        raise HTTPException(status_code=400, detail="Invalid or expired reset token. Please start again.")
    
    # Check token expiry
    expiry_str = user.get("pin_reset_expiry", "")
    if expiry_str:
        try:
            expiry = datetime.fromisoformat(expiry_str.replace("Z", "+00:00"))
            if datetime.now(timezone.utc) > expiry:
                raise HTTPException(status_code=400, detail="Reset token expired. Please start again.")
        except:
            pass
    
    # Verify security PIN
    stored_hash = user.get("security_pin_hash")
    if not stored_hash:
        # Fallback: user has no security PIN set, use last 4 digits of mobile
        mobile = user.get("mobile", "") or user.get("mobile_number", "")
        mobile_digits = ''.join(filter(str.isdigit, mobile))
        if len(mobile_digits) >= 4:
            default_pin = mobile_digits[-4:]
            stored_hash = hashlib.sha256(default_pin.encode()).hexdigest()
            # Also save it for future use
            await db.users.update_one(
                {"_id": user["_id"]},
                {"$set": {"security_pin_hash": stored_hash, "security_pin_set_at": datetime.now(timezone.utc).isoformat()}}
            )
        else:
            raise HTTPException(status_code=400, detail="Security PIN not configured. Contact support.")
    
    pin_hash = hashlib.sha256(security_pin.encode()).hexdigest()
    
    if pin_hash != stored_hash:
        raise HTTPException(status_code=400, detail="Incorrect Security PIN")
    
    # Generate new reset token for final step
    new_reset_token = secrets.token_urlsafe(32)
    new_expiry = datetime.now(timezone.utc) + timedelta(minutes=15)
    
    # Update to allow PIN reset
    await db.users.update_one(
        {"email": {"$regex": f"^{email}$", "$options": "i"}},
        {"$set": {
            "pin_reset_verify_step": 4,
            "pin_reset_token": new_reset_token,
            "pin_reset_expiry": new_expiry.isoformat()
        }}
    )
    
    return {
        "success": True,
        "reset_token": new_reset_token
    }


@api_router.post("/auth/forgot-pin/set-new-pin")
async def forgot_pin_set_new_pin(request: Request):
    """Step 4: Set new PIN after all verifications (including security question if set)"""
    data = await request.json()
    email = data.get("email", "").strip().lower()
    new_pin = data.get("new_pin", "").strip()
    reset_token = data.get("reset_token", "")
    
    if not email or not new_pin or not reset_token:
        raise HTTPException(status_code=400, detail="All fields required")
    
    # Validate PIN format
    if not new_pin.isdigit() or len(new_pin) != 6:
        raise HTTPException(status_code=400, detail="PIN must be exactly 6 digits")
    
    # Check for weak PINs
    if len(set(new_pin)) == 1:
        raise HTTPException(status_code=400, detail="PIN cannot be all same digits")
    
    sequential = ["012345", "123456", "234567", "345678", "456789", "567890", 
                  "987654", "876543", "765432", "654321", "543210"]
    if new_pin in sequential:
        raise HTTPException(status_code=400, detail="PIN cannot be sequential numbers")
    
    # Find user with valid reset token (step 4 = ready for PIN reset)
    user = await db.users.find_one({
        "email": {"$regex": f"^{email}$", "$options": "i"},
        "pin_reset_token": reset_token,
        "pin_reset_verify_step": 4
    })
    
    if not user:
        raise HTTPException(status_code=400, detail="Invalid or expired reset token. Please start again.")
    
    # Check token expiry
    expiry_str = user.get("pin_reset_expiry", "")
    if expiry_str:
        try:
            expiry = datetime.fromisoformat(expiry_str.replace("Z", "+00:00"))
            if datetime.now(timezone.utc) > expiry:
                raise HTTPException(status_code=400, detail="Reset token expired. Please start again.")
        except:
            pass
    
    # Hash new PIN and update
    hashed_pin = hash_password(new_pin)
    
    await db.users.update_one(
        {"_id": user["_id"]},
        {
            "$set": {
                "password": hashed_pin,
                "password_hash": hashed_pin,  # For login compatibility
                "pin_hash": hashed_pin,  # Primary PIN field for login
                "pin_migrated": True,
                "pin_updated_at": datetime.now(timezone.utc).isoformat()
            },
            "$unset": {
                "pin_reset_token": "",
                "pin_reset_expiry": "",
                "pin_reset_verify_token": "",
                "pin_reset_verify_step": "",
                "pin_reset_verify_email": "",
                "pin_reset_verify_mobile": "",
                "pin_reset_verify_document": "",
                "pin_reset_verify_started": ""
            }
        }
    )
    
    # Clear any login attempts/lockouts
    await db.login_attempts.delete_many({
        "$or": [
            {"identifier": email},
            {"identifier": user.get("uid", "")}
        ]
    })
    
    logging.info(f"PIN reset successful for user {user.get('uid')} via field verification")
    
    return {
        "success": True,
        "message": "PIN reset successfully. Please login with your new PIN."
    }



# ========== BIOMETRIC AUTHENTICATION ROUTES ==========

async def get_biometric_register_options(user_id: str):
    """Get WebAuthn registration options for biometric setup"""
    from webauthn import generate_registration_options
    from webauthn.helpers.structs import (
        PublicKeyCredentialDescriptor,
        AuthenticatorSelectionCriteria,
        UserVerificationRequirement,
        AuthenticatorAttachment,
        ResidentKeyRequirement
    )
    
    # Get user
    user = await db.users.find_one({"uid": user_id})
    if not user:
        raise HTTPException(status_code=404, detail="User not found")
    
    # Get existing credentials to exclude
    existing_creds = await db.biometric_credentials.find({"user_id": user_id}).to_list(1000)
    exclude_credentials = [
        PublicKeyCredentialDescriptor(id=bytes.fromhex(cred["credential_raw_id"]))
        for cred in existing_creds
    ]
    
    # Generate registration options
    webauthn_rp_id = os.environ.get('WEBAUTHN_RP_ID', 'localhost')
    options = generate_registration_options(
        rp_id=webauthn_rp_id,
        rp_name="PARAS REWARD",
        user_id=user_id.encode('utf-8'),
        user_name=user.get("email", "user"),
        user_display_name=user.get("name", "User"),
        exclude_credentials=exclude_credentials,
        authenticator_selection=AuthenticatorSelectionCriteria(
            authenticator_attachment=AuthenticatorAttachment.PLATFORM,
            resident_key=ResidentKeyRequirement.PREFERRED,
            user_verification=UserVerificationRequirement.PREFERRED
        ),
        timeout=60000  # 60 seconds
    )
    
    # Store challenge in session (in production, use Redis/session store)
    await db.webauthn_challenges.insert_one({
        "user_id": user_id,
        "challenge": options.challenge.hex(),
        "created_at": datetime.now(timezone.utc).isoformat(),
        "expires_at": (datetime.now(timezone.utc) + timedelta(minutes=5)).isoformat()
    })
    
    return {
        "options": {
            "challenge": options.challenge.hex(),
            "rp": {"id": options.rp.id, "name": options.rp.name},
            "user": {
                "id": options.user.id.hex(),
                "name": options.user.name,
                "displayName": options.user.display_name
            },
            "pubKeyCredParams": [{"type": p.type, "alg": p.alg} for p in options.pub_key_cred_params],
            "timeout": options.timeout,
            "excludeCredentials": [{"id": c.id.hex(), "type": c.type} for c in options.exclude_credentials],
            "authenticatorSelection": {
                "authenticatorAttachment": options.authenticator_selection.authenticator_attachment,
                "residentKey": options.authenticator_selection.resident_key,
                "userVerification": options.authenticator_selection.user_verification
            },
            "attestation": options.attestation
        }
    }

async def register_biometric_credential(
    user_id: str,
    device_name: str,
    credential_data: Dict
):
    """Register a new biometric credential"""
    from webauthn import verify_registration_response
    from webauthn.helpers.structs import RegistrationCredential
    
    # Get user
    user = await db.users.find_one({"uid": user_id})
    if not user:
        raise HTTPException(status_code=404, detail="User not found")
    
    # Check device limit (max 5 devices)
    existing_count = await db.biometric_credentials.count_documents({"user_id": user_id})
    if existing_count >= 5:
        raise HTTPException(status_code=400, detail="Maximum 5 devices allowed. Please remove an old device first.")
    
    # Get stored challenge
    challenge_doc = await db.webauthn_challenges.find_one(
        {"user_id": user_id},
        sort=[("created_at", -1)]
    )
    
    if not challenge_doc:
        raise HTTPException(status_code=400, detail="No registration challenge found. Please restart registration.")
    
    # Check if challenge expired
    expires_at = datetime.fromisoformat(challenge_doc["expires_at"])
    if datetime.now(timezone.utc) > expires_at:
        raise HTTPException(status_code=400, detail="Registration challenge expired. Please restart registration.")
    
    try:
        # Create RegistrationCredential object
        credential = RegistrationCredential(
            id=credential_data["id"],
            raw_id=bytes.fromhex(credential_data["rawId"]),
            response={
                "client_data_json": bytes.fromhex(credential_data["response"]["clientDataJSON"]),
                "attestation_object": bytes.fromhex(credential_data["response"]["attestationObject"]),
            },
            type=credential_data["type"]
        )
        
        # Verify registration
        webauthn_origin = os.environ.get('WEBAUTHN_ORIGIN', 'http://localhost:3000')
        webauthn_rp_id = os.environ.get('WEBAUTHN_RP_ID', 'localhost')
        
        verification = verify_registration_response(
            credential=credential,
            expected_challenge=bytes.fromhex(challenge_doc["challenge"]),
            expected_origin=webauthn_origin,
            expected_rp_id=webauthn_rp_id
        )
        
        # Store credential
        biometric_cred = {
            "credential_id": str(uuid.uuid4()),
            "user_id": user_id,
            "device_name": device_name,
            "credential_public_key": verification.credential_public_key.hex(),
            "credential_raw_id": verification.credential_id.hex(),
            "counter": verification.sign_count,
            "transports": credential_data.get("transports", []),
            "created_at": datetime.now(timezone.utc).isoformat(),
            "last_used_at": None
        }
        
        await db.biometric_credentials.insert_one(biometric_cred)
        
        # Delete used challenge
        await db.webauthn_challenges.delete_one({"_id": challenge_doc["_id"]})
        
        # Log activity
        await log_activity(
            user_id=user_id,
            action_type="biometric_registered",
            description=f"Registered biometric credential on {device_name}",
            metadata={"device_name": device_name}
        )
        
        return {
            "message": "Biometric credential registered successfully",
            "credential_id": biometric_cred["credential_id"]
        }
        
    except Exception as e:
        print(f"Biometric registration error: {str(e)}")
        raise HTTPException(status_code=400, detail="Biometric registration failed. Please try again.")

async def get_biometric_login_options(email: str):
    """Get WebAuthn authentication options for biometric login"""
    from webauthn import generate_authentication_options
    from webauthn.helpers.structs import PublicKeyCredentialDescriptor
    
    # Find user by email
    user = await db.users.find_one({"email": {"$regex": f"^{email}$", "$options": "i"}})
    if not user:
        raise HTTPException(status_code=404, detail="User not found")
    
    # Get user's credentials
    credentials = await db.biometric_credentials.find({"user_id": user["uid"]}).to_list(1000)
    if not credentials:
        raise HTTPException(status_code=404, detail="No biometric credentials registered for this user")
    
    # Create credential descriptors
    allow_credentials = [
        PublicKeyCredentialDescriptor(id=bytes.fromhex(cred["credential_raw_id"]))
        for cred in credentials
    ]
    
    # Generate authentication options
    webauthn_rp_id = os.environ.get('WEBAUTHN_RP_ID', 'localhost')
    options = generate_authentication_options(
        rp_id=webauthn_rp_id,
        allow_credentials=allow_credentials,
        user_verification="preferred",
        timeout=60000
    )
    
    # Store challenge
    await db.webauthn_challenges.insert_one({
        "user_id": user["uid"],
        "challenge": options.challenge.hex(),
        "created_at": datetime.now(timezone.utc).isoformat(),
        "expires_at": (datetime.now(timezone.utc) + timedelta(minutes=5)).isoformat()
    })
    
    return {
        "options": {
            "challenge": options.challenge.hex(),
            "timeout": options.timeout,
            "rpId": options.rp_id,
            "allowCredentials": [{"id": c.id.hex(), "type": c.type} for c in options.allow_credentials],
            "userVerification": options.user_verification
        }
    }

async def biometric_login(
    email: str,
    credential_data: Dict
):
    """Authenticate user with biometric"""
    from webauthn import verify_authentication_response
    from webauthn.helpers.structs import AuthenticationCredential
    
    # Find user
    user = await db.users.find_one({"email": {"$regex": f"^{email}$", "$options": "i"}})
    if not user:
        raise HTTPException(status_code=404, detail="User not found")
    
    # Get stored challenge
    challenge_doc = await db.webauthn_challenges.find_one(
        {"user_id": user["uid"]},
        sort=[("created_at", -1)]
    )
    
    if not challenge_doc:
        raise HTTPException(status_code=400, detail="No authentication challenge found")
    
    # Get credential
    credential_raw_id = credential_data["rawId"]
    stored_credential = await db.biometric_credentials.find_one({
        "user_id": user["uid"],
        "credential_raw_id": credential_raw_id
    })
    
    if not stored_credential:
        raise HTTPException(status_code=404, detail="Credential not found")
    
    try:
        # Create AuthenticationCredential object
        credential = AuthenticationCredential(
            id=credential_data["id"],
            raw_id=bytes.fromhex(credential_data["rawId"]),
            response={
                "client_data_json": bytes.fromhex(credential_data["response"]["clientDataJSON"]),
                "authenticator_data": bytes.fromhex(credential_data["response"]["authenticatorData"]),
                "signature": bytes.fromhex(credential_data["response"]["signature"]),
                "user_handle": bytes.fromhex(credential_data["response"].get("userHandle", "")) if credential_data["response"].get("userHandle") else None
            },
            type=credential_data["type"]
        )
        
        # Verify authentication
        webauthn_origin = os.environ.get('WEBAUTHN_ORIGIN', 'http://localhost:3000')
        webauthn_rp_id = os.environ.get('WEBAUTHN_RP_ID', 'localhost')
        
        verification = verify_authentication_response(
            credential=credential,
            expected_challenge=bytes.fromhex(challenge_doc["challenge"]),
            expected_origin=webauthn_origin,
            expected_rp_id=webauthn_rp_id,
            credential_public_key=bytes.fromhex(stored_credential["credential_public_key"]),
            credential_current_sign_count=stored_credential["counter"]
        )
        
        # Update credential counter and last used
        await db.biometric_credentials.update_one(
            {"credential_id": stored_credential["credential_id"]},
            {
                "$set": {
                    "counter": verification.new_sign_count,
                    "last_used_at": datetime.now(timezone.utc).isoformat()
                }
            }
        )
        
        # Update user last login
        await db.users.update_one(
            {"uid": user["uid"]},
            {
                "$set": {"last_login": datetime.now(timezone.utc).isoformat()},
                "$inc": {"login_count": 1}
            }
        )
        
        # Delete used challenge
        await db.webauthn_challenges.delete_one({"_id": challenge_doc["_id"]})
        
        # Log activity
        await log_activity(
            user_id=user["uid"],
            action_type="biometric_login",
            description=f"Logged in with biometric on {stored_credential['device_name']}",
            metadata={"device_name": stored_credential["device_name"]}
        )
        
        # Return user data
        user.pop("password_hash", None)
        user.pop("reset_token", None)
        
        return User(**user)
        
    except Exception as e:
        print(f"Biometric authentication error: {str(e)}")
        raise HTTPException(status_code=401, detail="Biometric authentication failed")

async def get_user_biometric_credentials(user_id: str):
    """Get list of registered biometric credentials for a user"""
    credentials = await db.biometric_credentials.find({"user_id": user_id}).to_list(1000)
    
    # Remove sensitive data
    for cred in credentials:
        cred.pop("_id", None)
        cred.pop("credential_public_key", None)
    
    return {
        "credentials": credentials,
        "count": len(credentials),
        "max_devices": 5
    }

async def delete_biometric_credential(credential_id: str, user_id: str):
    """Delete a biometric credential"""
    result = await db.biometric_credentials.delete_one({
        "credential_id": credential_id,
        "user_id": user_id
    })
    
    if result.deleted_count == 0:
        raise HTTPException(status_code=404, detail="Credential not found")
    
    # Log activity
    await log_activity(
        user_id=user_id,
        action_type="biometric_removed",
        description="Removed biometric credential",
        metadata={"credential_id": credential_id}
    )
    
    return {"message": "Biometric credential deleted successfully"}

# ========== USER PROFILE ROUTES ==========


async def get_user(uid: str):
    """Get user data by UID"""
    user = await db.users.find_one({"uid": uid})
    if not user:
        raise HTTPException(status_code=404, detail="User not found")
    
    # Remove sensitive data
    user.pop("password_hash", None)
    user.pop("reset_token", None)
    user.pop("security_pin_hash", None)  # Never expose security PIN hash
    user.pop("pin_reset_token", None)
    user.pop("pin_reset_expiry", None)
    user["_id"] = str(user["_id"])
    
    return user

async def get_user_children(uid: str):
    """Get children (subordinates) of a user"""
    try:
        # Find users where parent_id or assigned_* fields match this uid
        children = await db.users.find({
            "$or": [
                {"parent_id": uid},
                {"assigned_master_stockist": uid},
                {"assigned_sub_stockist": uid}
            ]
        }).to_list(1000)
        
        # Remove sensitive data from each child
        for child in children:
            child.pop("password_hash", None)
            child.pop("reset_token", None)
            child.pop("security_pin_hash", None)  # Never expose security PIN hash
            child.pop("pin_reset_token", None)
            child.pop("pin_reset_expiry", None)
            child.pop("_id", None)
        
        return {"children": children, "count": len(children)}
    except Exception as e:
        print(f"Error fetching children: {str(e)}")
        return {"children": [], "count": 0}

async def update_profile(uid: str, request: Request):
    """Update user profile"""
    user = await db.users.find_one({"uid": uid})
    if not user:
        raise HTTPException(status_code=404, detail="User not found")
    
    data = await request.json()
    
    # Fields that can be updated - comprehensive list
    updatable_fields = [
        # Personal Info
        "first_name", "middle_name", "last_name", "name",
        "gender", "date_of_birth", "birthday", "bio",
        # Contact Info
        "mobile", "phone", "alternate_mobile", "email",
        "address", "address_line1", "address_line2",
        "state", "district", "taluka", "tahsil", "city", "village", "pincode",
        # Emergency Contact
        "emergency_contact_name", "emergency_contact_number",
        # Documents
        "aadhaar_number", "pan_number", "upi_id",
        # Profile Picture
        "profile_picture",
        # Security Options
        "two_factor_enabled", "login_notifications", "transaction_alerts",
        "biometric_enabled", "session_timeout"
    ]
    
    update_data = {}
    for field in updatable_fields:
        if field in data:
            update_data[field] = data[field]
    
    # Update name if name components changed
    if any(f in data for f in ["first_name", "middle_name", "last_name"]):
        name_parts = []
        if data.get('first_name') or user.get('first_name'):
            name_parts.append(data.get('first_name', user.get('first_name', '')))
        if data.get('middle_name') or user.get('middle_name'):
            name_parts.append(data.get('middle_name', user.get('middle_name', '')))
        if data.get('last_name') or user.get('last_name'):
            name_parts.append(data.get('last_name', user.get('last_name', '')))
        update_data['name'] = ' '.join(filter(None, name_parts))
    
    update_data['updated_at'] = datetime.now(timezone.utc).isoformat()
    
    # Check if mobile is being updated and if it's already taken by another user
    if 'mobile' in update_data and update_data['mobile']:
        existing_user = await db.users.find_one({
            "mobile": update_data['mobile'],
            "uid": {"$ne": uid}
        })
        if existing_user:
            raise HTTPException(status_code=400, detail="This mobile number is already registered with another account")
    
    try:
        await db.users.update_one(
            {"uid": uid},
            {"$set": update_data}
        )
    except Exception as e:
        if "duplicate key" in str(e).lower():
            raise HTTPException(status_code=400, detail="This mobile number is already registered with another account")
        raise HTTPException(status_code=500, detail="Profile update failed. Please try again.")
    
    # Clear user cache
    await cache.delete(f"user_data:{uid}")
    
    return {"message": "Profile updated successfully"}

async def upload_profile_picture(uid: str, file: UploadFile = File(...)):
    """Upload profile picture (stores as base64)"""
    user = await db.users.find_one({"uid": uid})
    if not user:
        raise HTTPException(status_code=404, detail="User not found")
    
    # Validate file type
    if not file.content_type.startswith("image/"):
        raise HTTPException(status_code=400, detail="File must be an image")
    
    # Read file content
    content = await file.read()
    
    # Check file size (max 5MB)
    if len(content) > 5 * 1024 * 1024:
        raise HTTPException(status_code=400, detail="Image size must be less than 5MB")
    
    # Convert to base64
    base64_image = base64.b64encode(content).decode('utf-8')
    image_data_url = f"data:{file.content_type};base64,{base64_image}"
    
    # Update user profile
    await db.users.update_one(
        {"uid": uid},
        {"$set": {
            "profile_picture": image_data_url,
            "updated_at": datetime.now(timezone.utc).isoformat()
        }}
    )
    
    return {
        "message": "Profile picture uploaded successfully",
        "profile_picture": image_data_url[:100] + "..."  # Return truncated preview
    }

async def delete_profile_picture(uid: str):
    """Delete profile picture"""
    user = await db.users.find_one({"uid": uid})
    if not user:
        raise HTTPException(status_code=404, detail="User not found")
    
    await db.users.update_one(
        {"uid": uid},
        {"$set": {
            "profile_picture": None,
            "updated_at": datetime.now(timezone.utc).isoformat()
        }}
    )
    
    return {"message": "Profile picture deleted successfully"}

async def complete_profile(uid: str, request: Request):
    """Complete user profile with all additional fields"""
    user = await db.users.find_one({"uid": uid})
    if not user:
        raise HTTPException(status_code=404, detail="User not found")
    
    data = await request.json()
    
    # Check for duplicate unique fields with detailed error messages
    unique_fields = {
        "mobile": "Mobile number",
        "aadhaar_number": "Aadhaar number", 
        "pan_number": "PAN number"
    }
    
    for field, field_label in unique_fields.items():
        if data.get(field):
            # Clean the value
            value = data[field].strip()
            if field == "pan_number":
                value = value.upper()
            if field == "aadhaar_number":
                value = value.replace(" ", "")
            
            data[field] = value  # Update with cleaned value
            
            if not await check_unique_fields(field, value, exclude_uid=uid):
                # Get info about who owns this value
                owner = await get_duplicate_field_owner(field, value)
                owner_hint = ""
                if owner:
                    masked_email = owner.get("email", "")[:3] + "***" if owner.get("email") else ""
                    owner_hint = f" (already registered with {masked_email})"
                
                raise HTTPException(
                    status_code=400,
                    detail=f"{field_label} already registered{owner_hint}. कृपया दुसरा {field_label} वापरा."
                )
    
    # Build update data
    update_data = {
        "first_name": data.get("first_name"),
        "middle_name": data.get("middle_name"),
        "last_name": data.get("last_name"),
        "mobile": data.get("mobile"),
        "gender": data.get("gender"),
        "date_of_birth": data.get("date_of_birth"),
        "address_line1": data.get("address_line1"),
        "address_line2": data.get("address_line2"),
        "city": data.get("city"),
        "state": data.get("state"),
        "district": data.get("district"),
        "tahsil": data.get("tahsil"),
        "pincode": data.get("pincode"),
        "aadhaar_number": data.get("aadhaar_number"),
        "pan_number": data.get("pan_number"),
        "upi_id": data.get("upi_id"),
        "profile_complete": True,
        "updated_at": datetime.now(timezone.utc).isoformat()
    }
    
    # Remove None values
    update_data = {k: v for k, v in update_data.items() if v is not None}
    
    # Update name
    if any(f in data for f in ["first_name", "middle_name", "last_name"]):
        name_parts = []
        if data.get('first_name'):
            name_parts.append(data['first_name'])
        if data.get('middle_name'):
            name_parts.append(data['middle_name'])
        if data.get('last_name'):
            name_parts.append(data['last_name'])
        if name_parts:
            update_data['name'] = ' '.join(name_parts)
    
    await db.users.update_one(
        {"uid": uid},
        {"$set": update_data}
    )
    
    return {"message": "Profile completed successfully", "profile_complete": True}

async def change_password(uid: str, request: Request):
    """Change user password"""
    user = await db.users.find_one({"uid": uid})
    if not user:
        raise HTTPException(status_code=404, detail="User not found")
    
    data = await request.json()
    current_password = data.get("current_password")
    new_password = data.get("new_password")
    
    if not current_password or not new_password:
        raise HTTPException(status_code=400, detail="Both passwords are required")
    
    # Verify current password
    if not user.get("password_hash"):
        raise HTTPException(status_code=400, detail="Password not set for this account")
    
    if not verify_password(current_password, user["password_hash"]):
        raise HTTPException(status_code=401, detail="Current password is incorrect")
    
    # Validate new password
    if len(new_password) < 6:
        raise HTTPException(status_code=400, detail="New password must be at least 6 characters")
    
    # Update password
    new_hash = hash_password(new_password)
    await db.users.update_one(
        {"uid": uid},
        {"$set": {
            "password_hash": new_hash,
            "updated_at": datetime.now(timezone.utc).isoformat()
        }}
    )
    
    return {"message": "Password changed successfully"}

# ========== PASSWORD RESET ROUTES ==========

async def reset_password_request(email: str):
    """Request password reset"""
    user = await db.users.find_one({"email": email})
    if not user:
        # Don't reveal if email exists
        return {"message": "If the email exists, a reset link has been sent"}
    
    # Generate reset token
    reset_token = generate_reset_token()
    reset_expiry = datetime.now(timezone.utc) + timedelta(hours=1)
    
    await db.users.update_one(
        {"email": email},
        {
            "$set": {
                "reset_token": reset_token,
                "reset_token_expiry": reset_expiry.isoformat()
            }
        }
    )
    
    # In production, send email here
    # For now, return token (remove in production)
    return {
        "message": "Password reset token generated",
        "reset_token": reset_token,
        "note": "In production, this would be sent via email"
    }

async def reset_password(reset_token: str, new_password: str):
    """Reset password using token"""
    user = await db.users.find_one({"reset_token": reset_token})
    
    if not user:
        raise HTTPException(status_code=404, detail="Invalid reset token")
    
    # Check if token expired
    if user.get("reset_token_expiry"):
        expiry = datetime.fromisoformat(user["reset_token_expiry"])
        if datetime.now(timezone.utc) > expiry:
            raise HTTPException(status_code=400, detail="Reset token expired")
    
    # Update password
    await db.users.update_one(
        {"uid": user["uid"]},
        {
            "$set": {
                "password_hash": hash_password(new_password),
                "reset_token": None,
                "reset_token_expiry": None
            }
        }
    )
    
    return {"message": "Password reset successful"}

async def change_password(uid: str, old_password: str, new_password: str):
    """Change password for logged in user"""
    user = await db.users.find_one({"uid": uid})
    
    if not user:
        raise HTTPException(status_code=404, detail="User not found")
    
    # Verify old password
    if user.get("password_hash"):
        if not verify_password(old_password, user["password_hash"]):
            raise HTTPException(status_code=401, detail="Current password is incorrect")
    
    # Update password
    await db.users.update_one(
        {"uid": uid},
        {"$set": {"password_hash": hash_password(new_password)}}
    )
    
    return {"message": "Password changed successfully"}

# ========== ACCOUNT DELETION ROUTES ==========

async def request_account_deletion(uid: str, request: Request):
    """
    Request account deletion with soft delete.
    Account will be marked for deletion and permanently deleted after 30 days.
    User can cancel within 30 days.
    """
    user = await db.users.find_one({"uid": uid})
    if not user:
        raise HTTPException(status_code=404, detail="User not found")
    
    # Check if already scheduled for deletion
    if user.get("is_deleted") or user.get("deletion_scheduled_at"):
        raise HTTPException(status_code=400, detail="Account is already scheduled for deletion")
    
    data = await request.json()
    password = data.get("password")
    reason = data.get("reason", "User requested deletion")
    
    if not password:
        raise HTTPException(status_code=400, detail="Password confirmation required")
    
    # Verify password
    if not user.get("password_hash"):
        raise HTTPException(status_code=400, detail="Password not set for this account")
    
    if not verify_password(password, user["password_hash"]):
        raise HTTPException(status_code=401, detail="Incorrect password")
    
    # Calculate deletion dates
    now = datetime.now(timezone.utc)
    hard_delete_date = now + timedelta(days=30)
    
    # Get current balances for warning
    prc_balance = user.get("prc_balance", 0)
    cashback_balance = user.get("cashback_wallet_balance", 0) or user.get("cashback_balance", 0) or 0
    
    # Soft delete - mark user as deleted
    await db.users.update_one(
        {"uid": uid},
        {"$set": {
            "is_deleted": True,
            "deleted_at": now.isoformat(),
            "deletion_scheduled_at": hard_delete_date.isoformat(),
            "deletion_reason": reason,
            "prc_balance_forfeited": prc_balance,
            "cashback_forfeited": cashback_balance,
            "prc_balance": 0,  # Forfeit PRC
            "cashback_wallet_balance": 0,  # Forfeit cashback
            "cashback_balance": 0,
            "updated_at": now.isoformat()
        }}
    )
    
    # Remove from referral hierarchy
    # Update children to have no parent
    await db.users.update_many(
        {"referred_by": uid},
        {"$set": {"referred_by": None, "referral_chain": []}}
    )
    
    # Log the deletion request
    await db.account_deletions.insert_one({
        "uid": uid,
        "email": user.get("email"),
        "name": user.get("name"),
        "requested_at": now.isoformat(),
        "hard_delete_scheduled": hard_delete_date.isoformat(),
        "reason": reason,
        "prc_forfeited": prc_balance,
        "cashback_forfeited": cashback_balance,
        "status": "pending",
        "created_at": now.isoformat()
    })
    
    return {
        "success": True,
        "message": "Account scheduled for deletion",
        "deleted_at": now.isoformat(),
        "hard_delete_date": hard_delete_date.isoformat(),
        "days_to_recover": 30,
        "prc_forfeited": prc_balance,
        "cashback_forfeited": cashback_balance,
        "warning": "Your account will be permanently deleted after 30 days. You can cancel this within 30 days by logging in."
    }

async def cancel_account_deletion(uid: str, request: Request):
    """
    Cancel account deletion request within 30-day grace period.
    Restores the account but does NOT restore forfeited PRC/cashback.
    """
    user = await db.users.find_one({"uid": uid})
    if not user:
        raise HTTPException(status_code=404, detail="User not found")
    
    if not user.get("is_deleted"):
        raise HTTPException(status_code=400, detail="Account is not scheduled for deletion")
    
    data = await request.json()
    password = data.get("password")
    
    if not password:
        raise HTTPException(status_code=400, detail="Password confirmation required")
    
    # Verify password
    if not verify_password(password, user["password_hash"]):
        raise HTTPException(status_code=401, detail="Incorrect password")
    
    # Check if still within grace period
    deletion_scheduled = user.get("deletion_scheduled_at")
    if deletion_scheduled:
        scheduled_date = datetime.fromisoformat(deletion_scheduled.replace('Z', '+00:00'))
        if datetime.now(timezone.utc) > scheduled_date:
            raise HTTPException(status_code=400, detail="Grace period expired. Account cannot be recovered.")
    
    now = datetime.now(timezone.utc)
    
    # Restore account (but not forfeited balances)
    await db.users.update_one(
        {"uid": uid},
        {"$set": {
            "is_deleted": False,
            "deleted_at": None,
            "deletion_scheduled_at": None,
            "deletion_reason": None,
            "account_recovered_at": now.isoformat(),
            "updated_at": now.isoformat()
        }}
    )
    
    # Update deletion log
    await db.account_deletions.update_one(
        {"uid": uid, "status": "pending"},
        {"$set": {
            "status": "cancelled",
            "cancelled_at": now.isoformat()
        }}
    )
    
    return {
        "success": True,
        "message": "Account deletion cancelled successfully",
        "recovered_at": now.isoformat(),
        "note": "Your account has been restored. Note: Forfeited PRC and cashback cannot be recovered."
    }

async def get_deletion_status(uid: str):
    """Get account deletion status"""
    user = await db.users.find_one({"uid": uid}, {"_id": 0})
    if not user:
        raise HTTPException(status_code=404, detail="User not found")
    
    if not user.get("is_deleted"):
        return {
            "is_scheduled_for_deletion": False,
            "message": "Account is active"
        }
    
    deletion_scheduled = user.get("deletion_scheduled_at")
    if deletion_scheduled:
        scheduled_date = datetime.fromisoformat(deletion_scheduled.replace('Z', '+00:00'))
        now = datetime.now(timezone.utc)
        days_remaining = (scheduled_date - now).days
        
        return {
            "is_scheduled_for_deletion": True,
            "deleted_at": user.get("deleted_at"),
            "hard_delete_date": deletion_scheduled,
            "days_remaining": max(0, days_remaining),
            "can_recover": days_remaining > 0,
            "prc_forfeited": user.get("prc_balance_forfeited", 0),
            "cashback_forfeited": user.get("cashback_forfeited", 0),
            "reason": user.get("deletion_reason")
        }
    
    return {
        "is_scheduled_for_deletion": True,
        "can_recover": False,
        "message": "Account is scheduled for permanent deletion"
    }

async def get_user_as_model(uid: str):
    """Get user details as Pydantic model"""
    user = await db.users.find_one({"uid": uid})
    if not user:
        raise HTTPException(status_code=404, detail="User not found")
    
    if isinstance(user.get('created_at'), str):
        user['created_at'] = datetime.fromisoformat(user['created_at'])
    if isinstance(user.get('last_login'), str):
        user['last_login'] = datetime.fromisoformat(user['last_login'])
    if user.get('membership_expiry') and isinstance(user['membership_expiry'], str):
        user['membership_expiry'] = datetime.fromisoformat(user['membership_expiry'])
    
    return User(**user)

