# ============ USER DASHBOARD COMBINED API ============

@api_router.get("/user/{uid}/dashboard")
async def get_user_dashboard_combined(uid: str, request: Request):
    """
    Combined API for User Dashboard - returns ALL data in ONE call.
    CRITICAL OPTIMIZATION: Skip slow count_documents, use cached referral_count from user doc.
    Cached for 60 seconds.
    SECURITY (Phase B, Apr 30 2026): IDOR Protection — auth REQUIRED.
    Anonymous or invalid-token requests now get 401 (was silently passing).
    """
    
    # SECURITY: Verify user authorization (strict — no silent fallback).
    auth_header = request.headers.get("Authorization", "")
    if not auth_header.startswith("Bearer "):
        raise HTTPException(status_code=401, detail="Authentication required")
    token = auth_header.replace("Bearer ", "")
    try:
        payload = jwt.decode(token, JWT_SECRET_KEY, algorithms=[JWT_ALGORITHM])
        requesting_uid = payload.get("uid")
        requesting_role = payload.get("role", "user")
        # IDOR Protection: Non-admins can only access their own dashboard
        if requesting_role not in ["admin", "sub_admin"] and requesting_uid != uid:
            raise HTTPException(
                status_code=403,
                detail="Access denied. You can only view your own dashboard."
            )
    except jwt.ExpiredSignatureError:
        raise HTTPException(status_code=401, detail="Token expired")
    except jwt.InvalidTokenError:
        raise HTTPException(status_code=401, detail="Invalid token")
    
    cache_key = f"user:dashboard:{uid}"
    
    # Try cache first
    if cache:
        cached = await cache.get(cache_key)
        if cached:
            return cached
    
    # CRITICAL: Single DB query only - get user data
    # Referral count is stored in user document (updated during signup)
    user = await db.users.find_one(
        {"uid": uid}, 
        {"_id": 0, "password": 0, "password_hash": 0, "profile_picture": 0}
    )
    
    if not user:
        raise HTTPException(status_code=404, detail="User not found")
    
    now = datetime.now(timezone.utc)
    
    # Use stored referral_count from user document (no expensive count query)
    referral_count = user.get("referral_count", 0)
    
    # recent_activity will be fetched in parallel asyncio.gather below (see "Build response")
    recent_activity = []
    
    # Check mining session validity (no DB query - from user data)
    mining_active = False
    mining_session_end = None
    remaining_hours = 0
    mined_this_session = 0
    
    if user.get("mining_start_time"):
        start_time = user["mining_start_time"]
        if isinstance(start_time, str):
            start_time = datetime.fromisoformat(start_time.replace('Z', '+00:00'))
        if start_time.tzinfo is None:
            start_time = start_time.replace(tzinfo=timezone.utc)
        
        session_end = start_time + timedelta(hours=24)
        if now < session_end:
            mining_active = True
            mining_session_end = session_end.isoformat()
            remaining_hours = (session_end - now).total_seconds() / 3600
            
            elapsed_hours = (now - start_time).total_seconds() / 3600
            base_rate = user.get("mining_rate", 0.5)
            mined_this_session = elapsed_hours * base_rate
    
    # All data from user document - no extra queries
    subscription_plan = user.get("subscription_plan", "explorer")
    subscription_expiry = user.get("subscription_expiry")
    subscription_start = (
        user.get("subscription_start_date") or 
        user.get("subscription_start") or 
        user.get("vip_activation_date") or
        user.get("vip_activated_at")
    )
    kyc_status = user.get("kyc_status", "not_submitted")
    
    # CHECK SUBSCRIPTION EXPIRY in dashboard too
    if subscription_plan and subscription_plan.lower() not in ["explorer", "free", ""]:
        expiry_val = get_user_expiry(user)
        should_downgrade = False
        
        if expiry_val:
            # CASE 1: Has expiry date - check if passed
            try:
                if isinstance(expiry_val, str):
                    expiry_dt = datetime.fromisoformat(str(expiry_val).replace('Z', '+00:00'))
                elif isinstance(expiry_val, datetime):
                    expiry_dt = expiry_val
                else:
                    expiry_dt = None
                
                if expiry_dt:
                    if expiry_dt.tzinfo is None:
                        expiry_dt = expiry_dt.replace(tzinfo=timezone.utc)
                    if now > expiry_dt:
                        should_downgrade = True
            except Exception as e:
                logging.error(f"[DASHBOARD EXPIRY] Parse error: {e}")
        else:
            # CASE 2: No expiry date - check if subscription_status is active
            if user.get("subscription_status") != "active":
                # No expiry + no active status → check payment records
                has_payment = await db.razorpay_orders.find_one(
                    {"uid": uid, "payment_status": {"$in": ["captured", "paid"]}}, {"_id": 1}
                )
                if not has_payment:
                    has_payment = await db.vip_payments.find_one(
                        {"user_id": uid, "status": "approved"}, {"_id": 1}
                    )
                if not has_payment:
                    should_downgrade = True
        
        if should_downgrade:
            logging.info(f"[DASHBOARD EXPIRY] User {uid} plan '{subscription_plan}' expired, setting to explorer")
            await db.users.update_one(
                {"uid": uid},
                {"$set": {
                    "subscription_plan": "explorer",
                    "subscription_expired": True,
                    "subscription_expired_at": now.isoformat(),
                    "subscription_status": "expired"
                }}
            )
            subscription_plan = "explorer"
            user["subscription_expired"] = True
            if cache:
                await cache.delete(f"user_data:{uid}")
                await cache.delete(f"user:dashboard:{uid}")
    
    # Build response
    # PARALLEL FETCH — run all independent lookups concurrently to minimize latency
    from utils.helpers import get_prc_rate as _get_prc_rate

    async def _fetch_prc_rate():
        try:
            val = await _get_prc_rate(db)
            return val if val else None
        except Exception as e:
            logging.warning(f"[DASHBOARD] PRC rate fetch failed: {e}")
            return None

    async def _fetch_pending_refund_count():
        try:
            cfg = await db.system_config.find_one(
                {"key": "refund_blocker_modal_enabled"},
                {"_id": 0, "value": 1}
            )
            if not (cfg and cfg.get("value")):
                return 0
            # Run all 4 count_documents in parallel (not sequentially)
            counts = await asyncio.gather(*[
                db[coll].count_documents({"user_id": uid, "status": "refund_pending"})
                for coll in ["recharge_transactions", "bill_payment_requests",
                             "dmt_transactions", "bank_transfer_requests"]
            ], return_exceptions=True)
            return sum(c for c in counts if isinstance(c, int))
        except Exception as e:
            logging.warning(f"[DASHBOARD] Pending refund check failed: {e}")
            return 0

    async def _fetch_lifetime_redeemed():
        try:
            return round(await get_user_all_time_redeemed(uid), 2)
        except Exception as e:
            logging.warning(f"[DASHBOARD] Lifetime redeemed calc failed: {e}")
            return 0

    async def _fetch_pool_wallet():
        try:
            pool_wallet = await db.pool_wallet.find_one({"wallet_id": "main"}, {"_id": 0, "balance": 1, "total_distributed": 1})
            pool_balance = round(float(pool_wallet.get("balance", 0)), 4) if pool_wallet else 0
            pool_total_dist = round(float(pool_wallet.get("total_distributed", 0)), 4) if pool_wallet else 0
            core_team_count, is_core = await asyncio.gather(
                db.core_team_members.count_documents({"status": "active"}),
                db.core_team_members.find_one({"uid": uid, "status": "active"})
            )
            return {
                "balance": pool_balance,
                "total_distributed": pool_total_dist,
                "core_team_count": core_team_count,
                "is_core_member": is_core is not None,
            }
        except Exception:
            return {"balance": 0, "total_distributed": 0, "core_team_count": 0, "is_core_member": False}

    async def _fetch_upcoming_plan():
        try:
            upcoming_count = await db.subscription_payments.count_documents({"user_id": uid, "status": "upcoming"})
            if upcoming_count > 0:
                upcoming_plan = await db.subscription_payments.find_one(
                    {"user_id": uid, "status": "upcoming"},
                    {"_id": 0, "plan_name": 1, "scheduled_start": 1, "scheduled_end": 1,
                     "duration_days": 1, "payment_method": 1, "prc_amount": 1, "created_at": 1},
                    sort=[("scheduled_start", 1)]
                )
                return upcoming_plan, upcoming_count
            return None, 0
        except Exception:
            return None, 0

    async def _fetch_recent_activity():
        try:
            return await asyncio.wait_for(
                db.transactions.find({"user_id": uid}, {"_id": 0}).sort("created_at", -1).limit(5).to_list(5),
                timeout=5.0
            )
        except asyncio.TimeoutError:
            print(f"[DASHBOARD] Activity query timed out for {uid}")
            return []
        except Exception as e:
            print(f"[DASHBOARD] Activity query failed: {e}")
            return []

    prc_rate, pending_refund_count, lifetime_redeemed, pool_wallet_info, upcoming_result, recent_activity = await asyncio.gather(
        _fetch_prc_rate(),
        _fetch_pending_refund_count(),
        _fetch_lifetime_redeemed(),
        _fetch_pool_wallet(),
        _fetch_upcoming_plan(),
        _fetch_recent_activity(),
    )
    upcoming_plan, upcoming_count = upcoming_result

    result = {
        "user": {
            "uid": uid,
            "name": user.get("name", ""),
            "email": user.get("email", ""),
            "mobile": user.get("mobile", ""),
            "prc_balance": round(user.get("prc_balance", 0), 4),
            "total_mined": round(user.get("total_mined", 0), 4),
            "total_redeemed": lifetime_redeemed,  # Pre-computed via asyncio.gather above
            "referral_count": referral_count,
            "referral_code": user.get("referral_code", ""),
            "subscription_plan": subscription_plan,
            "subscription_expiry": subscription_expiry,
            "subscription_start": subscription_start,
            "mining_rate": user.get("mining_rate", 0.5),
            "created_at": user.get("created_at"),
            "profile_image": user.get("profile_image"),
            "kyc_status": kyc_status,
            "city": user.get("city", ""),
            "district": user.get("district", ""),
            "state": user.get("state", ""),
            "role": user.get("role", "user")
        },
        "mining": {
            "active": mining_active,
            "session_end": mining_session_end,
            "remaining_hours": round(remaining_hours, 2),
            "mined_this_session": round(mined_this_session, 4),
            "session_start": user.get("mining_start_time")
        },
        "prc_rate": prc_rate,
        "recent_activity": recent_activity,
        "requires_refund_action": pending_refund_count > 0,
        "pending_refund_count": pending_refund_count,
        "cached_at": now.isoformat(),
        "pool_wallet": pool_wallet_info,  # Pre-computed via asyncio.gather
        "upcoming_plan": upcoming_plan,
        "upcoming_plans_count": upcoming_count,
    }
    
    # Cache for 60 seconds
    await cache.set(cache_key, result, ttl=60)
    
    return result


# ========== USER DATA ENDPOINT ==========
@api_router.get("/user/{uid}")
async def get_user_data(uid: str, request: Request):
    """Get user details - Comprehensive user data endpoint with caching
    SECURITY (Phase B, Apr 30 2026): IDOR Protection — auth REQUIRED.
    Anonymous or invalid-token requests now get 401 (was silently passing).
    """
    
    # SECURITY: Verify user authorization (strict — no silent fallback).
    auth_header = request.headers.get("Authorization", "")
    if not auth_header.startswith("Bearer "):
        raise HTTPException(status_code=401, detail="Authentication required")
    token = auth_header.replace("Bearer ", "")
    try:
        payload = jwt.decode(token, JWT_SECRET_KEY, algorithms=[JWT_ALGORITHM])
        requesting_uid = payload.get("uid")
        requesting_role = payload.get("role", "user")
        # IDOR Protection: Non-admins can only access their own data
        if requesting_role not in ["admin", "sub_admin"] and requesting_uid != uid:
            raise HTTPException(
                status_code=403,
                detail="Access denied. You can only view your own profile."
            )
    except jwt.ExpiredSignatureError:
        raise HTTPException(status_code=401, detail="Token expired")
    except jwt.InvalidTokenError:
        raise HTTPException(status_code=401, detail="Invalid token")
    
    # Try to get from cache first (cache for 2 minutes)
    cache_key = f"user_data:{uid}"
    cache_key = f"user_data:{uid}"
    if cache:
        cached_user = await cache.get(cache_key)
        if cached_user:
            return cached_user
    
    # PERFORMANCE FIX: Exclude profile_picture from user fetch
    # Profile pictures can be very large base64 strings causing slow responses
    # Use /api/users/{uid}/profile-picture endpoint for profile pictures
    # SECURITY: Exclude sensitive fields - security_pin_hash, reset tokens
    user = await db.users.find_one({"uid": uid}, {
        "_id": 0, 
        "password_hash": 0, 
        "profile_picture": 0,
        "security_pin_hash": 0,
        "pin_reset_token": 0,
        "pin_reset_expiry": 0,
        "reset_token": 0
    })
    if not user:
        raise HTTPException(status_code=404, detail="User not found")
    
    # Process datetime fields
    for field in ['created_at', 'last_login', 'membership_expiry', 'mining_start_time', 'mining_session_end']:
        if user.get(field) and isinstance(user[field], str):
            try:
                user[field] = datetime.fromisoformat(user[field].replace('Z', '+00:00'))
            except:
                pass
    
    # Check mining session validity
    now = datetime.now(timezone.utc)
    if user.get("mining_start_time"):
        start_time = user["mining_start_time"]
        if isinstance(start_time, str):
            start_time = datetime.fromisoformat(start_time.replace('Z', '+00:00'))
        if start_time.tzinfo is None:
            start_time = start_time.replace(tzinfo=timezone.utc)
        
        session_end = start_time + timedelta(hours=24)
        if now < session_end:
            user["mining_active"] = True
            user["mining_session_end"] = session_end.isoformat()
        else:
            user["mining_active"] = False
    
    # Reset taps_today if last_tap_date is not today (daily reset)
    today = now.strftime("%Y-%m-%d")
    last_tap_date = user.get("last_tap_date", "")
    if last_tap_date != today:
        # Return 0 taps for a new day
        user["taps_today"] = 0
    
    # AUTO-SYNC KYC STATUS: Check canonical `kyc` collection (uid field) and
    # heal stale `users.kyc_status` if a verified KYC document exists.
    # FIX (Jun 9, 2026 — Vinod 9325250224): previous code looked in the empty
    # `kyc_documents` collection with `user_id` field, so it NEVER healed
    # drift. The canonical KYC data lives in `db.kyc` keyed by `uid`.
    current_kyc_status = (user.get("kyc_status") or "").lower()
    if current_kyc_status != "verified":
        try:
            verified_kyc = await db.kyc.find_one(
                {"uid": uid, "status": {"$in": ["verified", "approved", "Verified", "VERIFIED"]}},
                {"_id": 0, "verified_at": 1},
                max_time_ms=2000
            )
            if verified_kyc:
                heal_now = datetime.now(timezone.utc).isoformat()
                await db.users.update_one(
                    {"uid": uid},
                    {"$set": {
                        "kyc_status": "verified",
                        "kyc_verified_at": verified_kyc.get("verified_at") or heal_now,
                        "kyc_auto_healed_at": heal_now,
                    }}
                )
                user["kyc_status"] = "verified"
                user["kyc_verified_at"] = verified_kyc.get("verified_at") or heal_now
                # Invalidate cache so subsequent reads aren't stale
                if cache:
                    try:
                        await cache.delete(cache_key)
                    except Exception:
                        pass
                print(f"[KYC AUTO-HEAL /user/{{uid}}] uid={uid} mirrored kyc.verified → users.kyc_status")
            else:
                user["kyc_status"] = user.get("kyc_status") or "not_submitted"
        except Exception as e:
            print(f"[KYC SYNC] Skipped due to error: {e}")
            user["kyc_status"] = user.get("kyc_status") or "not_submitted"
    
    # OPTIMIZED: Use aggregation pipeline to get all counts in parallel
    # This reduces 5 DB calls to 1 aggregation + 1 count
    
    # Get referral count (uses index) - query both uid and referral_code
    referral_code = user.get("referral_code", "")
    ref_or_conditions = [{"referred_by": uid}]
    if referral_code:
        ref_or_conditions.append({"referred_by": referral_code})
    referral_count = await db.users.count_documents({"$or": ref_or_conditions})
    user["referral_count"] = referral_count
    
    # OPTIMIZED: Calculate total_redeemed using the centralized function
    # This ensures consistency across all endpoints (dashboard, profile, admin, etc.)
    total_redeemed = await get_user_all_time_redeemed(uid)
    
    user["total_redeemed"] = round(total_redeemed, 2)
    
    # Normalize subscription_start field for frontend compatibility
    # The database may have different field names - pick the most recent/accurate one
    subscription_plan = user.get("subscription_plan", "explorer")
    subscription_expiry = user.get("subscription_expiry")
    subscription_start = (
        user.get("subscription_start_date") or 
        user.get("subscription_created_at") or 
        user.get("vip_activated_at") or
        user.get("vip_activation_date")
    )
    
    # SYNC FIX: If user has approved VIP payment but subscription_plan is not set correctly
    # This can happen if payment was approved but user data wasn't synced properly
    # PERFORMANCE: Only run this check if subscription looks incorrect AND not cached
    if (subscription_plan == "explorer" or not subscription_expiry):
        # Check for approved subscription payment from VIP or PRC
        # OPTIMIZED: Add timeout and limit to prevent slow queries
        try:
            # Check vip_payments (Razorpay/INR payments)
            latest_payment = await db.vip_payments.find_one(
                {"user_id": uid, "status": "approved"},
                sort=[("approved_at", -1)],
                max_time_ms=3000  # 3 second timeout
            )
            
            # Also check subscription_payments (PRC payments)
            if not latest_payment:
                latest_prc_payment = await db.subscription_payments.find_one(
                    {"user_id": uid, "status": {"$in": ["paid", "Paid", "PAID"]}, "payment_method": "prc"},
                    sort=[("created_at", -1)],
                    max_time_ms=3000
                )
                if latest_prc_payment:
                    latest_payment = latest_prc_payment
            
            if latest_payment:
                # Get plan and expiry from approved payment
                payment_plan = latest_payment.get("subscription_plan") or latest_payment.get("plan_name") or "elite"
                if payment_plan not in ["elite", "startup", "premium"]:
                    payment_plan = "elite"
                payment_expiry = (
                    latest_payment.get("subscription_end") or 
                    latest_payment.get("new_expiry") or 
                    latest_payment.get("subscription_expiry")
                )
                payment_start = (
                    latest_payment.get("subscription_start") or 
                    latest_payment.get("approved_at") or 
                    latest_payment.get("vip_activated_at") or
                    latest_payment.get("created_at")
                )
                
                # Check if payment expiry is still valid
                now = datetime.now(timezone.utc)
                if payment_expiry:
                    try:
                        if isinstance(payment_expiry, datetime):
                            expiry_dt = payment_expiry
                        else:
                            expiry_dt = datetime.fromisoformat(str(payment_expiry).replace('Z', '+00:00'))
                        if expiry_dt.tzinfo is None:
                            expiry_dt = expiry_dt.replace(tzinfo=timezone.utc)
                        if expiry_dt > now:
                            # Valid subscription from payment - sync to user
                            subscription_plan = payment_plan
                            subscription_expiry = payment_expiry
                            subscription_start = payment_start
                            
                            # Also update the user document for consistency
                            await db.users.update_one(
                                {"uid": uid},
                                {"$set": {
                                    "subscription_plan": payment_plan,
                                    "subscription_expiry": payment_expiry,
                                    "subscription_start": payment_start,
                                    "membership_type": "vip",
                                    "subscription_status": "active",
                                    "subscription_expired": False
                                }}
                            )
                            print(f"[SYNC] Updated user {uid} subscription from payment: {payment_plan}, expiry: {payment_expiry}")
                            # Invalidate cache
                            if cache:
                                await cache.delete(f"user_data:{uid}")
                                await cache.delete(f"user:dashboard:{uid}")
                    except Exception as e:
                        print(f"[SYNC] Error parsing payment expiry: {e}")
        except Exception as e:
            # If payment query times out, just skip sync
            print(f"[SYNC] Payment check skipped due to timeout: {e}")
    
    # Update user dict with correct values
    user["subscription_plan"] = subscription_plan
    if subscription_expiry:
        user["subscription_expiry"] = subscription_expiry
    
    # CHECK SUBSCRIPTION EXPIRY: If user has active paid plan, verify it hasn't expired
    if subscription_plan and subscription_plan.lower() not in ["explorer", "free", ""]:
        expiry_val = get_user_expiry(user)
        if expiry_val:
            try:
                if isinstance(expiry_val, str):
                    expiry_dt = datetime.fromisoformat(str(expiry_val).replace('Z', '+00:00'))
                elif isinstance(expiry_val, datetime):
                    expiry_dt = expiry_val
                else:
                    expiry_dt = None
                
                if expiry_dt:
                    # Ensure timezone-aware comparison
                    if expiry_dt.tzinfo is None:
                        expiry_dt = expiry_dt.replace(tzinfo=timezone.utc)
                    
                    now_check = datetime.now(timezone.utc)
                    if now_check > expiry_dt:
                        # Subscription expired — downgrade to explorer
                        logging.info(f"[SUBSCRIPTION EXPIRY] User {uid} plan '{subscription_plan}' expired at {expiry_val}, setting to explorer")
                        await db.users.update_one(
                            {"uid": uid},
                            {"$set": {
                                "subscription_plan": "explorer",
                                "subscription_expired": True,
                                "subscription_expired_at": now_check.isoformat()
                            }}
                        )
                        user["subscription_plan"] = "explorer"
                        user["subscription_expired"] = True
                        user["subscription_expired_at"] = now_check.isoformat()
                        subscription_plan = "explorer"
                        
                        # Check for upcoming plan to auto-activate
                        try:
                            from routes.admin_subscription import check_and_activate_upcoming
                            activation = await check_and_activate_upcoming(uid)
                            if activation:
                                # Refresh user data after activation
                                updated_user = await db.users.find_one({"uid": uid}, {"_id": 0, "password_hash": 0, "profile_picture": 0})
                                if updated_user:
                                    user["subscription_plan"] = updated_user.get("subscription_plan", "explorer")
                                    user["subscription_expiry"] = updated_user.get("subscription_expiry")
                                    user["subscription_start"] = updated_user.get("subscription_start")
                                    user["subscription_status"] = "active"
                                    subscription_plan = user["subscription_plan"]
                                    logging.info(f"[UPCOMING-SUB] Auto-activated upcoming plan for {uid}: {subscription_plan}")
                        except Exception as upcoming_err:
                            logging.error(f"[UPCOMING-SUB] Error activating upcoming: {upcoming_err}")
                        
                        # Invalidate cache
                        if cache:
                            await cache.delete(f"user_data:{uid}")
                            await cache.delete(f"user:dashboard:{uid}")
            except Exception as e:
                logging.error(f"[SUBSCRIPTION EXPIRY] Error checking expiry for {uid}: {e}")
    
    # If user has a paid subscription but no start date, use created_at as fallback
    if not subscription_start and subscription_plan in ["startup", "growth", "elite"]:
        subscription_start = user.get("created_at")
    
    if subscription_start:
        user["subscription_start"] = subscription_start
    
    # SAFETY NET: If user is on explorer with subscription_expired=True, check for upcoming plans
    if subscription_plan in ["explorer", "free", "", None] and user.get("subscription_expired"):
        try:
            from routes.admin_subscription import check_and_activate_upcoming
            activation = await check_and_activate_upcoming(uid)
            if activation:
                updated_user = await db.users.find_one({"uid": uid}, {"_id": 0, "password_hash": 0, "profile_picture": 0})
                if updated_user:
                    user["subscription_plan"] = updated_user.get("subscription_plan", "explorer")
                    user["subscription_expiry"] = updated_user.get("subscription_expiry")
                    user["subscription_start"] = updated_user.get("subscription_start")
                    user["subscription_status"] = "active"
                    user["subscription_expired"] = False
                    subscription_plan = user["subscription_plan"]
                    logging.info(f"[UPCOMING-SUB] Safety net: auto-activated upcoming plan for {uid}: {subscription_plan}")
                    if cache:
                        await cache.delete(f"user_data:{uid}")
                        await cache.delete(f"user:dashboard:{uid}")
        except Exception as upcoming_err:
            logging.error(f"[UPCOMING-SUB] Safety net error: {upcoming_err}")
    
    # Fetch upcoming plans count for user dashboard
    try:
        upcoming_count = await db.subscription_payments.count_documents({"user_id": uid, "status": "upcoming"})
        if upcoming_count > 0:
            upcoming_plan = await db.subscription_payments.find_one(
                {"user_id": uid, "status": "upcoming"},
                {"_id": 0, "plan_name": 1, "scheduled_start": 1, "scheduled_end": 1, "duration_days": 1, "payment_method": 1, "prc_amount": 1, "amount": 1, "amount_inr": 1, "created_at": 1},
                sort=[("scheduled_start", 1)]
            )
            user["upcoming_plan"] = upcoming_plan
            user["upcoming_plans_count"] = upcoming_count
    except Exception:
        pass
    
    # Cache the result for 2 minutes
    await cache.set(cache_key, user, ttl=120)
    
    return user

@api_router.get("/user/{uid}/weekly-limits")
async def get_user_weekly_limits(uid: str, request: Request):
    """
    Get user's weekly redemption limits and current usage per service type.
    Shows cooldown timer after first redemption of the week.
    SECURITY: IDOR Protection - Users can only access their own limits
    """
    # SECURITY (Jul 2026 hardened): Bearer token now REQUIRED — previously silent-bypass leaked data.
    auth_header = request.headers.get("Authorization", "")
    if not auth_header.startswith("Bearer "):
        raise HTTPException(status_code=401, detail="Authentication required.")
    token = auth_header.replace("Bearer ", "")
    try:
        payload = jwt.decode(token, JWT_SECRET_KEY, algorithms=[JWT_ALGORITHM])
        requesting_uid = payload.get("uid")
        requesting_role = payload.get("role", "user")
        if requesting_role not in ["admin", "sub_admin"] and requesting_uid != uid:
            raise HTTPException(status_code=403, detail="Access denied. You can only view your own limits.")
    except jwt.InvalidTokenError:
        raise HTTPException(status_code=401, detail="Invalid token")
    
    try:
        user = await db.users.find_one({"uid": uid})
        if not user:
            raise HTTPException(status_code=404, detail="User not found")
        
        subscription_plan = user.get("subscription_plan", "explorer").lower()
        tier_limits = WEEKLY_SERVICE_LIMITS.get(subscription_plan, WEEKLY_SERVICE_LIMITS["explorer"])
        
        # Get week bounds
        monday, sunday, next_monday = get_current_week_bounds()
        now = datetime.now(timezone.utc)
        days_until_reset = (next_monday - now).days
        hours_until_reset = int((next_monday - now).total_seconds() // 3600)
        
        # Check ONE SERVICE PER WEEK limit
        one_service_check = await check_weekly_one_service_limit(uid, "check")
        
        # Get usage for each service type
        services_status = {}
        has_any_redemption = False
        first_redemption_date = None
        
        service_types = [
            "mobile_recharge", "dish_recharge", "electricity_bill", 
            "credit_card_payment", "loan_emi", "gift_voucher", "shopping"
        ]
        
        # PERFORMANCE FIX: Fetch all service usages in parallel instead of sequential loop
        import asyncio
        usage_tasks = [get_weekly_service_usage(uid, service_type) for service_type in service_types]
        usage_results = await asyncio.gather(*usage_tasks, return_exceptions=True)
        
        for i, service_type in enumerate(service_types):
            usage = usage_results[i] if not isinstance(usage_results[i], Exception) else {"count": 0, "first_redemption_time": None}
            max_allowed = tier_limits.get(service_type, 1)
            current_count = usage["count"]
            
            if current_count > 0:
                has_any_redemption = True
                if usage["first_redemption_time"]:
                    if first_redemption_date is None or usage["first_redemption_time"] < first_redemption_date:
                        first_redemption_date = usage["first_redemption_time"]
            
            services_status[service_type] = {
                "used": current_count,
                "limit": max_allowed,
                "remaining": max(0, max_allowed - current_count),
                "available": current_count < max_allowed,
                "display_name": service_type.replace("_", " ").title()
            }
        
        # Build cooldown info only if user has made at least one redemption this week
        cooldown_info = None
        if has_any_redemption:
            cooldown_info = {
                "first_redemption_date": first_redemption_date,
                "next_reset": next_monday.isoformat(),
                "next_reset_formatted": next_monday.strftime("%A, %B %d"),
                "days_until_reset": days_until_reset,
                "hours_until_reset": hours_until_reset,
                "display_timer": f"{days_until_reset}d {hours_until_reset % 24}h until weekly reset"
            }
        
        return {
            "user_id": uid,
            "subscription_plan": subscription_plan,
            "week_start": monday.isoformat(),
            "week_end": sunday.isoformat(),
            "services": services_status,
            "cooldown_info": cooldown_info,
            "message": "Redemption limits reset every Monday at 00:00 UTC"
        }
        
    except HTTPException:
        raise
    except Exception as e:
        logging.error(f"Error getting weekly limits: {e}")
        raise HTTPException(status_code=500, detail=get_user_friendly_error(e))


@api_router.get("/user/{uid}/redemption-stats")
async def get_user_redemption_stats(uid: str, request: Request):
    """
    Comprehensive stats for user's PRC redemption and earnings.
    Shows:
    - Total PRC redeemed (orders + bill payments + gift vouchers)
    - Total money value of redemptions
    - Total PRC earned (mining, referral, tap game, etc.)
    - Cashback received
    - Orders count
    
    OPTIMIZED: Cached for 2 minutes to reduce DB load on Mining page
    SECURITY: IDOR Protection - Users can only access their own stats
    """
    # SECURITY (Jul 2026 hardened): Bearer token now REQUIRED.
    auth_header = request.headers.get("Authorization", "")
    if not auth_header.startswith("Bearer "):
        raise HTTPException(status_code=401, detail="Authentication required.")
    token = auth_header.replace("Bearer ", "")
    try:
        payload = jwt.decode(token, JWT_SECRET_KEY, algorithms=[JWT_ALGORITHM])
        requesting_uid = payload.get("uid")
        requesting_role = payload.get("role", "user")
        if requesting_role not in ["admin", "sub_admin"] and requesting_uid != uid:
            raise HTTPException(status_code=403, detail="Access denied. You can only view your own stats.")
    except jwt.InvalidTokenError:
        raise HTTPException(status_code=401, detail="Invalid token")
    
    # Try cache first (2 minute TTL)
    cache_key = f"redemption_stats:{uid}"
    cached = await cache.get(cache_key)
    if cached:
        return cached
    
    try:
        # Get user data
        user = await db.users.find_one({"uid": uid}, {"_id": 0})
        if not user:
            raise HTTPException(status_code=404, detail="User not found")
        
        # Use centralized deduped function for total_prc_redeemed (single source of truth)
        total_prc_redeemed = await get_user_all_time_redeemed(uid)
        
        # Earnings from transactions collection
        credit_types = ["mining", "tap_game", "referral", "cashback", "admin_credit", "prc_rain_gain", "profit_share"]
        earnings_pipeline = [
            {"$match": {"user_id": uid, "type": {"$in": credit_types}}},
            {"$group": {"_id": "$type", "total": {"$sum": "$amount"}}}
        ]
        
        # Orders for count/cashback info (separate from redeem total)
        orders_result, earnings_result = await asyncio.gather(
            db.orders.find(
                {"user_id": uid},
                {"_id": 0, "total_prc": 1, "prc_amount": 1, "cashback_amount": 1, "status": 1}
            ).to_list(1000),
            db.transactions.aggregate(earnings_pipeline).to_list(100),
            return_exceptions=True
        )
        
        all_orders = orders_result if not isinstance(orders_result, Exception) else []
        earnings_result = earnings_result if not isinstance(earnings_result, Exception) else []
        
        total_cashback = sum(order.get("cashback_amount", 0) for order in all_orders if order.get("status") == "delivered")
        total_orders = len(all_orders)
        delivered_orders = len([o for o in all_orders if o.get("status") == "delivered"])
        
        # ========== EARNINGS STATS ==========
        # Build earnings breakdown
        earnings_breakdown = {
            "mining": 0,
            "referral": 0,
            "tap_game": 0,
            "cashback": 0,
            "rain_game": 0,
            "other": 0
        }
        
        total_earned = 0
        for item in earnings_result:
            amount = item.get("total", 0)
            total_earned += amount
            
            if item["_id"] == "mining":
                earnings_breakdown["mining"] = round(amount, 2)
            elif item["_id"] == "referral":
                earnings_breakdown["referral"] = round(amount, 2)
            elif item["_id"] == "tap_game":
                earnings_breakdown["tap_game"] = round(amount, 2)
            elif item["_id"] in ["cashback", "admin_credit", "profit_share"]:
                earnings_breakdown["cashback"] += round(amount, 2)
            elif item["_id"] == "prc_rain_gain":
                earnings_breakdown["rain_game"] = round(amount, 2)
            else:
                earnings_breakdown["other"] += round(amount, 2)
        
        # Also include total_mined from user record if available
        if user.get("total_mined", 0) > earnings_breakdown["mining"]:
            earnings_breakdown["mining"] = round(user.get("total_mined", 0), 2)
            total_earned = sum(earnings_breakdown.values())
        
        # ========== DEDUCTIONS BREAKDOWN ==========
        # Get service charges from transactions
        service_charges_result = await db.transactions.aggregate([
            {"$match": {"user_id": uid, "type": {"$in": ["service_charge", "fee", "processing_fee"]}}},
            {"$group": {"_id": None, "total": {"$sum": {"$abs": "$amount"}}}}
        ]).to_list(1)
        service_charges = service_charges_result[0]["total"] if service_charges_result else 0
        
        # Get expired/burned PRC
        expired_result = await db.transactions.aggregate([
            {"$match": {"user_id": uid, "type": {"$in": ["expired", "prc_burn", "auto_burn", "burn"]}}},
            {"$group": {"_id": None, "total": {"$sum": {"$abs": "$amount"}}}}
        ]).to_list(1)
        expired_prc = expired_result[0]["total"] if expired_result else 0
        
        # Get luxury savings (20% auto-deducted from mining)
        luxury_savings = user.get("luxury_savings", 0)
        
        # Get PRC rain losses
        rain_losses_result = await db.transactions.aggregate([
            {"$match": {"user_id": uid, "type": "prc_rain_loss"}},
            {"$group": {"_id": None, "total": {"$sum": {"$abs": "$amount"}}}}
        ]).to_list(1)
        rain_losses = rain_losses_result[0]["total"] if rain_losses_result else 0
        
        # Get admin adjustments (credits and debits separately)
        admin_credits_result = await db.transactions.aggregate([
            {"$match": {"user_id": uid, "type": {"$in": ["admin_credit", "admin_adjustment", "bonus", "reward"]}, "amount": {"$gt": 0}}},
            {"$group": {"_id": None, "total": {"$sum": "$amount"}}}
        ]).to_list(1)
        admin_credits = admin_credits_result[0]["total"] if admin_credits_result else 0
        
        admin_debits_result = await db.transactions.aggregate([
            {"$match": {"user_id": uid, "type": {"$in": ["admin_debit", "admin_adjustment", "penalty", "correction"]}, "amount": {"$lt": 0}}},
            {"$group": {"_id": None, "total": {"$sum": {"$abs": "$amount"}}}}
        ]).to_list(1)
        admin_debits = admin_debits_result[0]["total"] if admin_debits_result else 0
        
        # Get tap game losses (if any negative tap transactions)
        tap_losses_result = await db.transactions.aggregate([
            {"$match": {"user_id": uid, "type": "tap_game", "amount": {"$lt": 0}}},
            {"$group": {"_id": None, "total": {"$sum": {"$abs": "$amount"}}}}
        ]).to_list(1)
        tap_losses = tap_losses_result[0]["total"] if tap_losses_result else 0
        
        # Calculate expected balance vs actual
        current_balance = round(user.get("prc_balance", 0), 2)
        total_deductions = total_prc_redeemed + service_charges + expired_prc + luxury_savings + rain_losses + admin_debits + tap_losses
        total_additions = total_earned + admin_credits
        expected_balance = total_additions - total_deductions
        unaccounted = round(abs(expected_balance - current_balance), 2)
        
        result = {
            "total_prc_redeemed": round(total_prc_redeemed, 2),
            "total_money_value": round(total_prc_redeemed * 0.1, 2),  # 1 PRC = ₹0.10
            "total_earned": round(total_earned, 2),
            "total_cashback": round(total_cashback, 2),
            "total_orders": total_orders,
            "delivered_orders": delivered_orders,
            "current_balance": current_balance,
            "earnings_breakdown": earnings_breakdown,
            "deductions_breakdown": {
                "redeemed": round(total_prc_redeemed, 2),
                "service_charges": round(service_charges, 2),
                "expired_burned": round(expired_prc, 2),
                "luxury_savings": round(luxury_savings, 2),
                "rain_game_losses": round(rain_losses, 2),
                "tap_game_losses": round(tap_losses, 2),
                "admin_debits": round(admin_debits, 2),
                "unaccounted": round(max(0, unaccounted), 2)
            },
            "credits_breakdown": {
                "mining": earnings_breakdown.get("mining", 0),
                "tap_game": earnings_breakdown.get("tap_game", 0),
                "rain_game": earnings_breakdown.get("rain_game", 0),
                "referral": earnings_breakdown.get("referral", 0),
                "cashback": earnings_breakdown.get("cashback", 0),
                "admin_credits": round(admin_credits, 2),
                "other": earnings_breakdown.get("other", 0)
            },
            "luxury_life": {
                "total_savings": round(luxury_savings, 2),
                "savings_inr": round(luxury_savings * 0.1, 2),
                "percent_rate": 20,
                "status": "accumulating"
            },
            "balance_equation": {
                "total_earned": round(total_earned, 2),
                "plus_admin_credits": round(admin_credits, 2),
                "minus_redeemed": round(total_prc_redeemed, 2),
                "minus_service_charges": round(service_charges, 2),
                "minus_expired_burned": round(expired_prc, 2),
                "minus_luxury_savings": round(luxury_savings, 2),
                "minus_rain_losses": round(rain_losses, 2),
                "minus_tap_losses": round(tap_losses, 2),
                "minus_admin_debits": round(admin_debits, 2),
                "equals_balance": current_balance
            }
        }
        
        # Cache for 2 minutes
        await cache.set(cache_key, result, ttl=120)
        
        return result
    except HTTPException:
        raise
    except Exception as e:
        print(f"Error getting redemption stats: {e}")
        raise HTTPException(status_code=500, detail=get_user_friendly_error(e))


