@api_router.get("/subscription/plans")
async def get_subscription_plans():
    """Get all subscription plans with pricing and special offers - CACHED 10 min"""
    # Check cache first
    cache_key = "subscription_plans"
    cached = await cache.get(cache_key)
    if cached:
        return cached
    
    pricing = await get_subscription_pricing()
    
    # ========== NEW PRICING (March 2026) ==========
    # Formula: ₹999 + 18% GST = ₹1178.82
    manual_pricing = calculate_manual_subscription_price()
    elite_total_price = manual_pricing["total_price"]  # ₹1178.82
    
    # No more special offers - standard GST pricing
    special_offers = None
    
    plans = []
    for plan_id, config in SUBSCRIPTION_PLANS.items():
        # Skip legacy/internal plans (start with underscore)
        if plan_id.startswith("_"):
            continue
            
        # Skip discontinued plans
        if config.get("discontinued"):
            continue
        
        # Only show active plans: explorer and elite
        if plan_id not in ACTIVE_SUBSCRIPTION_PLANS:
            continue
            
        if config["is_free"]:
            plans.append({
                "id": plan_id,
                "name": config["name"],
                "description": config.get("description", ""),
                "multiplier": config["multiplier"],
                "referral_weight": config["referral_weight"],
                "tap_limit": config.get("tap_limit", 100),
                "can_collect": config.get("can_collect", False),
                "can_redeem": config.get("can_redeem", False),
                "is_free": True,
                "pricing": None,
                "offer": None
            })
        else:
            # Use new pricing: ₹999 + 18% GST = ₹1178.82
            monthly_price = elite_total_price
            
            plans.append({
                "id": plan_id,
                "name": config["name"],
                "description": config.get("description", ""),
                "multiplier": config["multiplier"],
                "referral_weight": config["referral_weight"],
                "tap_limit": config.get("tap_limit", 100),
                "can_collect": config.get("can_collect", True),
                "can_redeem": config.get("can_redeem", True),
                "is_free": False,
                "pricing": {
                    "monthly": monthly_price,
                    "base_price": manual_pricing["base_price"],
                    "gst_amount": manual_pricing["gst_amount"],
                    "gst_rate": manual_pricing["gst_rate"]
                },
                "offer": special_offers,
                "pricing_formula": manual_pricing["formula"]
            })
    
    result = {
        "plans": plans, 
        "durations": SUBSCRIPTION_DURATIONS,
        "has_active_offer": False,
        "pricing_info": {
            "formula": "₹999 + 18% GST",
            "base_price": manual_pricing["base_price"],
            "gst_rate": f"{manual_pricing['gst_rate']}%",
            "gst_amount": manual_pricing["gst_amount"],
            "total_price": manual_pricing["total_price"]
        }
    }
    
    # Cache for 10 minutes (plans don't change frequently)
    await cache.set(cache_key, result, ttl=600)
    
    return result

@api_router.get("/subscription/user/{uid}")
async def get_user_subscription(uid: str, request: Request):
    """Get user's current subscription status
    SECURITY: IDOR Protection - Users can only access their own subscription
    """
    # SECURITY: Verify user authorization
    auth_header = request.headers.get("Authorization", "")
    if not auth_header.startswith("Bearer "):
        raise HTTPException(status_code=401, detail="Authentication required.")
    token = auth_header.replace("Bearer ", "")
    try:
        payload = jwt.decode(token, JWT_SECRET_KEY, algorithms=[JWT_ALGORITHM])
        requesting_uid = payload.get("uid")
        requesting_role = payload.get("role", "user")
        if requesting_role not in ["admin", "sub_admin"] and requesting_uid != uid:
            raise HTTPException(status_code=403, detail="Access denied. You can only view your own subscription.")
    except jwt.InvalidTokenError:
        raise HTTPException(status_code=401, detail="Invalid token")
    
    user = await db.users.find_one({"uid": uid}, {"_id": 0})
    if not user:
        raise HTTPException(status_code=404, detail="User not found")
    
    sub_info = await get_user_subscription_info(user)
    
    return {
        "user_id": uid,
        "subscription": sub_info,
        "benefits": {
            "mining_multiplier": f"{sub_info['multiplier']}x",
            "referral_weight": f"{sub_info['referral_weight']}x",
            "daily_tap_limit": sub_info["tap_limit"],
            "can_redeem": sub_info["can_redeem"]
        }
    }


@api_router.get("/subscription/history/{uid}")
async def get_user_subscription_history(uid: str, request: Request):
    """Get user's complete subscription history including expired ones.
    SECURITY (Jul 2026 hardened): Bearer token now REQUIRED. Previously the
    JWT check silently no-op'd when no Authorization header was present,
    which meant anonymous callers could scrape any UID's subscription
    payment history (financial PII).
    """
    auth_header = request.headers.get("Authorization", "")
    if not auth_header.startswith("Bearer "):
        raise HTTPException(status_code=401, detail="Authentication required.")
    token = auth_header.replace("Bearer ", "")
    try:
        payload = jwt.decode(token, JWT_SECRET_KEY, algorithms=[JWT_ALGORITHM])
        requesting_uid = payload.get("uid")
        requesting_role = payload.get("role", "user")
        if requesting_role not in ["admin", "sub_admin"] and requesting_uid != uid:
            raise HTTPException(status_code=403, detail="Access denied. You can only view your own history.")
    except jwt.InvalidTokenError:
        raise HTTPException(status_code=401, detail="Invalid token")
    
    user = await db.users.find_one({"uid": uid}, {"_id": 0, "name": 1, "subscription_plan": 1, "subscription_start": 1, "subscription_expiry": 1})
    if not user:
        raise HTTPException(status_code=404, detail="User not found")
    
    # Get Razorpay payments (ALL statuses to show history)
    razorpay_payments = await db.razorpay_orders.find(
        {"user_id": uid}
    ).sort("created_at", -1).to_list(100)
    
    # Get VIP payments (manual payments with screenshot) - query both uid and user_id
    vip_payments_uid = await db.vip_payments.find(
        {"uid": uid}
    ).sort("created_at", -1).to_list(100)
    vip_payments_user_id = await db.vip_payments.find(
        {"user_id": uid}
    ).sort("created_at", -1).to_list(100)
    
    # Deduplicate vip payments
    seen_vip_ids = set()
    vip_payments = []
    for vp in vip_payments_uid + vip_payments_user_id:
        vp_id = str(vp.get("_id", ""))
        if vp_id not in seen_vip_ids:
            seen_vip_ids.add(vp_id)
            vip_payments.append(vp)
    
    # Get manual subscription payments (legacy)
    manual_payments = await db.subscription_payments.find(
        {"user_id": uid}
    ).sort("created_at", -1).to_list(100)
    
    history = []
    
    # Process Razorpay payments (ALL statuses)
    for payment in razorpay_payments:
        paid_at = payment.get("paid_at")
        if paid_at and isinstance(paid_at, str):
            try:
                paid_at = datetime.fromisoformat(paid_at.replace('Z', '+00:00'))
            except:
                paid_at = None
        
        created_at = payment.get("created_at")
        status = payment.get("status", "created")
        
        history.append({
            "id": payment.get("order_id"),
            "type": "razorpay",
            "plan_name": payment.get("plan_name", "").title(),
            "plan_type": payment.get("plan_type", "monthly"),
            "amount": payment.get("amount", 0),
            "prc_amount": payment.get("prc_amount", 0),
            "inr_equivalent": payment.get("inr_equivalent", 0),
            "status": "completed" if status == "paid" else status,
            "payment_method": "Online (Razorpay)",
            "payment_id": payment.get("payment_id"),
            "activated_at": paid_at.isoformat() if paid_at else None,
            "created_at": str(created_at) if created_at else None,
            "instant_activation": True,
            "duration_days": payment.get("duration_days"),
            "remaining_days_added": payment.get("remaining_days_added", 0)
        })
    
    # Process VIP payments (manual with screenshot)
    for payment in vip_payments:
        created_at = payment.get("created_at")
        approved_at = payment.get("approved_at")
        
        history.append({
            "id": str(payment.get("_id", "")),
            "type": "vip_payment",
            "plan_name": payment.get("plan", "").title(),
            "plan_type": payment.get("plan_type", "monthly"),
            "amount": payment.get("amount", 0),
            "prc_amount": payment.get("prc_amount", 0),
            "inr_equivalent": payment.get("inr_equivalent", 0),
            "status": payment.get("status", "pending"),
            "payment_method": "UPI/Bank Transfer",
            "utr_number": payment.get("utr_number"),
            "created_at": str(created_at) if created_at else None,
            "activated_at": str(approved_at) if approved_at and payment.get("status") == "approved" else None,
            "instant_activation": False,
            "duration_days": payment.get("duration_days")
        })
    
    # Process legacy manual payments
    for payment in manual_payments:
        created_at = payment.get("created_at")
        approved_at = payment.get("approved_at") or payment.get("verified_at")
        
        history.append({
            "id": str(payment.get("_id", "")),
            "type": "manual",
            "plan_name": payment.get("plan_name", payment.get("plan", "")).title(),
            "plan_type": payment.get("plan_type", payment.get("duration", "monthly")),
            "amount": payment.get("amount", 0),
            "prc_amount": payment.get("prc_amount", 0),
            "inr_equivalent": payment.get("inr_equivalent", 0),
            "status": payment.get("status", "pending"),
            "payment_method": "UPI/Bank Transfer" if not payment.get("payment_method") else payment.get("payment_method"),
            "utr_number": payment.get("utr_number"),
            "created_at": str(created_at) if created_at else None,
            "activated_at": str(approved_at) if approved_at and payment.get("status") == "approved" else None,
            "instant_activation": False
        })
    
    # Sort by created_at descending
    history.sort(key=lambda x: x.get("created_at") or "", reverse=True)
    
    # Build plan_periods from ALL successful payments in history
    plan_periods = []
    now = datetime.now(timezone.utc)
    duration_map = {"monthly": 28, "quarterly": 84, "half_yearly": 168, "yearly": 365}
    
    sub_plan = user.get("subscription_plan", "explorer")

    # Determine if user currently has an active subscription
    current_expiry_dt = get_user_expiry(user)
    if not (sub_plan and sub_plan != "explorer"):
        current_expiry_dt = None
    
    successful = [h for h in history if h.get("status") in ("completed", "approved", "paid")]
    
    for i, payment in enumerate(successful):
        created = payment.get("activated_at") or payment.get("created_at")
        if not created:
            continue
        try:
            start_dt = datetime.fromisoformat(str(created).replace('Z', '+00:00'))
            if start_dt.tzinfo is None:
                start_dt = start_dt.replace(tzinfo=timezone.utc)
            
            duration_days = payment.get("duration_days") or duration_map.get(payment.get("plan_type", "monthly"), 28)
            end_dt = start_dt + timedelta(days=duration_days)
            
            # For the most recent payment, use user's actual expiry if available
            is_most_recent = (i == 0)
            if is_most_recent and current_expiry_dt:
                end_dt = current_expiry_dt
            
            # Only the MOST RECENT payment can be "ongoing"
            # All older payments are "expired" (superseded by newer plan)
            is_ongoing = is_most_recent and end_dt > now and current_expiry_dt is not None
            days_remaining = max(0, (end_dt - now).days) if is_ongoing else 0
            
            # Calculate amount: prefer INR amount, fallback to PRC/10 or inr_equivalent
            pay_amount = float(payment.get("amount", 0) or 0)
            if pay_amount == 0:
                prc_amt = float(payment.get("prc_amount", 0) or 0)
                inr_eq = float(payment.get("inr_equivalent", 0) or 0)
                pay_amount = inr_eq if inr_eq > 0 else (prc_amt / 10 if prc_amt > 0 else 0)
            
            plan_periods.append({
                "plan_name": (payment.get("plan_name") or sub_plan or "Elite").title(),
                "status": "ongoing" if is_ongoing else "expired",
                "start_date": start_dt.isoformat(),
                "expiry_date": end_dt.isoformat(),
                "days_remaining": days_remaining,
                "amount": pay_amount,
                "payment_method": payment.get("payment_method", ""),
                "is_current": is_most_recent and is_ongoing
            })
        except Exception:
            continue
    
    # If no successful payments but user has active plan (admin-activated), add from user doc
    if not plan_periods and sub_plan and sub_plan != "explorer" and current_expiry_dt:
        sub_start = user.get("subscription_start")
        plan_periods.append({
            "plan_name": sub_plan.title(),
            "status": "ongoing" if current_expiry_dt > now else "expired",
            "start_date": str(sub_start) if sub_start else None,
            "expiry_date": current_expiry_dt.isoformat() if current_expiry_dt else None,
            "days_remaining": max(0, (current_expiry_dt - now).days) if current_expiry_dt > now else 0,
            "amount": 0,
            "payment_method": "Admin Activated",
            "is_current": True
        })
    
    # Sort: ongoing first, then by start_date descending
    def sort_key(x):
        status_order = 0 if x.get("status") == "ongoing" else 1
        try:
            ts = datetime.fromisoformat(str(x.get("start_date", "2000-01-01")).replace('Z', '+00:00')).timestamp()
        except Exception:
            ts = 0
        return (status_order, -ts)
    plan_periods.sort(key=sort_key)
    
    return {
        "user_id": uid,
        "user_name": user.get("name"),
        "current_plan": user.get("subscription_plan", "explorer"),
        "total_payments": len(history),
        "history": history,
        "plan_periods": plan_periods
    }


@api_router.get("/admin/razorpay-subscriptions")
async def get_admin_razorpay_subscriptions(
    status: str = None,
    search: str = None,
    limit: int = 100,
    skip: int = 0
):
    """Get all Razorpay subscription payments for admin dashboard with enhanced search"""
    
    query = {}
    if status:
        query["status"] = status
    
    # If search is provided, search across multiple fields
    matching_user_ids = []
    if search:
        search_term = search.strip()
        
        # Search in users collection
        user_query = {"$or": [
            {"name": {"$regex": search_term, "$options": "i"}},
            {"email": {"$regex": search_term, "$options": "i"}},
            {"mobile": {"$regex": search_term, "$options": "i"}},
            {"uid": search_term}
        ]}
        matching_users = await db.users.find(user_query, {"uid": 1}).to_list(100)
        matching_user_ids = [u["uid"] for u in matching_users]
        
        # Build comprehensive search query for razorpay_orders
        order_search_conditions = [
            {"order_id": {"$regex": search_term, "$options": "i"}},
            {"payment_id": {"$regex": search_term, "$options": "i"}},
            {"user_id": {"$regex": search_term, "$options": "i"}},
            # Search by user details stored in order
            {"user_name": {"$regex": search_term, "$options": "i"}},
            {"user_email": {"$regex": search_term, "$options": "i"}},
            {"user_mobile": {"$regex": search_term, "$options": "i"}},
            # Search by payment method details
            {"payment_vpa": {"$regex": search_term, "$options": "i"}},  # UPI ID
            {"payment_bank": {"$regex": search_term, "$options": "i"}},
            {"payment_wallet": {"$regex": search_term, "$options": "i"}},
            # Search by UTR in acquirer_data
            {"acquirer_data.rrn": {"$regex": search_term, "$options": "i"}},  # UTR/RRN
            {"acquirer_data.utr": {"$regex": search_term, "$options": "i"}},
            {"acquirer_data.bank_transaction_id": {"$regex": search_term, "$options": "i"}},
            # Search by amount (if numeric)
        ]
        
        # If search term is numeric, also search by amount
        try:
            search_amount = float(search_term)
            order_search_conditions.append({"amount": search_amount})
        except ValueError:
            pass
        
        # Add matching user IDs to search
        if matching_user_ids:
            order_search_conditions.append({"user_id": {"$in": matching_user_ids}})
        
        query["$or"] = order_search_conditions
    
    orders = await db.razorpay_orders.find(query).sort("created_at", -1).skip(skip).limit(limit).to_list(limit)
    total = await db.razorpay_orders.count_documents(query)
    
    # FIXED N+1: Batch fetch all users at once instead of one query per order
    user_ids = list(set([order.get("user_id") for order in orders if order.get("user_id")]))
    users_map = {}
    if user_ids:
        users_list = await db.users.find(
            {"uid": {"$in": user_ids}}, 
            {"_id": 0, "uid": 1, "name": 1, "email": 1, "mobile": 1, "subscription_plan": 1, "subscription_expiry": 1}
        ).to_list(len(user_ids))
        users_map = {u["uid"]: u for u in users_list}
    
    result = []
    for order in orders:
        user_id = order.get("user_id")
        user = users_map.get(user_id, {})
        
        # Get user's current subscription status
        current_plan = user.get("subscription_plan") if user else None
        current_expiry = get_user_expiry(user) if user else None
        
        # Extract UTR/RRN from acquirer_data
        acquirer_data = order.get("acquirer_data", {})
        utr_number = acquirer_data.get("rrn") or acquirer_data.get("utr") or acquirer_data.get("bank_transaction_id")
        
        result.append({
            "order_id": order.get("order_id"),
            "user_id": user_id,
            "user_name": order.get("user_name") or (user.get("name") if user else "Unknown"),
            "user_email": order.get("user_email") or (user.get("email") if user else None),
            "user_mobile": order.get("user_mobile") or (user.get("mobile") if user else None),
            "plan_name": order.get("plan_name", "").title(),
            "plan_type": order.get("plan_type", "monthly"),
            "amount": order.get("amount", 0),
            "status": order.get("status", "created"),
            "payment_id": order.get("payment_id"),
            "failure_reason": order.get("failure_reason"),
            "error_code": order.get("error_code"),
            "created_at": order.get("created_at"),
            "paid_at": order.get("paid_at"),
            "razorpay_payment_time": order.get("razorpay_payment_time"),  # Actual Razorpay timestamp
            "verified_at": order.get("verified_at"),
            "status_updated_at": order.get("status_updated_at"),
            # Payment method details
            "payment_method": order.get("payment_method"),
            "payment_bank": order.get("payment_bank"),
            "payment_wallet": order.get("payment_wallet"),
            "payment_vpa": order.get("payment_vpa"),  # UPI ID
            "utr_number": utr_number,  # UTR/RRN for bank transfers
            # User's current subscription info
            "user_current_plan": current_plan,
            "user_subscription_expiry": str(current_expiry) if current_expiry else None
        })
    
    # Stats
    paid_count = await db.razorpay_orders.count_documents({"status": "paid"})
    failed_count = await db.razorpay_orders.count_documents({"status": {"$in": ["failed", "error", "cancelled"]}})
    pending_count = await db.razorpay_orders.count_documents({"status": "created"})
    
    paid_orders = await db.razorpay_orders.find({"status": "paid"}).to_list(1000)
    total_revenue = sum(o.get("amount", 0) for o in paid_orders)
    
    return {
        "orders": result,
        "total": total,
        "stats": {
            "total_orders": await db.razorpay_orders.count_documents({}),
            "paid_orders": paid_count,
            "failed_orders": failed_count,
            "pending_orders": pending_count,
            "total_revenue": total_revenue
        }
    }


@api_router.post("/admin/razorpay-cleanup-fraudulent")
async def cleanup_fraudulent_razorpay_subscriptions(request: Request):
    """
    SMART CLEANUP: Reset only fraudulent Razorpay subscriptions.
    - SKIPS users who have legitimate manual/UPI approved payments
    - ONLY resets users whose subscription came from fraudulent Razorpay
    """
    try:
        data = await request.json()
        admin_pin = data.get("admin_pin")
        
        # Security check - require admin PIN
        if admin_pin != ADMIN_OPERATION_PIN:
            raise HTTPException(status_code=403, detail="Invalid admin PIN")
        
        # Find all "paid" Razorpay orders
        paid_orders = await db.razorpay_orders.find({"status": "paid"}).to_list(1000)
        
        if not paid_orders:
            return {
                "success": True,
                "message": "No paid orders found to cleanup",
                "reset_count": 0,
                "skipped_count": 0
            }
        
        reset_users = []
        skipped_users = []
        
        for order in paid_orders:
            user_id = order.get("user_id")
            razorpay_payment_id = order.get("payment_id")
            
            # Get user details
            user = await db.users.find_one(
                {"uid": user_id}, 
                {"_id": 0, "name": 1, "email": 1, "subscription_plan": 1, "last_payment_id": 1}
            )
            
            if not user:
                continue
            
            # Check if user has legitimate manual payment
            legitimate_payment = await db.vip_payments.find_one({
                "uid": user_id,
                "status": "approved"
            }, sort=[("approved_at", -1)])
            
            if legitimate_payment:
                # SKIP this user - they have legitimate subscription
                skipped_users.append({
                    "user_id": user_id,
                    "name": user.get("name"),
                    "reason": "Has legitimate manual payment",
                    "legitimate_plan": legitimate_payment.get("plan")
                })
                
                # Still mark the Razorpay order as fraudulent
                await db.razorpay_orders.update_one(
                    {"order_id": order.get("order_id")},
                    {"$set": {
                        "status": "fraudulent",
                        "reason": "Payment failed but user has legitimate subscription elsewhere"
                    }}
                )
                continue
            
            # Reset this user - no legitimate payment found
            await db.users.update_one(
                {"uid": user_id},
                {
                    "$set": {
                        "subscription_plan": "explorer",
                        "membership_type": "free",
                        "subscription_status": "inactive",
                        "fraudulent_activation_reverted": True,
                        "reverted_at": datetime.now(timezone.utc).isoformat()
                    },
                    "$unset": {
                        "subscription_start": "",
                        "subscription_expiry": "",
                        "last_payment_id": "",
                        "last_payment_date": ""
                    }
                }
            )
            
            reset_users.append({
                "user_id": user_id,
                "name": user.get("name"),
                "email": user.get("email"),
                "previous_plan": user.get("subscription_plan"),
                "payment_id": razorpay_payment_id
            })
            
            # Mark order as fraudulent
            await db.razorpay_orders.update_one(
                {"order_id": order.get("order_id")},
                {
                    "$set": {
                        "status": "fraudulent",
                        "original_status": "paid",
                        "marked_fraudulent_at": datetime.now(timezone.utc).isoformat(),
                        "reason": "Payment failed - user reset to free"
                    }
                }
            )
        
        # Log the cleanup action
        await db.admin_audit_logs.insert_one({
            "action": "razorpay_fraud_cleanup",
            "reset_count": len(reset_users),
            "skipped_count": len(skipped_users),
            "reset_users": reset_users,
            "skipped_users": skipped_users,
            "performed_at": datetime.now(timezone.utc).isoformat()
        })
        
        return {
            "success": True,
            "message": f"Cleanup complete! Reset {len(reset_users)} users, Skipped {len(skipped_users)} legitimate users",
            "reset_count": len(reset_users),
            "skipped_count": len(skipped_users),
            "reset_users": reset_users,
            "skipped_users": skipped_users
        }
        
    except HTTPException:
        raise
    except Exception as e:
        logging.error(f"Fraud cleanup error: {e}")
        raise HTTPException(status_code=500, detail=get_user_friendly_error(e))


@api_router.post("/admin/razorpay-delete-pending")
async def delete_pending_razorpay_orders(request: Request):
    """
    Delete all pending (status='created') Razorpay orders.
    These are orders where user started payment but never completed.
    """
    try:
        data = await request.json()
        admin_pin = data.get("admin_pin")
        
        if admin_pin != ADMIN_OPERATION_PIN:
            raise HTTPException(status_code=403, detail="Invalid admin PIN")
        
        # Count pending orders
        pending_count = await db.razorpay_orders.count_documents({"status": "created"})
        
        if pending_count == 0:
            return {
                "success": True,
                "message": "No pending orders to delete",
                "deleted_count": 0
            }
        
        # Delete all pending orders
        result = await db.razorpay_orders.delete_many({"status": "created"})
        
        # Log the action
        await db.admin_audit_logs.insert_one({
            "action": "razorpay_delete_pending",
            "deleted_count": result.deleted_count,
            "performed_at": datetime.now(timezone.utc).isoformat()
        })
        
        return {
            "success": True,
            "message": f"Deleted {result.deleted_count} pending orders",
            "deleted_count": result.deleted_count
        }
        
    except HTTPException:
        raise
    except Exception as e:
        logging.error(f"Delete pending error: {e}")
        raise HTTPException(status_code=500, detail=get_user_friendly_error(e))


@api_router.post("/admin/razorpay/sync-pending")
async def manual_sync_razorpay_payments():
    """
    Manually trigger sync of pending Razorpay payments.
    Checks Razorpay API and activates subscriptions for captured payments.
    """
    try:
        import razorpay
        
        RAZORPAY_KEY_ID = os.environ.get("RAZORPAY_KEY_ID")
        RAZORPAY_KEY_SECRET = os.environ.get("RAZORPAY_KEY_SECRET")
        
        print(f"[SYNC] Starting manual sync. Razorpay configured: {bool(RAZORPAY_KEY_ID and RAZORPAY_KEY_SECRET)}")
        
        if not RAZORPAY_KEY_ID or not RAZORPAY_KEY_SECRET:
            return {"success": False, "error": "Razorpay not configured"}
        
        razorpay_client = razorpay.Client(auth=(RAZORPAY_KEY_ID, RAZORPAY_KEY_SECRET))
        
        # Plan durations (28 days per month)
        PLAN_DURATIONS = {
            "monthly": 28,
            "quarterly": 84,
            "half_yearly": 168,
            "yearly": 336
        }
        
        # Get all pending orders - include more statuses
        pending_orders = await db.razorpay_orders.find({
            "status": {"$in": ["created", "pending", "attempted"]}
        }).to_list(200)  # Increased limit
        
        print(f"[SYNC] Found {len(pending_orders)} pending orders to sync")
        
        if not pending_orders:
            return {"success": True, "message": "No pending orders to sync", "synced": 0, "total_pending": 0}
        
        synced_count = 0
        errors = []
        results = []
        
        for order in pending_orders:
            order_id = order.get("order_id")
            user_id = order.get("user_id")
            
            try:
                # FIXED: Use asyncio.to_thread() to prevent blocking the event loop
                razorpay_order = await asyncio.to_thread(razorpay_client.order.fetch, order_id)
                razorpay_status = razorpay_order.get("status")
                
                if razorpay_status == "paid":
                    # Order is paid - fetch payment details
                    # FIXED: Use asyncio.to_thread() for async-safe call
                    payments = await asyncio.to_thread(razorpay_client.order.payments, order_id)
                    
                    # Find captured payment
                    captured_payment = None
                    for payment in payments.get("items", []):
                        if payment.get("status") == "captured":
                            captured_payment = payment
                            break
                    
                    if captured_payment:
                        payment_id = captured_payment.get("id")
                        amount = captured_payment.get("amount", 0) / 100
                        
                        # Update order status
                        await db.razorpay_orders.update_one(
                            {"order_id": order_id},
                            {
                                "$set": {
                                    "status": "paid",
                                    "payment_id": payment_id,
                                    "payment_captured": True,
                                    "verified_amount": amount,
                                    "synced_at": datetime.now(timezone.utc).isoformat(),
                                    "synced_via": "manual_sync"
                                }
                            }
                        )
                        
                        # ACTIVATE SUBSCRIPTION
                        plan_type = order.get("plan_type", "monthly")
                        plan_name = order.get("plan_name", "startup")
                        duration_days = PLAN_DURATIONS.get(plan_type, 28)
                        
                        now = datetime.now(timezone.utc)
                        
                        # Check for existing subscription
                        user = await db.users.find_one({"uid": user_id})
                        remaining_days = 0
                        
                        if user:
                            expiry = get_user_expiry(user)
                            if expiry:
                                try:
                                    exp_date = datetime.fromisoformat(expiry.replace('Z', '+00:00'))
                                    if exp_date.tzinfo is None:
                                        exp_date = exp_date.replace(tzinfo=timezone.utc)
                                    if exp_date > now:
                                        remaining_days = (exp_date - now).days
                                except:
                                    pass
                        
                        total_days = duration_days + remaining_days
                        new_expiry = now + timedelta(days=total_days)
                        
                        # Update user subscription
                        await db.users.update_one(
                            {"uid": user_id},
                            {
                                "$set": {
                                    "subscription_plan": plan_name,
                                    "subscription_type": plan_type,
                                    "subscription_status": "active",
                                    "subscription_start": now.isoformat(),
                                    "subscription_expiry": new_expiry.isoformat(),
                                    "razorpay_subscription_id": order_id,
                                    "membership_type": plan_name,
                                    "last_payment_id": payment_id,
                                    "last_payment_amount": amount,
                                    "last_payment_date": now.isoformat()
                                }
                            }
                        )
                        
                        # Assign subscription position for mining network
                        try:
                            await assign_subscription_position(user_id)
                        except Exception as pos_err:
                            logging.warning(f"[MANUAL-ACTIVATE] Sub position error: {pos_err}")
                        
                        synced_count += 1
                        results.append({
                            "order_id": order_id,
                            "user_id": user_id,
                            "status": "activated",
                            "plan": plan_name,
                            "days": total_days
                        })
                else:
                    results.append({
                        "order_id": order_id,
                        "user_id": user_id,
                        "status": f"still_{razorpay_status}"
                    })
                    
            except Exception as e:
                errors.append({"order_id": order_id, "error": str(e)})
        
        return {
            "success": True,
            "synced": synced_count,
            "total_pending": len(pending_orders),
            "results": results,
            "errors": errors
        }
        
    except Exception as e:
        return {"success": False, "error": str(e)}


@api_router.post("/admin/razorpay/search-payment")
async def search_razorpay_payment(request: Request):
    """
    Search for a payment in Razorpay by various criteria.
    Use this when payment was made but not found in our system.
    """
    try:
        import razorpay
        
        data = await request.json()
        payment_id = data.get("payment_id")  # pay_xxx
        amount = data.get("amount")  # Amount in INR (e.g., 799)
        date_str = data.get("date")  # Date string YYYY-MM-DD
        upi_ref = data.get("upi_ref")  # UPI transaction reference
        
        RAZORPAY_KEY_ID = os.environ.get("RAZORPAY_KEY_ID")
        RAZORPAY_KEY_SECRET = os.environ.get("RAZORPAY_KEY_SECRET")
        
        if not RAZORPAY_KEY_ID or not RAZORPAY_KEY_SECRET:
            raise HTTPException(status_code=500, detail="Razorpay not configured")
        
        razorpay_client = razorpay.Client(auth=(RAZORPAY_KEY_ID, RAZORPAY_KEY_SECRET))
        
        # If payment_id provided, fetch directly
        if payment_id:
            try:
                # FIXED: Use asyncio.to_thread() to prevent blocking
                payment = await asyncio.to_thread(razorpay_client.payment.fetch, payment_id)
                return {
                    "success": True,
                    "found": True,
                    "payment": {
                        "id": payment.get("id"),
                        "amount": payment.get("amount", 0) / 100,
                        "status": payment.get("status"),
                        "captured": payment.get("captured"),
                        "order_id": payment.get("order_id"),
                        "method": payment.get("method"),
                        "email": payment.get("email"),
                        "contact": payment.get("contact"),
                        "vpa": payment.get("vpa"),
                        "created_at": datetime.fromtimestamp(payment.get("created_at", 0)).isoformat() if payment.get("created_at") else None,
                        "description": payment.get("description"),
                        "notes": payment.get("notes", {})
                    }
                }
            except Exception as e:
                return {"success": False, "found": False, "error": str(e)}
        
        # Search by criteria
        search_params = {"count": 50}
        
        if date_str:
            try:
                search_date = datetime.strptime(date_str, "%Y-%m-%d")
                search_params["from"] = int(search_date.timestamp())
                search_params["to"] = int((search_date + timedelta(days=1)).timestamp())
            except:
                pass
        
        # FIXED: Use asyncio.to_thread() to prevent blocking
        payments_response = await asyncio.to_thread(razorpay_client.payment.all, search_params)
        all_payments = payments_response.get("items", [])
        
        # Filter by amount if provided
        if amount:
            amount_paise = int(float(amount) * 100)
            all_payments = [p for p in all_payments if p.get("amount") == amount_paise]
        
        # Filter by status - only captured/authorized
        captured_payments = [p for p in all_payments if p.get("status") in ["captured", "authorized"]]
        
        # Search for UPI reference in notes/description if provided
        if upi_ref:
            matching = []
            for p in captured_payments:
                notes = p.get("notes", {})
                desc = p.get("description", "")
                acquirer_data = p.get("acquirer_data", {})
                
                # Check in various fields
                if (upi_ref in str(notes) or 
                    upi_ref in str(desc) or 
                    upi_ref in str(acquirer_data) or
                    upi_ref == acquirer_data.get("rrn") or
                    upi_ref == acquirer_data.get("upi_transaction_id")):
                    matching.append(p)
            
            captured_payments = matching if matching else captured_payments
        
        # Format results
        results = []
        for p in captured_payments[:20]:  # Limit to 20
            results.append({
                "id": p.get("id"),
                "amount": p.get("amount", 0) / 100,
                "status": p.get("status"),
                "captured": p.get("captured"),
                "order_id": p.get("order_id"),
                "method": p.get("method"),
                "email": p.get("email"),
                "contact": p.get("contact"),
                "vpa": p.get("vpa"),
                "created_at": datetime.fromtimestamp(p.get("created_at", 0)).isoformat() if p.get("created_at") else None,
                "acquirer_data": p.get("acquirer_data", {})
            })
        
        return {
            "success": True,
            "total_found": len(results),
            "payments": results,
            "search_criteria": {
                "amount": amount,
                "date": date_str,
                "upi_ref": upi_ref
            }
        }
        
    except Exception as e:
        logging.error(f"[SEARCH-PAYMENT] Error: {e}")
        raise HTTPException(status_code=500, detail=get_user_friendly_error(e))


@api_router.post("/admin/razorpay/manual-activate")
async def manual_activate_subscription(request: Request):
    """
    Manually activate a subscription for a payment that exists in Razorpay
    but has no corresponding order in our system.
    Use this for edge cases where payment was made outside the normal flow.
    """
    try:
        import razorpay
        
        data = await request.json()
        payment_id = data.get("payment_id")  # Required: pay_xxx
        user_email = data.get("user_email")  # Required: User's email to activate
        plan_name = data.get("plan_name", "elite")  # Optional: startup/elite
        plan_type = data.get("plan_type", "monthly")  # Optional: monthly/quarterly/etc
        admin_pin = data.get("admin_pin")
        
        if admin_pin != ADMIN_OPERATION_PIN:
            raise HTTPException(status_code=403, detail="Invalid admin PIN")
        
        if not payment_id:
            raise HTTPException(status_code=400, detail="payment_id is required")
        
        if not user_email:
            raise HTTPException(status_code=400, detail="user_email is required")
        
        RAZORPAY_KEY_ID = os.environ.get("RAZORPAY_KEY_ID")
        RAZORPAY_KEY_SECRET = os.environ.get("RAZORPAY_KEY_SECRET")
        
        if not RAZORPAY_KEY_ID or not RAZORPAY_KEY_SECRET:
            raise HTTPException(status_code=500, detail="Razorpay not configured")
        
        razorpay_client = razorpay.Client(auth=(RAZORPAY_KEY_ID, RAZORPAY_KEY_SECRET))
        
        # Verify payment exists and is captured
        # FIXED: Use asyncio.to_thread() to prevent blocking
        try:
            payment = await asyncio.to_thread(razorpay_client.payment.fetch, payment_id)
        except Exception as e:
            raise HTTPException(status_code=404, detail=f"Payment not found in Razorpay: {e}")
        
        if payment.get("status") != "captured":
            raise HTTPException(status_code=400, detail=f"Payment status is {payment.get('status')}, not captured")
        
        amount = payment.get("amount", 0) / 100
        
        # Find user by email
        user = await db.users.find_one({"email": {"$regex": f"^{user_email}$", "$options": "i"}})
        if not user:
            raise HTTPException(status_code=404, detail=f"User with email {user_email} not found")
        
        user_id = user.get("uid")
        user_name = user.get("name", "Unknown")
        
        # Check if this payment was already used
        existing = await db.vip_payments.find_one({"payment_id": payment_id})
        if existing:
            raise HTTPException(status_code=400, detail="This payment has already been used for activation")
        
        # Plan durations
        PLAN_DURATIONS = {
            "monthly": 28,
            "quarterly": 84,
            "half_yearly": 168,
            "yearly": 336
        }
        
        duration_days = PLAN_DURATIONS.get(plan_type, 28)
        now = datetime.now(timezone.utc)
        
        # Check for existing subscription - add remaining days
        remaining_days = 0
        expiry = get_user_expiry(user)
        if expiry:
            try:
                if isinstance(expiry, str):
                    exp_date = datetime.fromisoformat(expiry.replace('Z', '+00:00'))
                else:
                    exp_date = expiry
                if exp_date.tzinfo is None:
                    exp_date = exp_date.replace(tzinfo=timezone.utc)
                if exp_date > now:
                    remaining_days = (exp_date - now).days
            except:
                pass
        
        total_days = duration_days + remaining_days
        new_expiry = now + timedelta(days=total_days)
        
        # Create a synthetic order record
        order_id = f"manual_{payment_id}"
        
        await db.razorpay_orders.insert_one({
            "order_id": order_id,
            "user_id": user_id,
            "plan_name": plan_name,
            "plan_type": plan_type,
            "amount": amount,
            "status": "paid",
            "payment_id": payment_id,
            "payment_captured": True,
            "created_at": now,
            "paid_at": now,
            "synced_via": "manual_activate",
            "notes": "Manually activated - payment found in Razorpay but no order existed"
        })
        
        # Update user subscription
        await db.users.update_one(
            {"uid": user_id},
            {
                "$set": {
                    "subscription_plan": plan_name.lower(),
                    "subscription_type": plan_type,
                    "subscription_status": "active",
                    "subscription_start": now.isoformat(),
                    "subscription_expiry": new_expiry.isoformat(),
                    "membership_type": "vip",
                    "last_payment_id": payment_id,
                    "last_payment_amount": amount,
                    "last_payment_date": now.isoformat(),
                    "activated_via": "manual_activate",
                    "subscription_payment_type": "cash"
                }
            }
        )
        
        # Log to vip_payments
        await db.vip_payments.insert_one({
            "user_id": user_id,
            "order_id": order_id,
            "payment_id": payment_id,
            "amount": amount,
            "subscription_plan": plan_name.lower(),
            "plan_type": plan_type,
            "status": "approved",
            "payment_method": "razorpay",
            "payment_captured": True,
            "new_expiry": new_expiry.isoformat(),
            "duration_days": total_days,
            "remaining_days_added": remaining_days,
            "approved_at": now.isoformat(),
            "created_at": now.isoformat(),
            "auto_activated": False,
            "activation_source": "manual_activate",
            "notes": "Manually activated by admin"
        })
        
        logging.info(f"[MANUAL-ACTIVATE] ✅ Activated {user_name} ({user_email}), Plan: {plan_name}, Payment: {payment_id}")

        # Community success-story hook
        try:
            from routes.community import create_success_story_post
            asyncio.create_task(create_success_story_post(
                user_id=user_id,
                service_type="subscription",
                amount_inr=float(amount or 0),
                plan_name=plan_name,
                ref_id=f"sub_{payment_id}",
            ))
        except Exception as _e:
            logging.warning(f"[COMMUNITY] manual-activate post hook failed (non-fatal): {_e}")

        return {
            "success": True,
            "message": f"✅ Subscription activated for {user_name}!",
            "user": {
                "uid": user_id,
                "name": user_name,
                "email": user_email
            },
            "subscription": {
                "plan": plan_name,
                "type": plan_type,
                "duration_days": duration_days,
                "remaining_days_added": remaining_days,
                "total_days": total_days,
                "new_expiry": new_expiry.isoformat()
            },
            "payment": {
                "id": payment_id,
                "amount": amount
            }
        }
        
    except HTTPException:
        raise
    except Exception as e:
        logging.error(f"[MANUAL-ACTIVATE] Error: {e}")
        raise HTTPException(status_code=500, detail=get_user_friendly_error(e))


@api_router.post("/admin/razorpay/bulk-sync-captured")
async def bulk_sync_captured_payments(request: Request):
    """
    SMART BULK SYNC: Fetch recent captured payments from Razorpay API
    and activate any that are not yet activated in our system.
    This is the FASTEST way to sync missing activations.
    """
    try:
        import razorpay
        
        RAZORPAY_KEY_ID = os.environ.get("RAZORPAY_KEY_ID")
        RAZORPAY_KEY_SECRET = os.environ.get("RAZORPAY_KEY_SECRET")
        
        if not RAZORPAY_KEY_ID or not RAZORPAY_KEY_SECRET:
            raise HTTPException(status_code=500, detail="Razorpay not configured")
        
        razorpay_client = razorpay.Client(auth=(RAZORPAY_KEY_ID, RAZORPAY_KEY_SECRET))
        
        # Plan durations
        PLAN_DURATIONS = {
            "monthly": 28,
            "quarterly": 84,
            "half_yearly": 168,
            "yearly": 336
        }
        
        # Fetch recent captured payments from Razorpay (last 7 days)
        # Using timestamp for 7 days ago
        from_timestamp = int((datetime.now(timezone.utc) - timedelta(days=7)).timestamp())
        
        logging.info(f"[BULK-SYNC] Fetching payments from Razorpay since {from_timestamp}")
        
        # FIXED: Use asyncio.to_thread() to prevent blocking
        payments_response = await asyncio.to_thread(
            razorpay_client.payment.all,
            {"count": 100, "from": from_timestamp}
        )
        
        all_payments = payments_response.get("items", [])
        logging.info(f"[BULK-SYNC] Found {len(all_payments)} total payments from Razorpay")
        
        # Filter only captured payments
        captured_payments = [p for p in all_payments if p.get("status") == "captured"]
        logging.info(f"[BULK-SYNC] {len(captured_payments)} are captured")
        
        activated_count = 0
        already_active = 0
        not_found = 0
        errors = []
        results = []
        
        for payment in captured_payments:
            payment_id = payment.get("id")
            order_id = payment.get("order_id")
            amount = payment.get("amount", 0) / 100
            
            if not order_id:
                continue
            
            try:
                # Check if this order exists in our DB
                order = await db.razorpay_orders.find_one({"order_id": order_id})
                
                if not order:
                    not_found += 1
                    continue
                
                # ==================== HARD IDEMPOTENCY GUARD (May 2026 fix) ====================
                # PRIOR BUG: Code only skipped when (order.status=paid AND user.last_payment_id == this payment_id).
                # If user.last_payment_id was later overwritten by a newer payment, the
                # OLD order would re-activate on the next bulk_sync sweep, adding 28
                # MORE days on top of the original activation. Example: Rutuja Sunil
                # was activated 26 Apr 26 (28 days → expiry 24 May) then re-activated
                # again, expiry stretched to 20 Jun 26 (55 days).
                # FIX: Treat ANY of these as definitive "already activated":
                #   (a) vip_payments has a doc with this payment_id (canonical idempotency key)
                #   (b) transactions has a subscription_payment doc with this payment_id
                #   (c) order.status="paid" AND user.last_payment_id matches (legacy check)
                already_activated_check = await db.vip_payments.find_one(
                    {"payment_id": payment_id}, {"_id": 1}
                )
                if not already_activated_check:
                    already_activated_check = await db.transactions.find_one(
                        {"payment_id": payment_id, "type": "subscription_payment"},
                        {"_id": 1}
                    )
                if already_activated_check:
                    already_active += 1
                    logging.info(f"[BULK-SYNC] Skipping payment {payment_id} — already has vip_payment/transaction record (idempotent)")
                    continue

                # Legacy fallback check (kept for very-old orders without vip_payment record)
                if order.get("status") == "paid":
                    user_id = order.get("user_id")
                    user = await db.users.find_one({"uid": user_id})

                    if user and user.get("last_payment_id") == payment_id:
                        already_active += 1
                        continue
                    # If status=paid but no canonical record exists AND last_payment_id
                    # mismatches, we STILL skip to be safe (prior bug: this fell through
                    # and double-activated). Log as a warning so the operator can
                    # investigate orphan paid-but-unrecorded orders manually.
                    logging.warning(
                        f"[BULK-SYNC] Order {order_id} marked paid but no vip_payment/"
                        f"transaction record; user.last_payment_id={user.get('last_payment_id') if user else None}. "
                        f"Skipping to prevent double-activation. Manual review needed."
                    )
                    already_active += 1
                    continue

                # Need to activate!
                user_id = order.get("user_id")
                plan_type = order.get("plan_type", "monthly")
                plan_name = order.get("plan_name", "startup")
                duration_days = PLAN_DURATIONS.get(plan_type, 28)
                
                now = datetime.now(timezone.utc)
                
                # Get user and check existing subscription
                user = await db.users.find_one({"uid": user_id})
                remaining_days = 0
                user_name = "Unknown"
                user_email = "Unknown"
                
                if user:
                    user_name = user.get("name", "Unknown")
                    user_email = user.get("email", "Unknown")
                    
                    # Check for existing active subscription
                    expiry = get_user_expiry(user)
                    if expiry:
                        try:
                            if isinstance(expiry, str):
                                exp_date = datetime.fromisoformat(expiry.replace('Z', '+00:00'))
                            else:
                                exp_date = expiry
                            if exp_date.tzinfo is None:
                                exp_date = exp_date.replace(tzinfo=timezone.utc)
                            if exp_date > now:
                                remaining_days = (exp_date - now).days
                        except:
                            pass
                
                total_days = duration_days + remaining_days
                new_expiry = now + timedelta(days=total_days)
                
                # Update order status
                await db.razorpay_orders.update_one(
                    {"order_id": order_id},
                    {
                        "$set": {
                            "status": "paid",
                            "payment_id": payment_id,
                            "payment_captured": True,
                            "verified_amount": amount,
                            "synced_at": now.isoformat(),
                            "synced_via": "bulk_sync"
                        }
                    }
                )
                
                # Update user subscription
                await db.users.update_one(
                    {"uid": user_id},
                    {
                        "$set": {
                            "subscription_plan": plan_name.lower(),
                            "subscription_type": plan_type,
                            "subscription_status": "active",
                            "subscription_start": now.isoformat(),
                            "subscription_expiry": new_expiry.isoformat(),
                            "membership_type": "vip",
                            "last_payment_id": payment_id,
                            "last_payment_amount": amount,
                            "last_payment_date": now.isoformat(),
                            "activated_via": "bulk_sync",
                            "subscription_payment_type": "cash"
                        }
                    }
                )
                
                # Log to vip_payments
                await db.vip_payments.insert_one({
                    "user_id": user_id,
                    "order_id": order_id,
                    "payment_id": payment_id,
                    "amount": amount,
                    "subscription_plan": plan_name.lower(),
                    "plan_type": plan_type,
                    "status": "approved",
                    "payment_method": "razorpay",
                    "payment_captured": True,
                    "new_expiry": new_expiry.isoformat(),
                    "duration_days": total_days,
                    "remaining_days_added": remaining_days,
                    "approved_at": now.isoformat(),
                    "created_at": now.isoformat(),
                    "auto_activated": True,
                    "activation_source": "bulk_sync"
                })
                
                activated_count += 1

                # ── SUBSCRIPTION POSITION (Feb 6 2026 fix) ─────────────────
                # CRITICAL: bulk_sync path was missing assign_subscription_position
                # → activated users had `subscription_position=None` → their
                # `get_subscription_network_size()` returned 0 → mining Network
                # Size stuck at 0 forever, hourly rate never went above the
                # base 30 PRC/hr (740 PRC/day / 24). Verify-payment path was
                # patched in May 2026 but the bulk sync path was overlooked.
                # Now aligned across all 3 subscription-activation entry points.
                try:
                    from routes.mining import assign_subscription_position
                    await assign_subscription_position(user_id)
                    logging.info(f"[BULK-SYNC] Assigned subscription_position for {user_id}")
                except Exception as _pos_err:
                    logging.warning(f"[BULK-SYNC] assign_subscription_position failed (non-fatal) for {user_id}: {_pos_err}")

                # Community success-story hook
                try:
                    from routes.community import create_success_story_post
                    asyncio.create_task(create_success_story_post(
                        user_id=user_id,
                        service_type="subscription",
                        amount_inr=float(amount or 0),
                        plan_name=plan_name,
                        ref_id=f"sub_{payment_id}",
                    ))
                except Exception as _e:
                    logging.warning(f"[COMMUNITY] bulk-sync post hook failed: {_e}")

                results.append({
                    "order_id": order_id,
                    "payment_id": payment_id,
                    "user_name": user_name,
                    "user_email": user_email,
                    "plan": plan_name,
                    "amount": amount,
                    "total_days": total_days,
                    "status": "ACTIVATED"
                })
                
                logging.info(f"[BULK-SYNC] ✅ Activated: {user_name} ({user_email}) - {plan_name} for {total_days} days")
                
            except Exception as e:
                errors.append({"order_id": order_id, "error": str(e)})
                logging.error(f"[BULK-SYNC] Error for {order_id}: {e}")
        
        return {
            "success": True,
            "total_captured_in_razorpay": len(captured_payments),
            "newly_activated": activated_count,
            "already_active": already_active,
            "orders_not_in_db": not_found,
            "errors": len(errors),
            "activated_users": results,
            "error_details": errors[:10] if errors else []
        }
        
    except Exception as e:
        logging.error(f"[BULK-SYNC] Error: {e}")
        raise HTTPException(status_code=500, detail=get_user_friendly_error(e))


@api_router.post("/admin/razorpay/sync-single")
async def sync_single_razorpay_order(request: Request):
    """
    Sync a SINGLE Razorpay order by order_id.
    Fast endpoint for activating individual captured payments.
    """
    try:
        import razorpay
        
        data = await request.json()
        order_id = data.get("order_id")
        
        if not order_id:
            raise HTTPException(status_code=400, detail="order_id is required")
        
        RAZORPAY_KEY_ID = os.environ.get("RAZORPAY_KEY_ID")
        RAZORPAY_KEY_SECRET = os.environ.get("RAZORPAY_KEY_SECRET")
        
        if not RAZORPAY_KEY_ID or not RAZORPAY_KEY_SECRET:
            raise HTTPException(status_code=500, detail="Razorpay not configured")
        
        razorpay_client = razorpay.Client(auth=(RAZORPAY_KEY_ID, RAZORPAY_KEY_SECRET))
        
        # Get order from our DB
        order = await db.razorpay_orders.find_one({"order_id": order_id})
        if not order:
            raise HTTPException(status_code=404, detail=f"Order {order_id} not found in database")
        
        user_id = order.get("user_id")
        
        # Fetch from Razorpay API
        # FIXED: Use asyncio.to_thread() to prevent blocking
        razorpay_order = await asyncio.to_thread(razorpay_client.order.fetch, order_id)
        razorpay_status = razorpay_order.get("status")
        
        if razorpay_status != "paid":
            return {
                "success": False,
                "order_id": order_id,
                "razorpay_status": razorpay_status,
                "message": f"Order not paid yet. Status: {razorpay_status}"
            }
        
        # Get captured payment
        # FIXED: Use asyncio.to_thread() to prevent blocking
        payments = await asyncio.to_thread(razorpay_client.order.payments, order_id)
        captured_payment = None
        for payment in payments.get("items", []):
            if payment.get("status") == "captured":
                captured_payment = payment
                break
        
        if not captured_payment:
            return {
                "success": False,
                "order_id": order_id,
                "message": "No captured payment found for this order"
            }
        
        payment_id = captured_payment.get("id")
        amount = captured_payment.get("amount", 0) / 100
        
        # Plan durations
        PLAN_DURATIONS = {
            "monthly": 28,
            "quarterly": 84,
            "half_yearly": 168,
            "yearly": 336
        }
        
        # Update order status
        await db.razorpay_orders.update_one(
            {"order_id": order_id},
            {
                "$set": {
                    "status": "paid",
                    "payment_id": payment_id,
                    "payment_captured": True,
                    "verified_amount": amount,
                    "synced_at": datetime.now(timezone.utc).isoformat(),
                    "synced_via": "single_sync"
                }
            }
        )
        
        # ACTIVATE SUBSCRIPTION
        plan_type = order.get("plan_type", "monthly")
        plan_name = order.get("plan_name", "startup")
        duration_days = PLAN_DURATIONS.get(plan_type, 28)
        
        now = datetime.now(timezone.utc)
        
        # Check for existing subscription
        user = await db.users.find_one({"uid": user_id})
        remaining_days = 0
        user_name = "Unknown"
        user_email = "Unknown"
        
        if user:
            user_name = user.get("name", "Unknown")
            user_email = user.get("email", "Unknown")
            expiry = get_user_expiry(user)
            if expiry:
                try:
                    if isinstance(expiry, str):
                        exp_date = datetime.fromisoformat(expiry.replace('Z', '+00:00'))
                    else:
                        exp_date = expiry
                    if exp_date.tzinfo is None:
                        exp_date = exp_date.replace(tzinfo=timezone.utc)
                    if exp_date > now:
                        remaining_days = (exp_date - now).days
                except:
                    pass
        
        total_days = duration_days + remaining_days
        new_expiry = now + timedelta(days=total_days)
        
        # Update user subscription
        await db.users.update_one(
            {"uid": user_id},
            {
                "$set": {
                    "subscription_plan": plan_name.lower(),
                    "subscription_type": plan_type,
                    "subscription_status": "active",
                    "subscription_start": now.isoformat(),
                    "subscription_expiry": new_expiry.isoformat(),
                    "membership_type": "vip",
                    "last_payment_id": payment_id,
                    "last_payment_amount": amount,
                    "last_payment_date": now.isoformat(),
                    "activated_via": "single_sync",
                    "subscription_payment_type": "cash"
                }
            }
        )
        
        # Log to vip_payments
        await db.vip_payments.insert_one({
            "user_id": user_id,
            "order_id": order_id,
            "payment_id": payment_id,
            "amount": amount,
            "subscription_plan": plan_name.lower(),
            "plan_type": plan_type,
            "status": "approved",
            "payment_method": "razorpay",
            "payment_captured": True,
            "new_expiry": new_expiry.isoformat(),
            "duration_days": total_days,
            "remaining_days_added": remaining_days,
            "approved_at": now.isoformat(),
            "created_at": now.isoformat(),
            "auto_activated": True,
            "activation_source": "single_sync"
        })
        
        logging.info(f"[SINGLE-SYNC] ✅ Activated {user_name} ({user_email}), Plan: {plan_name}, Days: {total_days}")

        # Community success-story hook
        try:
            from routes.community import create_success_story_post
            asyncio.create_task(create_success_story_post(
                user_id=user_id,
                service_type="subscription",
                amount_inr=float(amount or 0),
                plan_name=plan_name,
                ref_id=f"sub_{payment_id}",
            ))
        except Exception as _e:
            logging.warning(f"[COMMUNITY] single-sync post hook failed: {_e}")
        
        return {
            "success": True,
            "order_id": order_id,
            "user_id": user_id,
            "user_name": user_name,
            "user_email": user_email,
            "payment_id": payment_id,
            "amount": amount,
            "plan": plan_name,
            "plan_type": plan_type,
            "duration_days": duration_days,
            "remaining_days_added": remaining_days,
            "total_days": total_days,
            "new_expiry": new_expiry.isoformat(),
            "message": f"✅ Subscription activated for {user_name}!"
        }
        
    except HTTPException:
        raise
    except Exception as e:
        logging.error(f"[SINGLE-SYNC] Error: {e}")
        raise HTTPException(status_code=500, detail=get_user_friendly_error(e))


@api_router.post("/admin/razorpay-delete-all")
async def delete_all_razorpay_orders(request: Request):
    """
    Delete ALL Razorpay orders (both paid and pending).
    Use this to completely reset Razorpay data.
    WARNING: This is irreversible!
    """
    try:
        data = await request.json()
        admin_pin = data.get("admin_pin")
        confirm = data.get("confirm", False)
        
        if admin_pin != ADMIN_OPERATION_PIN:
            raise HTTPException(status_code=403, detail="Invalid admin PIN")
        
        if not confirm:
            raise HTTPException(status_code=400, detail="Please set confirm=true to proceed")
        
        # Get counts before deletion
        total_count = await db.razorpay_orders.count_documents({})
        paid_count = await db.razorpay_orders.count_documents({"status": "paid"})
        pending_count = await db.razorpay_orders.count_documents({"status": "created"})
        
        # Delete all orders
        result = await db.razorpay_orders.delete_many({})
        
        # Log the action
        await db.admin_audit_logs.insert_one({
            "action": "razorpay_delete_all",
            "total_deleted": result.deleted_count,
            "paid_deleted": paid_count,
            "pending_deleted": pending_count,
            "performed_at": datetime.now(timezone.utc).isoformat()
        })
        
        return {
            "success": True,
            "message": f"Deleted ALL {result.deleted_count} orders ({paid_count} paid, {pending_count} pending)",
            "deleted_count": result.deleted_count,
            "paid_deleted": paid_count,
            "pending_deleted": pending_count
        }
        
    except HTTPException:
        raise
    except Exception as e:
        logging.error(f"Delete all error: {e}")
        raise HTTPException(status_code=500, detail=get_user_friendly_error(e))


@api_router.get("/admin/audit-logs/fraud-cleanup")
async def get_fraud_cleanup_logs():
    """Get all fraud cleanup audit logs to review what was reset"""
    logs = await db.admin_audit_logs.find({
        "action": {"$in": ["razorpay_fraud_cleanup", "razorpay_delete_pending", "razorpay_delete_all"]}
    }).sort("performed_at", -1).to_list(50)
    
    result = []
    for log in logs:
        # Remove MongoDB _id for JSON serialization
        log_data = {
            "action": log.get("action"),
            "performed_at": log.get("performed_at"),
            "reset_count": log.get("reset_count", 0),
            "skipped_count": log.get("skipped_count", 0),
            "deleted_count": log.get("deleted_count", 0),
            "reset_users": log.get("reset_users", []),
            "skipped_users": log.get("skipped_users", [])
        }
        result.append(log_data)
    
    return {"logs": result, "total": len(result)}


@api_router.post("/admin/restore-users-from-vip-payments")
async def restore_users_from_vip_payments(request: Request):
    """
    Restore users who had legitimate VIP payments.
    This will check vip_payments collection and restore their subscription.
    """
    try:
        data = await request.json()
        admin_pin = data.get("admin_pin")
        
        if admin_pin != ADMIN_OPERATION_PIN:
            raise HTTPException(status_code=403, detail="Invalid admin PIN")
        
        # Find all users who were marked as fraudulent but have legitimate vip_payments
        affected_users = await db.users.find({
            "fraudulent_activation_reverted": True
        }).to_list(1000)
        
        restored_users = []
        
        for user in affected_users:
            uid = user.get("uid")
            
            # Check if user has approved vip_payments
            vip_payment = await db.vip_payments.find_one({
                "uid": uid,
                "status": "approved"
            }, sort=[("approved_at", -1)])
            
            if vip_payment:
                # Restore from VIP payment
                plan = vip_payment.get("plan", "startup")
                duration = vip_payment.get("duration", "monthly")
                approved_at = vip_payment.get("approved_at")
                
                # Calculate expiry based on duration (28 days per month)
                duration_days_map = {
                    "monthly": 28,
                    "quarterly": 84,
                    "half_yearly": 168,
                    "yearly": 336
                }
                duration_days = duration_days_map.get(duration, 28)
                
                # Calculate expiry from approval date
                if approved_at:
                    if isinstance(approved_at, str):
                        try:
                            approved_at = datetime.fromisoformat(approved_at.replace('Z', '+00:00'))
                        except:
                            approved_at = datetime.now(timezone.utc)
                    expiry_date = approved_at + timedelta(days=duration_days)
                else:
                    expiry_date = datetime.now(timezone.utc) + timedelta(days=duration_days)
                
                # Restore subscription
                await db.users.update_one(
                    {"uid": uid},
                    {
                        "$set": {
                            "subscription_plan": plan,
                            "membership_type": "vip",
                            "subscription_status": "active",
                            "subscription_expiry": expiry_date.isoformat() if hasattr(expiry_date, "isoformat") else expiry_date,
                            "restored_from": "vip_payments",
                            "restored_at": datetime.now(timezone.utc).isoformat()
                        },
                        "$unset": {
                            "fraudulent_activation_reverted": ""
                        }
                    }
                )
                
                restored_users.append({
                    "uid": uid,
                    "name": user.get("name"),
                    "email": user.get("email"),
                    "restored_plan": plan,
                    "restored_expiry": expiry_date.isoformat()
                })
        
        # Log the restoration
        await db.admin_audit_logs.insert_one({
            "action": "restore_from_vip_payments",
            "restored_count": len(restored_users),
            "restored_users": restored_users,
            "performed_at": datetime.now(timezone.utc).isoformat()
        })
        
        return {
            "success": True,
            "message": f"Restored {len(restored_users)} users from VIP payments",
            "restored_count": len(restored_users),
            "restored_users": restored_users
        }
        
    except HTTPException:
        raise
    except Exception as e:
        logging.error(f"Restore error: {e}")
        raise HTTPException(status_code=500, detail=get_user_friendly_error(e))


