@api_router.post("/admin/recalculate-prc-balance")
async def recalculate_prc_balance(request: Request):
    """
    Recalculate PRC balance for affected users from transaction history.
    This will fix PRC balances that became 0 incorrectly.
    """
    try:
        data = await request.json()
        admin_pin = data.get("admin_pin")
        user_ids = data.get("user_ids", [])  # Optional: specific users to recalculate
        
        if admin_pin != ADMIN_OPERATION_PIN:
            raise HTTPException(status_code=403, detail="Invalid admin PIN")
        
        # If no specific users, find users with 0 PRC who might need fixing
        if not user_ids:
            users_to_fix = await db.users.find({
                "prc_balance": {"$lte": 0}
            }).to_list(500)
        else:
            users_to_fix = await db.users.find({
                "uid": {"$in": user_ids}
            }).to_list(500)
        
        fixed_users = []
        
        for user in users_to_fix:
            uid = user.get("uid")
            old_balance = user.get("prc_balance", 0)
            
            # Get all transactions for this user
            transactions = await db.transactions.find({"user_id": uid}).to_list(10000)
            
            # Calculate PRC earned (positive)
            prc_earned = sum(
                t.get("amount", 0) for t in transactions 
                if t.get("type") in ["mining", "tap_game", "referral", "signup_bonus", "daily_bonus", "prc_credit", "admin_credit"]
            )
            
            # Calculate PRC spent (negative)
            prc_spent = sum(
                abs(t.get("amount", 0)) for t in transactions 
                if t.get("type") in ["order", "bill_payment_request", "gift_voucher_request", "prc_burn", "prc_debit"]
            )
            
            # Correct balance
            correct_balance = prc_earned - prc_spent
            
            if correct_balance != old_balance:
                # Update user balance
                await db.users.update_one(
                    {"uid": uid},
                    {
                        "$set": {
                            "prc_balance": max(0, correct_balance),
                            "prc_balance_recalculated": True,
                            "prc_recalculated_at": datetime.now(timezone.utc).isoformat()
                        }
                    }
                )
                
                fixed_users.append({
                    "uid": uid,
                    "name": user.get("name"),
                    "old_balance": old_balance,
                    "new_balance": max(0, correct_balance),
                    "prc_earned": prc_earned,
                    "prc_spent": prc_spent
                })
        
        # Log the action
        await db.admin_audit_logs.insert_one({
            "action": "prc_balance_recalculation",
            "fixed_count": len(fixed_users),
            "fixed_users": fixed_users,
            "performed_at": datetime.now(timezone.utc).isoformat()
        })
        
        return {
            "success": True,
            "message": f"Recalculated PRC balance for {len(fixed_users)} users",
            "fixed_count": len(fixed_users),
            "fixed_users": fixed_users
        }
        
    except HTTPException:
        raise
    except Exception as e:
        logging.error(f"PRC recalculation error: {e}")
        raise HTTPException(status_code=500, detail=get_user_friendly_error(e))


@api_router.get("/admin/razorpay-fraud-preview")
async def preview_fraudulent_subscriptions():
    """
    Preview: List all users who will be affected by fraud cleanup.
    SMART VERSION: Only shows users whose subscription came from Razorpay (not manual/UPI)
    """
    paid_orders = await db.razorpay_orders.find({"status": "paid"}).to_list(1000)
    
    affected_users = []
    skipped_users = []  # Users with legitimate subscriptions
    
    for order in paid_orders:
        user_id = order.get("user_id")
        order_created = order.get("created_at")
        razorpay_payment_id = order.get("payment_id")
        
        user = await db.users.find_one(
            {"uid": user_id}, 
            {"_id": 0, "name": 1, "email": 1, "subscription_plan": 1, "mobile": 1, 
             "subscription_start": 1, "last_payment_id": 1}
        )
        
        if not user:
            continue
        
        # Check if user has an APPROVED manual VIP payment (legitimate subscription)
        legitimate_payment = await db.vip_payments.find_one({
            "uid": user_id,
            "status": "approved"
        }, sort=[("approved_at", -1)])
        
        user_info = {
            "user_id": user_id,
            "name": user.get("name"),
            "email": user.get("email"),
            "mobile": user.get("mobile"),
            "current_plan": user.get("subscription_plan"),
            "order_id": order.get("order_id"),
            "payment_id": razorpay_payment_id,
            "amount": order.get("amount"),
            "razorpay_order_date": str(order_created) if order_created else None
        }
        
        # If user has legitimate manual payment, skip them
        if legitimate_payment:
            user_info["legitimate_payment"] = {
                "payment_id": str(legitimate_payment.get("_id")),
                "plan": legitimate_payment.get("plan"),
                "approved_at": str(legitimate_payment.get("approved_at"))
            }
            user_info["reason"] = "Has legitimate manual payment - WILL BE SKIPPED"
            skipped_users.append(user_info)
        else:
            # Check if subscription came from this Razorpay payment
            if user.get("last_payment_id") == razorpay_payment_id:
                user_info["reason"] = "Subscription from fraudulent Razorpay - WILL BE RESET"
                affected_users.append(user_info)
            else:
                # Extra check: if no last_payment_id but has razorpay order
                user_info["reason"] = "Razorpay order exists - WILL BE RESET"
                affected_users.append(user_info)
    
    return {
        "total_will_reset": len(affected_users),
        "total_will_skip": len(skipped_users),
        "users_to_reset": affected_users,
        "users_to_skip": skipped_users,
        "warning": "Only 'users_to_reset' will be converted to FREE. Users with legitimate payments will be SKIPPED."
    }


@api_router.post("/subscription/payment/{uid}")
async def submit_subscription_payment(uid: str, request: Request):
    """Submit subscription payment for verification with fraud prevention.

    Hardened (May 2026):
      • All Atlas calls wrapped in 8s asyncio.wait_for to prevent hangs.
      • motor/pymongo timeout exceptions → HTTP 504 (frontend auto-retries).
      • Idempotency key support via `client_request_id` to prevent
        accidental duplicate submissions on retry.
      • Better error messages so frontend shows the real reason, not
        the generic "Failed to submit payment" toast.
    """
    DB_FAST_TIMEOUT = 8.0

    def _is_timeout_err(e: Exception) -> bool:
        s = str(e).lower()
        return any(t in s for t in ["timeout", "timed out", "serverselection", "networktimeout"])

    try:
        data = await request.json()

        plan = data.get("plan")
        duration = data.get("duration")
        amount = data.get("amount")
        utr_number = data.get("utr_number")
        screenshot = data.get("screenshot_base64")
        payment_date = data.get("date")
        payment_time = data.get("time")
        client_request_id = data.get("client_request_id")

        idem_scope = f"sub_payment:{uid}"
        # Idempotency: if this exact request was already submitted, replay
        if client_request_id:
            try:
                existing = await asyncio.wait_for(
                    db.idempotency_keys.find_one(
                        {"scope": idem_scope, "key": client_request_id},
                        {"_id": 0},
                    ),
                    timeout=DB_FAST_TIMEOUT,
                )
                if existing and existing.get("status") == "completed":
                    cached = existing.get("response")
                    if isinstance(cached, dict):
                        return {**cached, "_idempotency_replay": True}
                elif existing and existing.get("status") == "claimed":
                    raise HTTPException(
                        status_code=409,
                        detail="Your previous payment submission is still being processed. Please wait a moment and check Subscription page — it may already be submitted.",
                    )
            except HTTPException:
                raise
            except Exception:
                pass  # Idempotency check is best-effort

        # ==================== FRAUD PREVENTION ====================

        if plan not in ["elite"]:
            raise HTTPException(status_code=400, detail="Invalid plan selected. Only Elite plan is available.")

        if duration not in SUBSCRIPTION_DURATIONS:
            raise HTTPException(status_code=400, detail="Invalid duration selected")

        # 2. STRICT UTR VALIDATION - Must be exactly 12 digits
        if not utr_number:
            raise HTTPException(status_code=400, detail="UTR number is required")

        utr_cleaned = ''.join(filter(str.isdigit, utr_number))
        if len(utr_cleaned) != 12:
            raise HTTPException(
                status_code=400,
                detail=f"UTR number must be exactly 12 digits. You entered: {len(utr_cleaned)} digits."
            )
        utr_number = utr_cleaned

        # 3. Check for duplicate UTR (with timeout)
        try:
            is_unique = await asyncio.wait_for(
                check_unique_utr(utr_number),
                timeout=DB_FAST_TIMEOUT,
            )
            if not is_unique:
                try:
                    utr_info = await asyncio.wait_for(
                        get_utr_usage_info(utr_number),
                        timeout=DB_FAST_TIMEOUT,
                    )
                except Exception:
                    utr_info = None
                info_msg = f" (Used in {utr_info['type']}, Status: {utr_info['status']})" if utr_info else ""
                raise HTTPException(
                    status_code=400,
                    detail=f"UTR ALREADY IN USE! This UTR number '{utr_number}' has already been used{info_msg}. Please enter the correct UTR from your payment receipt."
                )
        except HTTPException:
            raise
        except asyncio.TimeoutError:
            raise HTTPException(
                status_code=504,
                detail="Database is slow right now. Please try again in a few seconds.",
            )
        except Exception as e:
            if _is_timeout_err(e):
                raise HTTPException(status_code=504, detail="Database is slow right now. Please try again.")
            raise

        # 4. Rate limiting — count recent submissions
        now = datetime.now(timezone.utc)
        yesterday = (now - timedelta(hours=24)).isoformat()
        try:
            recent_submissions = await asyncio.wait_for(
                db.vip_payments.count_documents({
                    "user_id": uid,
                    "submitted_at": {"$gte": yesterday}
                }),
                timeout=DB_FAST_TIMEOUT,
            )
        except asyncio.TimeoutError:
            raise HTTPException(status_code=504, detail="Database is slow right now. Please try again.")
        except Exception as e:
            if _is_timeout_err(e):
                raise HTTPException(status_code=504, detail="Database is slow right now. Please try again.")
            raise

        if recent_submissions >= 5:
            raise HTTPException(
                status_code=429,
                detail="You have submitted too many payments today. Please wait 24 hours, or contact support if you believe this is an error."
            )

        # 5. Suspicious-pattern check — same amount in last hour
        try:
            recent_same_amount = await asyncio.wait_for(
                db.vip_payments.count_documents({
                    "user_id": uid,
                    "amount": amount,
                    "submitted_at": {"$gte": (now - timedelta(hours=1)).isoformat()}
                }),
                timeout=DB_FAST_TIMEOUT,
            )
        except Exception:
            recent_same_amount = 0  # Best-effort; don't block submission on a DB hiccup

        if recent_same_amount >= 2:
            raise HTTPException(
                status_code=429,
                detail="A similar payment was already submitted recently. Please wait a few minutes — your earlier submission may already be in queue."
            )

        if not screenshot:
            raise HTTPException(status_code=400, detail="Payment screenshot is required")

        # ==================== CREATE PAYMENT RECORD ====================

        payment_id = str(uuid.uuid4())

        client_ip = request.headers.get("X-Forwarded-For", request.headers.get("X-Real-IP", "unknown"))
        if client_ip and "," in client_ip:
            client_ip = client_ip.split(",")[0].strip()

        payment_doc = {
            "payment_id": payment_id,
            "user_id": uid,
            "subscription_plan": plan,
            "plan_type": duration,
            "amount": amount,
            "utr_number": utr_number,
            "screenshot_url": screenshot,
            "date": payment_date,
            "time": payment_time,
            "status": "pending",
            "submitted_at": now.isoformat(),
            "created_at": now.isoformat(),
            "client_ip": client_ip,
            "user_agent": request.headers.get("User-Agent", "unknown")[:200],
            "fraud_flags": [],
            "verification_attempts": 0
        }

        # Claim idempotency sentinel just before the insert.
        if client_request_id:
            try:
                claim = await check_and_claim_idempotency_key(
                    client_request_id, idem_scope, ttl_seconds=600
                )
                if claim is not None:
                    if claim.get("_inflight"):
                        raise HTTPException(
                            status_code=409,
                            detail="Your previous payment submission is still being processed. Please wait.",
                        )
                    return claim
            except HTTPException:
                raise
            except Exception:
                pass  # Best-effort

        try:
            await asyncio.wait_for(
                db.vip_payments.insert_one(payment_doc),
                timeout=DB_FAST_TIMEOUT,
            )
        except asyncio.TimeoutError:
            if client_request_id:
                try:
                    await release_idempotency_key(client_request_id, idem_scope)
                except Exception:
                    pass
            raise HTTPException(status_code=504, detail="Database is slow right now. Please try again.")
        except Exception as e:
            if client_request_id:
                try:
                    await release_idempotency_key(client_request_id, idem_scope)
                except Exception:
                    pass
            if _is_timeout_err(e):
                raise HTTPException(status_code=504, detail="Database is slow right now. Please try again.")
            raise

        # Activity log — best-effort, never block submission
        try:
            await asyncio.wait_for(
                log_activity(
                    user_id=uid,
                    action_type="payment_submission",
                    description=f"Submitted payment for {plan} ({duration})",
                    metadata={"payment_id": payment_id, "amount": amount, "utr": utr_number[-4:]}
                ),
                timeout=5.0,
            )
        except Exception:
            pass

        response = {
            "success": True,
            "payment_id": payment_id,
            "message": "Payment submitted for verification"
        }
        if client_request_id:
            try:
                await store_idempotency_response(
                    client_request_id, idem_scope, response, ttl_seconds=600
                )
            except Exception:
                pass
        return response

    except HTTPException:
        raise
    except Exception as e:
        err_str = str(e).lower()
        if any(t in err_str for t in ["timeout", "timed out", "serverselection", "networktimeout"]):
            raise HTTPException(
                status_code=504,
                detail="Database is slow right now. Please try again — your action will work next time.",
            )
        logging.error(f"[SUB-PAYMENT] Unexpected error for {uid}: {e}")
        raise HTTPException(status_code=500, detail=get_user_friendly_error(e))

