@api_router.get("/admin/subscription-stats")
async def get_subscription_stats():
    """Get subscription statistics using fast aggregation queries — Phase-2 perf: 60s cache."""
    CACHE_KEY = "admin:subscription_stats:v1"
    if cache:
        try:
            cached = await cache.get(CACHE_KEY)
            if cached:
                return cached
        except Exception:
            pass
    try:
        now = datetime.now(timezone.utc)
        week_later = now + timedelta(days=7)
        # Single $facet over users collection — replaces 2 separate round-trips.
        users_facet_pipeline = [
            {"$facet": {
                "plan_counts": [
                    {"$group": {
                        "_id": {"$ifNull": ["$subscription_plan", "explorer"]},
                        "count": {"$sum": 1}
                    }}
                ],
                "expiring_this_week": [
                    {"$match": {
                        "subscription_expiry": {
                            "$gte": now.isoformat(),
                            "$lte": week_later.isoformat()
                        }
                    }},
                    {"$count": "n"}
                ],
            }}
        ]
        # Fire users-facet + vip_payments count in parallel (different collections)
        users_facet_task = db.users.aggregate(users_facet_pipeline, allowDiskUse=True).to_list(1)
        pending_payments_task = db.vip_payments.count_documents({"status": "pending"})
        users_facet_result, pending_payments = await asyncio.gather(
            users_facet_task, pending_payments_task
        )

        facet_doc = users_facet_result[0] if users_facet_result else {}
        plan_counts_result = facet_doc.get("plan_counts") or []
        expiring_arr = facet_doc.get("expiring_this_week") or []
        expiring_count = expiring_arr[0]["n"] if expiring_arr else 0

        plan_counts = {"explorer": 0, "startup": 0, "growth": 0, "elite": 0}
        total_users = 0
        for item in plan_counts_result:
            plan = item["_id"] or "explorer"
            if plan in plan_counts:
                plan_counts[plan] = item["count"]
            else:
                plan_counts["explorer"] += item["count"]
            total_users += item["count"]

        # Calculate approximate revenue (current pricing: startup 299, growth 549, elite 999 base — GST excluded)
        monthly_revenue = (plan_counts["startup"] * 299) + (plan_counts["growth"] * 549) + (plan_counts["elite"] * 999)
        
        payload = {
            "total_users": total_users,
            "plan_counts": plan_counts,
            "pending_payments": pending_payments,
            "expiring_this_week": expiring_count,
            "monthly_revenue": monthly_revenue
        }
        if cache:
            try:
                await cache.set(CACHE_KEY, payload, ttl=60)
            except Exception:
                pass
        return payload
    except Exception as e:
        return {"error": str(e)}


@api_router.get("/admin/paid-users-wallet-summary")
async def get_paid_users_wallet_summary():
    """
    Get wallet summary for PAID users only (startup, growth, elite)
    Returns:
    - Total PRC balance for all paid users with INR value
    - Total PRC redeemed with INR value
    - Breakdown by plan type

    Conversion: 10 PRC = ₹1 INR
    Phase-2 perf: 120s cache (4 cross-collection $lookup aggregations).
    """
    CACHE_KEY = "admin:paid_users_wallet_summary:v1"
    if cache:
        try:
            cached = await cache.get(CACHE_KEY)
            if cached:
                return cached
        except Exception:
            pass
    try:
        # Define paid plans
        paid_plans = ["startup", "growth", "elite", "vip", "pro"]
        
        # Get total PRC balance for paid users
        prc_balance_pipeline = [
            {"$match": {"subscription_plan": {"$in": paid_plans}}},
            {"$group": {
                "_id": "$subscription_plan",
                "total_prc": {"$sum": "$prc_balance"},
                "user_count": {"$sum": 1}
            }}
        ]
        prc_by_plan = await db.users.aggregate(prc_balance_pipeline).to_list(10)
        
        # Calculate totals
        total_prc_balance = 0
        plan_breakdown = {}
        total_paid_users = 0
        
        for item in prc_by_plan:
            plan = item["_id"]
            prc = item["total_prc"] or 0
            count = item["user_count"]
            total_prc_balance += prc
            total_paid_users += count
            plan_breakdown[plan] = {
                "total_prc": round(prc, 2),
                "inr_value": round(prc / 10, 2),
                "user_count": count
            }
        
        # Get total redeemed by paid users
        # 1. Bank Redemptions (EMI Pay)
        bank_redeems = await db.bank_redeems.aggregate([
            {"$match": {"status": "approved"}},
            {"$lookup": {
                "from": "users",
                "localField": "user_id",
                "foreignField": "uid",
                "as": "user"
            }},
            {"$unwind": "$user"},
            {"$match": {"user.subscription_plan": {"$in": paid_plans}}},
            {"$group": {"_id": None, "total": {"$sum": "$prc_amount"}}}
        ]).to_list(1)
        bank_redeemed_prc = bank_redeems[0]["total"] if bank_redeems else 0
        
        # 2. Bill Payments
        valid_redeemed = ["approved", "completed", "paid"]
        bill_payments = await db.bill_payments.aggregate([
            {"$match": {"status": {"$in": valid_redeemed}}},
            {"$lookup": {
                "from": "users",
                "localField": "user_id",
                "foreignField": "uid",
                "as": "user"
            }},
            {"$unwind": "$user"},
            {"$match": {"user.subscription_plan": {"$in": paid_plans}}},
            {"$group": {"_id": None, "total": {"$sum": "$total_prc_deducted"}}}
        ]).to_list(1)
        bill_redeemed_prc = bill_payments[0]["total"] if bill_payments else 0
        
        # 3. Gift Vouchers
        vouchers = await db.gift_voucher_requests.aggregate([
            {"$match": {"status": {"$in": valid_redeemed}}},
            {"$lookup": {
                "from": "users",
                "localField": "user_id",
                "foreignField": "uid",
                "as": "user"
            }},
            {"$unwind": "$user"},
            {"$match": {"user.subscription_plan": {"$in": paid_plans}}},
            {"$group": {"_id": None, "total": {"$sum": "$total_prc_deducted"}}}
        ]).to_list(1)
        voucher_redeemed_prc = vouchers[0]["total"] if vouchers else 0
        
        # 4. Marketplace Orders
        orders = await db.marketplace_orders.aggregate([
            {"$match": {"status": {"$in": valid_redeemed}}},
            {"$lookup": {
                "from": "users",
                "localField": "user_id",
                "foreignField": "uid",
                "as": "user"
            }},
            {"$unwind": "$user"},
            {"$match": {"user.subscription_plan": {"$in": paid_plans}}},
            {"$group": {"_id": None, "total": {"$sum": "$total_prc"}}}
        ]).to_list(1)
        orders_redeemed_prc = orders[0]["total"] if orders else 0
        
        # Calculate total redeemed
        total_redeemed_prc = bank_redeemed_prc + bill_redeemed_prc + voucher_redeemed_prc + orders_redeemed_prc
        
        payload = {
            "summary": {
                "total_paid_users": total_paid_users,
                "total_prc_balance": round(total_prc_balance, 2),
                "total_prc_inr_value": round(total_prc_balance / 10, 2),
                "total_redeemed_prc": round(total_redeemed_prc, 2),
                "total_redeemed_inr": round(total_redeemed_prc / 10, 2)
            },
            "balance_by_plan": plan_breakdown,
            "redemption_breakdown": {
                "bank_redeem": {
                    "prc": round(bank_redeemed_prc, 2),
                    "inr": round(bank_redeemed_prc / 10, 2)
                },
                "bill_payments": {
                    "prc": round(bill_redeemed_prc, 2),
                    "inr": round(bill_redeemed_prc / 10, 2)
                },
                "gift_vouchers": {
                    "prc": round(voucher_redeemed_prc, 2),
                    "inr": round(voucher_redeemed_prc / 10, 2)
                },
                "marketplace_orders": {
                    "prc": round(orders_redeemed_prc, 2),
                    "inr": round(orders_redeemed_prc / 10, 2)
                }
            },
            "conversion_rate": "10 PRC = ₹1 INR"
        }
        if cache:
            try:
                await cache.set(CACHE_KEY, payload, ttl=120)
            except Exception:
                pass
        return payload
        
    except Exception as e:
        logging.error(f"Error getting paid users wallet summary: {e}")
        return {"error": str(e)}


@api_router.get("/admin/subscription-analytics")
async def get_subscription_analytics(period: str = "month"):
    """
    Admin API: Get detailed subscription analytics
    - New subscriptions vs Renewals
    - Upgrades vs Downgrades
    - Revenue breakdown
    - User retention stats
    """
    try:
        now = datetime.now(timezone.utc)
        
        # Calculate period start
        if period == "today":
            period_start = now.replace(hour=0, minute=0, second=0, microsecond=0)
        elif period == "week":
            period_start = now - timedelta(days=7)
        elif period == "month":
            period_start = now - timedelta(days=30)
        elif period == "year":
            period_start = now - timedelta(days=365)
        else:
            period_start = now - timedelta(days=30)
        
        period_start_str = period_start.isoformat()
        
        # Get approved payments in this period with subscription_type breakdown
        type_pipeline = [
            {
                "$match": {
                    "status": "approved",
                    "approved_at": {"$gte": period_start_str}
                }
            },
            {
                "$group": {
                    "_id": {"$ifNull": ["$subscription_type", "unknown"]},
                    "count": {"$sum": 1},
                    "revenue": {"$sum": {"$ifNull": ["$amount", 0]}}
                }
            }
        ]
        
        type_stats = await db.vip_payments.aggregate(type_pipeline).to_list(10)
        
        # Convert to dict
        subscription_breakdown = {
            "new": {"count": 0, "revenue": 0},
            "renewal": {"count": 0, "revenue": 0},
            "upgrade": {"count": 0, "revenue": 0},
            "downgrade": {"count": 0, "revenue": 0},
            "unknown": {"count": 0, "revenue": 0}  # Legacy payments without type
        }
        
        total_subscriptions = 0
        total_revenue = 0
        
        for item in type_stats:
            sub_type = item["_id"] or "unknown"
            if sub_type in subscription_breakdown:
                subscription_breakdown[sub_type]["count"] = item["count"]
                subscription_breakdown[sub_type]["revenue"] = item["revenue"]
            else:
                subscription_breakdown["unknown"]["count"] += item["count"]
                subscription_breakdown["unknown"]["revenue"] += item["revenue"]
            
            total_subscriptions += item["count"]
            total_revenue += item["revenue"]
        
        # Plan-wise breakdown
        plan_pipeline = [
            {
                "$match": {
                    "status": "approved",
                    "approved_at": {"$gte": period_start_str}
                }
            },
            {
                "$group": {
                    "_id": {
                        "plan": {"$ifNull": ["$subscription_plan", "startup"]},
                        "type": {"$ifNull": ["$subscription_type", "unknown"]}
                    },
                    "count": {"$sum": 1},
                    "revenue": {"$sum": {"$ifNull": ["$amount", 0]}}
                }
            }
        ]
        
        plan_stats = await db.vip_payments.aggregate(plan_pipeline).to_list(50)
        
        plan_breakdown = {}
        for item in plan_stats:
            plan = item["_id"]["plan"]
            sub_type = item["_id"]["type"]
            
            if plan not in plan_breakdown:
                plan_breakdown[plan] = {"new": 0, "renewal": 0, "upgrade": 0, "downgrade": 0, "total": 0, "revenue": 0}
            
            if sub_type in ["new", "renewal", "upgrade", "downgrade"]:
                plan_breakdown[plan][sub_type] = item["count"]
            plan_breakdown[plan]["total"] += item["count"]
            plan_breakdown[plan]["revenue"] += item["revenue"]
        
        # First-time subscribers count (users with subscription_count = 1)
        first_time_subscribers = await db.users.count_documents({
            "subscription_count": 1,
            "subscription_plan": {"$in": ["startup", "growth", "elite"]}
        })
        
        # Returning subscribers (subscription_count > 1)
        returning_subscribers = await db.users.count_documents({
            "subscription_count": {"$gt": 1},
            "subscription_plan": {"$in": ["startup", "growth", "elite"]}
        })
        
        # Expiring soon (for renewal predictions)
        expiring_7_days = await db.users.count_documents({
            "subscription_plan": {"$in": ["startup", "growth", "elite"]},
            "subscription_expiry": {
                "$gte": now.isoformat(),
                "$lte": (now + timedelta(days=7)).isoformat()
            }
        })
        
        expiring_30_days = await db.users.count_documents({
            "subscription_plan": {"$in": ["startup", "growth", "elite"]},
            "subscription_expiry": {
                "$gte": now.isoformat(),
                "$lte": (now + timedelta(days=30)).isoformat()
            }
        })
        
        return {
            "period": period,
            "period_start": period_start_str,
            "summary": {
                "total_subscriptions": total_subscriptions,
                "total_revenue": total_revenue,
                "new_subscriptions": subscription_breakdown["new"]["count"],
                "renewals": subscription_breakdown["renewal"]["count"],
                "upgrades": subscription_breakdown["upgrade"]["count"],
                "downgrades": subscription_breakdown["downgrade"]["count"]
            },
            "subscription_breakdown": subscription_breakdown,
            "plan_breakdown": plan_breakdown,
            "user_stats": {
                "first_time_subscribers": first_time_subscribers,
                "returning_subscribers": returning_subscribers,
                "retention_rate": round((returning_subscribers / (first_time_subscribers + returning_subscribers) * 100), 2) if (first_time_subscribers + returning_subscribers) > 0 else 0
            },
            "upcoming_renewals": {
                "expiring_7_days": expiring_7_days,
                "expiring_30_days": expiring_30_days
            }
        }
    except Exception as e:
        print(f"Error in subscription analytics: {e}")
        raise HTTPException(status_code=500, detail=get_user_friendly_error(e))

