async def cleanup_database(request: Request):
    """
    Admin: Clean up test data from database
    WARNING: This will delete all users except admin accounts!
    Requires confirmation code: 'CONFIRM_DELETE_ALL'
    """
    data = await request.json()
    confirmation = data.get("confirmation")
    keep_emails = data.get("keep_emails", ["admin@paras.com"])  # Emails to keep
    
    if confirmation != "CONFIRM_DELETE_ALL":
        raise HTTPException(
            status_code=400, 
            detail="Invalid confirmation. Send {'confirmation': 'CONFIRM_DELETE_ALL'} to proceed"
        )
    
    try:
        # Count before deletion
        total_users = await db.users.count_documents({})
        admin_users = await db.users.count_documents({"email": {"$in": keep_emails}})
        
        # Delete all users EXCEPT those in keep_emails
        delete_result = await db.users.delete_many({
            "email": {"$nin": keep_emails}
        })
        
        # Clean up related collections
        deleted_transactions = await db.transactions.delete_many({})
        deleted_orders = await db.orders.delete_many({})
        deleted_payments = await db.vip_payments.delete_many({})
        deleted_wallet_txns = await db.wallet_transactions.delete_many({})
        deleted_notifications = await db.notifications.delete_many({})
        deleted_activity = await db.activity_logs.delete_many({})
        
        # Reset admin user's data (optional - keep the account but reset stats)
        for email in keep_emails:
            await db.users.update_one(
                {"email": email},
                {
                    "$set": {
                        "prc_balance": 0,
                        "cash_balance": 0,
                        "total_mined": 0,
                        "taps_today": 0,
                        "mining_history": [],
                        "subscription_plan": "elite",  # Keep admin as elite
                        "subscription_expiry": (datetime.now(timezone.utc) + timedelta(days=365)).isoformat()
                    }
                }
            )
        
        return {
            "success": True,
            "message": "Database cleaned successfully",
            "deleted": {
                "users": delete_result.deleted_count,
                "transactions": deleted_transactions.deleted_count,
                "orders": deleted_orders.deleted_count,
                "payments": deleted_payments.deleted_count,
                "wallet_transactions": deleted_wallet_txns.deleted_count,
                "notifications": deleted_notifications.deleted_count,
                "activity_logs": deleted_activity.deleted_count
            },
            "kept_users": keep_emails,
            "before_count": total_users,
            "after_count": await db.users.count_documents({})
        }
        
    except Exception as e:
        logging.error(f"Database cleanup error: {e}")
        raise HTTPException(status_code=500, detail=get_user_friendly_error(e))

async def get_database_stats():
    """Get database statistics"""
    stats = {
        "users": await db.users.count_documents({}),
        "transactions": await db.transactions.count_documents({}),
        "orders": await db.orders.count_documents({}),
        "vip_payments": await db.vip_payments.count_documents({}),
        "wallet_transactions": await db.wallet_transactions.count_documents({}),
        "notifications": await db.notifications.count_documents({}),
        "products": await db.products.count_documents({}),
        "activity_logs": await db.activity_logs.count_documents({})
    }
    
    # User breakdown by subscription
    subscription_counts = {}
    for plan in ["explorer", "startup", "growth", "elite"]:
        subscription_counts[plan] = await db.users.count_documents({"subscription_plan": plan})
    subscription_counts["no_plan"] = await db.users.count_documents({"subscription_plan": {"$exists": False}})
    
    stats["subscription_breakdown"] = subscription_counts
    
    return stats

@api_router.get("/settings/public")
async def get_public_settings():
    """Get public settings (payment UPI, company info, etc.)"""
    # Get fresh PRC rate from economy (always fresh, no cache for this value)
    prc_to_inr_rate = await get_dynamic_prc_rate()
    
    settings = await db.settings.find_one({}, {"_id": 0})
    payment_config = await db.payment_config.find_one({}, {"_id": 0})
    
    # Get UPI from payment_config first, then fallback to settings
    payment_upi = ""
    qr_code_url = ""
    bank_details = {}
    payment_instructions = ""
    
    if payment_config:
        payment_upi = payment_config.get("upi_id", "")
        qr_code_url = payment_config.get("qr_code_url", "")
        payment_instructions = payment_config.get("instructions", "")
        if payment_config.get("account_number"):
            bank_details = {
                "bank_name": payment_config.get("bank_name", ""),
                "account_number": payment_config.get("account_number", ""),
                "ifsc_code": payment_config.get("ifsc_code", ""),
                "account_holder": payment_config.get("account_holder", "")
            }
    
    # Fallback to settings if payment_config is empty
    if not payment_upi and settings:
        payment_upi = settings.get("payment_upi_id", "paras@upi")
    
    # Check if manual subscription is enabled
    manual_subscription_enabled = True
    manual_sub_setting = await db.app_settings.find_one({"key": "manual_subscription_enabled"})
    if manual_sub_setting:
        manual_subscription_enabled = manual_sub_setting.get("value", True)
    
    # Check if Razorpay is enabled
    razorpay_enabled = True
    razorpay_setting = await db.app_settings.find_one({"key": "razorpay_enabled"})
    if razorpay_setting:
        razorpay_enabled = razorpay_setting.get("value", True)
    
    # Check if PRC subscription payment is enabled
    prc_subscription_enabled = True
    prc_sub_setting = await db.app_settings.find_one({"key": "prc_subscription_enabled"})
    if prc_sub_setting:
        prc_subscription_enabled = prc_sub_setting.get("value", True)
    
    # prc_to_inr_rate already fetched above
    
    result = {
        "payment_upi_id": payment_upi or "paras@upi",
        "qr_code_url": qr_code_url,
        "bank_details": bank_details,
        "payment_instructions": payment_instructions,
        "company_name": settings.get("company_name", "PARAS REWARD") if settings else "PARAS REWARD",
        "support_email": settings.get("support_email", "support@parasreward.com") if settings else "support@parasreward.com",
        "support_phone": settings.get("support_phone", "+91 9876543210") if settings else "+91 9876543210",
        "manual_subscription_enabled": manual_subscription_enabled,
        "razorpay_enabled": razorpay_enabled,
        "prc_subscription_enabled": prc_subscription_enabled,
        "prc_to_inr_rate": prc_to_inr_rate
    }
    
    return result


@api_router.post("/admin/toggle-manual-subscription")
async def toggle_manual_subscription(request: Request):
    """Enable or disable manual subscription (UPI/Bank Transfer) payment method"""
    try:
        data = await request.json()
        enabled = data.get("enabled", True)
        admin_pin = data.get("admin_pin")
        
        if admin_pin != ADMIN_OPERATION_PIN:
            raise HTTPException(status_code=403, detail="Invalid admin PIN")
        
        await db.app_settings.update_one(
            {"key": "manual_subscription_enabled"},
            {"$set": {"key": "manual_subscription_enabled", "value": enabled, "updated_at": datetime.now(timezone.utc).isoformat()}},
            upsert=True
        )
        
        # Clear public settings cache
        await cache.delete("public_settings")
        
        return {
            "success": True,
            "message": f"Manual subscription {'enabled' if enabled else 'disabled'}",
            "enabled": enabled
        }
    except HTTPException:
        raise
    except Exception as e:
        raise HTTPException(status_code=500, detail=get_user_friendly_error(e))


