@api_router.get("/admin/prc-subscription-stats")
async def get_prc_subscription_stats():
    """
    Get statistics of subscriptions activated via PRC vs Razorpay
    Shows how many users paid with PRC balance
    Phase-2 perf: 90s cache.
    """
    CACHE_KEY = "admin:prc_subscription_stats:v1"
    if cache:
        try:
            cached = await cache.get(CACHE_KEY)
            if cached:
                return cached
        except Exception:
            pass
    try:
        now = datetime.now(timezone.utc)
        today_start = now.replace(hour=0, minute=0, second=0, microsecond=0)
        week_start = today_start - timedelta(days=now.weekday())
        month_start = today_start.replace(day=1)
        
        # Count PRC subscriptions
        prc_total = await db.subscription_payments.count_documents({"payment_method": "prc"})
        prc_today = await db.subscription_payments.count_documents({
            "payment_method": "prc",
            "created_at": {"$gte": today_start.isoformat()}
        })
        prc_week = await db.subscription_payments.count_documents({
            "payment_method": "prc",
            "created_at": {"$gte": week_start.isoformat()}
        })
        prc_month = await db.subscription_payments.count_documents({
            "payment_method": "prc",
            "created_at": {"$gte": month_start.isoformat()}
        })
        
        # Total PRC amount used for subscriptions
        prc_amount_pipeline = [
            {"$match": {"payment_method": "prc"}},
            {"$group": {"_id": None, "total": {"$sum": "$prc_amount"}}}
        ]
        prc_amount_result = await db.subscription_payments.aggregate(prc_amount_pipeline).to_list(1)
        total_prc_used = prc_amount_result[0]["total"] if prc_amount_result else 0
        
        # Count Razorpay subscriptions
        razorpay_total = await db.razorpay_orders.count_documents({"status": "paid"})
        razorpay_today = await db.razorpay_orders.count_documents({
            "status": "paid",
            "paid_at": {"$gte": today_start}
        })
        razorpay_week = await db.razorpay_orders.count_documents({
            "status": "paid",
            "paid_at": {"$gte": week_start}
        })
        razorpay_month = await db.razorpay_orders.count_documents({
            "status": "paid",
            "paid_at": {"$gte": month_start}
        })
        
        # Total Razorpay revenue
        razorpay_amount_pipeline = [
            {"$match": {"status": "paid"}},
            {"$group": {"_id": None, "total": {"$sum": "$amount"}}}
        ]
        razorpay_amount_result = await db.razorpay_orders.aggregate(razorpay_amount_pipeline).to_list(1)
        total_razorpay_revenue = razorpay_amount_result[0]["total"] if razorpay_amount_result else 0
        
        # Plan-wise breakdown for PRC
        prc_plan_pipeline = [
            {"$match": {"payment_method": "prc"}},
            {"$group": {
                "_id": "$plan_name",
                "count": {"$sum": 1},
                "total_prc": {"$sum": "$prc_amount"}
            }}
        ]
        prc_by_plan = await db.subscription_payments.aggregate(prc_plan_pipeline).to_list(10)
        
        # Recent PRC subscriptions (last 10)
        recent_prc = await db.subscription_payments.find(
            {"payment_method": "prc"},
            {"_id": 0, "user_id": 1, "user_name": 1, "plan_name": 1, "prc_amount": 1, "created_at": 1}
        ).sort("created_at", -1).limit(10).to_list(10)
        
        # Users currently active with PRC subscription
        active_prc_users = await db.users.count_documents({
            "subscription_plan": {"$in": ["elite", "growth", "startup"]},
            "subscription_expiry": {"$gt": now.isoformat()},
            "last_prc_subscription": {"$exists": True}
        })
        
        payload = {
            "success": True,
            "prc_subscriptions": {
                "total": prc_total,
                "today": prc_today,
                "this_week": prc_week,
                "this_month": prc_month,
                "total_prc_used": total_prc_used,
                "active_users": active_prc_users
            },
            "razorpay_subscriptions": {
                "total": razorpay_total,
                "today": razorpay_today,
                "this_week": razorpay_week,
                "this_month": razorpay_month,
                "total_revenue": total_razorpay_revenue
            },
            "comparison": {
                "prc_percentage": round((prc_total / (prc_total + razorpay_total) * 100), 1) if (prc_total + razorpay_total) > 0 else 0,
                "razorpay_percentage": round((razorpay_total / (prc_total + razorpay_total) * 100), 1) if (prc_total + razorpay_total) > 0 else 0,
                "total_subscriptions": prc_total + razorpay_total
            },
            "prc_by_plan": {item["_id"]: {"count": item["count"], "total_prc": item["total_prc"]} for item in prc_by_plan},
            "recent_prc_subscriptions": recent_prc
        }
        if cache:
            try:
                await cache.set(CACHE_KEY, payload, ttl=90)
            except Exception:
                pass
        return payload
        
    except Exception as e:
        logging.error(f"Error getting PRC subscription stats: {e}")
        raise HTTPException(status_code=500, detail=str(e))


@api_router.post("/admin/update-prc-rate")
async def update_prc_rate(request: Request):
    """Admin: Update PRC to INR conversion rate"""
    try:
        data = await request.json()
        new_rate = data.get("prc_to_inr_rate")
        admin_pin = data.get("admin_pin")
        
        if not new_rate or new_rate <= 0:
            raise HTTPException(status_code=400, detail="Invalid rate. Must be a positive number")
        
        if admin_pin != ADMIN_OPERATION_PIN:
            raise HTTPException(status_code=403, detail="Invalid admin PIN")
        
        # Update rate in app_settings
        await db.app_settings.update_one(
            {"key": "prc_to_inr_rate"},
            {"$set": {"key": "prc_to_inr_rate", "value": new_rate, "updated_at": datetime.now(timezone.utc).isoformat()}},
            upsert=True
        )
        
        # Also update in main settings collection
        await db.settings.update_one(
            {},
            {"$set": {"prc_to_inr_rate": new_rate}},
            upsert=True
        )
        
        # Clear public settings cache
        await cache.delete("public_settings")
        
        return {
            "success": True,
            "message": f"PRC to INR rate updated to {new_rate}",
            "prc_to_inr_rate": new_rate
        }
    except HTTPException:
        raise
    except Exception as e:
        raise HTTPException(status_code=500, detail=get_user_friendly_error(e))


@api_router.post("/admin/prc-rate/manual-override")
async def set_manual_prc_rate_override(request: Request):
    """
    Admin: Set manual PRC rate override.
    This overrides the dynamic economy calculation.
    
    Body:
    - rate: The PRC rate to set (e.g., 10 means 10 PRC = ₹1)
    - enabled: true/false to enable/disable override
    - expires_hours: Optional - hours until override expires (null = permanent)
    """
    try:
        data = await request.json()
        rate = data.get("rate")
        enabled = data.get("enabled", True)
        expires_hours = data.get("expires_hours")  # null = permanent
        
        if enabled and (not rate or rate <= 0):
            raise HTTPException(status_code=400, detail="Invalid rate. Must be a positive number")
        
        now = datetime.now(timezone.utc)
        expires_at = None
        if expires_hours:
            expires_at = (now + timedelta(hours=int(expires_hours))).isoformat()
        
        await db.app_settings.update_one(
            {"key": "prc_rate_manual_override"},
            {"$set": {
                "key": "prc_rate_manual_override",
                "enabled": enabled,
                "rate": int(rate) if rate else None,
                "expires_at": expires_at,
                "set_at": now.isoformat(),
                "set_by": "admin"
            }},
            upsert=True
        )
        
        # Clear cache
        await cache.delete("public_settings")
        
        if enabled:
            return {
                "success": True,
                "message": f"Manual PRC rate override set to {rate}",
                "rate": rate,
                "expires_at": expires_at,
                "note": "Permanent override" if not expires_at else f"Expires in {expires_hours} hours"
            }
        else:
            return {
                "success": True,
                "message": "Manual PRC rate override disabled. Using dynamic economy rate.",
                "enabled": False
            }
    except HTTPException:
        raise
    except Exception as e:
        raise HTTPException(status_code=500, detail=get_user_friendly_error(e))


@api_router.get("/admin/prc-rate/current")
async def get_current_rate_info():
    """Get current PRC rate with details about source (override/dynamic/fallback)"""
    try:
        current_rate = await get_dynamic_prc_rate()
        
        # Check override status
        override = await db.app_settings.find_one({"key": "prc_rate_manual_override"})
        override_active = False
        override_info = None
        
        if override and override.get("enabled"):
            expires_at = override.get("expires_at")
            if expires_at:
                try:
                    expiry = datetime.fromisoformat(expires_at.replace('Z', '+00:00'))
                    if expiry > datetime.now(timezone.utc):
                        override_active = True
                        override_info = {
                            "rate": override.get("rate"),
                            "expires_at": expires_at,
                            "set_at": override.get("set_at")
                        }
                except:
                    pass
            else:
                override_active = True
                override_info = {
                    "rate": override.get("rate"),
                    "expires_at": None,
                    "set_at": override.get("set_at"),
                    "permanent": True
                }
        
        from fastapi.responses import JSONResponse
        response = JSONResponse(content={
            "success": True,
            "current_rate": current_rate,
            "source": "manual_override" if override_active else "dynamic_economy",
            "override": override_info,
            "note": f"Currently {current_rate} PRC = ₹1",
            "timestamp": datetime.now(timezone.utc).isoformat(),
            "cache_ttl_seconds": 300  # 5 minutes - frontend should refetch after this
        })
        # Add cache control headers to prevent stale rate caching
        response.headers["Cache-Control"] = "no-cache, no-store, must-revalidate"
        response.headers["Pragma"] = "no-cache"
        response.headers["Expires"] = "0"
        return response
    except Exception as e:
        return {"success": False, "error": str(e)}


