# ========== AUTO-RENEWAL NOTIFICATIONS ==========

async def send_renewal_notifications():
    """
    Send renewal notifications to users whose subscription is expiring
    Sends at: 15 days, 7 days, 3 days, 1 day before expiry
    """
    now = datetime.now(timezone.utc)
    
    # Define notification triggers
    notification_triggers = [
        {"days": 15, "urgency": "low", "emoji": "📅"},
        {"days": 7, "urgency": "medium", "emoji": "⚠️"},
        {"days": 3, "urgency": "high", "emoji": "🔔"},
        {"days": 1, "urgency": "critical", "emoji": "🚨"},
    ]
    
    notifications_sent = 0
    notified_users = []
    
    for trigger in notification_triggers:
        days = trigger["days"]
        target_date = now + timedelta(days=days)
        # Check users expiring on this specific day (±12 hours window)
        window_start = target_date - timedelta(hours=12)
        window_end = target_date + timedelta(hours=12)
        
        # FIX: Use to_list() instead of async for to prevent cursor leak
        expiring_users = await db.users.find({
            "subscription_plan": {"$in": ["startup", "growth", "elite"]},
            "subscription_expiry": {"$exists": True}
        }).to_list(length=1000)
        
        for user in expiring_users:
            expiry_str = user.get("subscription_expiry")
            if not expiry_str:
                continue
                
            try:
                expiry = datetime.fromisoformat(expiry_str.replace('Z', '+00:00'))
                if expiry.tzinfo is None:
                    expiry = expiry.replace(tzinfo=timezone.utc)
                
                # Check if expiry falls in this trigger window
                if window_start <= expiry <= window_end:
                    uid = user.get("uid")
                    days_left = max(1, (expiry - now).days)
                    
                    # Check if notification already sent today for this trigger
                    today_start = now.replace(hour=0, minute=0, second=0, microsecond=0)
                    existing = await db.notifications.find_one({
                        "user_id": uid,
                        "notification_type": "subscription_expiry",
                        "created_at": {"$gte": today_start.isoformat()},
                        "data.days_trigger": days
                    })
                    
                    if existing:
                        continue  # Already notified today
                    
                    # Create notification
                    plan_name = user.get("subscription_plan", "").capitalize()
                    
                    if days == 1:
                        title = f"{trigger['emoji']} LAST DAY! {plan_name} expires tomorrow"
                        message = f"Your {plan_name} plan expires TOMORROW! Renew now to keep your benefits."
                    elif days == 3:
                        title = f"{trigger['emoji']} {plan_name} expiring in 3 days"
                        message = f"Don't lose your {plan_name} benefits! Only 3 days left to renew."
                    elif days == 7:
                        title = f"{trigger['emoji']} {plan_name} expiring in 1 week"
                        message = f"Your {plan_name} subscription expires in 7 days. Plan your renewal!"
                    else:
                        title = f"{trigger['emoji']} {plan_name} renewal reminder"
                        message = f"Your {plan_name} plan will expire in {days_left} days ({expiry_str[:10]})."
                    
                    await db.notifications.insert_one({
                        "notification_id": str(uuid.uuid4()),
                        "user_id": uid,
                        "title": title,
                        "message": message,
                        "notification_type": "subscription_expiry",
                        "data": {
                            "days_trigger": days,
                            "plan": user.get("subscription_plan"),
                            "expiry_date": expiry_str
                        },
                        "read": False,
                        "created_at": now.isoformat()
                    })
                    
                    notifications_sent += 1
                    notified_users.append({
                        "uid": uid,
                        "email": user.get("email"),
                        "plan": user.get("subscription_plan"),
                        "days_left": days_left,
                        "urgency": trigger["urgency"]
                    })
                    
            except Exception as e:
                print(f"[RENEWAL NOTIFY] Error for user {user.get('uid')}: {e}")
                continue
    
    return {
        "success": True,
        "notifications_sent": notifications_sent,
        "users": notified_users
    }


@api_router.post("/admin/trigger-renewal-notifications")
async def trigger_renewal_notifications():
    """Admin: Manually trigger renewal notification check"""
    result = await send_renewal_notifications()
    return result

@api_router.get("/subscription/expiring")
async def get_expiring_subscriptions():
    """Get list of subscriptions expiring within 7 days"""
    now = datetime.now(timezone.utc)
    expiry_threshold = now + timedelta(days=7)
    
    expiring_users = []
    # FIX: Use to_list() instead of async for to prevent cursor leak
    all_users = await db.users.find({
        "subscription_plan": {"$in": ["startup", "growth", "elite"]},
        "subscription_expiry": {"$exists": True}
    }, {"_id": 0, "password_hash": 0}).to_list(length=1000)
    
    for user in all_users:
        expiry_str = user.get("subscription_expiry")
        if expiry_str:
            try:
                expiry = datetime.fromisoformat(expiry_str.replace('Z', '+00:00'))
                if expiry.tzinfo is None:
                    expiry = expiry.replace(tzinfo=timezone.utc)
                
                if now < expiry <= expiry_threshold:
                    user["days_until_expiry"] = (expiry - now).days
                    expiring_users.append(user)
            except:
                pass
    
    return {"expiring_users": expiring_users, "count": len(expiring_users)}


# ========== USER: ACTIVATE UPCOMING PLAN ==========

@api_router.post("/subscription/activate-upcoming/{uid}")
async def user_activate_upcoming(uid: str):
    """
    User-facing: Manually activate an upcoming plan.
    Only works when current plan is expired/explorer AND upcoming plan exists.
    """
    user = await db.users.find_one({"uid": uid}, {"_id": 0, "subscription_plan": 1, "subscription_expiry": 1, "subscription_expired": 1})
    if not user:
        raise HTTPException(status_code=404, detail="User not found")

    plan = user.get("subscription_plan", "explorer")
    is_expired = user.get("subscription_expired", False)

    # Check if current plan is still active (non-expired paid plan)
    if plan not in ["explorer", "free", "", None] and not is_expired:
        expiry_val = get_user_expiry(user)
        if expiry_val:
            from routes.admin_subscription import parse_expiry
            expiry_dt = parse_expiry(expiry_val)
            from datetime import datetime, timezone
            if expiry_dt and expiry_dt > datetime.now(timezone.utc):
                return {"success": False, "message": "Your current plan is still active. Upcoming plan will auto-activate after expiry."}

    # Check if upcoming plan exists
    upcoming = await db.subscription_payments.find_one(
        {"user_id": uid, "status": "upcoming"},
        {"_id": 0}
    )
    if not upcoming:
        return {"success": False, "message": "No upcoming plan found."}

    # Activate the upcoming plan
    from routes.admin_subscription import check_and_activate_upcoming
    result = await check_and_activate_upcoming(uid)

    if result:
        # Clear cache
        if cache:
            await cache.delete(f"user_data:{uid}")
            await cache.delete(f"user:dashboard:{uid}")
        return {
            "success": True,
            "message": f"{result.get('plan_name', 'Plan')} activated successfully!",
            "activated_plan": result.get("plan_name"),
        }
    else:
        return {"success": False, "message": "Could not activate upcoming plan. Please contact support."}


# ========== PLAN UPGRADE/DOWNGRADE ==========

@api_router.post("/subscription/upgrade/{uid}")
async def upgrade_subscription(uid: str, request: Request):
    """Admin: Upgrade user's subscription plan"""
    data = await request.json()
    new_plan = data.get("plan")
    extend_days = data.get("extend_days", 0)
    
    if new_plan not in ["explorer", "elite"]:
        raise HTTPException(status_code=400, detail="Invalid plan. Only 'explorer' or 'elite' are allowed.")
    
    user = await db.users.find_one({"uid": uid})
    if not user:
        raise HTTPException(status_code=404, detail="User not found")
    
    now = datetime.now(timezone.utc)
    current_expiry = user.get("subscription_expiry")
    
    # Calculate new expiry
    if current_expiry:
        try:
            expiry_dt = datetime.fromisoformat(current_expiry.replace('Z', '+00:00'))
            if expiry_dt.tzinfo is None:
                expiry_dt = expiry_dt.replace(tzinfo=timezone.utc)
            # Extend from current expiry
            new_expiry = (expiry_dt + timedelta(days=extend_days)).isoformat() if extend_days > 0 else current_expiry
        except:
            new_expiry = (now + timedelta(days=28)).isoformat()
    else:
        new_expiry = (now + timedelta(days=28)).isoformat()
    
    # Update user subscription
    await db.users.update_one(
        {"uid": uid},
        {
            "$set": {
                "subscription_plan": new_plan,
                "subscription_expiry": new_expiry,
                "membership_type": "vip"  # Legacy compatibility
            }
        }
    )
    
    # Log activity
    await log_activity(
        user_id=uid,
        action_type="subscription_change",
        description=f"Subscription changed to {new_plan}",
        metadata={"new_plan": new_plan, "new_expiry": new_expiry, "extend_days": extend_days}
    )
    
    # Create notification
    await create_notification(
        user_id=uid,
        title="Subscription Updated!",
        message=f"Your subscription has been upgraded to {new_plan.capitalize()}. Enjoy your new benefits!",
        notification_type="subscription"
    )
    
    return {
        "success": True,
        "uid": uid,
        "new_plan": new_plan,
        "new_expiry": new_expiry
    }

@api_router.post("/subscription/pay-with-prc")
async def subscription_pay_with_prc(request: Request):
    """
    Pay for Elite subscription using PRC.
    
    NEW FORMULA (1 April 2026):
    ===========================
    Base: ₹999 + 18% GST = ₹1178.82
    + ₹10 Processing Fee (→ Company Wallet)
    + 20% Admin Charges (→ Company Wallet)
    
    Total PRC = (₹1178.82 + ₹10 + 20% Admin) × PRC Rate
    
    Breakdown goes to Company Wallets:
    - GST → gst_collection wallet
    - Processing Fee → processing_fees wallet
    - Admin Charges → admin_charges wallet
    - Base Revenue → subscription wallet
    """
    try:
        data = await request.json()
        user_id = data.get("user_id")
        plan_name = data.get("plan_name", "elite")  # Only Elite available now
        plan_type = data.get("plan_type", "monthly")
        prc_amount = data.get("prc_amount")
        client_request_id = data.get("client_request_id")  # Idempotency key
        
        # VALIDATION: Check required fields
        if not user_id:
            raise HTTPException(status_code=400, detail="User ID is required. Please login again.")
        if not prc_amount or prc_amount <= 0:
            raise HTTPException(status_code=400, detail="Invalid PRC amount. Please refresh the page.")
        
        # ==================== IDEMPOTENCY GUARD (Layer 1) ====================
        # Prevents double-submit from double-taps, network retries, or duplicate
        # tab actions. Client MUST send a stable `client_request_id` (UUIDv4).
        # Legacy clients without the key still work (no idempotency protection
        # but atomic DB lock below still guards against concurrent double-charge).
        idem_scope = f"prc_sub:{user_id}"
        if client_request_id:
            cached = await check_and_claim_idempotency_key(
                client_request_id, idem_scope, ttl_seconds=300
            )
            if cached is not None:
                if cached.get("_inflight"):
                    # Another identical request is still processing — ask client to wait.
                    raise HTTPException(status_code=409, detail=cached.get("message"))
                # Replay previous successful response
                logging.info(f"[PRC-SUB] idempotency replay for {user_id} / {client_request_id[:8]}")
                return cached
        
        # Only Elite plan available
        plan_name = "elite"
        
        # Get user first
        user = await db.users.find_one({"uid": user_id})
        if not user:
            raise HTTPException(status_code=404, detail="User account not found. Please login again.")
        
        user_name = user.get("name", "User")
        current_balance = float(user.get("prc_balance", 0) or 0)
        
        logging.info(f"[PRC-SUB] Request: User={user_id}, Plan={plan_name}, Amount={prc_amount}, Balance={current_balance}")

        # ==================== UNLIMITED PRC SUBSCRIPTIONS (May 2026) ====================
        # Previously: 3-time PRC subscription lifetime cap. REMOVED per user
        # decision — users can now PRC-subscribe unlimited times. Only balance
        # and 7-day cooldown gate the flow now. The used_count is still tracked
        # for analytics but never blocks.
        COUNTING_STATUSES = ["paid", "upcoming", "active", "completed", "expired"]
        prior_count = await db.subscription_payments.count_documents({
            "user_id": user_id,
            "payment_method": "prc",
            "status": {"$in": COUNTING_STATUSES},
        })
        logging.info(f"[PRC-SUB] User {user_id} has {prior_count} prior PRC subscriptions (unlimited cap)")

        # CHECK COOLDOWN: 7 days between any subscription (PRC/UPI/Manual)
        # NOTE: This is a soft precheck for user-friendly error messages.
        # The HARD guarantee is the atomic CAS on `last_prc_subscription` further
        # below (Layer 2) which cannot be raced.
        try:
            cooldown = await check_service_cooldown(user_id, "subscription")
            if not cooldown["allowed"]:
                wait_days = cooldown.get("wait_days") or round(cooldown.get("wait_hours", 0) / 24, 1)
                last_date = cooldown.get("last_request", "recently")
                raise HTTPException(
                    status_code=429,
                    detail=f"Cooldown active. Please wait {wait_days:.0f} more days. Last subscription was on {last_date[:10] if isinstance(last_date, str) and len(last_date) > 10 else last_date}."
                )
        except HTTPException:
            # FIX (May 2026): cooldown check now fails CLOSED — never swallow
            # unexpected cooldown errors. 7-day cooldown is a critical business
            # rule and must not be bypassed by a transient DB hiccup.
            raise
        except Exception as cooldown_err:
            logging.error(f"[PRC-SUB] Cooldown check error for {user_id}: {cooldown_err}")
            raise HTTPException(
                status_code=503,
                detail="Unable to verify subscription eligibility. Please try again in a moment.",
            )
        
        # Calculate Elite pricing with new formula
        try:
            pricing = await calculate_elite_prc_price()
            expected_prc = pricing["total_prc"]
            prc_rate = pricing["prc_rate"]
        except Exception as rate_err:
            logging.error(f"[PRC-SUB] Pricing calc error: {rate_err}")
            raise HTTPException(status_code=500, detail="Could not calculate subscription price. Please try again.")
        
        # Allow 10% variance for rounding
        variance_allowed = expected_prc * 0.10
        if abs(prc_amount - expected_prc) > variance_allowed:
            logging.warning(f"[PRC-SUB] Amount mismatch: expected={expected_prc:.0f}, got={prc_amount:.0f}")
            raise HTTPException(
                status_code=400, 
                detail=f"PRC amount mismatch. Expected {expected_prc:.0f} PRC. Please refresh the page."
            )
        
        # Use expected amount for accuracy
        prc_amount = expected_prc
        
        # ==================== REDEEM LIMIT — REMOVED for SELF-Subscription (May 2026) ====================
        # Business decision: A user must always be able to renew/activate their OWN
        # Elite subscription using their available PRC balance — regardless of
        # months-active, network size, or redeem-limit unlock %. This is NOT a
        # service redemption (no INR leaves the system); it's an internal
        # purchase that keeps the user active and the company wallet credited.
        # Guards still active: (a) balance check below, 7-day cooldown above.
        # 3-time PRC cap removed May 2026 — unlimited.
        # (c) 7-day cooldown above. Sale Elite (P2P) flow is unaffected.
        try:
            limit_info = await calculate_user_redeem_limit(user_id)
            effective_available = float(limit_info.get("effective_available") or 0)
            unlock_percent = limit_info.get("unlock_percent", 0)
            logging.info(
                f"[PRC-SUB] Self-sub: redeem limit check SKIPPED for {user_id} "
                f"(available={effective_available:.0f}, unlock={unlock_percent}%) — "
                f"required={prc_amount:.0f}"
            )
        except Exception as _le:
            logging.warning(f"[PRC-SUB] Redeem limit info fetch error (non-blocking) for {user_id}: {_le}")

        # Check PRC balance (must also have raw balance — defense in depth)
        if current_balance < prc_amount:
            raise HTTPException(
                status_code=400, 
                detail=f"Insufficient PRC Balance. You have {current_balance:,.0f} PRC, but {prc_amount:,.0f} PRC is required."
            )
        
        # Calculate subscription duration - 28 days
        duration_days = 28
        now = datetime.now(timezone.utc)
        
        # Check if user has active subscription
        current_expiry = get_user_expiry(user)
        has_active_plan = False
        expiry_dt = None
        is_expired_flag = user.get("subscription_expired", False)
        
        if current_expiry and not is_expired_flag:
            try:
                if isinstance(current_expiry, str):
                    expiry_dt = datetime.fromisoformat(current_expiry.replace('Z', '+00:00'))
                else:
                    expiry_dt = current_expiry
                if expiry_dt.tzinfo is None:
                    expiry_dt = expiry_dt.replace(tzinfo=timezone.utc)
                if expiry_dt > now:
                    has_active_plan = True
            except:
                pass
        
        # Determine if this should be an upcoming plan or immediate activation
        is_upcoming = has_active_plan
        
        if is_upcoming:
            # Queue as upcoming: starts after current plan expires
            import uuid as _uuid
            payment_id = str(_uuid.uuid4())
            scheduled_start = expiry_dt.isoformat()
            scheduled_end = (expiry_dt + timedelta(days=duration_days)).isoformat()
        else:
            # Immediate activation
            import uuid as _uuid
            payment_id = str(_uuid.uuid4())
            new_expiry = (now + timedelta(days=duration_days)).isoformat()
        
        # DEDUCT PRC — ATOMIC CAS (Layer 2: race-safe guarantee)
        # Filter checks ALL in one atomic operation:
        #   - Balance sufficient
        #   - Cooldown honored: no PRC subscription within last 7 days
        # Update atomically:
        #   - Deduct balance
        #   - Mark last_prc_subscription = now (serializes future attempts)
        # Double-tap scenario: 2nd concurrent request's filter fails on
        # last_prc_subscription > 7d_ago → modified_count == 0 → rejected.
        try:
            seven_days_ago = (now - timedelta(days=7)).isoformat()
            result = await db.users.update_one(
                {
                    "uid": user_id,
                    "prc_balance": {"$gte": prc_amount},
                    "$or": [
                        {"last_prc_subscription": {"$exists": False}},
                        {"last_prc_subscription": None},
                        {"last_prc_subscription": {"$lt": seven_days_ago}},
                    ],
                },
                {
                    "$inc": {"prc_balance": -prc_amount},
                    "$set": {"last_prc_subscription": now.isoformat()},
                },
            )
            if result.modified_count == 0:
                # Figure out WHY it failed for a clearer error message.
                fresh = await db.users.find_one(
                    {"uid": user_id},
                    {"_id": 0, "prc_balance": 1, "last_prc_subscription": 1},
                )
                if fresh:
                    fresh_bal = float(fresh.get("prc_balance", 0) or 0)
                    last_sub = fresh.get("last_prc_subscription")
                    if last_sub and last_sub >= seven_days_ago:
                        # Most likely cause under race: a concurrent request just
                        # claimed the slot ~ms before this one.
                        try:
                            last_dt = datetime.fromisoformat(str(last_sub).replace("Z", "+00:00"))
                            remaining_days = max(
                                0,
                                7 - int((now - last_dt).total_seconds() // 86400),
                            )
                        except Exception:
                            remaining_days = 7
                        raise HTTPException(
                            status_code=429,
                            detail=(
                                f"Subscription cooldown active. Please wait "
                                f"{remaining_days} more day(s). Last subscription "
                                f"was on {str(last_sub)[:10]}."
                            ),
                        )
                    if fresh_bal < prc_amount:
                        raise HTTPException(
                            status_code=400,
                            detail=(
                                f"Insufficient PRC Balance. You have "
                                f"{fresh_bal:,.0f} PRC, but {prc_amount:,.0f} PRC "
                                f"is required."
                            ),
                        )
                raise HTTPException(
                    status_code=409,
                    detail="Could not activate subscription. Please refresh and try again.",
                )
        except HTTPException:
            raise
        except Exception as deduct_err:
            logging.error(f"[PRC-SUB] PRC deduction failed: {deduct_err}")
            raise HTTPException(status_code=500, detail="Payment processing failed. Please try again.")
        
        if not is_upcoming:
            # IMMEDIATE ACTIVATION
            try:
                await db.users.update_one(
                    {"uid": user_id},
                    {
                        "$set": {
                            "subscription_plan": "elite",
                            "subscription_expiry": new_expiry,
                            "subscription_start": now.isoformat(),
                            "membership_type": "vip",
                            "subscription_status": "active",
                            "subscription_payment_type": "prc",
                            "subscription_expired": False,
                            "last_prc_subscription": now.isoformat()
                        }
                    }
                )
            except Exception as update_err:
                logging.error(f"[PRC-SUB] Subscription update failed, refunding PRC: {update_err}")
                await db.users.update_one({"uid": user_id}, {"$inc": {"prc_balance": prc_amount}})
                raise HTTPException(status_code=500, detail="Subscription activation failed. PRC has been refunded.")
            
            # Invalidate user cache after subscription activation
            if cache:
                await cache.delete(f"user_data:{user_id}")
                await cache.delete(f"user:dashboard:{user_id}")
            
            # Assign subscription position for mining network
            try:
                await assign_subscription_position(user_id)
            except Exception as pos_err:
                logging.warning(f"[PRC-SUB] Sub position error: {pos_err}")
        
        # CREDIT COMPANY WALLETS
        try:
            await credit_company_wallets_for_subscription(user_id, pricing, user_name)
        except Exception as wallet_err:
            logging.error(f"[PRC-SUB] Company wallet credit failed: {wallet_err}")
        
        # RECORD PAYMENT
        payment_record = {
            "payment_id": payment_id,
            "user_id": user_id,
            "user_name": user_name,
            "plan_name": plan_name,
            "plan_type": plan_type,
            "payment_method": "prc",
            "prc_amount": round(prc_amount, 2),
            "prc_rate_used": prc_rate,
            "pricing_breakdown": {
                "base_inr": pricing["base_inr"],
                "gst_inr": pricing["gst_inr"],
                "gst_rate": pricing["gst_rate"],
                "processing_fee_inr": pricing["processing_fee_inr"],
                "admin_charge_rate": pricing["admin_charge_rate"],
                "base_prc": pricing["base_prc"],
                "gst_prc": pricing["gst_prc"],
                "processing_fee_prc": pricing["processing_fee_prc"],
                "admin_charges_prc": pricing["admin_charges_prc"],
                "total_prc": pricing["total_prc"]
            },
            "inr_equivalent": pricing["base_with_gst_inr"],
            "status": "upcoming" if is_upcoming else "paid",
            "created_at": now.isoformat(),
            "duration_days": duration_days,
        }
        
        if is_upcoming:
            payment_record["scheduled_start"] = scheduled_start
            payment_record["scheduled_end"] = scheduled_end
        else:
            payment_record["subscription_start"] = now.isoformat()
            payment_record["subscription_expiry"] = new_expiry
        
        await db.subscription_payments.insert_one(payment_record)
        
        # Log to transactions
        if is_upcoming:
            # Format scheduled_start as "DD MMM YYYY" for clear statement display
            try:
                sched_dt = datetime.fromisoformat(scheduled_start.replace('Z', '+00:00'))
                sched_display = sched_dt.strftime("%d %b %Y")
            except Exception:
                sched_display = scheduled_start[:10]
            desc_suffix = f"(Starts on {sched_display} after current plan expires)"
        else:
            desc_suffix = f"- ₹{pricing['base_inr']} + GST + Fees"
        # Fetch updated balance for statement
        updated_user = await db.users.find_one({"uid": user_id}, {"_id": 0, "prc_balance": 1})
        balance_after = round(float(updated_user.get("prc_balance", 0)), 2) if updated_user else 0
        await db.transactions.insert_one({
            "user_id": user_id,
            "transaction_id": f"SUB-PRC-{payment_id}",
            "type": "subscription_prc",
            "amount": -prc_amount,
            "prc_amount": prc_amount,
            "inr_value": pricing["base_with_gst_inr"],
            "description": f"Elite Subscription ({duration_days} days) {desc_suffix}",
            "balance_after": balance_after,
            "timestamp": now,
            "created_at": now.isoformat(),
            "status": "completed"
        })
        
        # Record service usage for cooldown (removed - function no longer exists)
        
        # Log activity and notification
        try:
            if is_upcoming:
                notify_msg = f"Your Elite plan has been queued! It will activate on {scheduled_start[:10]}. Paid {prc_amount:,.0f} PRC."
                await log_activity(user_id=user_id, action_type="subscription_prc_upcoming",
                    description=f"Paid {prc_amount:.0f} PRC for upcoming Elite subscription", metadata=payment_record)
            else:
                notify_msg = f"Your Elite plan is active until {new_expiry[:10]}. Paid {prc_amount:,.0f} PRC (₹{pricing['base_inr']} + GST + Fees)."
                await log_activity(user_id=user_id, action_type="subscription_prc_payment",
                    description=f"Paid {prc_amount:.0f} PRC for Elite subscription", metadata=payment_record)
            await create_notification(user_id=user_id, 
                title="Elite Subscription Queued!" if is_upcoming else "Elite Subscription Activated!",
                message=notify_msg, notification_type="subscription")
        except:
            pass
        
        if is_upcoming:
            logging.info(f"[PRC-SUB] UPCOMING: {user_name} ({user_id}) queued Elite for {prc_amount:.0f} PRC, starts {scheduled_start[:10]}")
        else:
            logging.info(f"[PRC-SUB] SUCCESS: {user_name} ({user_id}) bought Elite for {prc_amount:.0f} PRC, expires {new_expiry[:10]}")

        # Sustainability auto-burn (1% of post-deduction balance, threshold 30k)
        # Applied for both immediate AND upcoming subscriptions since PRC has
        # already been deducted at this point.
        try:
            await apply_sustainability_burn(
                user_id=user_id,
                service_type="subscription_prc",
                service_ref_id=payment_id,
                amount_inr=pricing.get("base_with_gst_inr"),
            )
        except Exception as burn_err:
            logging.warning(f"[SUSTAIN-BURN] subscription hook failed (non-fatal): {burn_err}")

        # Community success-story post (immediate activations only, not upcoming/queued)
        if not is_upcoming:
            try:
                from routes.community import create_success_story_post
                asyncio.create_task(create_success_story_post(
                    user_id=user_id,
                    service_type="subscription",
                    amount_inr=pricing.get("base_with_gst_inr") or 0,
                    plan_name="Elite",
                    ref_id=f"sub_{payment_id}",
                ))
            except Exception as _e:
                logging.warning(f"[COMMUNITY] subscription PRC post hook failed (non-fatal): {_e}")

        if is_upcoming:
            response = {
                "success": True,
                "message": "Elite subscription queued! It will activate after your current plan expires.",
                "is_upcoming": True,
                "subscription": {
                    "plan": "elite",
                    "scheduled_start": scheduled_start[:10],
                    "scheduled_end": scheduled_end[:10],
                    "prc_paid": round(prc_amount, 2),
                    "duration_days": duration_days,
                    "pricing_breakdown": pricing
                }
            }
        else:
            response = {
                "success": True,
                "message": "Elite subscription activated successfully!",
                "is_upcoming": False,
                "subscription": {
                    "plan": "elite",
                    "expiry": new_expiry[:10],
                    "prc_paid": round(prc_amount, 2),
                    "duration_days": duration_days,
                    "pricing_breakdown": pricing
                }
            }
        # Persist response for idempotent replay
        if client_request_id:
            await store_idempotency_response(
                client_request_id, idem_scope, response, ttl_seconds=300
            )
        return response
        
    except HTTPException:
        # Release the idempotency sentinel so the user can retry after fixing the
        # error (e.g., correcting amount, waiting out cooldown). Without release
        # they'd be locked out for the full TTL window.
        if client_request_id:
            try:
                await release_idempotency_key(client_request_id, idem_scope)
            except Exception:
                pass
        raise
    except Exception as e:
        logging.error(f"[PRC-SUB] Unexpected error: {str(e)}")
        import traceback
        logging.error(traceback.format_exc())
        if client_request_id:
            try:
                await release_idempotency_key(client_request_id, idem_scope)
            except Exception:
                pass
        raise HTTPException(status_code=500, detail=f"Subscription failed. Technical error: {str(e)}")


# ============================================================================
# SALE ELITE SUBSCRIPTION (Peer-to-Peer)
# ----------------------------------------------------------------------------
# Allows an Elite-subscribed user (sender) to purchase an Elite subscription
# for ANOTHER registered user (beneficiary) using sender's own PRC balance.
#
# RULES (confirmed with user, Feb 2026):
#  1. Only ACTIVE Elite subscribers can sell/sponsor.
#  2. Cost = same formula as self PRC subscription: ₹999 + 18% GST + ₹10
#     processing + 20% admin → × dynamic PRC rate.
#  3. Sender MUST have redeem limit >= cost (same check as Bank Redeem).
#  4. Sender PRC balance must cover cost.
#  5. Rate limit: max 1 sale per sender per calendar day (UTC midnight).
#  6. Beneficiary can be ANY registered user. If beneficiary already has an
#     active Elite plan, the new 28-day plan is QUEUED as upcoming.
#  7. Sender's transaction is recorded in `transactions` collection with
#     type="sale_elite_subscription" so it shows up in PRC Statement / History.
#  8. Separate audit record stored in `sponsored_subscriptions` collection.
#  9. Beneficiary receives in-app notification + subscription_history entry.
# 10. Sender auth = standard login PIN (same field chain as /api/login).
# ============================================================================

class SaleEliteLookupRequest(BaseModel):
    sender_uid: str
    beneficiary_mobile: str


class SaleEliteActivateRequest(BaseModel):
    sender_uid: str
    beneficiary_mobile: str
    pin: str  # Sender's login PIN
    client_request_id: Optional[str] = None  # Idempotency key


def _normalize_mobile(mobile: str) -> str:
    """Strip +91 / spaces / dashes → keep digits; take last 10 digits."""
    digits = ''.join(filter(str.isdigit, mobile or ''))
    return digits[-10:] if len(digits) >= 10 else digits


async def _find_user_by_mobile(mobile: str) -> Optional[dict]:
    """Find user by mobile/phone (matches last 10 digits)."""
    if not mobile:
        return None
    norm = _normalize_mobile(mobile)
    if len(norm) < 10:
        return None
    # Try exact match on common fields
    for fld in ("mobile", "phone"):
        doc = await db.users.find_one({fld: norm})
        if doc:
            return doc
        doc = await db.users.find_one({fld: f"+91{norm}"})
        if doc:
            return doc
    # Fallback: regex anchored on last 10 digits
    doc = await db.users.find_one({"mobile": {"$regex": f"{norm}$"}})
    return doc


async def _sender_is_active_elite(user: dict) -> bool:
    """Sender must currently hold an active Elite plan."""
    if not user:
        return False
    plan = (user.get("subscription_plan") or "").lower()
    if plan != "elite":
        return False
    if user.get("subscription_expired", False):
        return False
    now = datetime.now(timezone.utc)
    expiry = get_user_expiry(user)
    if not expiry:
        return False
    try:
        if isinstance(expiry, str):
            exp_dt = datetime.fromisoformat(expiry.replace('Z', '+00:00'))
        else:
            exp_dt = expiry
        if exp_dt.tzinfo is None:
            exp_dt = exp_dt.replace(tzinfo=timezone.utc)
        return exp_dt > now
    except Exception:
        return False


def _mask_name(name: str) -> str:
    """Mask name for preview (privacy): 'Rahul Sharma' → 'Rahul S.'"""
    if not name:
        return "User"
    parts = str(name).strip().split()
    if len(parts) == 1:
        return parts[0]
    return f"{parts[0]} {parts[-1][0]}."


