@api_router.post("/subscription/sale-elite/lookup")
async def sale_elite_lookup_beneficiary(request: SaleEliteLookupRequest):
    """Preview the beneficiary linked to a mobile number before charging.

    Returns minimal info: masked name + current subscription status.
    """
    sender = await db.users.find_one({"uid": request.sender_uid})
    if not sender:
        raise HTTPException(status_code=404, detail="Sender account not found.")

    # ELITE-ONLY (active) gate removed May 2026: inactive (expired) Elite users
    # AND Explorer users can now sponsor subscriptions for friends. Only
    # business gates are: sufficient PRC balance + daily 1-per-day cap + PIN.

    beneficiary = await _find_user_by_mobile(request.beneficiary_mobile)
    if not beneficiary:
        raise HTTPException(
            status_code=404,
            detail="No registered user found with this mobile number."
        )

    # Prevent self-sponsoring
    if beneficiary.get("uid") == sender.get("uid"):
        raise HTTPException(
            status_code=400,
            detail="You cannot sponsor a subscription for yourself."
        )

    # Active plan status
    now = datetime.now(timezone.utc)
    beneficiary_plan = (beneficiary.get("subscription_plan") or "explorer").lower()
    beneficiary_has_active_elite = False
    current_expiry_display = None
    expiry = get_user_expiry(beneficiary)
    if expiry and not beneficiary.get("subscription_expired", False):
        try:
            if isinstance(expiry, str):
                exp_dt = datetime.fromisoformat(expiry.replace('Z', '+00:00'))
            else:
                exp_dt = expiry
            if exp_dt.tzinfo is None:
                exp_dt = exp_dt.replace(tzinfo=timezone.utc)
            if exp_dt > now and beneficiary_plan == "elite":
                beneficiary_has_active_elite = True
                current_expiry_display = exp_dt.isoformat()
        except Exception:
            pass

    # Pricing
    pricing = await calculate_elite_prc_price()

    # Redeem-limit + balance snapshot for sender
    try:
        limit_info = await calculate_user_redeem_limit(sender.get("uid"))
        effective_available = float(limit_info.get("effective_available") or 0)
        unlock_percent = limit_info.get("unlock_percent", 0)
    except Exception:
        effective_available = 0
        unlock_percent = 0

    sender_balance = float(sender.get("prc_balance", 0) or 0)
    sender_locked = float(sender.get("prc_locked", 0) or 0)
    sender_available = max(0.0, sender_balance - sender_locked)

    # Rate limit: 3 per day (raised from 1 in Jun 2026)
    today_start = datetime(now.year, now.month, now.day, tzinfo=timezone.utc)
    today_count = await db.sponsored_subscriptions.count_documents({
        "sender_uid": sender.get("uid"),
        "created_at": {"$gte": today_start.isoformat()},
        "status": {"$in": ["active", "upcoming"]},
    })
    daily_limit_ok = today_count < 3

    return {
        "success": True,
        "beneficiary": {
            "uid": beneficiary.get("uid"),
            "masked_name": _mask_name(beneficiary.get("name", "User")),
            "mobile_last4": _normalize_mobile(request.beneficiary_mobile)[-4:],
            "current_plan": beneficiary_plan,
            "has_active_elite": beneficiary_has_active_elite,
            "current_expiry": current_expiry_display,
            "will_be_queued": beneficiary_has_active_elite,
        },
        "pricing": {
            "base_inr": pricing["base_inr"],
            "gst_inr": pricing["gst_inr"],
            "processing_fee_inr": pricing["processing_fee_inr"],
            "admin_charges_inr": pricing["admin_charges_inr"],
            "total_prc": pricing["total_prc"],
            "prc_rate": pricing["prc_rate"],
            "inr_equivalent": pricing["base_with_gst_inr"],
        },
        "sender": {
            "prc_balance": sender_balance,
            "prc_locked": sender_locked,
            "available_prc": sender_available,
            "effective_available": effective_available,
            "unlock_percent": unlock_percent,
            "can_afford_balance": sender_available >= pricing["total_prc"],
            "can_afford_redeem_limit": effective_available >= pricing["total_prc"],
            "daily_limit_ok": daily_limit_ok,
            "sales_today": today_count,
            "daily_quota": 3,
            "sales_remaining": max(0, 3 - today_count),
        },
    }


@api_router.post("/subscription/sale-elite/activate")
async def sale_elite_activate(request: SaleEliteActivateRequest):
    """Activate / queue an Elite subscription for another user.

    Atomic flow:
      1. Validate sender Elite + PIN + rate-limit.
      2. Validate beneficiary exists.
      3. Calculate price + verify redeem limit + balance.
      4. CAS-deduct sender PRC with race-safe daily-limit guard.
      5. Activate or queue beneficiary Elite plan.
      6. Record `sponsored_subscriptions`, `transactions` (sender ledger),
         subscription_payments, beneficiary subscription_history.
      7. Credit company wallets (GST / processing / admin / subscription).
      8. Notify beneficiary.
    """
    idem_scope = f"sale_elite:{request.sender_uid}"
    client_request_id = request.client_request_id

    # ===== Idempotency (Layer 1) =====
    if client_request_id:
        cached = await check_and_claim_idempotency_key(
            client_request_id, idem_scope, ttl_seconds=300
        )
        if cached is not None:
            if cached.get("_inflight"):
                raise HTTPException(status_code=409, detail=cached.get("message"))
            return cached

    try:
        # ===== Validate sender =====
        sender = await db.users.find_one({"uid": request.sender_uid})
        if not sender:
            raise HTTPException(status_code=404, detail="Sender account not found.")
        # ELITE-ONLY gate removed May 2026 — inactive/Explorer can sponsor too.

        # ===== Verify sender PIN =====
        stored_pin = (
            sender.get("pin_hash")
            or sender.get("hashed_pin")
            or sender.get("password_hash")
            or sender.get("password")
        )
        if not stored_pin:
            raise HTTPException(status_code=400, detail="PIN is not set on your account.")
        loop = asyncio.get_event_loop()
        pin_ok = await loop.run_in_executor(
            None, verify_password, request.pin, stored_pin
        )
        if not pin_ok:
            raise HTTPException(status_code=401, detail="Incorrect PIN. Please try again.")

        # ===== Validate beneficiary =====
        beneficiary = await _find_user_by_mobile(request.beneficiary_mobile)
        if not beneficiary:
            raise HTTPException(
                status_code=404,
                detail="No registered user found with this mobile number."
            )
        if beneficiary.get("uid") == sender.get("uid"):
            raise HTTPException(
                status_code=400,
                detail="You cannot sponsor a subscription for yourself."
            )

        # ===== Pricing =====
        pricing = await calculate_elite_prc_price()
        total_prc = pricing["total_prc"]

        # ===== Redeem limit — REMOVED for Sale Elite (May 2026) =====
        # Business decision: Sale Elite sponsorship is INTERNAL value exchange
        # (no INR leaves the system; sender's PRC → beneficiary's Elite plan
        # → company wallet credited). It should not be gated by the monthly
        # redeem-limit cap. Balance + daily-1-cap + PIN are sufficient guards.
        try:
            limit_info = await calculate_user_redeem_limit(sender.get("uid"))
            effective_available = float(limit_info.get("effective_available") or 0)
            unlock_percent = limit_info.get("unlock_percent", 0)
            logging.info(
                f"[SALE-ELITE] Redeem limit check SKIPPED for {sender.get('uid')} "
                f"(available={effective_available:.0f}, unlock={unlock_percent}%) — "
                f"required={total_prc:.0f}"
            )
        except Exception as _le:
            logging.warning(f"[SALE-ELITE] Redeem limit info fetch error (non-blocking): {_le}")

        # ===== Balance defense-in-depth (subtract locked PRC — Jun 9 2026) =====
        sender_balance = float(sender.get("prc_balance", 0) or 0)
        sender_locked = float(sender.get("prc_locked", 0) or 0)
        sender_available = max(0.0, sender_balance - sender_locked)
        if sender_available < total_prc:
            locked_note = (
                f" ({sender_locked:,.0f} PRC locked till "
                f"{(sender.get('prc_unlock_at') or '')[:10]})" if sender_locked > 0 else ""
            )
            raise HTTPException(
                status_code=400,
                detail=(
                    f"Insufficient PRC Balance. You have {sender_available:,.0f} PRC available, "
                    f"but {total_prc:,.0f} PRC is required{locked_note}."
                ),
            )

        now = datetime.now(timezone.utc)
        today_start = datetime(now.year, now.month, now.day, tzinfo=timezone.utc)

        # ===== Daily rate limit precheck (3 per day) =====
        today_count = await db.sponsored_subscriptions.count_documents({
            "sender_uid": sender.get("uid"),
            "created_at": {"$gte": today_start.isoformat()},
            "status": {"$in": ["active", "upcoming"]},
        })
        if today_count >= 3:
            raise HTTPException(
                status_code=429,
                detail="Daily limit reached: you can sponsor up to 3 Elite subscriptions per day."
            )

        # ===== CAS deduct sender PRC + atomic daily-counter increment =====
        # Race-safe: bumps `sale_elite_day_count` atomically per day-bucket
        # and bounds it to < 3. Resets to 1 when day-bucket rolls over.
        today_bucket = today_start.date().isoformat()  # e.g. "2026-06-09"
        result = await db.users.update_one(
            {
                "uid": sender.get("uid"),
                # Available (balance − locked) must cover total_prc
                "$expr": {
                    "$gte": [
                        {"$subtract": [
                            {"$ifNull": ["$prc_balance", 0]},
                            {"$ifNull": ["$prc_locked", 0]},
                        ]},
                        total_prc,
                    ]
                },
                "$or": [
                    {"sale_elite_day_bucket": {"$ne": today_bucket}},   # new day → reset
                    {"sale_elite_day_count": {"$lt": 3}},                # same day, slot free
                    {"sale_elite_day_count": {"$exists": False}},        # legacy doc
                ],
            },
            [{
                "$set": {
                    "prc_balance": {"$subtract": ["$prc_balance", total_prc]},
                    "sale_elite_day_bucket": today_bucket,
                    "sale_elite_day_count": {
                        "$cond": [
                            {"$eq": [{"$ifNull": ["$sale_elite_day_bucket", ""]}, today_bucket]},
                            {"$add": [{"$ifNull": ["$sale_elite_day_count", 0]}, 1]},
                            1,
                        ]
                    },
                    "last_sale_elite_at": now.isoformat(),
                }
            }],
        )
        if result.modified_count == 0:
            # Figure out why
            fresh = await db.users.find_one(
                {"uid": sender.get("uid")},
                {"_id": 0, "prc_balance": 1, "sale_elite_day_bucket": 1, "sale_elite_day_count": 1},
            )
            if fresh:
                fb = float(fresh.get("prc_balance", 0) or 0)
                bucket = fresh.get("sale_elite_day_bucket")
                count = int(fresh.get("sale_elite_day_count") or 0)
                if bucket == today_bucket and count >= 3:
                    raise HTTPException(
                        status_code=429,
                        detail="Daily limit reached: you can sponsor up to 3 Elite subscriptions per day."
                    )
                if fb < total_prc:
                    raise HTTPException(
                        status_code=400,
                        detail=f"Insufficient PRC Balance. You have {fb:,.0f} PRC."
                    )
            raise HTTPException(status_code=409, detail="Could not process. Please retry.")

        sale_id = f"SALE-{uuid.uuid4()}"
        duration_days = 28

        # ===== Beneficiary: activate OR queue =====
        benef_current_expiry = get_user_expiry(beneficiary)
        benef_plan = (beneficiary.get("subscription_plan") or "explorer").lower()
        benef_expired_flag = beneficiary.get("subscription_expired", False)

        benef_has_active_elite = False
        benef_expiry_dt = None
        if benef_current_expiry and not benef_expired_flag and benef_plan == "elite":
            try:
                if isinstance(benef_current_expiry, str):
                    benef_expiry_dt = datetime.fromisoformat(benef_current_expiry.replace('Z', '+00:00'))
                else:
                    benef_expiry_dt = benef_current_expiry
                if benef_expiry_dt.tzinfo is None:
                    benef_expiry_dt = benef_expiry_dt.replace(tzinfo=timezone.utc)
                if benef_expiry_dt > now:
                    benef_has_active_elite = True
            except Exception:
                pass

        is_upcoming = benef_has_active_elite

        try:
            if is_upcoming:
                scheduled_start = benef_expiry_dt.isoformat()
                scheduled_end = (benef_expiry_dt + timedelta(days=duration_days)).isoformat()
                await db.users.update_one(
                    {"uid": beneficiary.get("uid")},
                    {
                        "$push": {
                            "subscription_history": {
                                "type": "sale_elite_received_upcoming",
                                "plan": "elite",
                                "duration_days": duration_days,
                                "sponsor_uid": sender.get("uid"),
                                "sponsor_name": sender.get("name", "A friend"),
                                "sale_id": sale_id,
                                "scheduled_start": scheduled_start,
                                "scheduled_end": scheduled_end,
                                "created_at": now.isoformat(),
                            }
                        }
                    }
                )
            else:
                new_expiry = (now + timedelta(days=duration_days)).isoformat()
                await db.users.update_one(
                    {"uid": beneficiary.get("uid")},
                    {
                        "$set": {
                            "subscription_plan": "elite",
                            "subscription_expiry": new_expiry,
                            "subscription_start": now.isoformat(),
                            "membership_type": "vip",
                            "subscription_status": "active",
                            "subscription_payment_type": "sale_elite_subscription",
                            "subscription_expired": False,
                            "sponsored_by": sender.get("uid"),
                            "sponsored_by_name": sender.get("name", "A friend"),
                            "sponsored_at": now.isoformat(),
                        },
                        "$push": {
                            "subscription_history": {
                                "type": "sale_elite_received",
                                "plan": "elite",
                                "duration_days": duration_days,
                                "sponsor_uid": sender.get("uid"),
                                "sponsor_name": sender.get("name", "A friend"),
                                "sale_id": sale_id,
                                "activated_at": now.isoformat(),
                                "expires_at": new_expiry,
                            }
                        }
                    }
                )
                # Assign mining position
                try:
                    await assign_subscription_position(beneficiary.get("uid"))
                except Exception as _pos:
                    logging.warning(f"[SALE-ELITE] position assign error: {_pos}")
        except Exception as be_err:
            # CRITICAL: refund sender PRC + decrement daily counter
            logging.error(f"[SALE-ELITE] beneficiary update failed, refunding: {be_err}")
            await db.users.update_one(
                {"uid": sender.get("uid")},
                {
                    "$inc": {
                        "prc_balance": total_prc,
                        "sale_elite_day_count": -1,
                    },
                    "$unset": {"last_sale_elite_at": ""},
                },
            )
            raise HTTPException(status_code=500, detail="Activation failed. Your PRC has been refunded.")

        # ===== Company wallets =====
        try:
            await credit_company_wallets_for_subscription(
                sender.get("uid"), pricing, sender.get("name", "User")
            )
        except Exception as wallet_err:
            logging.error(f"[SALE-ELITE] Company wallet credit failed (non-fatal): {wallet_err}")

        # ===== subscription_payments (audit) =====
        payment_record = {
            "payment_id": sale_id,
            "user_id": beneficiary.get("uid"),
            "user_name": beneficiary.get("name", "User"),
            "plan_name": "elite",
            "plan_type": "monthly",
            "payment_method": "sale_elite_subscription",
            "sponsor_uid": sender.get("uid"),
            "sponsor_name": sender.get("name", "User"),
            "prc_amount": round(total_prc, 2),
            "prc_rate_used": pricing["prc_rate"],
            "pricing_breakdown": {
                "base_inr": pricing["base_inr"],
                "gst_inr": pricing["gst_inr"],
                "processing_fee_inr": pricing["processing_fee_inr"],
                "admin_charges_inr": pricing["admin_charges_inr"],
                "total_prc": pricing["total_prc"],
            },
            "inr_equivalent": pricing["base_with_gst_inr"],
            "status": "upcoming" if is_upcoming else "paid",
            "created_at": now.isoformat(),
            "duration_days": duration_days,
        }
        if is_upcoming:
            payment_record["scheduled_start"] = scheduled_start
            payment_record["scheduled_end"] = scheduled_end
        else:
            payment_record["subscription_start"] = now.isoformat()
            payment_record["subscription_expiry"] = new_expiry
        await db.subscription_payments.insert_one(payment_record)

        # ===== sponsored_subscriptions (dedicated audit collection) =====
        sponsored_doc = {
            "sale_id": sale_id,
            "sender_uid": sender.get("uid"),
            "sender_name": sender.get("name", "User"),
            "beneficiary_uid": beneficiary.get("uid"),
            "beneficiary_name": beneficiary.get("name", "User"),
            "beneficiary_mobile": _normalize_mobile(request.beneficiary_mobile),
            "plan": "elite",
            "duration_days": duration_days,
            "prc_cost": round(total_prc, 2),
            "prc_rate": pricing["prc_rate"],
            "inr_equivalent": pricing["base_with_gst_inr"],
            "status": "upcoming" if is_upcoming else "active",
            "created_at": now.isoformat(),
            "activated_at": None if is_upcoming else now.isoformat(),
            "expires_at": scheduled_end if is_upcoming else new_expiry,
            "scheduled_start": scheduled_start if is_upcoming else None,
        }
        await db.sponsored_subscriptions.insert_one(sponsored_doc)

        # ===== Sender transactions / PRC statement =====
        updated_sender = await db.users.find_one(
            {"uid": sender.get("uid")}, {"_id": 0, "prc_balance": 1}
        )
        balance_after = round(float(updated_sender.get("prc_balance", 0)), 2) if updated_sender else 0

        desc_tail = "(Queued - beneficiary already Elite)" if is_upcoming else "(Activated)"
        await db.transactions.insert_one({
            "user_id": sender.get("uid"),
            "transaction_id": f"SALE-PRC-{sale_id}",
            "type": "sale_elite_subscription",
            "amount": -total_prc,
            "prc_amount": total_prc,
            "inr_value": pricing["base_with_gst_inr"],
            "description": (
                f"Sold Elite subscription to "
                f"{_mask_name(beneficiary.get('name', 'User'))} "
                f"(Mobile ****{_normalize_mobile(request.beneficiary_mobile)[-4:]}) "
                f"{desc_tail}"
            ),
            "balance_after": balance_after,
            "reference_id": sale_id,
            "beneficiary_uid": beneficiary.get("uid"),
            "timestamp": now,
            "created_at": now.isoformat(),
            "status": "completed",
        })

        # ===== Sender prc_transactions array (some UIs read this) =====
        try:
            await db.users.update_one(
                {"uid": sender.get("uid")},
                {
                    "$push": {
                        "prc_transactions": {
                            "type": "sale_elite_subscription",
                            "amount": -total_prc,
                            "beneficiary_uid": beneficiary.get("uid"),
                            "beneficiary_name": _mask_name(beneficiary.get("name", "User")),
                            "sale_id": sale_id,
                            "timestamp": now.isoformat(),
                        }
                    }
                },
            )
        except Exception:
            pass

        # ===== Beneficiary notification =====
        try:
            if is_upcoming:
                title = "Elite Subscription Gift Queued!"
                msg = (
                    f"{sender.get('name', 'A friend')} has sponsored an Elite "
                    f"subscription for you. It will activate after your current "
                    f"plan ends on {scheduled_start[:10]}."
                )
            else:
                title = "Elite Subscription Activated!"
                msg = (
                    f"{sender.get('name', 'A friend')} has sponsored a 28-day "
                    f"Elite subscription for you. Enjoy all premium features!"
                )
            await create_notification(
                user_id=beneficiary.get("uid"),
                title=title,
                message=msg,
                notification_type="subscription",
            )
        except Exception:
            pass

        # ===== Sustainability burn =====
        try:
            await apply_sustainability_burn(
                user_id=sender.get("uid"),
                service_type="sale_elite_subscription",
                service_ref_id=sale_id,
                amount_inr=pricing.get("base_with_gst_inr"),
            )
        except Exception as burn_err:
            logging.warning(f"[SALE-ELITE] sustain burn non-fatal: {burn_err}")

        # ===== Activity log =====
        try:
            await log_activity(
                user_id=sender.get("uid"),
                action_type="sale_elite_subscription",
                description=(
                    f"Sponsored Elite subscription for "
                    f"{_mask_name(beneficiary.get('name', 'User'))} "
                    f"({total_prc:.0f} PRC)"
                ),
                metadata={"sale_id": sale_id, "beneficiary_uid": beneficiary.get("uid")},
            )
        except Exception:
            pass

        # ===== Invalidate caches =====
        if cache:
            try:
                await cache.delete(f"user_data:{sender.get('uid')}")
                await cache.delete(f"user_data:{beneficiary.get('uid')}")
                await cache.delete(f"user:dashboard:{sender.get('uid')}")
                await cache.delete(f"user:dashboard:{beneficiary.get('uid')}")
            except Exception:
                pass

        # Active network cache — sender's mining-network-size memoization must
        # be cleared so the dashboard / mining rate calc immediately reflect
        # the newly-added beneficiary instead of waiting up to 60s for TTL.
        # This also benefits the beneficiary (no stale "0 network" badge).
        try:
            from routes.growth_economy import invalidate_active_network_cache
            invalidate_active_network_cache(sender.get("uid"))
            invalidate_active_network_cache(beneficiary.get("uid"))
        except Exception as _net_err:
            logging.warning(f"[SALE-ELITE] network cache invalidation non-fatal: {_net_err}")

        # ===== Community Forum Success-Story post =====
        # Show BOTH sender and beneficiary names ("Vishal R. ➡️ Suwarna A.")
        # per user choice (May 11, 2026). Skipped for queued/upcoming
        # subscriptions so the post fires on actual activation only.
        if not is_upcoming:
            try:
                asyncio.create_task(_create_sale_elite_community_post(
                    sender_uid=sender.get("uid"),
                    sender_name=sender.get("name", "User"),
                    beneficiary_uid=beneficiary.get("uid"),
                    beneficiary_name=beneficiary.get("name", "User"),
                    amount_inr=pricing.get("base_with_gst_inr") or 0,
                    sale_id=sale_id,
                ))
            except Exception as _cp_err:
                logging.warning(f"[SALE-ELITE] community post hook failed (non-fatal): {_cp_err}")

        logging.info(
            f"[SALE-ELITE] {sender.get('uid')} sponsored Elite for "
            f"{beneficiary.get('uid')} ({total_prc:.0f} PRC, "
            f"{'upcoming' if is_upcoming else 'active'})"
        )

        response = {
            "success": True,
            "message": (
                "Elite subscription queued for beneficiary (activates after current plan expires)."
                if is_upcoming
                else "Elite subscription activated for beneficiary!"
            ),
            "sale_id": sale_id,
            "is_upcoming": is_upcoming,
            "beneficiary": {
                "uid": beneficiary.get("uid"),
                "masked_name": _mask_name(beneficiary.get("name", "User")),
                "mobile_last4": _normalize_mobile(request.beneficiary_mobile)[-4:],
            },
            "prc_deducted": round(total_prc, 2),
            "inr_value": pricing["base_with_gst_inr"],
            "sender_new_balance": balance_after,
            "duration_days": duration_days,
            "expires_at": (scheduled_end if is_upcoming else new_expiry)[:10],
        }

        if client_request_id:
            await store_idempotency_response(
                client_request_id, idem_scope, response, ttl_seconds=300
            )
        return response

    except HTTPException:
        if client_request_id:
            try:
                await release_idempotency_key(client_request_id, idem_scope)
            except Exception:
                pass
        raise
    except Exception as e:
        logging.error(f"[SALE-ELITE] Unexpected error: {e}")
        import traceback
        logging.error(traceback.format_exc())
        if client_request_id:
            try:
                await release_idempotency_key(client_request_id, idem_scope)
            except Exception:
                pass
        raise HTTPException(status_code=500, detail=f"Sponsor failed: {str(e)}")


@api_router.get("/subscription/sale-elite/history/{uid}")
async def sale_elite_history(uid: str):
    """Get sponsorship history: sales SENT by this user and sales RECEIVED."""
    sent = await db.sponsored_subscriptions.find(
        {"sender_uid": uid},
        {"_id": 0}
    ).sort("created_at", -1).to_list(100)

    received = await db.sponsored_subscriptions.find(
        {"beneficiary_uid": uid},
        {"_id": 0}
    ).sort("created_at", -1).to_list(100)

    # Mask beneficiary names in sent history (privacy)
    for s in sent:
        if s.get("beneficiary_name"):
            s["beneficiary_name"] = _mask_name(s["beneficiary_name"])
        if s.get("beneficiary_mobile"):
            m = str(s["beneficiary_mobile"])
            s["beneficiary_mobile"] = f"****{m[-4:]}" if len(m) >= 4 else "****"
    # Mask sender names in received history
    for r in received:
        if r.get("sender_name"):
            r["sender_name"] = _mask_name(r["sender_name"])

    return {
        "success": True,
        "uid": uid,
        "sent_count": len(sent),
        "received_count": len(received),
        "sent": sent,
        "received": received,
    }


@api_router.get("/subscription/sale-elite/eligibility/{uid}")
async def sale_elite_eligibility(uid: str):
    """Quick eligibility check for UI to show/hide the tab."""
    user = await db.users.find_one({"uid": uid})
    if not user:
        raise HTTPException(status_code=404, detail="User not found.")

    is_elite = await _sender_is_active_elite(user)
    pricing = await calculate_elite_prc_price()
    # Redeem limit info is still computed for display, but no longer blocks eligibility.
    try:
        limit_info = await calculate_user_redeem_limit(uid)
        effective_available = float(limit_info.get("effective_available") or 0)
        unlock_percent = limit_info.get("unlock_percent", 0)
    except Exception:
        effective_available = 0
        unlock_percent = 0

    now = datetime.now(timezone.utc)
    today_start = datetime(now.year, now.month, now.day, tzinfo=timezone.utc)
    today_count = await db.sponsored_subscriptions.count_documents({
        "sender_uid": uid,
        "created_at": {"$gte": today_start.isoformat()},
        "status": {"$in": ["active", "upcoming"]},
    })

    prc_balance = float(user.get("prc_balance", 0) or 0)
    # ELIGIBILITY (Jun 2026 update): Daily quota raised from 1 → 3 per day.
    is_eligible = (today_count < 3) and (prc_balance >= pricing["total_prc"])

    if today_count >= 3:
        reason = "Daily limit reached: you can sponsor up to 3 Elite subscriptions per day."
    elif prc_balance < pricing["total_prc"]:
        reason = (
            f"Insufficient PRC. You have {prc_balance:,.0f} PRC, "
            f"but {pricing['total_prc']:,.0f} PRC is required."
        )
    else:
        reason = None

    return {
        "success": True,
        "is_eligible": is_eligible,
        "is_active_elite": is_elite,
        "reason": reason,
        "pricing": {
            "base_inr": pricing["base_inr"],
            "gst_inr": pricing["gst_inr"],
            "processing_fee_inr": pricing["processing_fee_inr"],
            "admin_charges_inr": pricing["admin_charges_inr"],
            "total_prc": pricing["total_prc"],
            "prc_rate": pricing["prc_rate"],
            "inr_equivalent": pricing["base_with_gst_inr"],
        },
        "sender": {
            "prc_balance": prc_balance,
            "effective_available": effective_available,
            "unlock_percent": unlock_percent,
            "daily_limit_ok": today_count < 3,
            "sales_today": today_count,
            "daily_quota": 3,
            "sales_remaining": max(0, 3 - today_count),
        },
    }



@api_router.post("/admin/sale-elite/backfill-community-posts")
async def admin_backfill_sale_elite_community_posts():
    """One-time admin backfill: for every existing `sponsored_subscriptions`
    record, ensure 2 Community Forum posts (sender + beneficiary) exist with
    the correct service_type metadata. Re-runs are safe — deletes any
    legacy / wrongly-themed posts for the same sale_id first, then recreates
    with the new dual-post format.
    """
    try:
        cursor = db.sponsored_subscriptions.find(
            {"status": {"$in": ["active", "completed"]}},
            {"_id": 0}
        ).sort("created_at", -1).limit(500)

        scanned = 0
        recreated = 0
        async for s in cursor:
            scanned += 1
            sale_id = s.get("sale_id")
            if not sale_id:
                continue

            # Wipe any prior posts for this sale_id (legacy single post or
            # mis-themed Mobile-Recharge cards).
            await db.community_posts.delete_many(
                {"$or": [
                    {"metadata.ref_id": f"sale_elite_{sale_id}"},
                    {"metadata.sale_id": sale_id},
                ]}
            )

            await _create_sale_elite_community_post(
                sender_uid=s.get("sender_uid"),
                sender_name=s.get("sender_name", "User"),
                beneficiary_uid=s.get("beneficiary_uid"),
                beneficiary_name=s.get("beneficiary_name", "User"),
                amount_inr=s.get("inr_equivalent", 0),
                sale_id=sale_id,
            )
            recreated += 1

        return {
            "success": True,
            "scanned": scanned,
            "recreated": recreated,
        }
    except Exception as e:
        logging.error(f"[SALE-ELITE BACKFILL] {e}")
        raise HTTPException(status_code=500, detail=str(e))






# ============================================================================
# ADMIN OVERRIDE: Force Activate Elite Subscription via PRC
# ----------------------------------------------------------------------------
# Allows admin to manually activate an Elite plan for a user using PRC,
# bypassing the standard redeem-limit and balance checks. PRC balance IS
# allowed to go negative (overdraft) — subsequent user earnings will
# naturally pay off the debt via `$inc`.
#
# RULES (confirmed with user):
#  1. Admin PIN required (153759)
#  2. Only Elite plan, dynamic price (₹999 + 18% GST + Fees → PRC via rate)
#  3. Consumes 1 of 3 lifetime PRC subscription chances
#  4. Enforces the existing 7-day subscription cooldown
#  5. Redeem-limit + balance checks are SKIPPED (overdraft allowed)
#  6. Full audit trail: admin_audit_logs + user transactions statement
#  7. Auto-posts Success Story to Community Forum (immediate activations)
# ============================================================================
ADMIN_OVERRIDE_PIN = ADMIN_OVERRIDE_PIN_ENV  # Matches existing hardcoded admin PIN pattern

@api_router.post("/admin/subscription/force-activate-elite-prc")
async def admin_force_activate_elite_prc(request: Request):
    """Admin PIN-protected force activation of Elite subscription via PRC.
    Allows PRC balance to go negative (debt). Consumes 1 PRC-subscription
    chance and enforces the 7-day cooldown.
    """
    try:
        data = await request.json()
        admin_uid = (data.get("admin_uid") or "").strip()
        admin_pin = str(data.get("admin_pin") or "").strip()
        target_identifier = (data.get("target_identifier") or "").strip()
        admin_note = (data.get("admin_note") or "").strip() or "Admin force-activated Elite via PRC"

        # 1) Admin PIN validation
        if admin_pin != ADMIN_OVERRIDE_PIN:
            raise HTTPException(status_code=403, detail="Invalid Admin PIN.")

        if not target_identifier:
            raise HTTPException(status_code=400, detail="Target user identifier (mobile or email) is required.")

        # 2) Lookup target user: try mobile → email (case-insensitive)
        target_user = None
        digits = "".join(ch for ch in target_identifier if ch.isdigit())
        if len(digits) >= 10:
            mobile10 = digits[-10:]
            target_user = await db.users.find_one({"mobile": {"$regex": f"{mobile10}$"}})
        if not target_user and "@" in target_identifier:
            target_user = await db.users.find_one({"email": {"$regex": f"^{re.escape(target_identifier)}$", "$options": "i"}})
        if not target_user:
            target_user = await db.users.find_one({"uid": target_identifier})
        if not target_user:
            raise HTTPException(status_code=404, detail=f"No user found for identifier '{target_identifier}'.")

        user_id = target_user["uid"]
        user_name = target_user.get("name", "User")
        current_balance = float(target_user.get("prc_balance", 0) or 0)

        logging.info(f"[ADMIN-FORCE-SUB] admin={admin_uid} target={user_id} ({user_name}) balance={current_balance}")

        # 3) PRC subscription cap — REMOVED May 2026 (unlimited)
        # Previously: lifetime cap of 3. Now tracked only for analytics.
        COUNTING_STATUSES = ["paid", "upcoming", "active", "completed", "expired"]
        prior_count = await db.subscription_payments.count_documents({
            "user_id": user_id,
            "payment_method": "prc",
            "status": {"$in": COUNTING_STATUSES},
        })
        logging.info(f"[ADMIN-FORCE-SUB] {user_id} prior_count={prior_count} (unlimited)")

        # 4) 7-day cooldown (NOT bypassed per user rule)
        try:
            cooldown = await check_service_cooldown(user_id, "subscription")
            if not cooldown["allowed"]:
                wait_days = cooldown.get("wait_days") or round(cooldown.get("wait_hours", 0) / 24, 1)
                raise HTTPException(
                    status_code=429,
                    detail=f"Cooldown active. User must wait {wait_days:.0f} more days before next subscription.",
                )
        except HTTPException:
            raise
        except Exception as cd_err:
            logging.warning(f"[ADMIN-FORCE-SUB] Cooldown check error for {user_id}: {cd_err}")

        # 5) Dynamic Elite pricing
        try:
            pricing = await calculate_elite_prc_price()
            prc_amount = pricing["total_prc"]
            prc_rate = pricing["prc_rate"]
        except Exception as rate_err:
            logging.error(f"[ADMIN-FORCE-SUB] Pricing calc error: {rate_err}")
            raise HTTPException(status_code=500, detail="Could not calculate Elite pricing.")

        # 6) Cooldown / duration / active-plan handling (mirrors normal flow)
        duration_days = 28
        now = datetime.now(timezone.utc)
        current_expiry = get_user_expiry(target_user)
        has_active_plan = False
        expiry_dt = None
        is_expired_flag = target_user.get("subscription_expired", False)
        if current_expiry and not is_expired_flag:
            try:
                if isinstance(current_expiry, str):
                    expiry_dt = datetime.fromisoformat(current_expiry.replace('Z', '+00:00'))
                else:
                    expiry_dt = current_expiry
                if expiry_dt.tzinfo is None:
                    expiry_dt = expiry_dt.replace(tzinfo=timezone.utc)
                if expiry_dt > now:
                    has_active_plan = True
            except Exception:
                pass

        is_upcoming = has_active_plan
        import uuid as _uuid
        payment_id = str(_uuid.uuid4())
        if is_upcoming:
            scheduled_start = expiry_dt.isoformat()
            scheduled_end = (expiry_dt + timedelta(days=duration_days)).isoformat()
        else:
            new_expiry = (now + timedelta(days=duration_days)).isoformat()

        # 7) DEDUCT PRC — allow overdraft (no $gte filter, no balance check)
        try:
            await db.users.update_one(
                {"uid": user_id},
                {"$inc": {"prc_balance": -prc_amount}},
            )
        except Exception as deduct_err:
            logging.error(f"[ADMIN-FORCE-SUB] PRC deduction failed: {deduct_err}")
            raise HTTPException(status_code=500, detail="Could not deduct PRC. Try again.")

        # 8) If balance went negative, annotate debt fields for UI transparency
        updated_user_doc = await db.users.find_one({"uid": user_id}, {"_id": 0, "prc_balance": 1})
        balance_after = round(float((updated_user_doc or {}).get("prc_balance", 0) or 0), 2)
        overdraft_applied = balance_after < 0
        if overdraft_applied:
            await db.users.update_one(
                {"uid": user_id},
                {"$set": {
                    "prc_debt_active": True,
                    "prc_debt_original": abs(balance_after),
                    "prc_debt_at": now.isoformat(),
                    "prc_debt_reason": "admin_force_activate_elite",
                }}
            )

        # 9) Activate or schedule subscription
        if not is_upcoming:
            try:
                await db.users.update_one(
                    {"uid": user_id},
                    {"$set": {
                        "subscription_plan": "elite",
                        "subscription_expiry": new_expiry,
                        "subscription_start": now.isoformat(),
                        "membership_type": "vip",
                        "subscription_status": "active",
                        "subscription_payment_type": "prc",
                        "subscription_expired": False,
                        "last_prc_subscription": now.isoformat(),
                    }},
                )
            except Exception as upd_err:
                # Best-effort refund if activation fails
                logging.error(f"[ADMIN-FORCE-SUB] Activation failed, refunding PRC: {upd_err}")
                await db.users.update_one({"uid": user_id}, {"$inc": {"prc_balance": prc_amount}})
                raise HTTPException(status_code=500, detail="Subscription activation failed. PRC refunded.")
            if cache:
                await cache.delete(f"user_data:{user_id}")
                await cache.delete(f"user:dashboard:{user_id}")
            try:
                await assign_subscription_position(user_id)
            except Exception as pos_err:
                logging.warning(f"[ADMIN-FORCE-SUB] Sub position error: {pos_err}")

        # 10) Credit company wallets (revenue recognised regardless of overdraft)
        try:
            await credit_company_wallets_for_subscription(user_id, pricing, user_name)
        except Exception as w_err:
            logging.error(f"[ADMIN-FORCE-SUB] Company wallet credit failed: {w_err}")

        # ==================== STEP 11: ADD TO VIP_PAYMENTS (IDEMPOTENT) ====================
        # NOTE: removed redeem-limit gate + 3-time cap May 2026.
        # remaining_days_added counts toward analytics only (not capped).
        payment_record = {
            "payment_id": payment_id,
            "user_id": user_id,
            "user_name": user_name,
            "plan_name": "elite",
            "plan_type": "monthly",
            "payment_method": "prc",
            "prc_amount": round(prc_amount, 2),
            "prc_rate_used": prc_rate,
            "pricing_breakdown": {
                "base_inr": pricing["base_inr"],
                "gst_inr": pricing["gst_inr"],
                "gst_rate": pricing["gst_rate"],
                "processing_fee_inr": pricing["processing_fee_inr"],
                "admin_charge_rate": pricing["admin_charge_rate"],
                "base_prc": pricing["base_prc"],
                "gst_prc": pricing["gst_prc"],
                "processing_fee_prc": pricing["processing_fee_prc"],
                "admin_charges_prc": pricing["admin_charges_prc"],
                "total_prc": pricing["total_prc"],
            },
            "inr_equivalent": pricing["base_with_gst_inr"],
            "status": "upcoming" if is_upcoming else "paid",
            "created_at": now.isoformat(),
            "duration_days": duration_days,
            "admin_force_activated": True,
            "admin_uid": admin_uid,
            "admin_note": admin_note,
            "overdraft_applied": overdraft_applied,
            "balance_before": round(current_balance, 2),
            "balance_after": balance_after,
        }
        if is_upcoming:
            payment_record["scheduled_start"] = scheduled_start
            payment_record["scheduled_end"] = scheduled_end
        else:
            payment_record["subscription_start"] = now.isoformat()
            payment_record["subscription_expiry"] = new_expiry
        await db.subscription_payments.insert_one(payment_record)

        # 12) Transaction statement (negative if overdraft) — visible in user's PRC statement
        if is_upcoming:
            try:
                sched_dt = datetime.fromisoformat(scheduled_start.replace('Z', '+00:00'))
                sched_display = sched_dt.strftime("%d %b %Y")
            except Exception:
                sched_display = scheduled_start[:10]
            desc = f"Elite Subscription ({duration_days} days) — Admin Override (Starts {sched_display})"
        else:
            desc = f"Elite Subscription ({duration_days} days) — Admin Override"
        if overdraft_applied:
            desc += f" [Overdraft: {abs(balance_after):,.0f} PRC debt]"

        await db.transactions.insert_one({
            "user_id": user_id,
            "transaction_id": f"SUB-PRC-ADMIN-{payment_id}",
            "type": "subscription_prc_admin_override",
            "amount": -prc_amount,
            "prc_amount": prc_amount,
            "inr_value": pricing["base_with_gst_inr"],
            "description": desc,
            "balance_after": balance_after,
            "timestamp": now,
            "created_at": now.isoformat(),
            "status": "completed",
            "admin_uid": admin_uid,
            "admin_force_activated": True,
            "overdraft_applied": overdraft_applied,
        })

        # 13) Admin audit log
        try:
            await log_admin_action(
                admin_uid=admin_uid or "unknown",
                action="force_activate_elite_prc",
                entity_type="user",
                entity_id=user_id,
                details={
                    "target_user_name": user_name,
                    "target_user_mobile": target_user.get("mobile"),
                    "target_user_email": target_user.get("email"),
                    "prc_amount": round(prc_amount, 2),
                    "inr_value": pricing["base_with_gst_inr"],
                    "prc_rate_used": prc_rate,
                    "balance_before": round(current_balance, 2),
                    "balance_after": balance_after,
                    "overdraft_applied": overdraft_applied,
                    "is_upcoming": is_upcoming,
                    "note": admin_note,
                    "payment_id": payment_id,
                },
                before_data={"prc_balance": current_balance, "subscription_plan": target_user.get("subscription_plan")},
                after_data={"prc_balance": balance_after, "subscription_plan": "elite"},
            )
        except Exception as audit_err:
            logging.warning(f"[ADMIN-FORCE-SUB] Audit log failed (non-fatal): {audit_err}")

        # 14) Notify user
        try:
            if is_upcoming:
                notify_msg = f"Admin has queued an Elite plan for you (activates {scheduled_start[:10]}). {prc_amount:,.0f} PRC deducted."
                await log_activity(user_id=user_id, action_type="subscription_prc_admin_upcoming",
                    description=f"Admin queued Elite (PRC): {prc_amount:.0f}", metadata=payment_record)
            else:
                notify_msg = f"Admin has activated your Elite plan (expires {new_expiry[:10]}). {prc_amount:,.0f} PRC deducted."
                await log_activity(user_id=user_id, action_type="subscription_prc_admin_activated",
                    description=f"Admin activated Elite (PRC): {prc_amount:.0f}", metadata=payment_record)
            if overdraft_applied:
                notify_msg += f" Your PRC balance is now {balance_after:,.0f}. Future earnings will clear this debt."
            await create_notification(
                user_id=user_id,
                title="Elite Subscription — Admin Activated",
                message=notify_msg,
                notification_type="subscription",
            )
        except Exception:
            pass

        # 15) Sustainability burn hook (non-fatal)
        try:
            await apply_sustainability_burn(
                user_id=user_id,
                service_type="subscription_prc_admin",
                service_ref_id=payment_id,
                amount_inr=pricing.get("base_with_gst_inr"),
            )
        except Exception as burn_err:
            logging.warning(f"[ADMIN-FORCE-SUB] Sustain burn failed (non-fatal): {burn_err}")

        # 16) Community success story (immediate only)
        if not is_upcoming:
            try:
                from routes.community import create_success_story_post
                asyncio.create_task(create_success_story_post(
                    user_id=user_id,
                    service_type="subscription",
                    amount_inr=pricing.get("base_with_gst_inr") or 0,
                    plan_name="Elite",
                    ref_id=f"sub_{payment_id}",
                ))
            except Exception as _e:
                logging.warning(f"[ADMIN-FORCE-SUB] community post hook failed (non-fatal): {_e}")

        logging.info(
            f"[ADMIN-FORCE-SUB] OK admin={admin_uid} user={user_name} ({user_id}) "
            f"-{prc_amount:.0f} PRC balance_after={balance_after} overdraft={overdraft_applied} upcoming={is_upcoming}"
        )

        return {
            "success": True,
            "message": (
                f"Elite subscription {'queued' if is_upcoming else 'activated'} for {user_name}. "
                f"{prc_amount:,.0f} PRC deducted."
                + (f" Overdraft of {abs(balance_after):,.0f} PRC applied." if overdraft_applied else "")
            ),
            "is_upcoming": is_upcoming,
            "user": {
                "uid": user_id,
                "name": user_name,
                "mobile": target_user.get("mobile"),
                "email": target_user.get("email"),
            },
            "subscription": {
                "plan": "elite",
                "expiry": (scheduled_end if is_upcoming else new_expiry)[:10],
                "prc_deducted": round(prc_amount, 2),
                "inr_equivalent": pricing["base_with_gst_inr"],
                "prc_rate_used": prc_rate,
                "duration_days": duration_days,
                "pricing_breakdown": pricing,
            },
            "balance": {
                "before": round(current_balance, 2),
                "after": balance_after,
                "overdraft_applied": overdraft_applied,
                "debt_amount": abs(balance_after) if overdraft_applied else 0,
            },
            "chances": {
                "used_before": prior_count,
                "used_after": prior_count + 1,
                "remaining": None,
                "unlimited": True,
            },
            "payment_id": payment_id,
        }

    except HTTPException:
        raise
    except Exception as e:
        logging.error(f"[ADMIN-FORCE-SUB] Unexpected error: {str(e)}")
        import traceback
        logging.error(traceback.format_exc())
        raise HTTPException(status_code=500, detail=f"Admin force-activation failed: {str(e)}")


@api_router.get("/admin/subscription/force-activate-preview")
async def admin_force_activate_preview(identifier: str):
    """Preview endpoint: returns target user summary + Elite pricing + eligibility
    (cooldown, chances used) so the Admin UI can show a confirmation summary
    BEFORE the PIN is entered."""
    try:
        if not identifier or not identifier.strip():
            raise HTTPException(status_code=400, detail="Identifier required.")
        ident = identifier.strip()

        # Lookup
        target_user = None
        digits = "".join(ch for ch in ident if ch.isdigit())
        if len(digits) >= 10:
            mobile10 = digits[-10:]
            target_user = await db.users.find_one({"mobile": {"$regex": f"{mobile10}$"}})
        if not target_user and "@" in ident:
            target_user = await db.users.find_one({"email": {"$regex": f"^{re.escape(ident)}$", "$options": "i"}})
        if not target_user:
            target_user = await db.users.find_one({"uid": ident})
        if not target_user:
            raise HTTPException(status_code=404, detail=f"No user found for '{ident}'.")

        user_id = target_user["uid"]
        current_balance = float(target_user.get("prc_balance", 0) or 0)

        # Pricing
        pricing = await calculate_elite_prc_price()
        prc_required = pricing["total_prc"]

        # Chances used
        COUNTING_STATUSES = ["paid", "upcoming", "active", "completed", "expired"]
        used_count = await db.subscription_payments.count_documents({
            "user_id": user_id,
            "payment_method": "prc",
            "status": {"$in": COUNTING_STATUSES},
        })

        # Cooldown
        cooldown = await check_service_cooldown(user_id, "subscription")
        cooldown_blocked = not cooldown.get("allowed", True)
        cooldown_reason = None
        if cooldown_blocked:
            wait_days = cooldown.get("wait_days") or round(cooldown.get("wait_hours", 0) / 24, 1)
            cooldown_reason = f"Cooldown: must wait {wait_days:.0f} more days"

        # Active plan?
        current_expiry = get_user_expiry(target_user)
        is_expired_flag = target_user.get("subscription_expired", False)
        has_active_plan = False
        if current_expiry and not is_expired_flag:
            try:
                if isinstance(current_expiry, str):
                    expiry_dt = datetime.fromisoformat(current_expiry.replace('Z', '+00:00'))
                else:
                    expiry_dt = current_expiry
                if expiry_dt.tzinfo is None:
                    expiry_dt = expiry_dt.replace(tzinfo=timezone.utc)
                if expiry_dt > datetime.now(timezone.utc):
                    has_active_plan = True
            except Exception:
                pass

        projected_balance = round(current_balance - prc_required, 2)
        overdraft_will_apply = projected_balance < 0

        # PRC cap removed May 2026 — unlimited
        chances_exhausted = False

        return {
            "user": {
                "uid": user_id,
                "name": target_user.get("name", "User"),
                "mobile": target_user.get("mobile"),
                "email": target_user.get("email"),
                "current_plan": target_user.get("subscription_plan", "explorer"),
                "current_expiry": (current_expiry.isoformat() if hasattr(current_expiry, "isoformat") else current_expiry) if current_expiry else None,
                "prc_balance": round(current_balance, 2),
            },
            "pricing": {
                "prc_required": round(prc_required, 2),
                "prc_rate_used": pricing["prc_rate"],
                "inr_equivalent": pricing["base_with_gst_inr"],
                "breakdown": pricing,
            },
            "projection": {
                "balance_after": projected_balance,
                "overdraft_will_apply": overdraft_will_apply,
                "debt_amount": abs(projected_balance) if overdraft_will_apply else 0,
                "is_upcoming": has_active_plan,
            },
            "eligibility": {
                "chances_used": used_count,
                "chances_max": None,
                "chances_remaining": None,
                "chances_exhausted": chances_exhausted,
                "unlimited": True,
                "cooldown_blocked": cooldown_blocked,
                "cooldown_reason": cooldown_reason,
                "can_proceed": not cooldown_blocked,
                "blockers": ([cooldown_reason] if cooldown_blocked else []),
            },
        }
    except HTTPException:
        raise
    except Exception as e:
        logging.error(f"[ADMIN-FORCE-SUB-PREVIEW] Error: {e}")
        raise HTTPException(status_code=500, detail=f"Preview failed: {str(e)}")


@api_router.get("/user/prc-debt-status/{uid}")
async def user_prc_debt_status(uid: str):
    """Return whether a user currently has PRC overdraft debt (balance < 0).
    Also auto-clears the `prc_debt_active` flag when balance has recovered to >= 0.
    """
    user = await db.users.find_one(
        {"uid": uid},
        {"_id": 0, "prc_balance": 1, "prc_debt_active": 1, "prc_debt_original": 1, "prc_debt_at": 1, "prc_debt_reason": 1, "prc_debt_cleared_at": 1},
    )
    if not user:
        raise HTTPException(status_code=404, detail="User not found")
    balance = float(user.get("prc_balance", 0) or 0)
    debt_active_flag = bool(user.get("prc_debt_active"))
    in_debt = balance < 0
    # Auto-clear stale flag once user has climbed back to zero
    if debt_active_flag and not in_debt:
        await db.users.update_one(
            {"uid": uid},
            {"$set": {"prc_debt_active": False, "prc_debt_cleared_at": datetime.now(timezone.utc).isoformat()}},
        )
        debt_active_flag = False
    original = float(user.get("prc_debt_original", 0) or 0)
    remaining = abs(balance) if in_debt else 0
    recovered = max(0, original - remaining) if original > 0 else 0
    return {
        "uid": uid,
        "in_debt": in_debt,
        "debt_active_flag": debt_active_flag,
        "current_balance": round(balance, 2),
        "debt_original": round(original, 2),
        "debt_remaining": round(remaining, 2),
        "debt_recovered": round(recovered, 2),
        "debt_at": user.get("prc_debt_at"),
        "debt_reason": user.get("prc_debt_reason"),
        "debt_cleared_at": user.get("prc_debt_cleared_at"),
    }


@api_router.post("/subscription/downgrade/{uid}")
async def downgrade_subscription(uid: str, request: Request):
    """Admin: Downgrade user to Explorer (free) plan"""
    data = await request.json()
    reason = data.get("reason", "Manual downgrade by admin")
    
    user = await db.users.find_one({"uid": uid})
    if not user:
        raise HTTPException(status_code=404, detail="User not found")
    
    old_plan = user.get("subscription_plan", "explorer")
    
    # Downgrade to explorer
    await db.users.update_one(
        {"uid": uid},
        {
            "$set": {
                "subscription_plan": "explorer",
                "subscription_expiry": None,
                "membership_type": "free"
            }
        }
    )
    
    # Log activity
    await log_activity(
        user_id=uid,
        action_type="subscription_downgrade",
        description=f"Subscription downgraded from {old_plan} to explorer: {reason}",
        metadata={"old_plan": old_plan, "reason": reason}
    )
    
    return {
        "success": True,
        "uid": uid,
        "old_plan": old_plan,
        "new_plan": "explorer"
    }


@api_router.post("/admin/check-expired-subscriptions")
async def check_expired_subscriptions():
    """
    Admin: Check and auto-downgrade expired subscriptions
    Should be run daily via cron/scheduler
    """
    now = datetime.now(timezone.utc)
    
    expired_users = []
    downgraded_count = 0
    grace_period_users = []
    
    # FIX: Use to_list() instead of async for to prevent cursor leak
    all_paid_users = await db.users.find({
        "subscription_plan": {"$in": ["startup", "growth", "elite"]},
        "subscription_expiry": {"$exists": True}
    }).to_list(length=2000)
    
    for user in all_paid_users:
        expiry_str = user.get("subscription_expiry")
        if not expiry_str:
            continue
        
        try:
            expiry = datetime.fromisoformat(expiry_str.replace('Z', '+00:00'))
            if expiry.tzinfo is None:
                expiry = expiry.replace(tzinfo=timezone.utc)
            
            if expiry < now:
                days_expired = (now - expiry).days
                uid = user.get("uid")
                plan = user.get("subscription_plan")
                
                # Grace period: 3 days after expiry
                if days_expired <= 3:
                    grace_period_users.append({
                        "uid": uid,
                        "email": user.get("email"),
                        "plan": plan,
                        "days_expired": days_expired,
                        "grace_days_left": 3 - days_expired
                    })
                    
                    # Send grace period notification
                    await db.notifications.insert_one({
                        "notification_id": str(uuid.uuid4()),
                        "user_id": uid,
                        "title": f"🔴 {plan.capitalize()} Expired - Grace Period Active",
                        "message": f"Your subscription expired {days_expired} day(s) ago. You have {3 - days_expired} day(s) left in grace period. Renew NOW to avoid losing benefits!",
                        "notification_type": "subscription_expired",
                        "read": False,
                        "created_at": now.isoformat()
                    })
                else:
                    # Grace period over - Auto downgrade
                    await db.users.update_one(
                        {"uid": uid},
                        {"$set": {
                            "subscription_plan": "explorer",
                            "previous_subscription_plan": plan,
                            "subscription_expired_at": expiry_str,
                            "downgraded_at": now.isoformat(),
                            "downgrade_reason": "auto_expired"
                        }}
                    )
                    
                    # Create notification
                    await db.notifications.insert_one({
                        "notification_id": str(uuid.uuid4()),
                        "user_id": uid,
                        "title": "⬇️ Downgraded to Explorer",
                        "message": f"Your {plan.capitalize()} subscription has expired. You've been moved to Explorer (Free) plan. Upgrade anytime to restore benefits!",
                        "notification_type": "subscription_downgraded",
                        "read": False,
                        "created_at": now.isoformat()
                    })
                    
                    # Log activity
                    await log_activity(
                        user_id=uid,
                        action_type="auto_downgrade",
                        description=f"Auto-downgraded from {plan} to explorer after grace period",
                        metadata={"old_plan": plan, "days_expired": days_expired}
                    )
                    
                    downgraded_count += 1
                    expired_users.append({
                        "uid": uid,
                        "email": user.get("email"),
                        "old_plan": plan,
                        "days_expired": days_expired
                    })
                    
        except Exception as e:
            print(f"[AUTO-DOWNGRADE] Error processing user {user.get('uid')}: {e}")
    
    return {
        "success": True,
        "checked_at": now.isoformat(),
        "downgraded_count": downgraded_count,
        "downgraded_users": expired_users,
        "grace_period_users": grace_period_users,
        "grace_period_count": len(grace_period_users)
    }


@api_router.get("/admin/user/{uid}/fraud-score")
async def get_user_fraud_score(uid: str):
    """
    Calculate comprehensive fraud risk score for a user (0-100)
    Higher score = Higher risk
    """
    user = await db.users.find_one({"uid": uid})
    if not user:
        raise HTTPException(status_code=404, detail="User not found")
    
    now = datetime.now(timezone.utc)
    score = 0
    risk_factors = []
    
    # 1. Account Age (New accounts = higher risk)
    created_at = user.get("created_at")
    if created_at:
        try:
            created = datetime.fromisoformat(created_at.replace('Z', '+00:00'))
            account_age_days = (now - created).days
            if account_age_days < 7:
                score += 20
                risk_factors.append(f"New account ({account_age_days} days old)")
            elif account_age_days < 30:
                score += 10
                risk_factors.append("Account less than 30 days old")
        except:
            pass
    
    # 2. KYC Status
    kyc_status = user.get("kyc_status")
    if kyc_status not in ["verified", "approved"]:
        score += 15
        risk_factors.append("KYC not verified")
    
    # 3. Multiple failed login attempts
    failed_logins = user.get("failed_login_attempts", 0)
    if failed_logins >= 5:
        score += 15
        risk_factors.append(f"Multiple failed logins ({failed_logins})")
    elif failed_logins >= 3:
        score += 8
        risk_factors.append(f"Recent failed logins ({failed_logins})")
    
    # 4. IP reputation
    registration_ip = user.get("registration_ip")
    if registration_ip:
        # Check how many accounts from same IP
        same_ip_count = await db.users.count_documents({"registration_ip": registration_ip})
        if same_ip_count >= 5:
            score += 20
            risk_factors.append(f"IP has {same_ip_count} accounts")
        elif same_ip_count >= 3:
            score += 10
            risk_factors.append(f"IP has multiple accounts ({same_ip_count})")
    
    # 5. Device fingerprint check
    device = user.get("device_fingerprint") or user.get("device_id")
    if device:
        same_device_count = await db.users.count_documents({
            "$or": [
                {"device_fingerprint": device},
                {"device_id": device}
            ]
        })
        if same_device_count >= 3:
            score += 20
            risk_factors.append(f"Device linked to {same_device_count} accounts")
    
    # 6. Transaction velocity (last 24 hours)
    yesterday = (now - timedelta(days=1)).isoformat()
    
    bill_count = await db.bill_payment_requests.count_documents({
        "user_id": uid,
        "created_at": {"$gte": yesterday}
    })
    if bill_count >= 5:
        score += 10
        risk_factors.append(f"High transaction velocity ({bill_count} bill payments today)")
    
    # 7. Large redemption amounts
    total_redeemed = user.get("total_redeemed_inr", 0)
    if total_redeemed > 50000:
        score += 5
        risk_factors.append(f"High total redemptions (₹{total_redeemed:,.0f})")
    
    # 8. Referral patterns
    referral_code = user.get("referral_code")
    if referral_code:
        referral_count = await db.users.count_documents({"referred_by": referral_code})
        if referral_count > 20:
            # Check if referrals are from same IP
            referrals_same_ip = await db.users.count_documents({
                "referred_by": referral_code,
                "registration_ip": registration_ip
            })
            if referrals_same_ip > 3:
                score += 25
                risk_factors.append(f"Suspicious referral pattern ({referrals_same_ip} from same IP)")
    
    # 9. Night activity check
    last_login = user.get("last_login_at")
    if last_login:
        try:
            login_time = datetime.fromisoformat(last_login.replace('Z', '+00:00'))
            if login_time.hour >= 0 and login_time.hour <= 5:
                score += 5
                risk_factors.append("Frequent night activity (12 AM - 5 AM)")
        except:
            pass
    
    # 10. Subscription anomaly
    plan = user.get("subscription_plan", "explorer")
    if plan != "explorer" and account_age_days < 7 if 'account_age_days' in dir() else False:
        score += 10
        risk_factors.append("Premium subscription on new account")
    
    # Cap score at 100
    score = min(100, score)
    
    # Determine risk level
    if score >= 70:
        risk_level = "critical"
    elif score >= 50:
        risk_level = "high"
    elif score >= 30:
        risk_level = "medium"
    else:
        risk_level = "low"
    
    return {
        "uid": uid,
        "email": user.get("email"),
        "name": user.get("name"),
        "fraud_score": score,
        "risk_level": risk_level,
        "risk_factors": risk_factors,
        "recommendation": "Block user" if score >= 70 else ("Review manually" if score >= 50 else ("Monitor" if score >= 30 else "Safe")),
        "checked_at": now.isoformat()
    }


