@api_router.post("/membership/payment/{uid}", response_model=VIPPayment)
async def submit_vip_payment(uid: str, payment: VIPPaymentCreate):
    """Submit VIP payment for verification"""
    
    # Check if UTR number is unique
    if payment.utr_number:
        utr_clean = payment.utr_number.strip().upper()
        if not await check_unique_utr(utr_clean):
            raise HTTPException(
                status_code=400, 
                detail=f"UTR number '{utr_clean}' आधीच वापरला गेला आहे. कृपया योग्य UTR number टाका."
            )
        payment.utr_number = utr_clean
    
    vip_payment = VIPPayment(
        user_id=uid,
        amount=payment.amount,
        date=payment.date,
        time=payment.time,
        utr_number=payment.utr_number,
        screenshot_url=payment.screenshot_base64
    )
    
    doc = vip_payment.model_dump()
    doc['created_at'] = doc['created_at'].isoformat()
    await db.vip_payments.insert_one(doc)
    
    return vip_payment


# ==================== ADMIN VIP PAYMENT VERIFICATION ====================

async def get_pending_payments_count():
    """Super fast endpoint to get just the pending payments count"""
    try:
        # Try cache first
        cached = await cache.get("pending_payments_count")
        if cached is not None:
            return {"count": cached}
        
        count = await db.vip_payments.count_documents({"status": "pending"})
        await cache.set("pending_payments_count", count, ttl=10)  # 10 second cache
        return {"count": count}
    except Exception as e:
        return {"count": 0, "error": str(e)}


async def get_admin_vip_payments(status: str = None, page: int = 1, limit: int = 50, search: str = None):
    """Get VIP payments for admin verification - OPTIMIZED with caching and search"""
    try:
        # Build cache key (no cache if searching)
        cache_key = f"admin_vip_payments:{status or 'all'}:p{page}:l{limit}"
        
        # Try cache first only if not searching (5 second TTL for pending, 30 seconds for others)
        if not search:
            cached = await cache.get(cache_key)
            if cached:
                return cached
        
        query = {}
        if status:
            query["status"] = status
        
        # If search provided, search across user data
        user_ids_to_search = []
        if search:
            search_lower = search.lower()
            # Search in users collection first
            search_users = await db.users.find({
                "$or": [
                    {"name": {"$regex": search, "$options": "i"}},
                    {"email": {"$regex": search, "$options": "i"}},
                    {"phone": {"$regex": search, "$options": "i"}},
                    {"mobile": {"$regex": search, "$options": "i"}}
                ]
            }, {"_id": 0, "uid": 1}).to_list(100)
            user_ids_to_search = [u["uid"] for u in search_users]
            
            # Also search by UTR number in payments
            query["$or"] = [
                {"utr_number": {"$regex": search, "$options": "i"}},
                {"user_id": {"$in": user_ids_to_search}} if user_ids_to_search else {"user_id": None}
            ]
        
        skip = (page - 1) * limit
        
        # Use count_documents with hint for better performance
        total = await db.vip_payments.count_documents(query)
        
        # Optimized query with projection - only fetch needed fields
        payments = await db.vip_payments.find(
            query, 
            {
                "_id": 0,
                "payment_id": 1,
                "user_id": 1,
                "subscription_plan": 1,
                "plan_type": 1,
                "amount": 1,
                "utr_number": 1,
                "screenshot_url": 1,
                "date": 1,
                "time": 1,
                "status": 1,
                "submitted_at": 1,
                "approved_at": 1,
                "rejected_at": 1,
                "admin_notes": 1
            }
        ).sort("submitted_at", -1).skip(skip).limit(limit).to_list(limit)
        
        if not payments:
            result = {"payments": [], "total": total, "page": page, "pages": 0}
            await cache.set(cache_key, result, ttl=30)
            return result
        
        # Batch fetch all user details in ONE query
        user_ids = list(set(p.get("user_id") for p in payments if p.get("user_id")))
        users_data = {}
        
        if user_ids:
            users_cursor = db.users.find(
                {"uid": {"$in": user_ids}}, 
                {"_id": 0, "uid": 1, "name": 1, "email": 1, "phone": 1, "mobile": 1, "city": 1, "state": 1, 
                 "subscription_plan": 1, "subscription_expiry": 1, "prc_balance": 1, "total_mined": 1,
                 "kyc_status": 1, "referral_code": 1, "created_at": 1, "membership_type": 1}
            )
            # FIX: Use to_list() instead of async for to prevent cursor leak
            users_list = await users_cursor.to_list(length=1000)
            for user in users_list:
                users_data[user.get("uid")] = user
        
        # Batch count previous payments using aggregation
        prev_payments_pipeline = [
            {"$match": {"user_id": {"$in": user_ids}, "status": {"$in": ["approved", "completed", "paid", "APPROVED", "COMPLETED", "PAID"]}}},
            {"$group": {"_id": "$user_id", "count": {"$sum": 1}}}
        ]
        prev_payments_result = await db.vip_payments.aggregate(prev_payments_pipeline).to_list(100)
        prev_payments_map = {r["_id"]: r["count"] for r in prev_payments_result}
        
        # Enrich payments with cached data
        for payment in payments:
            user_id = payment.get("user_id")
            
            if user_id and user_id in users_data:
                user = users_data[user_id]
                payment["user_name"] = user.get("name", "Unknown")
                payment["user_email"] = user.get("email", "")
                payment["user_phone"] = user.get("phone") or user.get("mobile", "")
                payment["user_mobile"] = user.get("mobile", "")
                payment["user_city"] = user.get("city", "")
                payment["user_state"] = user.get("state", "")
                payment["current_plan"] = user.get("subscription_plan") or user.get("membership_type", "explorer")
                payment["current_expiry"] = user.get("subscription_expiry", "")
                payment["user_prc_balance"] = user.get("prc_balance", 0)
                payment["user_total_mined"] = user.get("total_mined", 0)
                payment["user_kyc_status"] = user.get("kyc_status", "pending")
                payment["user_referral_code"] = user.get("referral_code", "")
                payment["user_created_at"] = user.get("created_at", "")
            else:
                payment["user_name"] = "Unknown User"
                payment["user_email"] = ""
                payment["user_phone"] = ""
                payment["user_prc_balance"] = 0
                payment["user_kyc_status"] = "unknown"
            
            # Use batch counted data
            payment["user_previous_payments"] = prev_payments_map.get(user_id, 0)
            payment["user_total_orders"] = 0  # Skip for performance, not critical
        
        result = {
            "payments": payments,
            "total": total,
            "page": page,
            "pages": (total + limit - 1) // limit
        }
        
        # Cache the result (5 seconds for pending, 30 for others)
        cache_ttl = 5 if status == "pending" else 30
        await cache.set(cache_key, result, ttl=cache_ttl)
        
        return result
    except Exception as e:
        raise HTTPException(status_code=500, detail=get_user_friendly_error(e))


@api_router.get("/admin/subscription/fraud-check/{user_id}")
async def check_subscription_fraud(user_id: str, days: int = 10):
    """
    Check if user has recent subscription activity that might indicate fraud.
    Used by admin before approving a new subscription request.
    """
    try:
        from datetime import timedelta
        
        now = datetime.now(timezone.utc)
        check_date = now - timedelta(days=days)
        
        # Find recently approved subscriptions
        recent_subscriptions = await db.vip_payments.find({
            "$or": [{"user_id": user_id}, {"user_uid": user_id}],
            "status": "approved",
            "approved_at": {"$gte": check_date.isoformat()}
        }).sort("approved_at", -1).to_list(length=10)
        
        # Get user info
        user = await db.users.find_one({"uid": user_id})
        
        warnings = []
        
        if recent_subscriptions:
            for sub in recent_subscriptions:
                approved_at = sub.get("approved_at", "")
                if approved_at:
                    try:
                        approved_date = datetime.fromisoformat(approved_at.replace('Z', '+00:00'))
                        days_ago = (now - approved_date).days
                    except:
                        days_ago = 0
                else:
                    days_ago = 0
                
                warnings.append({
                    "type": "RECENT_SUBSCRIPTION",
                    "severity": "high" if days_ago <= 3 else "medium",
                    "message": f"User activated {sub.get('subscription_plan', 'N/A')} plan {days_ago} days ago",
                    "payment_id": sub.get("payment_id"),
                    "plan": sub.get("subscription_plan"),
                    "amount": sub.get("amount"),
                    "approved_at": approved_at,
                    "days_ago": days_ago
                })
        
        # Check total subscription count
        total_subscriptions = user.get("subscription_count", 0) if user else 0
        if total_subscriptions > 5:
            warnings.append({
                "type": "HIGH_SUBSCRIPTION_COUNT",
                "severity": "medium",
                "message": f"User has {total_subscriptions} total subscriptions",
                "count": total_subscriptions
            })
        
        # Check if current subscription is still active
        if user:
            current_expiry = get_user_expiry(user)
            if current_expiry:
                try:
                    if isinstance(current_expiry, str):
                        expiry_date = datetime.fromisoformat(current_expiry.replace('Z', '+00:00'))
                    else:
                        expiry_date = current_expiry
                    
                    if expiry_date > now:
                        remaining_days = (expiry_date - now).days
                        warnings.append({
                            "type": "ACTIVE_SUBSCRIPTION",
                            "severity": "high",
                            "message": f"User already has active subscription with {remaining_days} days remaining",
                            "current_plan": user.get("subscription_plan"),
                            "expiry": current_expiry if isinstance(current_expiry, str) else current_expiry.isoformat(),
                            "remaining_days": remaining_days
                        })
                except:
                    pass
        
        has_fraud_risk = len(warnings) > 0
        
        return {
            "user_id": user_id,
            "has_fraud_risk": has_fraud_risk,
            "risk_level": "high" if any(w.get("severity") == "high" for w in warnings) else ("medium" if warnings else "low"),
            "warnings": warnings,
            "checked_period_days": days,
            "user_info": {
                "name": user.get("name") if user else None,
                "current_plan": user.get("subscription_plan") if user else None,
                "total_subscriptions": total_subscriptions
            }
        }
    except Exception as e:
        raise HTTPException(status_code=500, detail=get_user_friendly_error(e))


@api_router.post("/admin/vip-payment/{payment_id}/approve")
async def approve_vip_payment(payment_id: str, request: Request):
    """Approve VIP payment and activate membership.

    Hardened (May 2026): Critical-path operations execute synchronously with
    fast 8s Atlas timeouts (was 25s causing client aborts). All non-critical
    work — fund routing, activity logs, cache invalidation, community hooks —
    is dispatched to background tasks so the user gets a response in <2s
    typical instead of the previous worst-case 95s.

    Idempotent: if `payment.status != pending` we short-circuit:
      • approved   → return success (replay-safe)
      • rejected/anything else → 400 with reason
    The atomic CAS on the status update also guards against double-approve
    races between two concurrent admins clicking "Approve" simultaneously.
    """
    # Tunable Atlas timeouts. Atlas P95 is ~500ms in healthy state but cold
    # connections + large COLLSCANs (pre-index) can push to 4-5s. 8s is a
    # 16× margin over P95 and tolerates a single slow query while still
    # aborting before frontend axios timeout (30s).
    DB_FAST_TIMEOUT = 8.0
    try:
        print(f"VIP Payment approve request: payment_id={payment_id}")

        data = await request.json()
        admin_id = data.get("admin_id")
        notes = data.get("notes", "")
        correct_plan = data.get("correct_plan")  # NEW: Admin can specify correct plan
        correct_duration = data.get("correct_duration")  # NEW: Admin can specify correct duration

        # Get payment with timeout
        try:
            payment = await asyncio.wait_for(
                db.vip_payments.find_one({"payment_id": payment_id}),
                timeout=DB_FAST_TIMEOUT,
            )
        except asyncio.TimeoutError:
            raise HTTPException(
                status_code=504,
                detail="Database is slow right now. Please try again — your action will work next time.",
            )
        except Exception as db_err:
            # Motor / pymongo timeouts (NetworkTimeout, ServerSelectionTimeoutError)
            # don't surface as asyncio.TimeoutError. Treat them as 504 so the
            # frontend's retry interceptor will replay the request.
            if any(t in str(db_err).lower() for t in ["timeout", "timed out", "serverselection", "networktimeout"]):
                raise HTTPException(
                    status_code=504,
                    detail="Database is slow right now. Please try again — your action will work next time.",
                )
            raise

        if not payment:
            print(f"VIP Payment not found: {payment_id}")
            raise HTTPException(status_code=404, detail=f"Payment not found: {payment_id}")

        current_status = payment.get("status")
        if current_status != "pending":
            print(f"VIP Payment already processed: {payment_id} status={current_status}")
            # Return success for already approved (idempotent)
            if current_status == "approved":
                return {"message": "Payment already approved", "status": "approved", "success": True}
            raise HTTPException(status_code=400, detail=f"Payment already {current_status}")
        
        user_id = payment.get("user_id")
        print(f"Processing VIP payment for user: {user_id}")
        
        # Use corrected plan/duration if admin specified (fraud prevention)
        original_plan = payment.get("subscription_plan", "startup")
        original_duration = payment.get("plan_type", "monthly")
        
        subscription_plan = correct_plan if correct_plan else original_plan
        plan_type = correct_duration if correct_duration else original_duration
        
        # Track if plan was corrected
        plan_corrected = (correct_plan and correct_plan != original_plan) or (correct_duration and correct_duration != original_duration)
        
        # Calculate duration days
        now = datetime.now(timezone.utc)
        duration_days = {
            "monthly": 28,
            "quarterly": 84,
            "half_yearly": 168,
            "yearly": 336
        }.get(plan_type, 28)
        
        # Get current user to check existing subscription with fast timeout
        try:
            user = await asyncio.wait_for(
                db.users.find_one({"uid": user_id}),
                timeout=DB_FAST_TIMEOUT,
            )
        except asyncio.TimeoutError:
            raise HTTPException(
                status_code=504,
                detail="Database is slow right now. Please try again.",
            )
        except Exception as db_err:
            if any(t in str(db_err).lower() for t in ["timeout", "timed out", "serverselection", "networktimeout"]):
                raise HTTPException(
                    status_code=504,
                    detail="Database is slow right now. Please try again.",
                )
            raise
        
        # ========== FRAUD PREVENTION: Check recent subscription activity ==========
        fraud_warning = None
        recent_days = 10  # Check for subscriptions in last 10 days
        check_date = now - timedelta(days=recent_days)
        
        # Find recently approved subscriptions for this user (fast timeout —
        # fraud check is informational only, never block approval on slow Atlas)
        try:
            recent_subscriptions = await asyncio.wait_for(
                db.vip_payments.find({
                    "$or": [{"user_id": user_id}, {"user_uid": user_id}],
                    "status": "approved",
                    "approved_at": {"$gte": check_date.isoformat()}
                }).to_list(length=10),
                timeout=DB_FAST_TIMEOUT,
            )
        except asyncio.TimeoutError:
            recent_subscriptions = []  # Fail open — fraud check is non-blocking
        
        if recent_subscriptions and len(recent_subscriptions) > 0:
            last_sub = recent_subscriptions[0]
            last_approved = last_sub.get("approved_at", "")
            last_plan = last_sub.get("subscription_plan", "")
            days_since = (now - datetime.fromisoformat(last_approved.replace('Z', '+00:00'))).days if last_approved else 0
            
            fraud_warning = {
                "type": "RECENT_SUBSCRIPTION_EXISTS",
                "message": f"⚠️ WARNING: This user already activated a subscription ({last_plan}) {days_since} days ago!",
                "last_subscription": {
                    "plan": last_plan,
                    "approved_at": last_approved,
                    "days_ago": days_since,
                    "payment_id": last_sub.get("payment_id")
                },
                "recommendation": "Please verify if this is a legitimate renewal or potential fraud."
            }
        
        # ========== DETERMINE IF NEW SUBSCRIPTION OR RENEWAL ==========
        is_renewal = False
        is_upgrade = False
        is_downgrade = False
        previous_plan = None
        subscription_count = 0
        
        if user:
            previous_plan = user.get("subscription_plan")
            subscription_count = user.get("subscription_count", 0)
            
            # Check if user ever had a paid subscription before
            if previous_plan and previous_plan in ["startup", "growth", "elite"]:
                is_renewal = True
                
                # Check if upgrading or downgrading
                plan_hierarchy = {"explorer": 0, "startup": 1, "growth": 2, "elite": 3}
                old_level = plan_hierarchy.get(previous_plan, 0)
                new_level = plan_hierarchy.get(subscription_plan, 0)
                
                if new_level > old_level:
                    is_upgrade = True
                    is_renewal = False  # Upgrade is different from renewal
                elif new_level < old_level:
                    is_downgrade = True
            else:
                # First time subscriber
                is_renewal = False
        
        subscription_type = "renewal" if is_renewal else ("upgrade" if is_upgrade else ("downgrade" if is_downgrade else "new"))
        
        # EXTEND LOGIC: Add new days to existing subscription if not expired
        start_date = now
        if user:
            current_expiry = get_user_expiry(user)
            if current_expiry:
                try:
                    # Parse current expiry date
                    if isinstance(current_expiry, str):
                        current_expiry_dt = datetime.fromisoformat(current_expiry.replace('Z', '+00:00'))
                    else:
                        current_expiry_dt = current_expiry
                    
                    # If current subscription is still valid, extend from that date
                    if current_expiry_dt > now:
                        start_date = current_expiry_dt
                        # Log the extension
                        remaining_days = (current_expiry_dt - now).days
                        print(f"Extending subscription: {remaining_days} days remaining + {duration_days} new days")
                except Exception as e:
                    print(f"Error parsing expiry date: {e}")
                    start_date = now
        
        # Calculate new expiry from start_date
        new_expiry = (start_date + timedelta(days=duration_days)).isoformat()
        
        # Get subscription plan from payment (default to startup for legacy)
        subscription_plan = payment.get("subscription_plan", "startup")
        
        # Update user with new subscription system - with fast timeout
        try:
            await asyncio.wait_for(
                db.users.update_one(
                    {"uid": user_id},
                    {
                        "$set": {
                            "membership_type": "vip",  # Legacy compatibility
                            "subscription_plan": subscription_plan,
                            "subscription_expiry": new_expiry,
                            "vip_activated_at": now.isoformat(),
                            "last_subscription_renewed": now.isoformat(),
                            "previous_subscription_plan": previous_plan,  # Track previous plan
                        },
                        "$inc": {
                            "subscription_count": 1  # Increment subscription count
                        }
                    }
                ),
                timeout=DB_FAST_TIMEOUT,
            )
        except asyncio.TimeoutError:
            raise HTTPException(
                status_code=504,
                detail="Database is slow right now. Please try again.",
            )
        except Exception as db_err:
            if any(t in str(db_err).lower() for t in ["timeout", "timed out", "serverselection", "networktimeout"]):
                raise HTTPException(
                    status_code=504,
                    detail="Database is slow right now. Please try again.",
                )
            raise
        
        # Update payment status with correction info
        # Generate TXN number
        txn_number = f"SUB{datetime.now(timezone.utc).strftime('%Y%m%d%H%M%S')}{uuid.uuid4().hex[:6].upper()}"
        
        try:
            # Atomic CAS: only flip from pending → approved. If another admin
            # raced ahead, this returns modified_count==0 and we DON'T return
            # an error (user already activated → success outcome stands).
            cas_res = await asyncio.wait_for(
                db.vip_payments.update_one(
                    {"payment_id": payment_id, "status": "pending"},
                    {
                        "$set": {
                            "status": "approved",
                            "txn_number": txn_number,
                            "approved_at": now.isoformat(),
                            "approved_by": admin_id,
                            "admin_notes": notes,
                            "subscription_extended": start_date != now,
                            "new_expiry": new_expiry,
                            # NEW vs RENEWAL tracking
                            "subscription_type": subscription_type,  # "new", "renewal", "upgrade", "downgrade"
                            "is_renewal": is_renewal,
                            "is_upgrade": is_upgrade,
                            "is_downgrade": is_downgrade,
                            "previous_plan": previous_plan,
                            "user_subscription_count": subscription_count + 1,
                            # Fraud prevention tracking
                            "plan_corrected": plan_corrected,
                            "original_plan_claimed": original_plan,
                            "original_duration_claimed": original_duration,
                            "actual_plan_approved": subscription_plan,
                            "actual_duration_approved": plan_type
                        }
                    }
                ),
                timeout=DB_FAST_TIMEOUT,
            )
            if cas_res.modified_count == 0:
                # Another admin already approved this in the last few ms.
                # Idempotent: tell client it's already done.
                logging.info(f"[APPROVE-VIP] CAS race — payment {payment_id} already approved")
        except asyncio.TimeoutError:
            # User already updated, payment update failed - log and continue
            print(f"Timeout updating payment status for {payment_id}, but user subscription activated")
        
        # ========== NON-CRITICAL POST-APPROVE WORK — BACKGROUNDED ==========
        # All of these are fire-and-forget so the admin gets an instant
        # "Approved!" toast. Failures here do NOT block subscription
        # activation (which already succeeded above).
        async def _post_approve_background():
            # GST Routing (manual subscription company wallets)
            try:
                payment_amount = payment.get("amount", 0)
                if payment_amount > 0:
                    user_name_for_wallet = (
                        user.get("name", user.get("email", "User")) if user else "User"
                    )
                    await asyncio.wait_for(
                        credit_company_wallets_for_manual_subscription(
                            user_id=user_id,
                            amount_paid=payment_amount,
                            user_name=user_name_for_wallet,
                        ),
                        timeout=DB_FAST_TIMEOUT,
                    )
                    logging.info(f"[GST-ROUTING] credited for {payment_id}")
            except Exception as wallet_error:
                logging.warning(
                    f"[GST-ROUTING] non-fatal failure for {payment_id}: {wallet_error}"
                )

            # Activity log
            try:
                await asyncio.wait_for(
                    db.activity_logs.insert_one({
                        "log_id": str(uuid.uuid4()),
                        "action": "vip_payment_approved",
                        "user_id": user_id,
                        "admin_id": admin_id,
                        "payment_id": payment_id,
                        "amount": payment.get("amount"),
                        "plan_type": plan_type,
                        "subscription_plan": subscription_plan,
                        "plan_corrected": plan_corrected,
                        "original_claimed": {"plan": original_plan, "duration": original_duration},
                        "extended": start_date != now,
                        "new_expiry": new_expiry,
                        "timestamp": now.isoformat(),
                    }),
                    timeout=5.0,
                )
            except Exception:
                pass  # Non-critical

            # Cache invalidation
            try:
                await cache.delete("admin_vip_payments:pending:p1:l50")
                await cache.delete("admin_vip_payments:all:p1:l50")
            except Exception:
                pass

            # Community success-story hook
            try:
                from routes.community import create_success_story_post
                await create_success_story_post(
                    user_id=user_id,
                    service_type="subscription",
                    amount_inr=float(payment.get("amount") or 0),
                    plan_name=subscription_plan,
                    ref_id=f"sub_{payment_id}",
                )
            except Exception as _e:
                logging.warning(f"[COMMUNITY] post hook failed (non-fatal): {_e}")

        asyncio.create_task(_post_approve_background())

        # Calculate total days for message
        if start_date != now:
            remaining = (start_date - now).days
            message = f"Payment approved! Subscription extended. {remaining} remaining + {duration_days} new = {remaining + duration_days} total days"
        else:
            message = f"Payment approved! {duration_days} days subscription activated"

        return {"success": True, "message": message, "new_expiry": new_expiry, "fraud_warning": fraud_warning}
    except HTTPException:
        raise
    except Exception as e:
        # If anything that escaped the inner try blocks looks like an Atlas
        # transient timeout, surface 504 (frontend will auto-retry once)
        # instead of 500 which is fatal in the eyes of the UI.
        err_str = str(e).lower()
        if any(t in err_str for t in ["timeout", "timed out", "serverselection", "networktimeout"]):
            raise HTTPException(
                status_code=504,
                detail="Database is slow right now. Please try again — your action will work next time.",
            )
        raise HTTPException(status_code=500, detail=get_user_friendly_error(e))


