async def get_referral_uids(referrer_uid: str) -> list:
    """Get list of UIDs of users referred by a specific user (checks both uid and referral_code)"""
    referrer = await db.users.find_one({"uid": referrer_uid}, {"_id": 0, "referral_code": 1})
    referral_code = referrer.get("referral_code", "") if referrer else ""
    
    or_conditions = [{"referred_by": referrer_uid}]
    if referral_code:
        or_conditions.append({"referred_by": referral_code})
    
    referrals = await db.users.find(
        {"$or": or_conditions},
        {"uid": 1, "_id": 0}
    ).to_list(1000)
    return [r["uid"] for r in referrals]

@api_router.post("/admin/vip-payment/{payment_id}/reject")
async def reject_vip_payment(payment_id: str, request: Request):
    """Reject VIP payment.

    Hardened (May 2026): 25s Atlas timeouts replaced with 8s fast-fail. All
    non-critical work (notifications, activity logs, cache invalidation)
    runs in background so the admin gets a sub-2s "Rejected!" toast.
    Idempotent — re-rejecting an already-rejected payment returns success.
    """
    DB_FAST_TIMEOUT = 8.0
    try:
        data = await request.json()
        admin_id = data.get("admin_id")
        reason = data.get("reason", "")

        # Require reject reason
        if not reason:
            raise HTTPException(status_code=400, detail="Reject reason is required")

        # Get payment with fast timeout
        try:
            payment = await asyncio.wait_for(
                db.vip_payments.find_one({"payment_id": payment_id}),
                timeout=DB_FAST_TIMEOUT,
            )
        except asyncio.TimeoutError:
            raise HTTPException(
                status_code=504,
                detail="Database is slow right now. Please try again — your action will work next time.",
            )
        except Exception as db_err:
            # Motor / pymongo timeouts surface as plain Exception, not asyncio.TimeoutError.
            # Coerce to 504 so frontend auto-retry kicks in.
            if any(t in str(db_err).lower() for t in ["timeout", "timed out", "serverselection", "networktimeout"]):
                raise HTTPException(
                    status_code=504,
                    detail="Database is slow right now. Please try again — your action will work next time.",
                )
            raise
        if not payment:
            raise HTTPException(status_code=404, detail="Payment not found")

        current_status = payment.get("status")
        if current_status != "pending":
            # Idempotent: re-rejecting an already-rejected payment is a no-op success
            if current_status == "rejected":
                return {"success": True, "message": "Payment already rejected", "reject_reason": payment.get("reject_reason") or payment.get("rejection_reason")}
            raise HTTPException(status_code=400, detail=f"Payment already {current_status}")

        now = datetime.now(timezone.utc)

        # Atomic CAS update — only flips pending → rejected. Concurrent reject
        # attempts: only one wins, second gets modified_count==0 and we treat
        # it as already-rejected (idempotent success).
        try:
            cas_res = await asyncio.wait_for(
                db.vip_payments.update_one(
                    {"payment_id": payment_id, "status": "pending"},
                    {
                        "$set": {
                            "status": "rejected",
                            "rejected_at": now.isoformat(),
                            "rejected_by": admin_id,
                            "rejection_reason": reason,
                            "reject_reason": reason,  # Consistent field name
                        }
                    }
                ),
                timeout=DB_FAST_TIMEOUT,
            )
            if cas_res.modified_count == 0:
                logging.info(f"[REJECT-VIP] CAS race — payment {payment_id} already rejected")
        except asyncio.TimeoutError:
            raise HTTPException(
                status_code=504,
                detail="Database is slow right now. Please try again.",
            )
        except Exception as db_err:
            if any(t in str(db_err).lower() for t in ["timeout", "timed out", "serverselection", "networktimeout"]):
                raise HTTPException(
                    status_code=504,
                    detail="Database is slow right now. Please try again.",
                )
            raise

        # ========== NON-CRITICAL POST-REJECT WORK — BACKGROUNDED ==========
        async def _post_reject_background():
            # Notify user
            try:
                await create_notification(
                    user_id=payment.get("user_id"),
                    notification_type="subscription",
                    title="Subscription Payment Rejected",
                    message=f"Your subscription payment was rejected. Reason: {reason}",
                    data={"payment_id": payment_id, "reason": reason},
                )
            except Exception as _ne:
                logging.warning(f"[REJECT-VIP] notification create failed: {_ne}")

            # Activity log
            try:
                await asyncio.wait_for(
                    db.activity_logs.insert_one({
                        "log_id": str(uuid.uuid4()),
                        "action": "vip_payment_rejected",
                        "user_id": payment.get("user_id"),
                        "admin_id": admin_id,
                        "payment_id": payment_id,
                        "reason": reason,
                        "timestamp": now.isoformat(),
                    }),
                    timeout=5.0,
                )
            except Exception as _le:
                logging.warning(f"[REJECT-VIP] activity_log insert failed: {_le}")

            # Cache invalidation
            try:
                await cache.delete("admin_vip_payments:pending:p1:l50")
                await cache.delete("admin_vip_payments:all:p1:l50")
            except Exception:
                pass

        asyncio.create_task(_post_reject_background())

        return {"success": True, "message": "Payment rejected", "reject_reason": reason}
    except HTTPException:
        raise
    except Exception as e:
        err_str = str(e).lower()
        if any(t in err_str for t in ["timeout", "timed out", "serverselection", "networktimeout"]):
            raise HTTPException(
                status_code=504,
                detail="Database is slow right now. Please try again — your action will work next time.",
            )
        raise HTTPException(status_code=500, detail=get_user_friendly_error(e))


@api_router.post("/admin/vip-payments/bulk-approve")
async def admin_bulk_approve_vip_payments(request: Request):
    """Bulk-approve multiple pending VIP/manual subscription payments.
    Internally calls the canonical `approve_vip_payment` per payment_id so
    every fraud-prevention check, community hook, fund-routing, and
    notification fires identically to single-approve.
    Body: {"payment_ids": [...], "admin_id": "...", "notes": "..."}
    Returns: {"results": [{payment_id, success, message|error}], "approved": N, "failed": M}
    """
    try:
        data = await request.json()
        payment_ids = data.get("payment_ids") or []
        admin_id = data.get("admin_id")
        notes = data.get("notes", "")
        if not isinstance(payment_ids, list) or not payment_ids:
            raise HTTPException(status_code=400, detail="payment_ids array is required")
        # Cap to prevent admin from accidentally bulk-approving 1000s
        if len(payment_ids) > 50:
            raise HTTPException(status_code=400, detail="Cannot bulk-approve more than 50 payments at once")

        # Build a synthetic Request per payment so we can reuse the canonical fn.
        class _SyntheticReq:
            def __init__(self, body):
                self._body = body
            async def json(self):
                return self._body

        async def _approve_one(pid):
            try:
                fake_req = _SyntheticReq({"admin_id": admin_id, "notes": notes})
                res = await approve_vip_payment(pid, fake_req)  # type: ignore
                return {"payment_id": pid, "success": True, "message": res.get("message", "Approved")}
            except HTTPException as he:
                return {"payment_id": pid, "success": False, "error": str(he.detail), "status_code": he.status_code}
            except Exception as e:
                logging.warning(f"[BULK-APPROVE] {pid} failed: {e}")
                return {"payment_id": pid, "success": False, "error": get_user_friendly_error(e)}

        # Sequential execution — approval mutates user.subscription_expiry and we
        # don't want race conditions if two payments belong to the same user.
        results = []
        for pid in payment_ids:
            results.append(await _approve_one(pid))

        approved = sum(1 for r in results if r.get("success"))
        failed = len(results) - approved
        return {"results": results, "approved": approved, "failed": failed, "total": len(results)}
    except HTTPException:
        raise
    except Exception as e:
        raise HTTPException(status_code=500, detail=get_user_friendly_error(e))


@api_router.post("/admin/vip-payments/bulk-reject")
async def admin_bulk_reject_vip_payments(request: Request):
    """Bulk-reject multiple pending VIP/manual subscription payments with the
    same reason. Body: {"payment_ids": [...], "reason": "...", "admin_id": "..."}
    """
    try:
        data = await request.json()
        payment_ids = data.get("payment_ids") or []
        reason = (data.get("reason") or "").strip()
        admin_id = data.get("admin_id")
        if not isinstance(payment_ids, list) or not payment_ids:
            raise HTTPException(status_code=400, detail="payment_ids array is required")
        if not reason:
            raise HTTPException(status_code=400, detail="Reject reason is required")
        if len(payment_ids) > 50:
            raise HTTPException(status_code=400, detail="Cannot bulk-reject more than 50 payments at once")

        class _SyntheticReq:
            def __init__(self, body):
                self._body = body
            async def json(self):
                return self._body

        async def _reject_one(pid):
            try:
                fake_req = _SyntheticReq({"admin_id": admin_id, "reason": reason})
                res = await reject_vip_payment(pid, fake_req)  # type: ignore
                return {"payment_id": pid, "success": True, "message": res.get("message", "Rejected")}
            except HTTPException as he:
                return {"payment_id": pid, "success": False, "error": str(he.detail), "status_code": he.status_code}
            except Exception as e:
                logging.warning(f"[BULK-REJECT] {pid} failed: {e}")
                return {"payment_id": pid, "success": False, "error": get_user_friendly_error(e)}

        # Reject is independent → run in parallel for speed.
        results = await asyncio.gather(*[_reject_one(pid) for pid in payment_ids])
        rejected = sum(1 for r in results if r.get("success"))
        failed = len(results) - rejected
        return {"results": list(results), "rejected": rejected, "failed": failed, "total": len(results)}
    except HTTPException:
        raise
    except Exception as e:
        raise HTTPException(status_code=500, detail=get_user_friendly_error(e))


@api_router.get("/admin/vip-payments")
async def admin_list_vip_payments(
    status: Optional[str] = None,
    page: int = 1,
    limit: int = 20,
    search: Optional[str] = None,
):
    """List VIP/manual subscription payments grouped by status (pending/approved/rejected).
    Used by Admin → Manual Subscription Management tabs."""
    try:
        query = {}
        if status:
            query["status"] = status

        # Optional substring search across UTR / payment_id / user_email / user_name
        if search:
            search = search.strip()
            search_users = await db.users.find(
                {"$or": [
                    {"name": {"$regex": search, "$options": "i"}},
                    {"email": {"$regex": search, "$options": "i"}},
                    {"mobile": {"$regex": search, "$options": "i"}},
                    {"phone": {"$regex": search, "$options": "i"}},
                ]},
                {"_id": 0, "uid": 1}
            ).to_list(200)
            uids = [u["uid"] for u in search_users]
            or_clause = [
                {"utr_number": {"$regex": search, "$options": "i"}},
                {"payment_id": {"$regex": search, "$options": "i"}},
                {"user_email": {"$regex": search, "$options": "i"}},
                {"user_name": {"$regex": search, "$options": "i"}},
            ]
            if uids:
                or_clause.append({"user_id": {"$in": uids}})
            query["$or"] = or_clause

        skip = max(0, (page - 1) * limit)
        sort_field = "submitted_at"
        if status == "approved":
            sort_field = "approved_at"
        elif status == "rejected":
            sort_field = "rejected_at"

        total = await db.vip_payments.count_documents(query)
        payments = await db.vip_payments.find(query, {"_id": 0}).sort(sort_field, -1).skip(skip).limit(limit).to_list(limit)

        # Enrich with current user info (name/email/mobile)
        uids = list({p.get("user_id") for p in payments if p.get("user_id")})
        users_map = {}
        if uids:
            ulist = await db.users.find(
                {"uid": {"$in": uids}},
                {"_id": 0, "uid": 1, "name": 1, "email": 1, "mobile": 1, "phone": 1, "subscription_plan": 1, "subscription_expiry": 1}
            ).to_list(len(uids))
            users_map = {u["uid"]: u for u in ulist}
        for p in payments:
            u = users_map.get(p.get("user_id") or "", {})
            p["user_name"] = p.get("user_name") or u.get("name") or "Unknown"
            p["user_email"] = p.get("user_email") or u.get("email") or ""
            p["user_phone"] = p.get("user_phone") or u.get("mobile") or u.get("phone") or ""
            p["plan"] = p.get("subscription_plan", "")
            p["duration"] = p.get("plan_type", "monthly")
            if status == "approved" and not p.get("new_expiry"):
                p["new_expiry"] = u.get("subscription_expiry")

        return {
            "payments": payments,
            "total": total,
            "page": page,
            "pages": max(1, (total + limit - 1) // limit),
        }
    except Exception as e:
        logging.error(f"[ADMIN-VIP-LIST] error: {e}")
        raise HTTPException(status_code=500, detail=get_user_friendly_error(e))


