async def check_redeem_limit(user_id: str, amount: float) -> dict:
    """
    Check if user can redeem the specified amount.
    Uses dynamic Growth Network based limits.
    Returns: {"allowed": bool, "reason": str, "limit_info": dict}
    """
    try:
        limit_info = await calculate_user_redeem_limit(user_id)
        effective_available = limit_info.get("effective_available", 0)
        unlock_percent = limit_info.get("unlock_percent", 0)
        override_active = limit_info.get("override_active", False)
        
        # Block zero-unlock only when no admin override is present
        if unlock_percent == 0 and not override_active:
            return {
                "allowed": False,
                "reason": "Your Growth Network is too small. Get referrals to unlock redeem.",
                "limit_info": limit_info
            }
        
        if amount > effective_available:
            return {
                "allowed": False,
                "reason": f"Redeem limit exceeded. Available: {effective_available:.2f} PRC (Unlock: {unlock_percent}%)",
                "limit_info": limit_info
            }
        
        return {
            "allowed": True,
            "reason": None,
            "limit_info": limit_info
        }
    except Exception as e:
        logging.error(f"Error checking redeem limit: {e}")
        return {
            "allowed": True,
            "reason": None,
            "limit_info": {"error": str(e)}
        }


@api_router.get("/user/{user_id}/redeem-limit")
async def get_user_redeem_limit(user_id: str, request: Request):
    """Get user's redeem limit information with carry forward and new referral formula
    SECURITY: IDOR Protection - Users can only access their own redeem limit
    """
    
    # SECURITY (Jul 2026 hardened): Bearer token now REQUIRED — previously silent-bypass leaked data.
    auth_header = request.headers.get("Authorization", "")
    if not auth_header.startswith("Bearer "):
        raise HTTPException(status_code=401, detail="Authentication required.")
    token = auth_header.replace("Bearer ", "")
    try:
        payload = jwt.decode(token, JWT_SECRET_KEY, algorithms=[JWT_ALGORITHM])
        requesting_uid = payload.get("uid")
        requesting_role = payload.get("role", "user")
        # IDOR Protection: Non-admins can only access their own data
        if requesting_role not in ["admin", "sub_admin"] and requesting_uid != user_id:
            raise HTTPException(
                status_code=403,
                detail="Access denied. You can only view your own redeem limit."
            )
    except jwt.InvalidTokenError:
        raise HTTPException(status_code=401, detail="Invalid token")
    
    # ---- Server-side cache (60s TTL) — endpoint repeatedly polled by
    # dashboard + redeem flows; result only needs minute-level freshness. ----
    rl_cache_key = f"user:redeem_limit:{user_id}"
    if cache:
        try:
            cached_rl = await cache.get(rl_cache_key)
            if cached_rl:
                return cached_rl
        except Exception:
            pass

    try:
        limit_info = await calculate_user_redeem_limit(user_id)
        
        return_payload = {
            "success": True,
            "user_id": user_id,
            "limit": {
                "unlock_percent": limit_info.get("unlock_percent", 0),
                "network_size": limit_info.get("network_size", 0),
                "growth_level": limit_info.get("growth_level", 0),
                "total_earned": limit_info.get("total_earned", 0),
                "total_mined": limit_info.get("total_mined", 0),
                "redeemable": limit_info.get("redeemable", 0),
                "total_limit": limit_info.get("total_limit", 0),
                "total_redeemed": limit_info.get("total_redeemed", 0),
                "available": limit_info.get("available", 0),
                "effective_available": limit_info.get("effective_available", 0),
                "current_balance": limit_info.get("current_balance", 0),
                "remaining_limit": limit_info.get("available", 0),
                "available_prc": limit_info.get("current_balance", 0),
                "effective_remaining": limit_info.get("effective_available", 0),
                "usage_percentage": round(
                    (limit_info.get("total_redeemed", 0) / limit_info.get("redeemable", 1)) * 100 
                    if limit_info.get("redeemable", 0) > 0 else 0, 2
                ),
                "unlimited": False,
                "override_active": limit_info.get("override_active", False),
                "override_value": limit_info.get("override_value", 0),
                "override_reason": limit_info.get("override_reason"),
                # Global toggle diagnostics — surfaced so the dashboard
                # can render an "Unlimited Mode" banner and QA can verify
                # which formula produced the unlock_percent above.
                "global_formula_enabled": limit_info.get("global_formula_enabled", True),
                "flat_unlock_percent": limit_info.get("flat_unlock_percent"),
                "note": "Dynamic limit based on Growth Network. Grow your network to unlock more."
            }
        }
        if cache:
            try:
                await cache.set(rl_cache_key, return_payload, ttl=60)
            except Exception:
                pass
        return return_payload
    except Exception as e:
        logging.error(f"Error getting redeem limit: {e}")
        raise HTTPException(status_code=500, detail=get_user_friendly_error(e))


# ========== PERFORMANCE SUMMARY API ==========

@api_router.get("/user/{user_id}/performance-summary")
async def get_performance_summary(user_id: str, request: Request):
    """
    Performance Summary Card - Legal safe, reward-based display.
    Shows: Total Subscription Paid (₹), Total Rewards Redeemed (₹),
           Available PRC Balance, Estimated PRC Value (₹).
    NO investment/profit/ROI language.

    Cached 60s — previously took 10s on cold call due to 17-collection scan
    in get_user_all_time_redeemed. Cache lives long enough to absorb the
    rapid-fire dashboard mount + remount pattern without becoming stale.

    SECURITY (Jul 2026 hardened): Bearer token now REQUIRED + path uid
    must match the JWT subject. Prior to this the endpoint returned data
    to anonymous callers, leaking lifetime spend / balance / subscription
    totals for any UID.
    """
    # ---- IDOR guard ----
    auth_header = request.headers.get("Authorization", "")
    if not auth_header.startswith("Bearer "):
        raise HTTPException(status_code=401, detail="Authentication required.")
    token = auth_header.replace("Bearer ", "")
    try:
        payload = jwt.decode(token, JWT_SECRET_KEY, algorithms=[JWT_ALGORITHM])
        requesting_uid = payload.get("uid")
        requesting_role = payload.get("role", "user")
        if requesting_role not in ["admin", "sub_admin"] and requesting_uid != user_id:
            raise HTTPException(
                status_code=403,
                detail="Access denied. You can only view your own performance summary.",
            )
    except jwt.InvalidTokenError:
        raise HTTPException(status_code=401, detail="Invalid token")

    # ---- Server-side cache (60s TTL) ----
    perf_cache_key = f"user:perf_summary:{user_id}"
    if cache:
        try:
            cached_perf = await cache.get(perf_cache_key)
            if cached_perf:
                return cached_perf
        except Exception:
            pass

    try:
        user = await db.users.find_one(
            {"uid": user_id},
            {"_id": 0, "prc_balance": 1, "subscription_start": 1}
        )
        if not user:
            raise HTTPException(status_code=404, detail="User not found")

        prc_balance = float(user.get("prc_balance", 0) or 0)
        success_statuses = [
            "completed", "COMPLETED", "Completed",
            "success", "SUCCESS", "Success",
            "approved", "APPROVED", "Approved",
            "paid", "PAID", "Paid"
        ]

        # 1. Total Subscription Paid (₹)
        total_subscription_inr = 0

        # a) INR payments from vip_payments (query both uid and user_id)
        try:
            vip_pipeline = [
                {"$match": {"$or": [{"user_id": user_id}, {"uid": user_id}], "status": {"$in": success_statuses}}},
                {"$group": {"_id": None, "total": {"$sum": "$amount"}}}
            ]
            vip_result = await db.vip_payments.aggregate(vip_pipeline).to_list(1)
            if vip_result:
                total_subscription_inr += float(vip_result[0].get("total", 0) or 0)
        except Exception:
            pass

        # b) Razorpay orders
        try:
            raz_pipeline = [
                {"$match": {"user_id": user_id, "status": {"$in": success_statuses}}},
                {"$group": {"_id": None, "total": {"$sum": "$amount"}}}
            ]
            raz_result = await db.razorpay_orders.aggregate(raz_pipeline).to_list(1)
            if raz_result:
                raz_total = float(raz_result[0].get("total", 0) or 0)
                # Add Razorpay total (avoid double counting: only if not already in vip_payments)
                if total_subscription_inr == 0:
                    total_subscription_inr += raz_total
        except Exception:
            pass

        # c) PRC-based subscription payments (use inr_equivalent, fallback to prc/10)
        try:
            prc_sub_pipeline = [
                {"$match": {"user_id": user_id, "payment_method": "prc", "status": {"$in": success_statuses}}},
                {"$group": {"_id": None, "total_inr": {"$sum": "$inr_equivalent"}, "total_prc": {"$sum": "$prc_amount"}}}
            ]
            prc_sub_result = await db.subscription_payments.aggregate(prc_sub_pipeline).to_list(1)
            if prc_sub_result:
                inr_total = float(prc_sub_result[0].get("total_inr", 0) or 0)
                prc_total = float(prc_sub_result[0].get("total_prc", 0) or 0)
                # Prefer inr_equivalent (actual plan price), fallback to prc/10
                total_subscription_inr += inr_total if inr_total > 0 else (prc_total / 10)
        except Exception:
            pass

        # 2. Total Rewards Redeemed (PRC → ₹)
        total_redeemed_prc = await get_user_all_time_redeemed(user_id)
        total_redeemed_inr = total_redeemed_prc / 10

        # 3. Available PRC Balance
        available_prc = prc_balance

        # 4. Estimated PRC Value (₹) = prc_balance / 10
        estimated_value_inr = prc_balance / 10

        result = {
            "success": True,
            "data": {
                "total_subscription_paid_inr": round(total_subscription_inr, 2),
                "total_rewards_redeemed_inr": round(total_redeemed_inr, 2),
                "total_rewards_redeemed_prc": round(total_redeemed_prc, 2),
                "available_prc_balance": round(available_prc, 2),
                "estimated_prc_value_inr": round(estimated_value_inr, 2)
            }
        }
        # Cache the result for 60 seconds — balances and lifetime redeemed
        # only need minute-level freshness for the summary card.
        if cache:
            try:
                await cache.set(perf_cache_key, result, ttl=60)
            except Exception:
                pass
        return result
    except HTTPException:
        raise
    except Exception as e:
        logging.error(f"Error in performance summary: {e}")
        raise HTTPException(status_code=500, detail=str(e))


# ========== PRC STATEMENT API ==========

@api_router.get("/user/prc-statement/{user_id}")
async def get_prc_statement(
    user_id: str,
    start_date: str = None,
    end_date: str = None,
    filter_type: str = "all",  # all, redeemed, refunds, credits
    service_type: str = "all"  # all, bill_payment, bank_redeem, dmt, mining, referral, subscription
):
    """
    Get comprehensive PRC statement for a user including all credits, debits, refunds.
    """
    try:
        # Build date filter
        date_filter = {}
        if start_date:
            date_filter["$gte"] = start_date
        if end_date:
            date_filter["$lte"] = end_date + "T23:59:59"
        
        # Base query
        base_query = {"user_id": user_id}
        if date_filter:
            base_query["$or"] = [
                {"created_at": date_filter},
                {"timestamp": date_filter},
                {"date": date_filter}
            ]
        
        all_transactions = []
        
        # 1. Get transactions from transactions collection
        tx_query = {"user_id": user_id}
        if date_filter:
            tx_query["timestamp"] = date_filter
        
        transactions = await db.transactions.find(tx_query).sort("timestamp", -1).limit(500).to_list(500)
        for tx in transactions:
            tx_type = tx.get("type", "")
            amount = tx.get("amount", 0) or tx.get("prc_amount", 0) or 0
            
            # Determine if credit or debit
            is_credit = tx_type in ["mining", "referral_bonus", "signup_bonus", "daily_reward", "refund", "prc_credit", "reward"]
            
            all_transactions.append({
                "id": str(tx.get("_id", "")),
                "type": "credit" if is_credit else "debit",
                "category": tx_type,
                "amount": abs(float(amount)),
                "description": tx.get("description", "") or tx.get("reason", "") or tx_type.replace("_", " ").title(),
                "service": tx.get("service_type", "") or tx_type,
                "status": tx.get("status", "success"),
                "date": tx.get("timestamp", "") or tx.get("created_at", ""),
                "reference": tx.get("reference_id", "") or tx.get("txn_id", "")
            })
        
        # 2. Get bill payments
        if service_type in ["all", "bill_payment"]:
            bill_query = {"user_id": user_id}
            if date_filter:
                bill_query["created_at"] = date_filter
            
            bill_payments = await db.bill_payment_requests.find(bill_query).sort("created_at", -1).limit(200).to_list(200)
            for bp in bill_payments:
                prc_amount = bp.get("prc_amount", 0) or bp.get("amount", 0) or 0
                status = bp.get("status", "pending")
                
                # Debit transaction
                all_transactions.append({
                    "id": str(bp.get("_id", "")),
                    "type": "debit",
                    "category": "bill_payment",
                    "amount": abs(float(prc_amount)),
                    "description": f"Bill - {bp.get('operator', '')} ({bp.get('customer_id', '')})",
                    "service": bp.get("service_type", "bill_payment"),
                    "status": status,
                    "date": bp.get("created_at", ""),
                    "reference": bp.get("eko_tid", "") or bp.get("request_id", "")
                })
                
                # If refunded, add refund transaction
                if status == "refunded" and bp.get("refund_amount"):
                    all_transactions.append({
                        "id": f"{bp.get('_id', '')}_refund",
                        "type": "credit",
                        "category": "refund",
                        "amount": abs(float(bp.get("refund_amount", prc_amount))),
                        "description": f"Refund - Bill Payment",
                        "service": "refund",
                        "status": "success",
                        "date": bp.get("refunded_at", bp.get("updated_at", "")),
                        "reference": bp.get("request_id", "")
                    })
        
        # 3. Get bank withdrawals
        if service_type in ["all", "bank_redeem"]:
            bank_query = {"user_id": user_id}
            if date_filter:
                bank_query["created_at"] = date_filter
            
            bank_withdrawals = await db.bank_withdrawal_requests.find(bank_query).sort("created_at", -1).limit(200).to_list(200)
            for bw in bank_withdrawals:
                prc_amount = bw.get("prc_amount", 0) or bw.get("amount", 0) or 0
                status = bw.get("status", "pending")
                
                all_transactions.append({
                    "id": str(bw.get("_id", "")),
                    "type": "debit",
                    "category": "bank_redeem",
                    "amount": abs(float(prc_amount)),
                    "description": f"Bank Transfer - {bw.get('bank_name', '')} ****{str(bw.get('account_number', ''))[-4:]}",
                    "service": "bank_redeem",
                    "status": status,
                    "date": bw.get("created_at", ""),
                    "reference": bw.get("eko_tid", "") or bw.get("request_id", "")
                })
                
                if status == "refunded" and bw.get("refund_amount"):
                    all_transactions.append({
                        "id": f"{bw.get('_id', '')}_refund",
                        "type": "credit",
                        "category": "refund",
                        "amount": abs(float(bw.get("refund_amount", prc_amount))),
                        "description": f"Refund - Bank Transfer",
                        "service": "refund",
                        "status": "success",
                        "date": bw.get("refunded_at", bw.get("updated_at", "")),
                        "reference": bw.get("request_id", "")
                    })
        
        # 4. Get DMT transactions
        if service_type in ["all", "dmt"]:
            dmt_query = {"user_id": user_id}
            if date_filter:
                dmt_query["created_at"] = date_filter
            
            dmt_txns = await db.dmt_transactions.find(dmt_query).sort("created_at", -1).limit(200).to_list(200)
            for dmt in dmt_txns:
                amount = dmt.get("prc_amount", 0) or dmt.get("amount", 0) or 0
                status = dmt.get("status", "pending")
                
                all_transactions.append({
                    "id": str(dmt.get("_id", "")),
                    "type": "debit",
                    "category": "dmt",
                    "amount": abs(float(amount)),
                    "description": f"DMT - {dmt.get('recipient_name', '')} ({dmt.get('customer_mobile', '')})",
                    "service": "dmt",
                    "status": status,
                    "date": dmt.get("created_at", ""),
                    "reference": dmt.get("eko_tid", "") or dmt.get("txn_id", "")
                })
                
                if status == "refunded":
                    all_transactions.append({
                        "id": f"{dmt.get('_id', '')}_refund",
                        "type": "credit",
                        "category": "refund",
                        "amount": abs(float(amount)),
                        "description": f"Refund - DMT",
                        "service": "refund",
                        "status": "success",
                        "date": dmt.get("refunded_at", ""),
                        "reference": dmt.get("txn_id", "")
                    })
        
        # 5. Get VIP payments (subscription credits used)
        if service_type in ["all", "subscription"]:
            vip_query = {"user_id": user_id}
            if date_filter:
                vip_query["created_at"] = date_filter
            
            vip_payments = await db.vip_payments.find(vip_query).sort("created_at", -1).limit(100).to_list(100)
            for vip in vip_payments:
                all_transactions.append({
                    "id": str(vip.get("_id", "")),
                    "type": "credit",
                    "category": "subscription",
                    "amount": float(vip.get("amount", 0)),
                    "description": f"Subscription - {vip.get('subscription_plan', '').title()} Plan",
                    "service": "subscription",
                    "status": vip.get("status", "approved"),
                    "date": vip.get("created_at", ""),
                    "reference": vip.get("payment_id", "")
                })
        
        # 6. Get mining rewards from prc_ledger if exists
        if service_type in ["all", "mining"]:
            mining_query = {"user_id": user_id, "type": {"$in": ["mining", "daily_mining", "hourly_mining"]}}
            if date_filter:
                mining_query["timestamp"] = date_filter
            
            mining_entries = await db.prc_ledger.find(mining_query).sort("timestamp", -1).limit(200).to_list(200)
            for entry in mining_entries:
                all_transactions.append({
                    "id": str(entry.get("_id", "")),
                    "type": "credit",
                    "category": "mining",
                    "amount": abs(float(entry.get("amount", 0) or entry.get("credit", 0))),
                    "description": entry.get("description", "Mining Reward"),
                    "service": "mining",
                    "status": "success",
                    "date": entry.get("timestamp", ""),
                    "reference": entry.get("entry_id", "")
                })
        
        # 7. Get referral bonuses
        if service_type in ["all", "referral"]:
            ref_query = {"user_id": user_id, "type": {"$in": ["referral", "referral_bonus", "referral_commission"]}}
            if date_filter:
                ref_query["timestamp"] = date_filter
            
            ref_entries = await db.prc_ledger.find(ref_query).sort("timestamp", -1).limit(100).to_list(100)
            for entry in ref_entries:
                all_transactions.append({
                    "id": str(entry.get("_id", "")),
                    "type": "credit",
                    "category": "referral",
                    "amount": abs(float(entry.get("amount", 0) or entry.get("credit", 0))),
                    "description": entry.get("description", "Referral Bonus"),
                    "service": "referral",
                    "status": "success",
                    "date": entry.get("timestamp", ""),
                    "reference": entry.get("entry_id", "")
                })
        
        # 8. Get Gift Voucher requests
        if service_type in ["all", "gift_voucher"]:
            voucher_query = {"user_id": user_id}
            if date_filter:
                voucher_query["created_at"] = date_filter
            
            voucher_requests = await db.gift_voucher_requests.find(voucher_query).sort("created_at", -1).limit(200).to_list(200)
            for vr in voucher_requests:
                prc_amount = vr.get("prc_used", 0) or vr.get("prc_amount", 0) or vr.get("total_prc_deducted", 0) or 0
                status = vr.get("status", "pending")
                brand = vr.get("brand_name", "") or vr.get("voucher_type", "Gift Voucher")
                
                all_transactions.append({
                    "id": str(vr.get("_id", "")),
                    "type": "debit",
                    "category": "gift_voucher",
                    "amount": abs(float(prc_amount)),
                    "description": f"Gift Voucher - {brand} (₹{vr.get('amount_inr', vr.get('amount', 0))})",
                    "service": "gift_voucher",
                    "status": status,
                    "date": vr.get("created_at", ""),
                    "reference": vr.get("request_id", "") or vr.get("voucher_code", "")[:8] if vr.get("voucher_code") else ""
                })
                
                # If rejected/refunded, add refund entry
                if status in ["rejected", "refunded", "failed"] and prc_amount > 0:
                    all_transactions.append({
                        "id": f"{vr.get('_id', '')}_refund",
                        "type": "credit",
                        "category": "refund",
                        "amount": abs(float(prc_amount)),
                        "description": f"Refund - Gift Voucher ({vr.get('rejection_reason', 'Rejected')})",
                        "service": "refund",
                        "status": "success",
                        "date": vr.get("rejected_at", vr.get("refunded_at", vr.get("updated_at", ""))),
                        "reference": vr.get("request_id", "")
                    })
        
        # 9. Get Shop/Marketplace Orders
        if service_type in ["all", "shop", "shopping"]:
            shop_query = {"user_id": user_id}
            if date_filter:
                shop_query["created_at"] = date_filter
            
            shop_orders = await db.orders.find(shop_query).sort("created_at", -1).limit(200).to_list(200)
            for order in shop_orders:
                prc_amount = order.get("total_prc", 0) or order.get("prc_used", 0) or order.get("prc_amount", 0) or 0
                status = order.get("status", "pending")
                product = order.get("product_name", "") or order.get("product_title", "Shop Order")
                qty = order.get("quantity", 1)
                
                all_transactions.append({
                    "id": str(order.get("_id", "")),
                    "type": "debit",
                    "category": "shop",
                    "amount": abs(float(prc_amount)),
                    "description": f"Shop - {product}" + (f" x{qty}" if qty > 1 else ""),
                    "service": "shop",
                    "status": status,
                    "date": order.get("created_at", ""),
                    "reference": order.get("order_id", "")
                })
                
                # If cancelled/refunded
                if status in ["cancelled", "refunded", "rejected"] and prc_amount > 0:
                    all_transactions.append({
                        "id": f"{order.get('_id', '')}_refund",
                        "type": "credit",
                        "category": "refund",
                        "amount": abs(float(prc_amount)),
                        "description": f"Refund - Shop Order ({status})",
                        "service": "refund",
                        "status": "success",
                        "date": order.get("cancelled_at", order.get("refunded_at", order.get("updated_at", ""))),
                        "reference": order.get("order_id", "")
                    })
        
        # 10. Get utility/recharge transactions (separate collection if exists)
        if service_type in ["all", "utility", "recharge"]:
            utility_query = {"user_id": user_id}
            if date_filter:
                utility_query["created_at"] = date_filter
            
            utility_txns = await db.recharge_requests.find(utility_query).sort("created_at", -1).limit(200).to_list(200)
            for ut in utility_txns:
                prc_amount = ut.get("prc_amount", 0) or ut.get("total_prc_deducted", 0) or 0
                status = ut.get("status", "pending")
                
                all_transactions.append({
                    "id": str(ut.get("_id", "")),
                    "type": "debit",
                    "category": "utility",
                    "amount": abs(float(prc_amount)),
                    "description": f"Recharge - {ut.get('operator', '')} ({ut.get('mobile', '')})",
                    "service": "utility",
                    "status": status,
                    "date": ut.get("created_at", ""),
                    "reference": ut.get("eko_tid", "") or ut.get("request_id", "")
                })
                
                if status in ["failed", "refunded", "rejected"] and prc_amount > 0:
                    all_transactions.append({
                        "id": f"{ut.get('_id', '')}_refund",
                        "type": "credit",
                        "category": "refund",
                        "amount": abs(float(prc_amount)),
                        "description": f"Refund - Recharge ({status})",
                        "service": "refund",
                        "status": "success",
                        "date": ut.get("refunded_at", ut.get("updated_at", "")),
                        "reference": ut.get("request_id", "")
                    })
        
        # 11. Get all refund entries from prc_ledger
        if service_type in ["all", "refund"]:
            refund_ledger_query = {"user_id": user_id, "type": {"$regex": "refund", "$options": "i"}}
            if date_filter:
                refund_ledger_query["timestamp"] = date_filter
            
            refund_entries = await db.prc_ledger.find(refund_ledger_query).sort("timestamp", -1).limit(200).to_list(200)
            for entry in refund_entries:
                all_transactions.append({
                    "id": str(entry.get("_id", "")),
                    "type": "credit",
                    "category": "refund",
                    "amount": abs(float(entry.get("amount", 0) or entry.get("credit", 0))),
                    "description": entry.get("description", "PRC Refund"),
                    "service": "refund",
                    "status": "success",
                    "date": entry.get("timestamp", ""),
                    "reference": entry.get("reference_id", "") or entry.get("entry_id", "")
                })
        
        # Filter by type
        if filter_type == "redeemed":
            all_transactions = [t for t in all_transactions if t["type"] == "debit"]
        elif filter_type == "refunds":
            all_transactions = [t for t in all_transactions if t["category"] == "refund"]
        elif filter_type == "credits":
            all_transactions = [t for t in all_transactions if t["type"] == "credit"]
        
        # Filter by service
        if service_type != "all":
            all_transactions = [t for t in all_transactions if t["service"] == service_type or t["category"] == service_type]
        
        # Sort by date descending
        all_transactions.sort(key=lambda x: x.get("date", ""), reverse=True)
        
        # Remove duplicates based on ID
        seen_ids = set()
        unique_transactions = []
        for tx in all_transactions:
            if tx["id"] not in seen_ids:
                seen_ids.add(tx["id"])
                unique_transactions.append(tx)
        
        # Calculate totals
        total_credits = sum(t["amount"] for t in unique_transactions if t["type"] == "credit")
        total_debits = sum(t["amount"] for t in unique_transactions if t["type"] == "debit")
        total_refunds = sum(t["amount"] for t in unique_transactions if t["category"] == "refund")
        
        return {
            "success": True,
            "transactions": unique_transactions[:500],
            "summary": {
                "total_credits": round(total_credits, 2),
                "total_debits": round(total_debits, 2),
                "total_refunds": round(total_refunds, 2),
                "net_balance": round(total_credits - total_debits, 2),
                "transaction_count": len(unique_transactions)
            },
            "filters": {
                "start_date": start_date,
                "end_date": end_date,
                "filter_type": filter_type,
                "service_type": service_type
            }
        }
        
    except Exception as e:
        logging.error(f"Error getting PRC statement: {e}")
        raise HTTPException(status_code=500, detail=get_user_friendly_error(e))


@api_router.get("/user/prc-statement/{user_id}/download")
async def download_prc_statement(
    user_id: str,
    start_date: str = None,
    end_date: str = None,
    filter_type: str = "all",
    service_type: str = "all"
):
    """Download PRC statement as CSV"""
    try:
        # Get statement data
        statement = await get_prc_statement(user_id, start_date, end_date, filter_type, service_type)
        
        if not statement.get("success"):
            raise HTTPException(status_code=500, detail="Failed to generate statement")
        
        transactions = statement.get("transactions", [])
        
        # Generate CSV
        import io
        import csv
        
        output = io.StringIO()
        writer = csv.writer(output)
        
        # Header
        writer.writerow(["Date", "Type", "Category", "Description", "Amount (PRC)", "Status", "Reference"])
        
        for tx in transactions:
            writer.writerow([
                tx.get("date", "")[:19],
                tx.get("type", "").upper(),
                tx.get("category", ""),
                tx.get("description", ""),
                f"{'+' if tx['type'] == 'credit' else '-'}{tx.get('amount', 0)}",
                tx.get("status", ""),
                tx.get("reference", "")
            ])
        
        # Summary
        writer.writerow([])
        writer.writerow(["SUMMARY"])
        writer.writerow(["Total Credits", statement["summary"]["total_credits"]])
        writer.writerow(["Total Debits", statement["summary"]["total_debits"]])
        writer.writerow(["Total Refunds", statement["summary"]["total_refunds"]])
        writer.writerow(["Net Balance", statement["summary"]["net_balance"]])
        
        csv_content = output.getvalue()
        
        from fastapi.responses import Response
        return Response(
            content=csv_content,
            media_type="text/csv",
            headers={
                "Content-Disposition": f"attachment; filename=prc_statement_{start_date or 'all'}_{end_date or 'all'}.csv"
            }
        )
        
    except Exception as e:
        logging.error(f"Error downloading PRC statement: {e}")
        raise HTTPException(status_code=500, detail=get_user_friendly_error(e))



@api_router.get("/admin/fix-double-subscriptions")
async def fix_double_subscriptions_preview():
    """
    Preview users affected by double subscription bug.
    Shows users whose subscription days don't match expected (28 days for monthly).
    """
    try:
        import razorpay
        
        RAZORPAY_KEY_ID = os.environ.get("RAZORPAY_KEY_ID")
        RAZORPAY_KEY_SECRET = os.environ.get("RAZORPAY_KEY_SECRET")
        
        if not RAZORPAY_KEY_ID or not RAZORPAY_KEY_SECRET:
            raise HTTPException(status_code=500, detail="Razorpay not configured")
        
        razorpay_client = razorpay.Client(auth=(RAZORPAY_KEY_ID, RAZORPAY_KEY_SECRET))
        
        PLAN_DURATIONS = {
            "monthly": 28,
            "quarterly": 84,
            "half_yearly": 168,
            "yearly": 336
        }
        
        # Get recent payments (last 7 days)
        from_timestamp = int((datetime.now(timezone.utc) - timedelta(days=7)).timestamp())
        payments = await asyncio.to_thread(
            razorpay_client.payment.all,
            {"count": 100, "from": from_timestamp}
        )
        
        captured = [p for p in payments.get("items", []) if p.get("status") == "captured"]
        
        affected_users = []
        
        for payment in captured:
            notes = payment.get("notes", {})
            user_id = notes.get("user_id")
            plan_type = notes.get("plan_type", "monthly")
            expected_days = PLAN_DURATIONS.get(plan_type, 28)
            
            if not user_id:
                continue
            
            # Get user from DB
            user = await db.users.find_one({"uid": user_id})
            if not user:
                continue
            
            # Calculate actual days
            expiry = get_user_expiry(user)
            payment_date = datetime.fromtimestamp(payment.get("created_at", 0), tz=timezone.utc)
            
            if expiry:
                try:
                    if isinstance(expiry, str):
                        exp_date = datetime.fromisoformat(expiry.replace('Z', '+00:00'))
                    else:
                        exp_date = expiry
                    if exp_date.tzinfo is None:
                        exp_date = exp_date.replace(tzinfo=timezone.utc)
                    
                    actual_days = (exp_date - payment_date).days
                    
                    # If actual days > expected + 3 (buffer), it's affected
                    if actual_days > expected_days + 3:
                        correct_expiry = payment_date + timedelta(days=expected_days)
                        affected_users.append({
                            "user_id": user_id,
                            "name": user.get("name"),
                            "email": user.get("email"),
                            "payment_id": payment.get("id"),
                            "payment_date": payment_date.isoformat(),
                            "plan_type": plan_type,
                            "expected_days": expected_days,
                            "actual_days": actual_days,
                            "extra_days": actual_days - expected_days,
                            "current_expiry": exp_date.isoformat(),
                            "correct_expiry": correct_expiry.isoformat()
                        })
                except Exception as e:
                    logging.error(f"Error processing user {user_id}: {e}")
        
        return {
            "success": True,
            "affected_count": len(affected_users),
            "affected_users": affected_users,
            "message": f"Found {len(affected_users)} users with extra subscription days"
        }
        
    except Exception as e:
        logging.error(f"Error in fix_double_subscriptions_preview: {e}")
        raise HTTPException(status_code=500, detail=get_user_friendly_error(e))


@api_router.get("/admin/today-double-subscriptions")
async def find_today_double_subscriptions():
    """
    Find users who got double subscription TODAY by checking duplicate transactions.
    """
    try:
        today = datetime.now(timezone.utc).replace(hour=0, minute=0, second=0, microsecond=0)
        now = datetime.now(timezone.utc)
        
        # Method 1: Check transactions for duplicates
        recent_txns = await db.transactions.find({
            "type": "subscription_payment",
            "timestamp": {"$gte": today}
        }).sort("timestamp", -1).to_list(500)
        
        # Group by payment_id
        payment_groups = {}
        for txn in recent_txns:
            pid = txn.get("payment_id")
            if pid:
                if pid not in payment_groups:
                    payment_groups[pid] = []
                payment_groups[pid].append(txn)
        
        duplicates_from_txns = []
        for pid, txns in payment_groups.items():
            if len(txns) > 1:
                user_id = txns[0].get("user_id")
                total_extra = sum([t.get("total_days", 28) for t in txns[1:]])  # Extra days from duplicates
                duplicates_from_txns.append({
                    "user_id": user_id,
                    "payment_id": pid,
                    "duplicate_count": len(txns),
                    "extra_days": total_extra,
                    "transactions": [{"via": t.get("activated_via"), "days": t.get("total_days", 28)} for t in txns]
                })
        
        # Method 2: Check vip_payments for duplicates
        recent_vip = await db.vip_payments.find({
            "payment_method": "razorpay",
            "$or": [
                {"created_at": {"$gte": today.isoformat()}},
                {"approved_at": {"$gte": today.isoformat()}}
            ]
        }).sort("created_at", -1).to_list(500)
        
        vip_groups = {}
        for vip in recent_vip:
            pid = vip.get("payment_id")
            if pid:
                if pid not in vip_groups:
                    vip_groups[pid] = []
                vip_groups[pid].append(vip)
        
        duplicates_from_vip = []
        for pid, vips in vip_groups.items():
            if len(vips) > 1:
                user_id = vips[0].get("user_id")
                total_extra = sum([v.get("duration_days", 28) for v in vips[1:]])
                duplicates_from_vip.append({
                    "user_id": user_id,
                    "payment_id": pid,
                    "duplicate_count": len(vips),
                    "extra_days": total_extra,
                    "vip_records": [{"source": v.get("activation_source"), "days": v.get("duration_days")} for v in vips]
                })
        
        # Method 3: Check users with suspiciously high days (paid today but >35 days remaining)
        users_paid_today = await db.users.find({
            "last_payment_date": {"$gte": today.isoformat()}
        }, {"_id": 0, "uid": 1, "name": 1, "mobile": 1, "email": 1, "subscription_plan": 1, 
            "subscription_expiry": 1, "last_payment_id": 1, 
            "last_payment_date": 1, "previous_remaining_days_added": 1}).to_list(100)
        
        suspicious_users = []
        for u in users_paid_today:
            expiry = u.get("subscription_expiry")
            if expiry:
                try:
                    if isinstance(expiry, str):
                        exp_date = datetime.fromisoformat(expiry.replace('Z', '+00:00'))
                    else:
                        exp_date = expiry
                    if exp_date.tzinfo is None:
                        exp_date = exp_date.replace(tzinfo=timezone.utc)
                    
                    days_remaining = (exp_date - now).days
                    prev_days = u.get("previous_remaining_days_added", 0)
                    
                    # If days > 28 + previous + 3 days buffer, suspicious
                    expected_max = 28 + prev_days + 3
                    if days_remaining > expected_max:
                        extra = days_remaining - 28 - prev_days
                        suspicious_users.append({
                            "user_id": u.get("uid"),
                            "name": u.get("name"),
                            "mobile": u.get("mobile"),
                            "email": u.get("email"),
                            "plan": u.get("subscription_plan"),
                            "days_remaining": days_remaining,
                            "previous_days_added": prev_days,
                            "expected_max": expected_max,
                            "extra_days": extra,
                            "current_expiry": exp_date.isoformat(),
                            "payment_id": u.get("last_payment_id")
                        })
                except:
                    pass
        
        return {
            "success": True,
            "timestamp": now.isoformat(),
            "duplicates_from_transactions": duplicates_from_txns,
            "duplicates_from_vip_payments": duplicates_from_vip,
            "suspicious_users": suspicious_users,
            "total_affected": len(set(
                [d["user_id"] for d in duplicates_from_txns] + 
                [d["user_id"] for d in duplicates_from_vip] + 
                [s["user_id"] for s in suspicious_users]
            ))
        }
    except Exception as e:
        logging.error(f"Error finding today's double subscriptions: {e}")
        raise HTTPException(status_code=500, detail=get_user_friendly_error(e))


@api_router.post("/admin/fix-user-subscription-days")
async def fix_user_subscription_days(request: Request):
    """
    Fix a specific user's subscription by removing extra days.
    
    Body:
    - user_id or mobile: User identifier
    - days_to_remove: Number of extra days to remove
    - reason: Reason for the fix
    - admin_id: Admin performing the fix
    """
    try:
        data = await request.json()
        user_id = data.get("user_id")
        mobile = data.get("mobile")
        days_to_remove = data.get("days_to_remove", 0)
        reason = data.get("reason", "Double subscription fix")
        admin_id = data.get("admin_id", "system")
        
        if not user_id and not mobile:
            raise HTTPException(status_code=400, detail="Please provide user_id or mobile")
        
        if days_to_remove <= 0:
            raise HTTPException(status_code=400, detail="days_to_remove must be positive")
        
        # Find user
        if user_id:
            user = await db.users.find_one({"uid": user_id})
        else:
            user = await db.users.find_one({"mobile": mobile})
        
        if not user:
            raise HTTPException(status_code=404, detail="User not found")
        
        user_id = user.get("uid")
        now = datetime.now(timezone.utc)
        
        # Get current expiry
        current_expiry = get_user_expiry(user)
        if not current_expiry:
            raise HTTPException(status_code=400, detail="User has no active subscription")
        
        if isinstance(current_expiry, str):
            current_expiry = datetime.fromisoformat(current_expiry.replace('Z', '+00:00'))
        if current_expiry.tzinfo is None:
            current_expiry = current_expiry.replace(tzinfo=timezone.utc)
        
        # Calculate new expiry
        new_expiry = current_expiry - timedelta(days=days_to_remove)
        
        # Don't allow expiry before today
        if new_expiry < now:
            new_expiry = now + timedelta(days=1)
        
        # Update user
        await db.users.update_one(
            {"uid": user_id},
            {
                "$set": {
                    "subscription_expiry": new_expiry.isoformat(),
                    "double_subscription_fixed": True,
                    "days_removed": days_to_remove,
                    "fixed_at": now.isoformat(),
                    "fixed_by": admin_id,
                    "fix_reason": reason,
                    "original_wrong_expiry": current_expiry.isoformat()
                }
            }
        )
        
        # Log the fix
        await db.subscription_fixes.insert_one({
            "fix_id": str(uuid.uuid4()),
            "user_id": user_id,
            "user_name": user.get("name"),
            "user_mobile": user.get("mobile"),
            "original_expiry": current_expiry.isoformat(),
            "new_expiry": new_expiry.isoformat(),
            "days_removed": days_to_remove,
            "reason": reason,
            "admin_id": admin_id,
            "fixed_at": now.isoformat()
        })
        
        return {
            "success": True,
            "message": f"Fixed subscription for {user.get('name')}",
            "user": {
                "uid": user_id,
                "name": user.get("name"),
                "mobile": user.get("mobile")
            },
            "fix_details": {
                "original_expiry": current_expiry.isoformat(),
                "new_expiry": new_expiry.isoformat(),
                "days_removed": days_to_remove,
                "days_remaining_now": (new_expiry - now).days
            }
        }
        
    except HTTPException:
        raise
    except Exception as e:
        logging.error(f"Error fixing user subscription: {e}")
        raise HTTPException(status_code=500, detail=get_user_friendly_error(e))


@api_router.post("/admin/fix-double-subscriptions")
async def fix_double_subscriptions_execute(request: Request):
    """
    Fix affected users by correcting their expiry dates.
    Only fixes users who have more days than expected.
    """
    try:
        data = await request.json()
        admin_id = data.get("admin_id", "")
        dry_run = data.get("dry_run", True)  # Default to dry run for safety
        
        # First get affected users
        preview = await fix_double_subscriptions_preview()
        affected = preview.get("affected_users", [])
        
        if not affected:
            return {
                "success": True,
                "message": "No affected users found",
                "fixed_count": 0
            }
        
        fixed_users = []
        
        for user_data in affected:
            user_id = user_data["user_id"]
            correct_expiry = datetime.fromisoformat(user_data["correct_expiry"])
            
            if not dry_run:
                # Update user expiry
                await db.users.update_one(
                    {"uid": user_id},
                    {
                        "$set": {
                            "subscription_expiry": correct_expiry.isoformat(),
                            "double_subscription_fixed": True,
                            "fixed_at": datetime.now(timezone.utc).isoformat(),
                            "fixed_by": admin_id,
                            "original_wrong_expiry": user_data["current_expiry"],
                            "extra_days_removed": user_data["extra_days"]
                        }
                    }
                )
                
                # Log the fix
                await db.activity_logs.insert_one({
                    "log_id": str(uuid.uuid4()),
                    "action": "double_subscription_fix",
                    "user_id": user_id,
                    "user_email": user_data["email"],
                    "original_expiry": user_data["current_expiry"],
                    "corrected_expiry": correct_expiry.isoformat(),
                    "extra_days_removed": user_data["extra_days"],
                    "admin_id": admin_id,
                    "timestamp": datetime.now(timezone.utc).isoformat()
                })
            
            fixed_users.append({
                "user_id": user_id,
                "email": user_data["email"],
                "name": user_data["name"],
                "original_expiry": user_data["current_expiry"],
                "corrected_expiry": correct_expiry.isoformat(),
                "days_removed": user_data["extra_days"]
            })
        
        return {
            "success": True,
            "dry_run": dry_run,
            "fixed_count": len(fixed_users),
            "fixed_users": fixed_users,
            "message": f"{'Would fix' if dry_run else 'Fixed'} {len(fixed_users)} users"
        }
        
    except Exception as e:
        logging.error(f"Error in fix_double_subscriptions_execute: {e}")
        raise HTTPException(status_code=500, detail=get_user_friendly_error(e))

# ========== SECURITY ALERTS API ==========

async def get_security_alerts(
    admin_uid: str,
    page: int = 1,
    limit: int = 20,
    unread_only: bool = False,
    severity: Optional[str] = None,
    alert_type: Optional[str] = None
):
    """Get security alerts with filtering and pagination"""
    admin = await db.users.find_one({"uid": admin_uid})
    if not admin or admin.get("role") not in ["admin", "sub_admin"]:
        raise HTTPException(status_code=403, detail="Admin access required")
    
    query = {}
    if unread_only:
        query["is_read"] = False
    if severity:
        query["severity"] = severity
    if alert_type:
        query["alert_type"] = alert_type
    
    skip = (page - 1) * limit
    total = await db.security_alerts.count_documents(query)
    alerts = await db.security_alerts.find(query, {"_id": 0}).sort("created_at", -1).skip(skip).limit(limit).to_list(limit)
    
    # Get unread count
    unread_count = await db.security_alerts.count_documents({"is_read": False})
    
    return {
        "alerts": alerts,
        "total": total,
        "unread_count": unread_count,
        "page": page,
        "pages": (total + limit - 1) // limit
    }

@api_router.get("/admin/security/alerts/unread-count")
async def get_unread_alerts_count(admin_uid: str):
    """Get count of unread security alerts (for notification badge)"""
    admin = await db.users.find_one({"uid": admin_uid})
    if not admin or admin.get("role") not in ["admin", "sub_admin"]:
        raise HTTPException(status_code=403, detail="Admin access required")
    
    unread_count = await db.security_alerts.count_documents({"is_read": False})
    
    # Get severity breakdown
    critical_count = await db.security_alerts.count_documents({"is_read": False, "severity": "critical"})
    high_count = await db.security_alerts.count_documents({"is_read": False, "severity": "high"})
    
    return {
        "unread_count": unread_count,
        "critical_count": critical_count,
        "high_count": high_count,
        "has_critical": critical_count > 0,
        "has_high": high_count > 0
    }

@api_router.post("/admin/security/alerts/mark-read")
async def mark_alerts_read(admin_uid: str, alert_ids: List[str] = None, mark_all: bool = False):
    """Mark security alerts as read"""
    admin = await db.users.find_one({"uid": admin_uid})
    if not admin or admin.get("role") not in ["admin", "sub_admin"]:
        raise HTTPException(status_code=403, detail="Admin access required")
    
    if mark_all:
        result = await db.security_alerts.update_many(
            {"is_read": False},
            {"$set": {"is_read": True, "read_at": datetime.now(timezone.utc).isoformat(), "read_by": admin_uid}}
        )
        return {"message": f"Marked {result.modified_count} alerts as read"}
    
    if alert_ids:
        result = await db.security_alerts.update_many(
            {"alert_id": {"$in": alert_ids}},
            {"$set": {"is_read": True, "read_at": datetime.now(timezone.utc).isoformat(), "read_by": admin_uid}}
        )
        return {"message": f"Marked {result.modified_count} alerts as read"}
    
    return {"message": "No alerts to mark"}

@api_router.delete("/admin/security/alerts/clear-old")
async def clear_old_alerts(admin_uid: str, days_old: int = 30):
    """Clear alerts older than specified days"""
    admin = await db.users.find_one({"uid": admin_uid})
    if not admin or admin.get("role") != "admin":
        raise HTTPException(status_code=403, detail="Admin access required")
    
    cutoff_date = (datetime.now(timezone.utc) - timedelta(days=days_old)).isoformat()
    result = await db.security_alerts.delete_many({
        "created_at": {"$lt": cutoff_date},
        "is_read": True
    })
    
    return {"message": f"Deleted {result.deleted_count} old alerts"}

# ========== ADMIN ROUTES ==========
async def promote_user(email: str, role: str):
    """Promote user to admin or outlet role"""
    if role not in ["admin", "outlet", "user", "master_stockist", "sub_stockist"]:
        raise HTTPException(status_code=400, detail="Invalid role")
    
    result = await db.users.update_one(
        {"email": email},
        {"$set": {"role": role}}
    )
    
    if result.matched_count == 0:
        raise HTTPException(status_code=404, detail="User not found")
    
    return {"message": f"User promoted to {role} successfully"}

