        all_orders = await asyncio.wait_for(
            db.orders.find(
                {},
                {"_id": 0, "created_at": 1, "timestamp": 1, "status": 1, "total_prc": 1, "total_prc_price": 1}
            ).to_list(1000),
            timeout=15.0
        )
        
        # Process orders per day
        date_data = {}
        for order in all_orders:
            date_val = order.get("created_at") or order.get("timestamp")
