@api_router.get("/admin/user-360-debug")
async def admin_user_360_debug(query: str = None):
    """
    Debug endpoint to identify what's causing User 360 to fail for specific users
    """
    if not query:
        raise HTTPException(status_code=400, detail="Query required")
    
    query = query.strip()
    debug_info = {"query": query, "steps": []}
    
    # Step 1: Find user
    try:
        search_conditions = [
            {"uid": query},
            {"email": {"$regex": f"^{query}$", "$options": "i"}},
            {"phone": query},
            {"referral_code": query.upper()}
        ]
        user = await db.users.find_one({"$or": search_conditions})
        debug_info["steps"].append({"step": "find_user", "success": user is not None, "uid": user.get("uid") if user else None})
        
        if not user:
            debug_info["error"] = "User not found"
            return debug_info
    except Exception as e:
        debug_info["steps"].append({"step": "find_user", "success": False, "error": str(e)[:200]})
        return debug_info
    
    uid = user.get("uid")
    
    # Step 2: Check user fields for problematic data
    problematic_fields = []
    for key, value in user.items():
        try:
            # Try to serialize each field
            import json
            json.dumps({key: str(value) if value is not None else None})
        except Exception as e:
            problematic_fields.append({"field": key, "type": type(value).__name__, "error": str(e)[:50]})
    
    debug_info["steps"].append({"step": "check_user_fields", "problematic_fields": problematic_fields})
    
    # Step 3: Check transactions aggregation
    try:
        total_mined_result = await db.transactions.aggregate([
            {"$match": {"user_id": uid, "type": {"$in": ["mining", "tap_game", "referral"]}}},
            {"$group": {"_id": None, "total": {"$sum": "$amount"}}}
        ]).to_list(1)
        debug_info["steps"].append({"step": "transactions_aggregation", "success": True, "count": len(total_mined_result)})
    except Exception as e:
        debug_info["steps"].append({"step": "transactions_aggregation", "success": False, "error": str(e)[:200]})
    
    # Step 4: Check referrals
    try:
        referrals_l1 = await db.users.find({"referred_by": uid}, {"uid": 1, "email": 1}).limit(5).to_list(5)
        debug_info["steps"].append({"step": "referrals_query", "success": True, "l1_count": len(referrals_l1)})
    except Exception as e:
        debug_info["steps"].append({"step": "referrals_query", "success": False, "error": str(e)[:200]})
    
    # Step 5: Check subscription history
    try:
        sub_hist = await db.razorpay_orders.find({"user_id": uid}).limit(5).to_list(5)
        debug_info["steps"].append({"step": "subscription_history", "success": True, "count": len(sub_hist)})
    except Exception as e:
        debug_info["steps"].append({"step": "subscription_history", "success": False, "error": str(e)[:200]})
    
    # Step 6: Check activity logs
    try:
        activities = await db.activity_logs.find({"user_id": uid}).limit(5).to_list(5)
        debug_info["steps"].append({"step": "activity_logs", "success": True, "count": len(activities)})
    except Exception as e:
        debug_info["steps"].append({"step": "activity_logs", "success": False, "error": str(e)[:200]})
    
    debug_info["user_basic"] = {
        "uid": uid,
        "email": user.get("email"),
        "subscription_plan": user.get("subscription_plan"),
        "subscription_expiry": str(user.get("subscription_expiry")),
        "created_at": str(user.get("created_at"))
    }
    
    return debug_info


# ========== USER-360 IN-PROCESS CACHE ==========
# 90 s per-uid TTL. Plain dict with monotonic timestamps — sub-ms cache hits on
# repeat admin clicks. Replaces failed Upstash REST attempt (Apr 30 2026).
import time as _u360_time
_USER360_CACHE: dict = {}  # uid -> {"data": payload, "ts": float}
_USER360_TTL = 90.0
_USER360_MAX_ENTRIES = 200  # bounded; admin views ~few dozen users per session


def _user360_cache_get(uid: str):
    entry = _USER360_CACHE.get(uid)
    if entry and (_u360_time.monotonic() - entry["ts"]) < _USER360_TTL:
        return entry["data"]
    if entry:
        _USER360_CACHE.pop(uid, None)
    return None


def _user360_cache_set(uid: str, payload):
    if len(_USER360_CACHE) >= _USER360_MAX_ENTRIES:
        # Evict oldest 25% — simple LRU-ish without OrderedDict overhead
        items = sorted(_USER360_CACHE.items(), key=lambda kv: kv[1]["ts"])
        for k, _ in items[: _USER360_MAX_ENTRIES // 4]:
            _USER360_CACHE.pop(k, None)
    _USER360_CACHE[uid] = {"data": payload, "ts": _u360_time.monotonic()}


@api_router.get("/admin/user-360")
async def get_user_360_view(query: str, request: Request):
    """
    Get comprehensive 360° view of a user for admin analytics.
    Search by: email, mobile, Aadhaar (last 4 digits), PAN, UID, or referral code.
    Returns: user profile, financial summary, referral network, all transactions, and activity timeline.

    PERF (May 2 2026): In-process per-uid TTL cache (90 s) — Upstash REST was too
    slow for this payload, but a plain dict + monotonic timestamp gives sub-ms
    cache hits on repeat admin clicks. Stale entries auto-evicted on access.
    """
    # Log the incoming request for debugging
    logging.info(f"[USER360] Request received - query: {query}")

    if not query or len(query.strip()) < 2:
        raise HTTPException(status_code=400, detail="Search query too short")

    query = query.strip()
    
    try:
        # Escape regex special characters to prevent injection and errors
        import re as regex_module
        escaped_query = regex_module.escape(query)

        # ----- INDEX-FIRST USER LOOKUP -----
        # The previous implementation issued a single `$or` with 5+ regex variants.
        # On Atlas with 6000+ users that pattern can't use any single index and
        # always took 8 s (asyncio.wait_for cap). Now we try each lookup
        # individually in priority order; first hit wins.
        DB_FAST_TIMEOUT = 6.0  # per-attempt
        DB_REGEX_TIMEOUT = 4.0
        user = None

        async def _try(coro):
            try:
                return await asyncio.wait_for(coro, timeout=DB_FAST_TIMEOUT)
            except asyncio.TimeoutError:
                return None
            except Exception as inner:
                logging.warning(f"[USER360] lookup attempt err: {inner}")
                return None

        # 1) Exact matches — all index-backed (uid, mobile, phone, email lower, referral_code upper, pan_number upper)
        exact_lookups = [
            db.users.find_one({"uid": query}),
            db.users.find_one({"mobile": query}),
            db.users.find_one({"phone": query}),
            db.users.find_one({"email": query.lower()}),
            db.users.find_one({"referral_code": query.upper()}),
            db.users.find_one({"pan_number": query.upper()}),
        ]
        try:
            exact_results = await asyncio.gather(*[_try(c) for c in exact_lookups], return_exceptions=False)
        except Exception as e:
            logging.error(f"[USER360] exact gather error: {e}")
            exact_results = [None] * len(exact_lookups)
        for r in exact_results:
            if r:
                user = r
                break

        # 2) Aadhaar (12-digit exact OR last-4 suffix)
        if not user:
            if len(query) == 12 and query.isdigit():
                user = await _try(db.users.find_one({"aadhaar_number": query}))
            elif query.isdigit() and len(query) == 4:
                try:
                    user = await asyncio.wait_for(
                        db.users.find_one({"aadhaar_number": {"$regex": f"{escaped_query}$"}}),
                        timeout=DB_REGEX_TIMEOUT,
                    )
                except (asyncio.TimeoutError, Exception):
                    user = None

        # 3) Final case-insensitive fallback (only if alpha chars present — avoids
        # accidentally regex-scanning numeric mobile/aadhaar collections)
        if not user and any(c.isalpha() for c in query):
            try:
                user = await asyncio.wait_for(
                    db.users.find_one({"$or": [
                        {"email":          {"$regex": f"^{escaped_query}$", "$options": "i"}},
                        {"referral_code":  {"$regex": f"^{escaped_query}$", "$options": "i"}},
                        {"pan_number":     {"$regex": f"^{escaped_query}$", "$options": "i"}},
                    ]}),
                    timeout=DB_REGEX_TIMEOUT,
                )
            except (asyncio.TimeoutError, Exception):
                user = None

        logging.info(f"[USER360] User search result: {'found' if user else 'not found'} for query: {query}")
        
        if not user:
            raise HTTPException(status_code=404, detail="User not found")
        
        # Safely get uid with fallback
        uid = user.get("uid")
        if not uid:
            logging.error(f"User 360: User found but no uid field! Query: {query}")
            raise HTTPException(status_code=500, detail="User data corrupted - missing uid")

        # ---- CACHE FAST-PATH (post user-lookup, pre heavy aggregations) ----
        _cached = _user360_cache_get(uid)
        if _cached is not None:
            logging.info(f"[USER360] cache hit for {uid}")
            return _cached

        logging.info(f"[USER360] Processing user: {uid}")

        # Remove sensitive data from user
        user.pop("password_hash", None)
        user.pop("pin_hash", None)
        user.pop("hashed_pin", None)
        user.pop("password", None)
        user.pop("reset_token", None)
        user.pop("_id", None)
    except HTTPException:
        raise
    except Exception as setup_error:
        logging.error(f"[USER360] Setup error for query '{query}': {str(setup_error)}", exc_info=True)
        raise HTTPException(status_code=500, detail=f"Setup error: {str(setup_error)[:100]}")
    
    # Helper function to convert ObjectIds and datetimes to serializable format
    def sanitize_mongo_doc(doc, depth=0):
        """Convert ObjectIds, datetimes and other non-serializable types to strings"""
        # Prevent infinite recursion
        if depth > 20:
            return str(doc) if doc is not None else None
        
        try:
            if doc is None:
                return None
            elif isinstance(doc, dict):
                return {str(k): sanitize_mongo_doc(v, depth + 1) for k, v in doc.items()}
            elif isinstance(doc, list):
                return [sanitize_mongo_doc(item, depth + 1) for item in doc]
            elif hasattr(doc, '__str__') and type(doc).__name__ == 'ObjectId':
                return str(doc)
            elif isinstance(doc, datetime):
                return doc.isoformat()
            elif isinstance(doc, (int, float, str, bool)):
                return doc
            elif isinstance(doc, bytes):
                return doc.decode('utf-8', errors='replace')
            else:
                # For any other type, convert to string
                return str(doc)
        except Exception as e:
            logging.warning(f"sanitize_mongo_doc error: {e}, returning str")
            return str(doc) if doc is not None else None
    
    # Sanitize user document
    user = sanitize_mongo_doc(user)
    
    # ========== FINANCIAL STATS ==========
    # ========== FINANCIAL STATS + REFERRAL PREP (PARALLELIZED) ==========
    # Was 2 sequential awaits → now fire in parallel with referral section's first
    # batch to eliminate wall-clock stacking on Atlas M10.
    async def _agg_total_mined():
        res = await db.transactions.aggregate([
            {"$match": {"user_id": uid, "type": {"$in": ["mining", "tap_game", "referral", "admin_credit", "prc_rain_gain"]}}},
            {"$group": {"_id": None, "total": {"$sum": "$amount"}}}
        ]).to_list(1)
        return res[0]["total"] if res else 0
    async def _get_total_redeemed():
        try:
            return await get_user_all_time_redeemed(uid)
        except Exception:
            return 0
    async def _get_referrer():
        if not user.get("referred_by"):
            return None
        try:
            return await db.users.find_one({"uid": user["referred_by"]}, {"_id": 0, "name": 1, "email": 1})
        except Exception:
            return None
    async def _get_referrals_list():
        try:
            return await db.users.find(
                {"referred_by": uid},
                {"_id": 0, "uid": 1, "name": 1, "email": 1, "created_at": 1, "mining_active": 1}
            ).sort("created_at", -1).limit(50).to_list(50)
        except Exception:
            return []
    async def _agg_referral_earnings():
        try:
            referral_types = ["referral", "referral_bonus", "referral_reward"]
            res = await db.transactions.aggregate([
                {"$match": {"user_id": uid, "type": {"$in": referral_types}}},
                {"$group": {"_id": None, "total": {"$sum": "$amount"}}}
            ]).to_list(1)
            return res[0]["total"] if res else 0
        except Exception:
            return 0

    try:
        _stats_block = await asyncio.gather(
            _agg_total_mined(),
            _get_total_redeemed(),
            _get_referrer(),
            _get_referrals_list(),
            _agg_referral_earnings(),
            return_exceptions=True,
        )
    except Exception as e:
        logging.error(f"User360 stats-block error for {uid}: {e}")
        _stats_block = [0, 0, None, [], 0]
    total_mined = _stats_block[0] if not isinstance(_stats_block[0], Exception) else 0
    total_redeemed = _stats_block[1] if not isinstance(_stats_block[1], Exception) else 0
    referrer = _stats_block[2] if not isinstance(_stats_block[2], Exception) else None
    referrals = _stats_block[3] if not isinstance(_stats_block[3], Exception) else []
    referral_earnings = _stats_block[4] if not isinstance(_stats_block[4], Exception) else 0

    stats = {
        "total_mined": round(total_mined, 2),
        "total_redeemed": round(total_redeemed, 2),
        "net_balance": round(float(user.get("prc_balance", 0) or 0), 2)
    }

    # ========== REFERRAL NETWORK ==========
    try:
        referred_by_name = None
        if referrer:
            referred_by_name = referrer.get("name") or referrer.get("email", "").split("@")[0]

        # Count active referrals (users who have mining_active or have mined recently)
        # PERF: parallelize the recent_activity probe across all referrals (was N+1 sequential — 503 on heavy users)
        active_referrals = 0
        cutoff_iso = (datetime.now(timezone.utc) - timedelta(days=7)).isoformat()
        probe_uids = []
        for ref in referrals:
            if ref.get("mining_active"):
                active_referrals += 1
            else:
                ru = ref.get("uid")
                if ru:
                    probe_uids.append(ru)
        if probe_uids:
            async def _probe(ru):
                try:
                    return await db.transactions.find_one(
                        {"user_id": ru, "created_at": {"$gte": cutoff_iso}},
                        {"_id": 1}
                    )
                except Exception:
                    return None
            probe_results = await asyncio.gather(*[_probe(ru) for ru in probe_uids], return_exceptions=True)
            active_referrals += sum(1 for r in probe_results if r and not isinstance(r, Exception))

        # Also check users collection for total_referral_earnings field if transactions don't have data
        if referral_earnings == 0:
            user_data = await db.users.find_one({"uid": uid}, {"_id": 0, "total_referral_earnings": 1})
            if user_data:
                referral_earnings = user_data.get("total_referral_earnings", 0)

        referral_data = {
            "referred_by_name": referred_by_name,
            "total_referrals": len(referrals),
            "active_referrals": active_referrals,
            "total_earnings": round(float(referral_earnings or 0), 2),
            "referrals": referrals[:10]  # First 10 referrals
        }
    except Exception as e:
        logging.error(f"User360 referral error for {uid}: {e}")
        referral_data = {
            "referred_by_name": None,
            "total_referrals": 0,
            "active_referrals": 0,
            "total_earnings": 0,
            "referrals": []
        }
    
    # ========== TRANSACTIONS HISTORY (PARALLELIZED) ==========
    # Batch all 7 independent collection queries to reduce wall-clock from sequential to ~max(t).
    async def _fetch_orders():
        return await db.orders.find(
            {"user_id": uid},
            {"_id": 0, "order_id": 1, "total_prc": 1, "prc_amount": 1, "status": 1, "created_at": 1}
        ).sort("created_at", -1).limit(20).to_list(20)
    async def _fetch_bills():
        return await db.bill_payment_requests.find(
            {"user_id": uid},
            {"_id": 0, "request_id": 1, "request_type": 1, "amount_inr": 1, "total_prc_deducted": 1, "status": 1, "created_at": 1}
        ).sort("created_at", -1).limit(20).to_list(20)
    async def _fetch_vouchers():
        return await db.gift_voucher_requests.find(
            {"user_id": uid},
            {"_id": 0, "request_id": 1, "denomination": 1, "total_prc_deducted": 1, "status": 1, "created_at": 1}
        ).sort("created_at", -1).limit(20).to_list(20)
    async def _fetch_subs():
        return await db.subscriptions.find(
            {"user_id": uid},
            {"payment_id": 1, "subscription_plan": 1, "plan_type": 1, "amount": 1, "status": 1, "submitted_at": 1}
        ).sort("submitted_at", -1).limit(20).to_list(20)
    async def _fetch_vip_subs():
        return await db.vip_subscriptions.find(
            {"user_id": uid},
            {"payment_id": 1, "subscription_plan": 1, "plan_type": 1, "amount": 1, "status": 1, "submitted_at": 1}
        ).sort("submitted_at", -1).limit(20).to_list(20)
    async def _fetch_vip_payments():
        return await db.vip_payments.find(
            {"uid": uid},
            {"payment_id": 1, "plan": 1, "plan_type": 1, "amount": 1, "status": 1, "created_at": 1, "approved_at": 1}
        ).sort("created_at", -1).limit(20).to_list(20)
    async def _fetch_rp_orders():
        return await db.razorpay_orders.find(
            {"user_id": uid},
            {"_id": 0, "order_id": 1, "plan_name": 1, "plan_type": 1, "amount": 1, "status": 1, "payment_id": 1, "created_at": 1, "paid_at": 1}
        ).sort("created_at", -1).limit(20).to_list(20)

    _txn_results = await asyncio.gather(
        _fetch_orders(), _fetch_bills(), _fetch_vouchers(),
        _fetch_subs(), _fetch_vip_subs(), _fetch_vip_payments(), _fetch_rp_orders(),
        return_exceptions=True,
    )
    orders = _txn_results[0] if not isinstance(_txn_results[0], Exception) else []
    bill_payments = _txn_results[1] if not isinstance(_txn_results[1], Exception) else []
    gift_vouchers = _txn_results[2] if not isinstance(_txn_results[2], Exception) else []
    subscriptions_raw = _txn_results[3] if not isinstance(_txn_results[3], Exception) else []
    vip_subscriptions_raw = _txn_results[4] if not isinstance(_txn_results[4], Exception) else []
    vip_payments_raw = _txn_results[5] if not isinstance(_txn_results[5], Exception) else []
    razorpay_orders = _txn_results[6] if not isinstance(_txn_results[6], Exception) else []
    # Stringify _id for subs/vip_subs/vip_payments (deletion capability)
    subscriptions = []
    for sub in subscriptions_raw:
        sub["_id"] = str(sub["_id"]) if "_id" in sub else None
        subscriptions.append(sub)
    vip_subscriptions = []
    for sub in vip_subscriptions_raw:
        sub["_id"] = str(sub["_id"]) if "_id" in sub else None
        vip_subscriptions.append(sub)
    vip_payments = []
    for payment in vip_payments_raw:
        payment["_id"] = str(payment["_id"]) if "_id" in payment else None
        vip_payments.append(payment)
    
    # Merge subscription lists
    all_subscriptions = subscriptions + vip_subscriptions
    all_subscriptions.sort(key=lambda x: x.get("submitted_at", "") or "", reverse=True)
    
    transactions = {
        "orders": orders,
        "bill_payments": bill_payments,
        "gift_vouchers": gift_vouchers,
        "subscriptions": all_subscriptions[:20],
        "vip_payments": vip_payments,
        "razorpay_orders": razorpay_orders,
        "redemptions": [],
        "mining_history": [],
        "prc_ledger": []
    }
    
    # ========== REDEMPTION REQUESTS ==========
    try:
        # Check multiple possible collections for redemptions
        redemptions = await db.redemption_requests.find(
            {"user_id": uid},
            {"_id": 0}
        ).sort("created_at", -1).limit(50).to_list(50)
        
        if not redemptions:
            # Also try bank_transfers collection
            redemptions = await db.bank_transfers.find(
                {"user_id": uid},
                {"_id": 0}
            ).sort("created_at", -1).limit(50).to_list(50)
        
        transactions["redemptions"] = redemptions
    except Exception as e:
        logging.error(f"User360 redemptions error for {uid}: {e}")
        transactions["redemptions"] = []
    
    # ========== MINING HISTORY ==========
    try:
        mining_history = await db.mining_sessions.find(
            {"user_id": uid},
            {"_id": 0, "prc_earned": 1, "session_duration": 1, "created_at": 1, "timestamp": 1, "amount": 1, "duration": 1}
        ).sort("created_at", -1).limit(100).to_list(100)
        
        if not mining_history:
            # Get from transactions with type mining
            mining_history = await db.transactions.find(
                {"user_id": uid, "type": {"$in": ["mining", "tap_game"]}},
                {"_id": 0, "amount": 1, "type": 1, "created_at": 1, "description": 1}
            ).sort("created_at", -1).limit(100).to_list(100)
            # Format for frontend
            for m in mining_history:
                m["prc_earned"] = m.get("amount", 0)
        
        transactions["mining_history"] = mining_history
    except Exception as e:
        logging.error(f"User360 mining_history error for {uid}: {e}")
        transactions["mining_history"] = []
    
    # ========== PRC LEDGER (All Transactions) ==========
    try:
        prc_ledger = await db.transactions.find(
            {"user_id": uid},
            {"_id": 0, "type": 1, "amount": 1, "description": 1, "reason": 1, "created_at": 1, "timestamp": 1, "balance_after": 1}
        ).sort("created_at", -1).limit(200).to_list(200)
        
        # Format ledger entries — preserve original type for display
        for entry in prc_ledger:
            amount = entry.get("amount", 0) or 0
            entry["direction"] = "credit" if amount > 0 else "debit"
        
        transactions["prc_ledger"] = prc_ledger
    except Exception as e:
        logging.error(f"User360 prc_ledger error for {uid}: {e}")
        transactions["prc_ledger"] = []
    
    # ========== ACTIVITY + KYC + LOGIN + REDEEM LIMIT + SUBSCRIPTION HISTORY + PLAN CHANGES
    # (ALL PARALLELIZED IN ONE BATCH — was 6 sequential awaits)
    async def _fetch_recent_transactions():
        try:
            return await db.transactions.find(
                {"user_id": uid},
                {"_id": 0, "type": 1, "amount": 1, "description": 1, "created_at": 1}
            ).sort("created_at", -1).limit(30).to_list(30)
        except Exception:
            return []
    async def _fetch_recent_activities():
        try:
            return await db.activity_logs.find(
                {"user_id": uid},
                {"_id": 0, "action_type": 1, "description": 1, "created_at": 1, "timestamp": 1}
            ).sort("created_at", -1).limit(20).to_list(20)
        except Exception:
            return []
    async def _fetch_kyc():
        try:
            return await db.kyc_documents.find_one({"user_id": uid}, {"_id": 0})
        except Exception:
            return None
    async def _fetch_login_history():
        try:
            return await db.login_history.find(
                {"user_id": uid},
                {"_id": 0, "timestamp": 1, "created_at": 1, "ip_address": 1, "user_agent": 1, "device": 1, "success": 1}
            ).sort("timestamp", -1).limit(50).to_list(50)
        except Exception:
            return []
    async def _fetch_redeem_limit():
        try:
            return await get_user_redeem_limit_internal(uid)
        except Exception:
            return {"total_limit": 0, "total_redeemed": 0, "remaining_limit": 0}
    async def _fetch_razorpay_hist():
        try:
            return await db.razorpay_orders.find(
                {"user_id": uid},
                {"_id": 0, "order_id": 1, "payment_id": 1, "amount": 1, "plan_name": 1, "plan_type": 1,
                 "status": 1, "created_at": 1, "paid_at": 1, "cancelled_at": 1, "failure_reason": 1}
            ).sort("created_at", -1).limit(50).to_list(50)
        except Exception:
            return []
    async def _fetch_vip_payments_hist():
        try:
            return await db.vip_payments.find(
                {"$or": [{"user_uid": uid}, {"user_id": uid}, {"uid": uid}]},
                {"_id": 0, "payment_id": 1, "amount": 1, "plan": 1, "plan_type": 1, "status": 1,
                 "created_at": 1, "approved_at": 1, "rejected_at": 1, "utr_number": 1, "screenshot_url": 1}
            ).sort("created_at", -1).limit(50).to_list(50)
        except Exception:
            return []
    async def _fetch_plan_changes():
        try:
            return await db.admin_actions.find(
                {"user_id": uid, "action": {"$in": ["plan_change", "subscription_update", "redeem_limit_override"]}},
                {"_id": 0}
            ).sort("timestamp", -1).limit(20).to_list(20)
        except Exception:
            return []

    _meta = await asyncio.gather(
        _fetch_recent_transactions(),
        _fetch_recent_activities(),
        _fetch_kyc(),
        _fetch_login_history(),
        _fetch_redeem_limit(),
        _fetch_razorpay_hist(),
        _fetch_vip_payments_hist(),
        _fetch_plan_changes(),
        return_exceptions=True,
    )
    recent_transactions = _meta[0] if not isinstance(_meta[0], Exception) else []
    recent_activities   = _meta[1] if not isinstance(_meta[1], Exception) else []
    kyc_docs            = _meta[2] if not isinstance(_meta[2], Exception) else None
    login_history       = _meta[3] if not isinstance(_meta[3], Exception) else []
    redeem_limit_data   = _meta[4] if not isinstance(_meta[4], Exception) else {"total_limit": 0, "total_redeemed": 0, "remaining_limit": 0}
    razorpay_payments   = _meta[5] if not isinstance(_meta[5], Exception) else []
    vip_payments_hist   = _meta[6] if not isinstance(_meta[6], Exception) else []
    plan_changes        = _meta[7] if not isinstance(_meta[7], Exception) else []

    # Merge and format activity
    activity = []
    for txn in recent_transactions:
        activity.append({
            "type": "transaction",
            "action_type": txn.get("type"),
            "description": f"{(txn.get('type') or 'Transaction').replace('_', ' ').title()}: {txn.get('amount', 0)} PRC",
            "created_at": txn.get("created_at")
        })
    
    for act in recent_activities:
        activity.append({
            "type": "activity",
            "action_type": act.get("action_type"),
            "description": act.get("description", act.get("action_type", "Activity")),
            "created_at": act.get("created_at") or act.get("timestamp")
        })
    
    # Sort by date (handle None values)
    activity.sort(key=lambda x: x.get("created_at") or "1970-01-01", reverse=True)
    
    # ========== REDEEM BREAKDOWN BY SERVICE (PARALLELIZED) ==========
    redeem_breakdown = {}
    
    valid_redeem_status = ["completed", "COMPLETED", "Completed", "success", "SUCCESS", "Success", "approved", "APPROVED", "Approved", "paid", "PAID", "Paid", "pending", "PENDING", "Pending", "processing", "PROCESSING", "Processing", "delivered", "DELIVERED", "Delivered"]

    async def _agg_bbps():
        return await db.redeem_requests.aggregate([
            {"$match": {"user_id": uid, "status": {"$in": valid_redeem_status}}},
            {"$group": {"_id": None, "total": {"$sum": {"$ifNull": ["$total_prc_deducted", {"$ifNull": ["$prc_amount", 0]}]}}}}
        ]).to_list(1)
    async def _agg_voucher():
        return await db.gift_voucher_requests.aggregate([
            {"$match": {"user_id": uid, "status": {"$in": valid_redeem_status}}},
            {"$group": {"_id": None, "total": {"$sum": {"$ifNull": ["$total_prc_deducted", {"$ifNull": ["$prc_used", 0]}]}}}}
        ]).to_list(1)
    async def _agg_bank():
        return await db.bank_transfer_requests.aggregate([
            {"$match": {"user_id": uid, "status": {"$in": valid_redeem_status}}},
            {"$group": {"_id": None, "total": {"$sum": {"$ifNull": ["$total_prc_deducted", {"$ifNull": ["$prc_amount", 0]}]}}}}
        ]).to_list(1)
    async def _agg_dmt():
        return await db.dmt_requests.aggregate([
            {"$match": {"user_id": uid, "status": {"$in": valid_redeem_status}}},
            {"$group": {"_id": None, "total": {"$sum": {"$ifNull": ["$total_prc_deducted", {"$ifNull": ["$prc_amount", 0]}]}}}}
        ]).to_list(1)
    async def _agg_shop():
        return await db.orders.aggregate([
            {"$match": {"user_id": uid, "status": {"$in": valid_redeem_status}}},
            {"$group": {"_id": None, "total": {"$sum": {"$ifNull": ["$total_prc", {"$ifNull": ["$prc_amount", 0]}]}}}}
        ]).to_list(1)

    _agg_results = await asyncio.gather(
        _agg_bbps(), _agg_voucher(), _agg_bank(), _agg_dmt(), _agg_shop(),
        return_exceptions=True,
    )
    _keys = ["bbps", "gift_voucher", "bank_transfer", "dmt", "shop"]
    for _k, _r in zip(_keys, _agg_results):
        try:
            if not isinstance(_r, Exception) and _r and _r[0].get("total", 0) > 0:
                redeem_breakdown[_k] = round(_r[0]["total"], 2)
        except Exception:
            pass
    
    # ========== FAILED/PENDING TRANSACTIONS (For Issue Resolution) — PARALLELIZED ==========
    failed_transactions = []

    async def _fetch_failed_bbps():
        return await db.redeem_requests.find(
            {"user_id": uid, "status": {"$in": ["failed", "rejected", "RETRY_FAILED", "eko_failed", "pending"]}},
            {"_id": 0, "request_id": 1, "service_type": 1, "amount": 1, "total_prc_deducted": 1, "prc_amount": 1,
             "status": 1, "created_at": 1, "error_message": 1, "prc_refunded": 1, "consumer_number": 1}
        ).sort("created_at", -1).limit(50).to_list(50)
    async def _fetch_failed_vouchers():
        return await db.gift_voucher_requests.find(
            {"user_id": uid, "status": {"$in": ["failed", "rejected", "pending", "processing"]}},
            {"_id": 0, "request_id": 1, "brand_name": 1, "denomination": 1, "total_prc_deducted": 1, "prc_used": 1,
             "status": 1, "created_at": 1, "rejection_reason": 1, "prc_refunded": 1}
        ).sort("created_at", -1).limit(50).to_list(50)
    async def _fetch_failed_bank():
        return await db.bank_transfer_requests.find(
            {"user_id": uid, "status": {"$in": ["failed", "rejected", "pending", "processing"]}},
            {"_id": 0, "request_id": 1, "amount_inr": 1, "total_prc_deducted": 1, "prc_amount": 1,
             "status": 1, "created_at": 1, "rejection_reason": 1, "prc_refunded": 1, "bank_name": 1, "account_number": 1}
        ).sort("created_at", -1).limit(50).to_list(50)

    _failed = await asyncio.gather(
        _fetch_failed_bbps(), _fetch_failed_vouchers(), _fetch_failed_bank(),
        return_exceptions=True,
    )
    failed_bbps = _failed[0] if not isinstance(_failed[0], Exception) else []
    failed_vouchers = _failed[1] if not isinstance(_failed[1], Exception) else []
    failed_bank = _failed[2] if not isinstance(_failed[2], Exception) else []

    for req in failed_bbps:
        req["type"] = "bbps"
        req["prc_amount"] = req.get("total_prc_deducted") or req.get("prc_amount") or 0
        failed_transactions.append(req)
    for req in failed_vouchers:
        req["type"] = "gift_voucher"
        req["prc_amount"] = req.get("total_prc_deducted") or req.get("prc_used") or 0
        failed_transactions.append(req)
    for req in failed_bank:
        req["type"] = "bank_transfer"
        req["prc_amount"] = req.get("total_prc_deducted") or req.get("prc_amount") or 0
        failed_transactions.append(req)
    
    # Sort all failed transactions by date
    failed_transactions.sort(key=lambda x: x.get("created_at") or "", reverse=True)
    
    # ========== SUBSCRIPTION HISTORY & FRAUD CHECK ==========
    subscription_history = []
    fraud_indicators = []

    # razorpay_payments + vip_payments_hist were already fetched in the
    # parallelized meta-batch above. Build unified subscription_history here.
    for rp in razorpay_payments:
        rp["source"] = "razorpay"
        rp["amount_display"] = f"₹{rp.get('amount', 0)}"
        subscription_history.append(rp)
    for vp in vip_payments_hist:
        vp["source"] = "vip_manual"
        vp["amount_display"] = f"₹{vp.get('amount', 0)}"
        subscription_history.append(vp)
    
    # Sort combined history (normalize datetime → iso string for stable sort)
    def _to_iso(v):
        if v is None:
            return ""
        if isinstance(v, datetime):
            try:
                return v.isoformat()
            except Exception:
                return ""
        return str(v)
    subscription_history.sort(key=lambda x: _to_iso(x.get("created_at") or x.get("paid_at")), reverse=True)
    
    # ========== FRAUD DETECTION ==========
    # 1. Multiple failed payments in short time
    failed_count = len([p for p in razorpay_payments if p.get("status") in ["failed", "cancelled"]])
    if failed_count >= 3:
        fraud_indicators.append({
            "type": "multiple_failed_payments",
            "severity": "medium",
            "description": f"{failed_count} failed/cancelled payments detected",
            "action": "Review payment attempts"
        })
    
    # 2. Subscription active but no successful payment
    user_plan = user.get("subscription_plan", "explorer")
    successful_payments = [p for p in razorpay_payments if p.get("status") == "paid"]
    successful_vip = [p for p in vip_payments if p.get("status") == "approved"]
    
    if user_plan not in ["explorer", "free", "", None] and len(successful_payments) == 0 and len(successful_vip) == 0:
        fraud_indicators.append({
            "type": "no_payment_record",
            "severity": "high",
            "description": f"User has '{user_plan}' subscription but NO payment record found",
            "action": "Investigate how subscription was activated"
        })
    
    # 3. Payment amount mismatch
    for rp in successful_payments[:5]:
        amount = rp.get("amount", 0)
        plan = rp.get("plan_name", "").lower()
        # Elite monthly = 799
        if "elite" in plan and "monthly" in rp.get("plan_type", ""):
            if amount < 700:
                fraud_indicators.append({
                    "type": "amount_mismatch",
                    "severity": "high",
                    "description": f"Elite monthly paid only ₹{amount} (expected ₹799)",
                    "action": "Check for coupon abuse or payment tampering"
                })
    
    # 4. Rapid plan changes (plan_changes was pre-fetched in the parallel meta-batch)
    if len(plan_changes) >= 5:
        fraud_indicators.append({
            "type": "frequent_plan_changes",
            "severity": "low",
            "description": f"{len(plan_changes)} admin plan changes detected",
            "action": "Review if changes were legitimate"
        })
    
    # 5. Subscription expiry in far future (manipulation)
    expiry = get_user_expiry(user)
    if expiry:
        try:
            if isinstance(expiry, str):
                expiry_date = datetime.fromisoformat(expiry.replace('Z', '+00:00'))
            else:
                expiry_date = expiry
            
            days_until_expiry = (expiry_date.replace(tzinfo=timezone.utc) - datetime.now(timezone.utc)).days
            if days_until_expiry > 400:  # More than 1 year + buffer
                fraud_indicators.append({
                    "type": "excessive_subscription_period",
                    "severity": "high",
                    "description": f"Subscription expires in {days_until_expiry} days ({days_until_expiry//30} months)",
                    "action": "Verify if this is legitimate multi-year purchase"
                })
        except:
            pass
    
    # Calculate fraud score
    fraud_score = 0
    for indicator in fraud_indicators:
        if indicator["severity"] == "high":
            fraud_score += 30
        elif indicator["severity"] == "medium":
            fraud_score += 15
        elif indicator["severity"] == "low":
            fraud_score += 5
        fraud_score = min(100, fraud_score)
    
    # Sanitize all data before returning to avoid ObjectId serialization errors
    try:
        # Trailing metadata (upcoming plan + core team + employee) — parallelized
        async def _fetch_upcoming():
            try:
                return await db.subscription_payments.find_one(
                    {"user_id": uid, "status": "upcoming"},
                    {"_id": 0, "plan_name": 1, "scheduled_start": 1, "scheduled_end": 1,
                     "duration_days": 1, "payment_method": 1, "prc_amount": 1, "created_at": 1},
                    sort=[("scheduled_start", 1)]
                )
            except Exception:
                return None
        async def _fetch_core_team():
            try:
                return await db.core_team_members.find_one(
                    {"uid": uid, "status": "active"},
                    {"_id": 0, "member_id": 1, "designation": 1, "added_at": 1}
                )
            except Exception:
                return None
        async def _fetch_employee():
            try:
                return await db.employees.find_one(
                    {"user_id": uid, "status": "active"},
                    {"_id": 0, "employee_id": 1, "designation": 1, "department": 1, "monthly_salary": 1, "joined_at": 1}
                )
            except Exception:
                return None

        _tail = await asyncio.gather(
            _fetch_upcoming(), _fetch_core_team(), _fetch_employee(),
            return_exceptions=True,
        )
        up = _tail[0] if not isinstance(_tail[0], Exception) else None
        ctm = _tail[1] if not isinstance(_tail[1], Exception) else None
        emp = _tail[2] if not isinstance(_tail[2], Exception) else None

        upcoming_plan = sanitize_mongo_doc(up) if up else None

        sanitized_user = sanitize_mongo_doc(user)
        if isinstance(sanitized_user, dict):
            sanitized_user["upcoming_plan"] = upcoming_plan
            sanitized_user["core_team"] = sanitize_mongo_doc(ctm) if ctm else None
            sanitized_user["employee"] = sanitize_mongo_doc(emp) if emp else None
        
        response_data = {
            "user": sanitized_user,
            "stats": sanitize_mongo_doc(stats),
            "referral": sanitize_mongo_doc(referral_data),
            "transactions": sanitize_mongo_doc(transactions),
            "activity": sanitize_mongo_doc(activity[:30]),
            "kyc": sanitize_mongo_doc(kyc_docs),
            "login_history": sanitize_mongo_doc(login_history),
            "redeem_limit": sanitize_mongo_doc(redeem_limit_data),
            "redeem_breakdown": sanitize_mongo_doc(redeem_breakdown),
            "failed_transactions": sanitize_mongo_doc(failed_transactions[:30]),
            "subscription_history": sanitize_mongo_doc(subscription_history[:30]),
            "fraud_check": {
                "score": fraud_score,
                "indicators": fraud_indicators,
                "status": "clean" if fraud_score == 0 else "suspicious" if fraud_score < 50 else "high_risk"
            }
        }
        logging.info(f"[USER360] Successfully returning data for user: {uid}")
        # Cache for 90 s — repeated admin clicks are sub-ms
        try:
            _user360_cache_set(uid, response_data)
        except Exception:
            pass
        return response_data
    except Exception as e:
        logging.error(f"[USER360] Serialization error for {uid}: {str(e)}", exc_info=True)
        raise HTTPException(status_code=500, detail=f"Data serialization error: {str(e)[:100]}")


@api_router.post("/admin/refund-transaction")
async def admin_refund_transaction(request: Request):
    """
    Manually refund PRC for a specific failed/rejected transaction.
    Used from User 360 page to resolve user issues.
    """
    data = await request.json()
    request_id = data.get("request_id")
    user_id = data.get("user_id")
    prc_amount = data.get("prc_amount", 0)
    txn_type = data.get("txn_type", "bbps")  # bbps, gift_voucher, bank_transfer
    reason = data.get("reason", "Admin manual refund")
    admin_id = data.get("admin_id")
    
    if not request_id or not user_id or prc_amount <= 0:
        raise HTTPException(status_code=400, detail="Missing required fields: request_id, user_id, prc_amount")
    
    timestamp = datetime.now(timezone.utc).isoformat()
    
    # Check if already refunded
    collection_map = {
        "bbps": "redeem_requests",
        "gift_voucher": "gift_voucher_requests",
        "bank_transfer": "bank_transfer_requests"
    }
    collection_name = collection_map.get(txn_type, "redeem_requests")
    
    existing = await db[collection_name].find_one({"request_id": request_id})
    if existing and existing.get("prc_refunded"):
        raise HTTPException(status_code=400, detail="Transaction already refunded")
    
    # Get user
    user = await db.users.find_one({"uid": user_id})
    if not user:
        raise HTTPException(status_code=404, detail="User not found")
    
    current_balance = float(user.get("prc_balance", 0) or 0)
    new_balance = current_balance + prc_amount
    
    # Update user balance
    await db.users.update_one(
        {"uid": user_id},
        {"$set": {"prc_balance": new_balance}}
    )
    
    # Mark transaction as refunded
    await db[collection_name].update_one(
        {"request_id": request_id},
        {"$set": {
            "prc_refunded": True,
            "refund_amount": prc_amount,
            "refund_reason": reason,
            "refunded_by": admin_id,
            "refunded_at": timestamp
        }}
    )
    
    # Log the refund
    await db.transactions.insert_one({
        "transaction_id": f"REFUND-{request_id}",
        "user_id": user_id,
        "type": "admin_refund",
        "amount": prc_amount,
        "balance_before": current_balance,
        "balance_after": new_balance,
        "description": f"Admin refund: {reason}",
        "reference": request_id,
        "admin_id": admin_id,
        "timestamp": timestamp,
        "created_at": timestamp
    })
    
    return {
        "success": True,
        "message": f"Refunded {prc_amount} PRC successfully",
        "new_balance": new_balance,
        "refund_details": {
            "request_id": request_id,
            "prc_refunded": prc_amount,
            "refunded_at": timestamp
        }
    }


@api_router.get("/admin/redeem-limits-overview")
async def admin_redeem_limits_overview():
    """
    Admin endpoint: Get redeem limit overview for all users.
    Returns aggregate totals + per-user breakdown.
    Cached 60 seconds — avoids expensive N-user calc on every admin refresh.
    """
    cache_key = "admin:redeem_limits_overview"
    if cache:
        cached = await cache.get(cache_key)
        if cached:
            return cached

    try:
        
        # Get all users with balance > 0
        users = await db.users.find(
            {"prc_balance": {"$gt": 0}},
            {"_id": 0, "uid": 1, "name": 1, "email": 1, "mobile_number": 1, "prc_balance": 1, "subscription_plan": 1}
        ).to_list(None)

        # OPTIMIZED: Parallelize N independent calculate_user_redeem_limit calls with concurrency cap
        # Throttled to 15 concurrent to avoid saturating DB connection pool on cold cache
        _sem = asyncio.Semaphore(15)

        async def _safe_limit(uid):
            async with _sem:
                try:
                    return await calculate_user_redeem_limit(uid)
                except Exception:
                    return {"total_earned": 0, "unlock_percent": 0, "redeemable": 0, "total_redeemed": 0, "effective_available": 0, "network_size": 0}

        limit_infos = await asyncio.gather(*[_safe_limit(u["uid"]) for u in users])

        user_data = []
        agg_total_earned = 0
        agg_total_redeemable = 0
        agg_total_redeemed = 0
        agg_total_available = 0
        agg_total_balance = 0

        for u, limit_info in zip(users, limit_infos):
            uid = u["uid"]
            balance = float(u.get("prc_balance", 0) or 0)
            total_earned = limit_info.get("total_earned", 0)
            unlock_pct = limit_info.get("unlock_percent", 0)
            redeemable = limit_info.get("redeemable", 0)
            total_redeemed = limit_info.get("total_redeemed", 0)
            available = limit_info.get("effective_available", 0)
            network_size = limit_info.get("network_size", 0)

            user_data.append({
                "uid": uid,
                "name": u.get("name", ""),
                "mobile": u.get("mobile_number", ""),
                "plan": u.get("subscription_plan", "explorer"),
                "balance": round(balance, 2),
                "total_earned": round(total_earned, 2),
                "unlock_percent": round(unlock_pct, 2),
                "redeemable": round(redeemable, 2),
                "total_redeemed": round(total_redeemed, 2),
                "available": round(available, 2),
                "network_size": network_size,
            })

            agg_total_earned += total_earned
            agg_total_redeemable += redeemable
            agg_total_redeemed += total_redeemed
            agg_total_available += available
            agg_total_balance += balance
        
        # Sort by balance desc
        user_data.sort(key=lambda x: x["balance"], reverse=True)
        
        result = {
            "aggregate": {
                "total_users": len(user_data),
                "total_balance": round(agg_total_balance, 2),
                "total_earned": round(agg_total_earned, 2),
                "total_redeemable": round(agg_total_redeemable, 2),
                "total_redeemed": round(agg_total_redeemed, 2),
                "total_available": round(agg_total_available, 2),
            },
            "users": user_data,
        }
        # Cache for 60 seconds to avoid repeated expensive recalculation
        if cache:
            try:
                await cache.set(cache_key, result, ttl=60)
            except Exception:
                pass
        return result
    except Exception as e:
        logging.error(f"Admin redeem limits overview error: {e}")
        import traceback
        traceback.print_exc()
        raise HTTPException(status_code=500, detail=str(e))



@api_router.get("/admin/debug/total-redeemed/{user_id}")
async def admin_debug_total_redeemed(user_id: str, request: Request):
    """
    ADMIN DIAGNOSTIC: Returns the full breakdown of get_user_all_time_redeemed
    for a user, plus the raw per-service scan (same as "Redeem Used Details"
    breakdown), so we can diagnose any "Total Redeemed = 0" inconsistency
    between the authoritative aggregator and the per-category breakdown.
    """
    auth_header = request.headers.get("Authorization", "")
    if auth_header.startswith("Bearer "):
        try:
            token = auth_header.replace("Bearer ", "")
            payload = jwt.decode(token, JWT_SECRET_KEY, algorithms=[JWT_ALGORITHM])
            role = payload.get("role", "user")
            if role not in ("admin", "sub_admin"):
                raise HTTPException(status_code=403, detail="Admin only")
        except jwt.InvalidTokenError:
            raise HTTPException(status_code=401, detail="Invalid token")
    else:
        raise HTTPException(status_code=401, detail="Admin token required")

    user = await db.users.find_one(
        {"uid": user_id},
        {"_id": 0, "uid": 1, "name": 1, "mobile": 1, "prc_balance": 1}
    )
    if not user:
        raise HTTPException(status_code=404, detail="User not found")

    try:
        total, info = await get_user_all_time_redeemed(user_id, debug=True)
    except Exception as e:
        raise HTTPException(status_code=500, detail=f"aggregator failed: {e}")

    service_sources = [
        ("recharge_requests", "Mobile Recharge", {}, ["prc_used", "prc_amount", "total_prc_deducted", "amount"]),
        ("bill_payment_requests", "Bill Pay", {}, ["prc_used", "total_prc_deducted", "prc_amount", "amount"]),
        ("bill_payments", "Bill Pay", {}, ["prc_used", "total_prc_deducted", "prc_amount"]),
        ("payment_requests", "Bill Pay", {}, ["total_prc_deducted", "prc_amount", "prc_used"]),
        ("gift_voucher_requests", "Gift Cards", {}, ["total_prc_deducted", "prc_amount", "prc_used", "amount"]),
        ("redeem_requests", "Bank Redeem", {}, ["total_prc_deducted", "prc_amount", "total_prc", "amount"]),
        ("bank_withdrawal_requests", "Bank Redeem", {}, ["total_prc_deducted", "prc_amount", "total_prc", "amount"]),
        ("bank_redeem_requests", "Bank Redeem", {}, ["prc_amount", "total_prc_deducted", "amount"]),
        ("bank_transfers", "Bank Redeem", {}, ["prc_amount", "total_prc_deducted", "amount"]),
        ("bank_transfer_requests", "Bank Redeem", {}, ["total_prc_deducted", "prc_deducted", "total_prc", "prc_amount"]),
        ("subscription_payments", "Subscription", {"payment_method": "prc"}, ["prc_amount", "inr_equivalent", "amount"]),
        ("vip_payments", "Subscription", {"payment_method": "prc"}, ["prc_amount", "prc_used", "amount"]),
        ("dmt_transactions", "Bank Redeem", {}, ["prc_deducted", "prc_amount", "total_prc", "amount"]),
        ("dmt_logs", "Bank Redeem", {}, ["prc_deducted", "prc_amount", "amount"]),
        ("orders", "Shopping", {}, ["total_prc", "prc_amount", "prc_used", "amount"]),
        ("unified_redemptions", "Redeem", {}, ["prc_deducted", "prc_amount", "total_prc", "amount"]),
    ]
    SUCCESS = [
        "completed", "COMPLETED", "Completed", "success", "SUCCESS", "Success",
        "approved", "APPROVED", "Approved", "paid", "PAID", "Paid",
        "pending", "PENDING", "Pending", "processing", "PROCESSING", "Processing",
        "delivered", "DELIVERED", "Delivered",
    ]
    by_category = {}
    service_entries = []
    for coll, cat, extra_match, amt_fields in service_sources:
        try:
            q = {"user_id": user_id, "status": {"$in": SUCCESS}}
            q.update(extra_match)
            async for doc in db[coll].find(q, {"_id": 0}):
                amt = 0.0
                used_field = None
                for af in amt_fields:
                    v = doc.get(af)
                    if v and float(v) > 0:
                        amt = round(float(v), 2)
                        used_field = af
                        break
                if amt <= 0:
                    continue
                by_category[cat] = by_category.get(cat, 0) + amt
                ref_id = (
                    doc.get("request_id") or doc.get("redeem_id") or doc.get("txn_id")
                    or doc.get("order_id") or doc.get("payment_id")
                )
                service_entries.append({
                    "collection": coll, "category": cat,
                    "amount_prc": amt, "via_field": used_field,
                    "ref_id": str(ref_id) if ref_id else None,
                    "status": doc.get("status"),
                    "created_at": str(doc.get("created_at") or doc.get("timestamp") or "")[:19],
                })
        except Exception as e:
            logging.warning(f"[DEBUG] {coll} scan error for {user_id}: {e}")

    by_category_rounded = {k: round(v, 2) for k, v in by_category.items()}
    by_category_total = round(sum(by_category.values()), 2)

    return {
        "success": True,
        "user": user,
        "authoritative_total_redeemed": total,
        "authoritative_debits": info["total_debits_prc"],
        "authoritative_refunds": info["total_refunds_prc"],
        "by_category_breakdown": by_category_rounded,
        "by_category_sum": by_category_total,
        "discrepancy_prc": round(by_category_total - total, 2),
        "ledger_entries": info["entries"],
        "service_entries": sorted(service_entries, key=lambda x: x["created_at"], reverse=True),
        "ledger_entry_count": len(info["entries"]),
        "service_entry_count": len(service_entries),
        "diagnosis_hint": (
            "If discrepancy_prc > 0: authoritative aggregator is MISSING debits. "
            "If discrepancy_prc < 0: authoritative has debits not in service scan. "
            "Refunds > debits (in authoritative) → net clamped to 0 by max(0, ...)."
        ),
    }



@api_router.post("/admin/override-redeem-limit")
async def admin_override_redeem_limit(request: Request):
    """
    Override redeem limit for a specific user.
    Used when user needs temporary or permanent limit increase.
    """
    data = await request.json()
    user_id = data.get("user_id")
    new_limit = data.get("new_limit")
    reason = data.get("reason", "Admin override")
    admin_id = data.get("admin_id")
    is_permanent = data.get("is_permanent", False)
    
    if not user_id or new_limit is None:
        raise HTTPException(status_code=400, detail="Missing user_id or new_limit")
    
    user = await db.users.find_one({"uid": user_id})
    if not user:
        raise HTTPException(status_code=404, detail="User not found")
    
    timestamp = datetime.now(timezone.utc).isoformat()
    old_limit = user.get("redeem_limit_override", user.get("monthly_redeem_limit", 0))
    
    update_fields = {
        "redeem_limit_override": new_limit,
        "redeem_limit_override_reason": reason,
        "redeem_limit_override_by": admin_id,
        "redeem_limit_override_at": timestamp
    }
    
    if is_permanent:
        update_fields["monthly_redeem_limit"] = new_limit
    
    await db.users.update_one(
        {"uid": user_id},
        {"$set": update_fields}
    )
    
    # Log the override
    await db.admin_actions.insert_one({
        "action": "redeem_limit_override",
        "user_id": user_id,
        "admin_id": admin_id,
        "old_limit": old_limit,
        "new_limit": new_limit,
        "reason": reason,
        "is_permanent": is_permanent,
        "timestamp": timestamp
    })
    
    return {
        "success": True,
        "message": f"Redeem limit updated to {new_limit}",
        "old_limit": old_limit,
        "new_limit": new_limit
    }


@api_router.post("/admin/update-subscription")
async def admin_update_subscription(request: Request):
    """
    Admin: Update user's subscription plan, expiry, or cancel subscription.
    Actions: update_plan, change_expiry, cancel, extend
    """
    data = await request.json()
    user_id = data.get("user_id")
    action = data.get("action")  # update_plan, change_expiry, cancel, extend
    admin_id = data.get("admin_id")
    reason = data.get("reason", "Admin action")
    
    if not user_id or not action:
        raise HTTPException(status_code=400, detail="Missing user_id or action")
    
    user = await db.users.find_one({"uid": user_id})
    if not user:
        raise HTTPException(status_code=404, detail="User not found")
    
    timestamp = datetime.now(timezone.utc).isoformat()
    old_data = {
        "plan": user.get("subscription_plan"),
        "expiry": user.get("subscription_expiry"),
        "membership_type": user.get("membership_type")
    }
    
    update_fields = {}
    action_description = ""
    
    if action == "update_plan":
        new_plan = data.get("new_plan", "explorer")
        if new_plan not in ["explorer", "startup", "growth", "elite"]:
            raise HTTPException(status_code=400, detail="Invalid plan name")
        
        update_fields["subscription_plan"] = new_plan
        update_fields["membership_type"] = "free" if new_plan == "explorer" else "paid"
        action_description = f"Plan changed from {old_data['plan']} to {new_plan}"
    
    elif action == "change_expiry":
        new_expiry = data.get("new_expiry")  # ISO date string or days to add
        if not new_expiry:
            raise HTTPException(status_code=400, detail="Missing new_expiry")
        
        if isinstance(new_expiry, int) or (isinstance(new_expiry, str) and new_expiry.isdigit()):
            # Days to add from now
            days = int(new_expiry)
            new_expiry_date = datetime.now(timezone.utc) + timedelta(days=days)
        else:
            # ISO date string
            new_expiry_date = datetime.fromisoformat(new_expiry.replace('Z', '+00:00'))
        
        update_fields["subscription_expiry"] = new_expiry_date.isoformat()
        action_description = f"Expiry changed from {old_data['expiry']} to {new_expiry_date.isoformat()}"
    
    elif action == "cancel":
        update_fields["subscription_plan"] = "explorer"
        update_fields["membership_type"] = "free"
        update_fields["subscription_cancelled_at"] = timestamp
        update_fields["subscription_cancelled_by"] = admin_id
        update_fields["subscription_cancelled_reason"] = reason
        action_description = f"Subscription cancelled (was {old_data['plan']})"
    
    elif action == "extend":
        days_to_add = data.get("days", 28)
        current_expiry = get_user_expiry(user)
        
        if current_expiry:
            if isinstance(current_expiry, str):
                current_expiry = datetime.fromisoformat(current_expiry.replace('Z', '+00:00'))
            base_date = max(current_expiry, datetime.now(timezone.utc))
        else:
            base_date = datetime.now(timezone.utc)
        
        new_expiry_date = base_date + timedelta(days=days_to_add)
        update_fields["subscription_expiry"] = new_expiry_date.isoformat()
        action_description = f"Extended by {days_to_add} days (new expiry: {new_expiry_date.date()})"
    
    else:
        raise HTTPException(status_code=400, detail=f"Invalid action: {action}")
    
    # Apply updates
    update_fields["subscription_last_modified"] = timestamp
    update_fields["subscription_modified_by"] = admin_id
    
    await db.users.update_one({"uid": user_id}, {"$set": update_fields})
    
    # Log admin action
    await db.admin_actions.insert_one({
        "action": "subscription_update",
        "sub_action": action,
        "user_id": user_id,
        "admin_id": admin_id,
        "old_data": old_data,
        "new_data": update_fields,
        "reason": reason,
        "description": action_description,
        "timestamp": timestamp
    })
    
    return {
        "success": True,
        "message": action_description,
        "old_data": old_data,
        "new_data": {k: str(v) if isinstance(v, datetime) else v for k, v in update_fields.items()}
    }


@api_router.post("/admin/delete-payment-record")
async def admin_delete_payment_record(request: Request):
    """
    Admin: Delete a fraudulent or erroneous payment record.
    This does NOT refund money - use for cleaning up fake/test records.
    """
    data = await request.json()
    order_id = data.get("order_id")
    payment_id = data.get("payment_id")
    source = data.get("source", "razorpay")  # razorpay or vip
    admin_id = data.get("admin_id")
    reason = data.get("reason", "Admin deletion")
    
    if not order_id and not payment_id:
        raise HTTPException(status_code=400, detail="Missing order_id or payment_id")
    
    timestamp = datetime.now(timezone.utc).isoformat()
    deleted_record = None
    
    if source == "razorpay":
        query = {"order_id": order_id} if order_id else {"payment_id": payment_id}
        deleted_record = await db.razorpay_orders.find_one(query)
        if deleted_record:
            await db.razorpay_orders.delete_one(query)
    else:
        query = {"payment_id": payment_id} if payment_id else {"_id": order_id}
        deleted_record = await db.vip_payments.find_one(query)
        if deleted_record:
            await db.vip_payments.delete_one(query)
    
    if not deleted_record:
        raise HTTPException(status_code=404, detail="Payment record not found")
    
    # Convert ObjectId for logging
    if "_id" in deleted_record:
        deleted_record["_id"] = str(deleted_record["_id"])
    
    # Log deletion
    await db.admin_actions.insert_one({
        "action": "payment_record_deleted",
        "source": source,
        "deleted_record": deleted_record,
        "admin_id": admin_id,
        "reason": reason,
        "timestamp": timestamp
    })
    
    return {
        "success": True,
        "message": f"Payment record deleted ({source})",
        "deleted_record": deleted_record
    }


# ==================== BACKGROUND BULK FIX SYSTEM ====================

async def run_bulk_fix_background(job_id: str, batch_size: int = 50):
    """
    Background task to fix all users in batches.
    Updates job status in database as it progresses.
    """
    import secrets, string
    
    try:
        timestamp = datetime.now(timezone.utc).isoformat()
        
        # Update job status to running
        await db.bulk_fix_jobs.update_one(
            {"job_id": job_id},
            {"$set": {"status": "running", "started_at": timestamp}}
        )
        
        # Get total user count
        total_users = await db.users.count_documents({})
        
        results = {
            "total_users": total_users,
            "processed": 0,
            "users_with_issues": 0,
            "issues_found": 0,
            "issues_fixed": 0,
            "prc_refunded": 0,
            "errors": []
        }
        
        # Process in batches
        skip = 0
        while skip < total_users:
            users = await db.users.find(
                {},
                {"uid": 1, "name": 1, "email": 1, "mobile": 1, "kyc_status": 1, "subscription_plan": 1, 
                 "subscription_expiry": 1,
                 "prc_balance": 1, "membership_type": 1, "mining_start_time": 1, "referral_code": 1}
            ).skip(skip).limit(batch_size).to_list(batch_size)
            
            if not users:
                break
            
            for user in users:
                uid = user.get("uid")
                user_fixed = False
                
                try:
                    # 1. KYC sync
                    kyc_status = user.get("kyc_status", "not_submitted")
                    kyc_doc = await db.kyc_documents.find_one({"user_id": uid})
                    
                    if kyc_doc and kyc_doc.get("status") == "verified" and kyc_status != "verified":
                        await db.users.update_one({"uid": uid}, {"$set": {"kyc_status": "verified"}})
                        results["issues_fixed"] += 1
                        user_fixed = True
                    
                    if kyc_status == "pending" and not kyc_doc:
                        await db.users.update_one({"uid": uid}, {"$set": {"kyc_status": "not_submitted"}})
                        results["issues_fixed"] += 1
                        user_fixed = True
                    
                    if kyc_status == "rejected":
                        await db.users.update_one({"uid": uid}, {"$set": {"kyc_status": "not_submitted", "kyc_can_resubmit": True}})
                        results["issues_fixed"] += 1
                        user_fixed = True
                    
                    # 2. Expired subscription
                    subscription_plan = user.get("subscription_plan", "explorer")
                    subscription_expiry = get_user_expiry(user)
                    membership_type = user.get("membership_type", "free")
                    
                    if subscription_expiry and subscription_plan not in ["explorer", "free", "", None]:
                        try:
                            expiry_date = datetime.fromisoformat(str(subscription_expiry).replace('Z', '+00:00'))
                            if expiry_date < datetime.now(timezone.utc):
                                await db.users.update_one(
                                    {"uid": uid},
                                    {"$set": {"subscription_plan": "explorer", "membership_type": "free"}}
                                )
                                results["issues_fixed"] += 1
                                user_fixed = True
                        except:
                            pass
                    
                    # 3. Membership type mismatch
                    if is_paid_subscriber(user) and membership_type == "free":
                        await db.users.update_one({"uid": uid}, {"$set": {"membership_type": "paid"}})
                        results["issues_fixed"] += 1
                        user_fixed = True
                    
                    # 4. Failed transactions refund
                    failed_txns = await db.redeem_requests.find({
                        "user_id": uid,
                        "status": {"$in": ["failed", "RETRY_FAILED", "eko_failed", "rejected"]},
                        "prc_refunded": {"$ne": True}
                    }).to_list(20)
                    
                    for ftxn in failed_txns:
                        prc_amount = ftxn.get("total_prc_deducted") or ftxn.get("prc_amount") or 0
                        if prc_amount > 0:
                            current_balance = float(user.get("prc_balance", 0) or 0)
                            new_balance = current_balance + prc_amount
                            
                            await db.users.update_one({"uid": uid}, {"$set": {"prc_balance": new_balance}})
                            await db.redeem_requests.update_one(
                                {"request_id": ftxn.get("request_id")},
                                {"$set": {"prc_refunded": True, "refunded_at": timestamp, "refunded_by": "bulk_fix_job"}}
                            )
                            
                            user["prc_balance"] = new_balance
                            results["prc_refunded"] += prc_amount
                            results["issues_fixed"] += 1
                            user_fixed = True
                    
                    # 5. Mining reset
                    mining_start = user.get("mining_start_time")
                    if mining_start:
                        try:
                            start_time = datetime.fromisoformat(str(mining_start).replace('Z', '+00:00'))
                            hours_mining = (datetime.now(timezone.utc) - start_time).total_seconds() / 3600
                            if hours_mining > 12:
                                await db.users.update_one(
                                    {"uid": uid},
                                    {"$set": {"mining_active": False, "mining_start_time": None}}
                                )
                                results["issues_fixed"] += 1
                                user_fixed = True
                        except:
                            pass
                    
                    # 6. Referral code
                    if not user.get("referral_code"):
                        new_code = ''.join(secrets.choice(string.ascii_uppercase + string.digits) for _ in range(8))
                        await db.users.update_one({"uid": uid}, {"$set": {"referral_code": new_code}})
                        results["issues_fixed"] += 1
                        user_fixed = True
                    
                    if user_fixed:
                        results["users_with_issues"] += 1
                    
                except Exception as user_err:
                    results["errors"].append({"uid": uid, "error": str(user_err)})
                
                results["processed"] += 1
            
            skip += batch_size
            
            # Update progress in database
            progress = int((results["processed"] / total_users) * 100)
            await db.bulk_fix_jobs.update_one(
                {"job_id": job_id},
                {"$set": {
                    "progress": progress,
                    "processed": results["processed"],
                    "issues_fixed": results["issues_fixed"],
                    "prc_refunded": round(results["prc_refunded"], 2),
                    "updated_at": datetime.now(timezone.utc).isoformat()
                }}
            )
        
        # Mark job as completed
        await db.bulk_fix_jobs.update_one(
            {"job_id": job_id},
            {"$set": {
                "status": "completed",
                "completed_at": datetime.now(timezone.utc).isoformat(),
                "results": results
            }}
        )
        
    except Exception as e:
        # Mark job as failed
        await db.bulk_fix_jobs.update_one(
            {"job_id": job_id},
            {"$set": {
                "status": "failed",
                "error": str(e),
                "failed_at": datetime.now(timezone.utc).isoformat()
            }}
        )
        logging.error(f"[BULK FIX JOB] Job {job_id} failed: {e}")


@api_router.post("/admin/bulk-fix-start")
async def start_bulk_fix_job(background_tasks: BackgroundTasks):
    """
    Start a background job to fix ALL users.
    Returns job_id to track progress.
    """
    import uuid
    
    job_id = f"BFJ-{uuid.uuid4().hex[:12].upper()}"
    timestamp = datetime.now(timezone.utc).isoformat()
    
    # Check if any job is already running
    running_job = await db.bulk_fix_jobs.find_one({"status": "running"})
    if running_job:
        return {
            "success": False,
            "message": "A bulk fix job is already running",
            "existing_job_id": running_job.get("job_id"),
            "progress": running_job.get("progress", 0)
        }
    
    # Get total users count
    total_users = await db.users.count_documents({})
    
    # Create job record
    await db.bulk_fix_jobs.insert_one({
        "job_id": job_id,
        "status": "pending",
        "total_users": total_users,
        "processed": 0,
        "progress": 0,
        "issues_fixed": 0,
        "prc_refunded": 0,
        "created_at": timestamp,
        "started_at": None,
        "completed_at": None
    })
    
    # Start background task
    background_tasks.add_task(run_bulk_fix_background, job_id)
    
    return {
        "success": True,
        "message": "Bulk fix job started",
        "job_id": job_id,
        "total_users": total_users,
        "estimated_time": f"~{total_users // 50} seconds"
    }


@api_router.get("/admin/bulk-fix-status/{job_id}")
async def get_bulk_fix_status(job_id: str):
    """Get status of a bulk fix job."""
    job = await db.bulk_fix_jobs.find_one({"job_id": job_id}, {"_id": 0})
    if not job:
        raise HTTPException(status_code=404, detail="Job not found")
    
    return {
        "success": True,
        "job": job
    }


@api_router.get("/admin/bulk-fix-latest")
async def get_latest_bulk_fix_job():
    """Get the latest/current bulk fix job."""
    job = await db.bulk_fix_jobs.find_one({}, {"_id": 0}, sort=[("created_at", -1)])
    if not job:
        return {"success": True, "job": None, "message": "No bulk fix jobs found"}
    
    return {
        "success": True,
        "job": job
    }


@api_router.get("/admin/bulk-diagnose-all")
@api_router.post("/admin/bulk-diagnose-all")
async def admin_bulk_diagnose_all_users(
    dry_run: bool = True,
    limit: int = 100
):
    """
    🔧 ADVANCED BULK AUTO-FIX: Diagnose and fix ALL issues for ALL users.
    
    Same as single-user diagnose but for all users:
    1. KYC sync/reset/resubmit
    2. Subscription expired/activation/sync
    3. Failed transactions PRC refund (BBPS, Vouchers, Bank)
    4. PRC balance restoration
    5. Login lockout clear
    6. Mining session reset
    7. Referral code generation
    8. Membership type sync
    9. Gift voucher refunds
    10. VIP payment sync
    
    Query Params:
    - dry_run: If True, only preview (default: True)
    - limit: Max users to process (default: 100, max: 200 to prevent timeout)
    
    ⚠️ SET dry_run=false TO ACTUALLY FIX ISSUES
    """
    
    # Limit to prevent timeout on large databases
    limit = min(limit, 200)
    
    timestamp = datetime.now(timezone.utc).isoformat()
    
    results = {
        "total_users_scanned": 0,
        "users_with_issues": 0,
        "issues_found": 0,
        "issues_fixed": 0,
        "prc_refunded": 0,
        "fixes_by_category": {
            "kyc_sync": 0,
            "kyc_reset": 0,
            "kyc_resubmit": 0,
            "subscription_expired": 0,
            "subscription_activate": 0,
            "subscription_vip_sync": 0,
            "membership_type_fix": 0,
            "prc_refund_bbps": 0,
            "prc_refund_voucher": 0,
            "prc_refund_bank": 0,
            "balance_restore": 0,
            "lockout_clear": 0,
            "mining_reset": 0,
            "referral_code": 0
        },
        "details": [],
        "errors": []
    }
    
    try:
        # Get all users with more fields
        users = await db.users.find(
            {},
            {"uid": 1, "name": 1, "email": 1, "mobile": 1, "kyc_status": 1, "subscription_plan": 1,
             "subscription_expiry": 1,
             "prc_balance": 1, "membership_type": 1, "mining_start_time": 1, "referral_code": 1}
        ).limit(limit).to_list(limit)
        
        results["total_users_scanned"] = len(users)
        
        for user in users:
            uid = user.get("uid")
            user_issues = []
            user_fixes = []
            user_prc_refunded = 0
            
            try:
                # ========== 1. KYC ISSUES ==========
                kyc_status = user.get("kyc_status", "not_submitted")
                kyc_doc = await db.kyc_documents.find_one({"user_id": uid})
                
                # KYC sync mismatch
                if kyc_doc and kyc_doc.get("status") == "verified" and kyc_status != "verified":
                    user_issues.append("KYC sync mismatch")
                    if not dry_run:
                        await db.users.update_one({"uid": uid}, {"$set": {"kyc_status": "verified"}})
                        user_fixes.append("✅ KYC synced")
                        results["fixes_by_category"]["kyc_sync"] += 1
                    results["issues_fixed"] += 1
                
                # Orphaned KYC
                if kyc_status == "pending" and not kyc_doc:
                    user_issues.append("Orphaned KYC status")
                    if not dry_run:
                        await db.users.update_one({"uid": uid}, {"$set": {"kyc_status": "not_submitted"}})
                        user_fixes.append("✅ KYC reset")
                        results["fixes_by_category"]["kyc_reset"] += 1
                    results["issues_fixed"] += 1
                
                # KYC rejected - allow resubmit
                if kyc_status == "rejected":
                    user_issues.append("KYC rejected - needs resubmit")
                    if not dry_run:
                        await db.users.update_one({"uid": uid}, {"$set": {"kyc_status": "not_submitted", "kyc_can_resubmit": True}})
                        user_fixes.append("✅ KYC resubmit allowed")
                        results["fixes_by_category"]["kyc_resubmit"] += 1
                    results["issues_fixed"] += 1
                
                # ========== 2. SUBSCRIPTION ISSUES ==========
                subscription_plan = user.get("subscription_plan", "explorer")
                subscription_expiry = get_user_expiry(user)
                membership_type = user.get("membership_type", "free")
                
                # Expired subscription
                if subscription_expiry and subscription_plan not in ["explorer", "free", "", None]:
                    try:
                        expiry_date = datetime.fromisoformat(subscription_expiry.replace('Z', '+00:00'))
                        if expiry_date < datetime.now(timezone.utc):
                            user_issues.append(f"Expired {subscription_plan} subscription")
                            if not dry_run:
                                await db.users.update_one(
                                    {"uid": uid},
                                    {"$set": {"subscription_plan": "explorer", "membership_type": "free"}}
                                )
                                user_fixes.append("✅ Subscription reset to explorer")
                                results["fixes_by_category"]["subscription_expired"] += 1
                            results["issues_fixed"] += 1
                    except:
                        pass
                
                # Membership type mismatch
                if is_paid_subscriber(user) and membership_type == "free":
                    user_issues.append("Membership type mismatch")
                    if not dry_run:
                        await db.users.update_one({"uid": uid}, {"$set": {"membership_type": "paid"}})
                        user_fixes.append("✅ Membership type fixed")
                        results["fixes_by_category"]["membership_type_fix"] += 1
                    results["issues_fixed"] += 1
                
                # Unactivated Razorpay payment
                if membership_type in ["free", None, ""] or subscription_plan in ["explorer", "free", None, ""]:
                    latest_razorpay = await db.razorpay_orders.find_one(
                        {"user_id": uid, "status": "paid"},
                        sort=[("paid_at", -1)]
                    )
                    if latest_razorpay:
                        user_issues.append(f"Razorpay not activated: {latest_razorpay.get('plan_name')}")
                        if not dry_run:
                            plan_name = latest_razorpay.get("plan_name", "").lower()
                            plan_type = latest_razorpay.get("plan_type", "monthly")
                            new_plan = "elite" if "elite" in plan_name else "growth" if "growth" in plan_name else "startup"
                            days = 365 if plan_type == "yearly" else 30
                            new_expiry = (datetime.now(timezone.utc) + timedelta(days=days)).isoformat()
                            
                            await db.users.update_one(
                                {"uid": uid},
                                {"$set": {
                                    "subscription_plan": new_plan,
                                    "membership_type": "paid",
                                    "subscription_expiry": new_expiry,
                                    "subscription_start": timestamp
                                }}
                            )
                            user_fixes.append(f"✅ Subscription activated: {new_plan}")
                            results["fixes_by_category"]["subscription_activate"] += 1
                        results["issues_fixed"] += 1
                
                # Unactivated VIP payment
                latest_vip = await db.vip_payments.find_one(
                    {"$or": [{"user_uid": uid}, {"user_id": uid}, {"uid": uid}], "status": "approved"},
                    sort=[("approved_at", -1)]
                )
                if latest_vip and is_free_user(user):
                    user_issues.append(f"VIP payment not synced: {latest_vip.get('plan')}")
                    if not dry_run:
                        await db.users.update_one(
                            {"uid": uid},
                            {"$set": {
                                "subscription_plan": latest_vip.get("plan", "startup"),
                                "membership_type": "paid",
                                "subscription_expiry": latest_vip.get("expiry"),
                                "subscription_start": latest_vip.get("approved_at")
                            }}
                        )
                        user_fixes.append(f"✅ VIP synced: {latest_vip.get('plan')}")
                        results["fixes_by_category"]["subscription_vip_sync"] += 1
                    results["issues_fixed"] += 1
                
                # ========== 3. FAILED TRANSACTIONS - BBPS ==========
                failed_bbps = await db.redeem_requests.find({
                    "user_id": uid,
                    "status": {"$in": ["failed", "RETRY_FAILED", "eko_failed", "rejected"]},
                    "prc_refunded": {"$ne": True}
                }).to_list(50)
                
                for ftxn in failed_bbps:
                    prc_amount = ftxn.get("total_prc_deducted") or ftxn.get("prc_amount") or 0
                    if prc_amount > 0:
                        user_issues.append(f"Failed BBPS no refund: {prc_amount} PRC")
                        if not dry_run:
                            current_balance = float(user.get("prc_balance", 0) or 0)
                            new_balance = current_balance + prc_amount
                            
                            await db.users.update_one({"uid": uid}, {"$set": {"prc_balance": new_balance}})
                            await db.redeem_requests.update_one(
                                {"request_id": ftxn.get("request_id")},
                                {"$set": {"prc_refunded": True, "refunded_at": timestamp, "refunded_by": "bulk_fix"}}
                            )
                            await db.transactions.insert_one({
                                "transaction_id": f"BULK-{ftxn.get('request_id', '')[:8]}",
                                "user_id": uid, "type": "bulk_refund", "amount": prc_amount,
                                "description": "Bulk fix refund", "timestamp": timestamp
                            })
                            
                            user_fixes.append(f"✅ Refunded {prc_amount} PRC (BBPS)")
                            user["prc_balance"] = new_balance
                            user_prc_refunded += prc_amount
                            results["fixes_by_category"]["prc_refund_bbps"] += 1
                        results["issues_fixed"] += 1
                
                # ========== 4. FAILED GIFT VOUCHERS ==========
                failed_vouchers = await db.gift_voucher_requests.find({
                    "user_id": uid,
                    "status": {"$in": ["failed", "rejected"]},
                    "prc_refunded": {"$ne": True}
                }).to_list(20)
                
                for fv in failed_vouchers:
                    prc_amount = fv.get("total_prc_deducted") or fv.get("prc_used") or 0
                    if prc_amount > 0:
                        user_issues.append(f"Failed voucher no refund: {prc_amount} PRC")
                        if not dry_run:
                            current_balance = float(user.get("prc_balance", 0) or 0)
                            new_balance = current_balance + prc_amount
                            
                            await db.users.update_one({"uid": uid}, {"$set": {"prc_balance": new_balance}})
                            await db.gift_voucher_requests.update_one(
                                {"request_id": fv.get("request_id")},
                                {"$set": {"prc_refunded": True, "refunded_at": timestamp}}
                            )
                            
                            user_fixes.append(f"✅ Refunded {prc_amount} PRC (Voucher)")
                            user["prc_balance"] = new_balance
                            user_prc_refunded += prc_amount
                            results["fixes_by_category"]["prc_refund_voucher"] += 1
                            
                            await db.transactions.insert_one({
                                "transaction_id": f"BULK-V-{fv.get('request_id', '')[:8]}",
                                "user_id": uid, "type": "bulk_refund", "amount": prc_amount,
                                "description": f"Bulk fix refund (Failed voucher)",
                                "balance_after": new_balance,
                                "timestamp": timestamp
                            })
                        results["issues_fixed"] += 1
                
                # ========== 5. FAILED BANK TRANSFERS ==========
                failed_bank = await db.bank_transfer_requests.find({
                    "user_id": uid,
                    "status": {"$in": ["failed", "rejected"]},
                    "prc_refunded": {"$ne": True}
                }).to_list(20)
                
                for fb in failed_bank:
                    prc_amount = fb.get("total_prc_deducted") or fb.get("prc_amount") or 0
                    if prc_amount > 0:
                        user_issues.append(f"Failed bank transfer no refund: {prc_amount} PRC")
                        if not dry_run:
                            current_balance = float(user.get("prc_balance", 0) or 0)
                            new_balance = current_balance + prc_amount
                            
                            await db.users.update_one({"uid": uid}, {"$set": {"prc_balance": new_balance}})
                            await db.bank_transfer_requests.update_one(
                                {"request_id": fb.get("request_id")},
                                {"$set": {"prc_refunded": True, "refunded_at": timestamp}}
                            )
                            
                            user_fixes.append(f"✅ Refunded {prc_amount} PRC (Bank)")
                            user["prc_balance"] = new_balance
                            user_prc_refunded += prc_amount
                            results["fixes_by_category"]["prc_refund_bank"] += 1
                            
                            await db.transactions.insert_one({
                                "transaction_id": f"BULK-B-{fb.get('request_id', '')[:8]}",
                                "user_id": uid, "type": "bulk_refund", "amount": prc_amount,
                                "description": f"Bulk fix refund (Failed bank transfer)",
                                "balance_after": new_balance,
                                "timestamp": timestamp
                            })
                        results["issues_fixed"] += 1
                
                # ========== 6. PRC BALANCE RESTORATION ==========
                prc_balance = float(user.get("prc_balance", 0) or 0)
                if is_paid_subscriber(user) and prc_balance == 0:
                    restore_log = await db.prc_corrections_log.find_one({"uid": uid}, sort=[("corrected_at", -1)])
                    if restore_log and restore_log.get("before", 0) > 0:
                        user_issues.append(f"Zero balance restorable: {restore_log.get('before')} PRC")
                        if not dry_run:
                            restore_amount = restore_log.get("before", 0)
                            await db.users.update_one({"uid": uid}, {"$set": {"prc_balance": restore_amount}})
                            user_fixes.append(f"✅ Restored {restore_amount} PRC")
                            user["prc_balance"] = restore_amount
                            results["fixes_by_category"]["balance_restore"] += 1
                            
                            await db.transactions.insert_one({
                                "transaction_id": f"BULK-R-{uid[:8]}",
                                "user_id": uid, "type": "admin_bulk_restore", "amount": restore_amount,
                                "description": f"Bulk fix PRC balance restoration",
                                "balance_before": prc_balance,
                                "balance_after": restore_amount,
                                "timestamp": timestamp
                            })
                        results["issues_fixed"] += 1
                
                # ========== 7. LOGIN LOCKOUT ==========
                identifier = user.get("mobile") or user.get("email")
                if identifier:
                    lockout = await db.login_attempts.find_one({"identifier": identifier})
                    if lockout and lockout.get("locked_until"):
                        try:
                            locked_until = datetime.fromisoformat(lockout["locked_until"].replace('Z', '+00:00'))
                            if locked_until > datetime.now(timezone.utc):
                                user_issues.append("Account locked")
                                if not dry_run:
                                    await db.login_attempts.delete_one({"identifier": identifier})
                                    user_fixes.append("✅ Lockout cleared")
                                    results["fixes_by_category"]["lockout_clear"] += 1
                                results["issues_fixed"] += 1
                        except:
                            pass
                
                # ========== 8. STUCK MINING ==========
                mining_start = user.get("mining_start_time")
                if mining_start:
                    try:
                        start_time = datetime.fromisoformat(mining_start.replace('Z', '+00:00'))
                        hours_mining = (datetime.now(timezone.utc) - start_time).total_seconds() / 3600
                        if hours_mining > 12:
                            user_issues.append(f"Mining stuck: {hours_mining:.0f}h")
                            if not dry_run:
                                await db.users.update_one(
                                    {"uid": uid},
                                    {"$set": {"mining_active": False, "mining_start_time": None}}
                                )
                                user_fixes.append("✅ Mining reset")
                                results["fixes_by_category"]["mining_reset"] += 1
                            results["issues_fixed"] += 1
                    except:
                        pass
                
                # ========== 9. REFERRAL CODE ==========
                if not user.get("referral_code"):
                    user_issues.append("Missing referral code")
                    if not dry_run:
                        new_code = ''.join(secrets.choice(string.ascii_uppercase + string.digits) for _ in range(8))
                        await db.users.update_one({"uid": uid}, {"$set": {"referral_code": new_code}})
                        user_fixes.append(f"✅ Referral: {new_code}")
                        results["fixes_by_category"]["referral_code"] += 1
                    results["issues_fixed"] += 1
                
                # Record user if has issues
                if user_issues:
                    results["users_with_issues"] += 1
                    results["issues_found"] += len(user_issues)
                    results["prc_refunded"] += user_prc_refunded
                    results["details"].append({
                        "uid": uid,
                        "name": user.get("name", ""),
                        "email": user.get("email", ""),
                        "issues_count": len(user_issues),
                        "issues": user_issues[:5],  # Limit to 5 issues per user
                        "fixes": user_fixes if not dry_run else [f"Would fix: {i}" for i in user_issues[:5]],
                        "prc_refunded": user_prc_refunded
                    })
                    
            except Exception as user_err:
                results["errors"].append({"uid": uid, "error": str(user_err)})
        
        return {
            "success": True,
            "dry_run": dry_run,
            "timestamp": timestamp,
            "summary": {
                "total_users_scanned": results["total_users_scanned"],
                "users_with_issues": results["users_with_issues"],
                "total_issues_found": results["issues_found"],
                "total_issues_fixed": results["issues_fixed"] if not dry_run else 0,
                "total_prc_refunded": round(results["prc_refunded"], 2),
                "fixes_by_category": results["fixes_by_category"] if not dry_run else {}
            },
            "affected_users": results["details"][:100],
            "errors": results["errors"][:20] if results["errors"] else [],
            "note": "Run with dry_run=false to apply fixes" if dry_run else "All issues fixed successfully! ✅"
        }
        
    except Exception as e:
        logging.error(f"[BULK DIAGNOSE] Error: {e}")
        import traceback
        return {
            "success": False,
            "error": str(e),
            "traceback": traceback.format_exc()
        }
        


@api_router.get("/admin/user/{uid}/diagnose")
@api_router.post("/admin/user/{uid}/diagnose")
async def admin_diagnose_user(uid: str, auto_fix: bool = True):
    """
    🔧 ADVANCED AUTO-DIAGNOSE & FIX for single user.
    
    Checks and Auto-Fixes:
    1. KYC sync issues
    2. Subscription problems
    3. PRC balance discrepancies
    4. Failed transactions without refund
    5. Mining issues
    6. Profile completeness
    7. Referral code generation
    8. Payment activation
    9. Lockout issues
    10. Redeem limit problems
    
    Query Params:
    - auto_fix: If True, automatically fix all fixable issues (default: True)
    """
    user = await db.users.find_one({"uid": uid})
    if not user:
        raise HTTPException(status_code=404, detail="User not found")
    
    timestamp = datetime.now(timezone.utc).isoformat()
    issues = []
    auto_fixed = []
    prc_refunded = 0
    
    # ========== 1. KYC ISSUES ==========
    kyc_status = user.get("kyc_status", "not_submitted")
    kyc_doc = await db.kyc_documents.find_one({"user_id": uid})
    
    # Orphaned KYC (pending but no document)
    if kyc_status == "pending" and not kyc_doc:
        issues.append({
            "category": "KYC",
            "severity": "high",
            "issue": "Orphaned KYC Status",
            "description": "User has 'pending' status but no KYC document exists",
            "can_auto_fix": True,
            "fix_action": "reset_kyc"
        })
        if auto_fix:
            await db.users.update_one({"uid": uid}, {"$set": {"kyc_status": "not_submitted"}})
            auto_fixed.append("✅ KYC reset to 'not_submitted'")
    
    # KYC sync mismatch
    if kyc_doc and kyc_doc.get("status") == "verified" and kyc_status != "verified":
        issues.append({
            "category": "KYC",
            "severity": "high",
            "issue": "KYC Sync Mismatch",
            "description": f"Document is 'verified' but profile shows '{kyc_status}'",
            "can_auto_fix": True,
            "fix_action": "sync_kyc"
        })
        if auto_fix:
            await db.users.update_one({"uid": uid}, {"$set": {"kyc_status": "verified"}})
            auto_fixed.append("✅ KYC synced to 'verified'")
    
    # KYC rejected but user wants to resubmit
    if kyc_status == "rejected":
        issues.append({
            "category": "KYC",
            "severity": "medium",
            "issue": "KYC Rejected",
            "description": "User's KYC was rejected. They may want to resubmit.",
            "can_auto_fix": True,
            "fix_action": "allow_kyc_resubmit"
        })
        if auto_fix:
            await db.users.update_one({"uid": uid}, {"$set": {"kyc_status": "not_submitted", "kyc_can_resubmit": True}})
            auto_fixed.append("✅ User can now resubmit KYC")
    
    # Paid user without KYC
    user_plan = get_user_plan(user)
    if is_paid_subscriber(user) and kyc_status == "not_submitted":
        issues.append({
            "category": "KYC",
            "severity": "medium",
            "issue": "Paid User Without KYC",
            "description": f"User has {user_plan} subscription but hasn't submitted KYC",
            "can_auto_fix": False,
            "fix_action": "notify_user"
        })
    
    # ========== 2. SUBSCRIPTION ISSUES ==========
    subscription_plan = user.get("subscription_plan", "explorer")
    subscription_expiry = get_user_expiry(user)
    membership_type = user.get("membership_type", "free")
    
    # Expired subscription not reset
    if subscription_expiry and subscription_plan not in ["explorer", "free", "", None]:
        try:
            expiry_date = datetime.fromisoformat(subscription_expiry.replace('Z', '+00:00'))
            if expiry_date < datetime.now(timezone.utc):
                issues.append({
                    "category": "Subscription",
                    "severity": "high",
                    "issue": "Expired Subscription Not Reset",
                    "description": f"Expired on {subscription_expiry[:10]} but plan is still '{subscription_plan}'",
                    "can_auto_fix": True,
                    "fix_action": "reset_subscription"
                })
                if auto_fix:
                    await db.users.update_one(
                        {"uid": uid},
                        {"$set": {"subscription_plan": "explorer", "membership_type": "free"}}
                    )
                    auto_fixed.append("✅ Subscription reset to explorer")
        except:
            pass
    
    # Membership type mismatch
    if is_paid_subscriber(user) and membership_type == "free":
        issues.append({
            "category": "Subscription",
            "severity": "medium",
            "issue": "Membership Type Mismatch",
            "description": f"Plan is '{subscription_plan}' but membership_type is 'free'",
            "can_auto_fix": True,
            "fix_action": "fix_membership_type"
        })
        if auto_fix:
            await db.users.update_one({"uid": uid}, {"$set": {"membership_type": "paid"}})
            auto_fixed.append("✅ Membership type fixed to 'paid'")
    
    # Unactivated Razorpay payment
    if membership_type in ["free", None, ""] or subscription_plan in ["explorer", "free", None, ""]:
        latest_razorpay = await db.razorpay_orders.find_one(
            {"user_id": uid, "status": "paid"},
            sort=[("paid_at", -1)]
        )
        if latest_razorpay:
            issues.append({
                "category": "Subscription",
                "severity": "critical",
                "issue": "Razorpay Payment Not Activated",
                "description": f"Plan: {latest_razorpay.get('plan_name')}, Amount: ₹{latest_razorpay.get('amount')}",
                "can_auto_fix": True,
                "fix_action": "activate_razorpay"
            })
            if auto_fix:
                plan_name = latest_razorpay.get("plan_name", "").lower()
                plan_type = latest_razorpay.get("plan_type", "monthly")
                new_plan = "elite" if "elite" in plan_name else "growth" if "growth" in plan_name else "startup"
                days = 365 if plan_type == "yearly" else 30
                new_expiry = (datetime.now(timezone.utc) + timedelta(days=days)).isoformat()
                
                await db.users.update_one(
                    {"uid": uid},
                    {"$set": {
                        "subscription_plan": new_plan,
                        "membership_type": "paid",
                        "subscription_expiry": new_expiry,
                        "subscription_start": timestamp
                    }}
                )
                auto_fixed.append(f"✅ Subscription activated: {new_plan}")
    
    # Unactivated VIP payment
    latest_vip = await db.vip_payments.find_one(
        {"$or": [{"user_uid": uid}, {"user_id": uid}, {"uid": uid}], "status": "approved"},
        sort=[("approved_at", -1)]
    )
    if latest_vip and is_free_user(user):
        issues.append({
            "category": "Subscription",
            "severity": "high",
            "issue": "VIP Payment Not Synced",
            "description": f"Plan: {latest_vip.get('plan')}, Amount: ₹{latest_vip.get('amount')}",
            "can_auto_fix": True,
            "fix_action": "sync_vip_subscription"
        })
        if auto_fix:
            await db.users.update_one(
                {"uid": uid},
                {"$set": {
                    "subscription_plan": latest_vip.get("plan", "startup"),
                    "membership_type": "paid",
                    "subscription_expiry": latest_vip.get("expiry"),
                    "subscription_start": latest_vip.get("approved_at")
                }}
            )
            auto_fixed.append(f"✅ VIP subscription synced: {latest_vip.get('plan')}")
    
    # ========== 3. FAILED TRANSACTIONS WITHOUT REFUND ==========
    failed_txns = await db.redeem_requests.find({
        "user_id": uid,
        "status": {"$in": ["failed", "RETRY_FAILED", "eko_failed", "rejected"]},
        "prc_refunded": {"$ne": True}
    }).to_list(100)
    
    for failed_txn in failed_txns:
        prc_amount = failed_txn.get("total_prc_deducted") or failed_txn.get("prc_amount") or 0
        if prc_amount > 0:
            issues.append({
                "category": "Failed Transaction",
                "severity": "high",
                "issue": f"Failed {failed_txn.get('service_type', 'BBPS')} - No Refund",
                "description": f"Request: {failed_txn.get('request_id', '')[:15]}... | {prc_amount} PRC not refunded",
                "can_auto_fix": True,
                "fix_action": "refund_prc",
                "prc_amount": prc_amount,
                "request_id": failed_txn.get("request_id")
            })
            if auto_fix:
                current_balance = float(user.get("prc_balance", 0) or 0)
                new_balance = current_balance + prc_amount
                
                await db.users.update_one({"uid": uid}, {"$set": {"prc_balance": new_balance}})
                await db.redeem_requests.update_one(
                    {"request_id": failed_txn.get("request_id")},
                    {"$set": {"prc_refunded": True, "refunded_at": timestamp, "refunded_by": "auto_diagnose"}}
                )
                await db.transactions.insert_one({
                    "transaction_id": f"DIAG-REFUND-{failed_txn.get('request_id', '')[:10]}",
                    "user_id": uid,
                    "type": "diagnose_refund",
                    "amount": prc_amount,
                    "description": f"Auto-diagnose refund for failed transaction",
                    "timestamp": timestamp
                })
                
                prc_refunded += prc_amount
                auto_fixed.append(f"✅ Refunded {prc_amount} PRC for failed transaction")
                # Update user object for next calculations
                user["prc_balance"] = new_balance
    
    # Failed Gift Vouchers
    failed_vouchers = await db.gift_voucher_requests.find({
        "user_id": uid,
        "status": {"$in": ["failed", "rejected"]},
        "prc_refunded": {"$ne": True}
    }).to_list(50)
    
    for fv in failed_vouchers:
        prc_amount = fv.get("total_prc_deducted") or fv.get("prc_used") or 0
        if prc_amount > 0:
            issues.append({
                "category": "Failed Transaction",
                "severity": "high",
                "issue": f"Failed Gift Voucher - No Refund",
                "description": f"{fv.get('brand_name', 'Voucher')} | {prc_amount} PRC not refunded",
                "can_auto_fix": True,
                "fix_action": "refund_voucher_prc"
            })
            if auto_fix:
                current_balance = float(user.get("prc_balance", 0) or 0)
                new_balance = current_balance + prc_amount
                
                await db.users.update_one({"uid": uid}, {"$set": {"prc_balance": new_balance}})
                await db.gift_voucher_requests.update_one(
                    {"request_id": fv.get("request_id")},
                    {"$set": {"prc_refunded": True, "refunded_at": timestamp}}
                )
                
                # Record transaction for PRC statement
                await db.transactions.insert_one({
                    "transaction_id": f"DIAG-V-{fv.get('request_id', '')[:8]}",
                    "user_id": uid, "type": "admin_refund", "amount": prc_amount,
                    "description": f"Auto-diagnose refund (Failed voucher)",
                    "balance_before": current_balance, "balance_after": new_balance,
                    "created_at": timestamp
                })
                
                prc_refunded += prc_amount
                auto_fixed.append(f"Refunded {prc_amount} PRC for failed voucher")
                user["prc_balance"] = new_balance
    
    # ========== 4. PRC BALANCE ISSUES ==========
    prc_balance = float(user.get("prc_balance", 0) or 0)
    
    # Zero balance for paid user with mining history
    if is_paid_subscriber(user) and prc_balance == 0:
        total_mined = await db.transactions.aggregate([
            {"$match": {"user_id": uid, "type": {"$in": ["mining", "tap_game"]}}},
            {"$group": {"_id": None, "total": {"$sum": "$amount"}}}
        ]).to_list(1)
        
        if total_mined and total_mined[0].get("total", 0) > 100:
            # Check restoration log
            restore_log = await db.prc_corrections_log.find_one({"uid": uid}, sort=[("corrected_at", -1)])
            if restore_log and restore_log.get("before", 0) > 0:
                issues.append({
                    "category": "PRC Balance",
                    "severity": "critical",
                    "issue": "Zero Balance Bug - Restorable",
                    "description": f"Previous balance: {restore_log.get('before')} PRC available to restore",
                    "can_auto_fix": True,
                    "fix_action": "restore_balance",
                    "restore_amount": restore_log.get("before")
                })
                if auto_fix:
                    restore_amount = restore_log.get("before", 0)
                    await db.users.update_one({"uid": uid}, {"$set": {"prc_balance": restore_amount}})
                    
                    # Record transaction for PRC statement
                    await db.transactions.insert_one({
                        "transaction_id": f"DIAG-R-{uid[:8]}",
                        "user_id": uid, "type": "admin_bulk_restore", "amount": restore_amount - prc_balance,
                        "description": f"Auto-diagnose PRC balance restoration",
                        "balance_before": prc_balance, "balance_after": restore_amount,
                        "created_at": timestamp
                    })
                    
                    auto_fixed.append(f"Restored {restore_amount} PRC from backup")
                    user["prc_balance"] = restore_amount
    
    # ========== 5. LOGIN LOCKOUT ==========
    lockout = await db.login_attempts.find_one({"identifier": user.get("mobile") or user.get("email")})
    if lockout and lockout.get("locked_until"):
        try:
            locked_until = datetime.fromisoformat(lockout["locked_until"].replace('Z', '+00:00'))
            if locked_until > datetime.now(timezone.utc):
                issues.append({
                    "category": "Security",
                    "severity": "medium",
                    "issue": "Account Locked",
                    "description": f"Locked until {lockout['locked_until'][:19]}",
                    "can_auto_fix": True,
                    "fix_action": "clear_lockout"
                })
                if auto_fix:
                    await db.login_attempts.delete_one({"identifier": user.get("mobile") or user.get("email")})
                    auto_fixed.append("✅ Login lockout cleared")
        except:
            pass
    
    # ========== 6. MINING ISSUES ==========
    mining_start = user.get("mining_start_time")
    if mining_start:
        try:
            start_time = datetime.fromisoformat(mining_start.replace('Z', '+00:00'))
            hours_mining = (datetime.now(timezone.utc) - start_time).total_seconds() / 3600
            if hours_mining > 12:
                issues.append({
                    "category": "Mining",
                    "severity": "low",
                    "issue": "Stuck Mining Session",
                    "description": f"Mining for {hours_mining:.1f} hours without claim",
                    "can_auto_fix": True,
                    "fix_action": "reset_mining"
                })
                if auto_fix:
                    await db.users.update_one(
                        {"uid": uid},
                        {"$set": {"mining_active": False, "mining_start_time": None}}
                    )
                    auto_fixed.append("✅ Mining session reset")
        except:
            pass
    
    # ========== 7. REFERRAL CODE ==========
    if not user.get("referral_code"):
        issues.append({
            "category": "Referral",
            "severity": "low",
            "issue": "Missing Referral Code",
            "description": "User has no referral code",
            "can_auto_fix": True,
            "fix_action": "generate_referral_code"
        })
        if auto_fix:
            import secrets, string
            new_code = ''.join(secrets.choice(string.ascii_uppercase + string.digits) for _ in range(8))
            await db.users.update_one({"uid": uid}, {"$set": {"referral_code": new_code}})
            auto_fixed.append(f"✅ Generated referral code: {new_code}")
    
    # ========== 8. PROFILE COMPLETENESS ==========
    if not user.get("name"):
        issues.append({
            "category": "Profile",
            "severity": "low",
            "issue": "Missing Name",
            "description": "User has not set their name",
            "can_auto_fix": False,
            "fix_action": "notify_user"
        })
    
    # ========== SUMMARY ==========
    critical_count = len([i for i in issues if i["severity"] == "critical"])
    high_count = len([i for i in issues if i["severity"] == "high"])
    medium_count = len([i for i in issues if i["severity"] == "medium"])
    low_count = len([i for i in issues if i["severity"] == "low"])
    info_count = len([i for i in issues if i.get("severity") == "info"])
    
    health_score = 100 - (critical_count * 30) - (high_count * 15) - (medium_count * 5) - (low_count * 2)
    health_score = max(0, min(100, health_score))
    
    return {
        "success": True,
        "user_id": uid,
        "user_name": user.get("name", "Unknown"),
        "user_email": user.get("email", ""),
        "health_score": health_score,
        "total_issues": len(issues),
        "issues_fixed": len(auto_fixed),
        "prc_refunded": round(prc_refunded, 2),
        "summary": {
            "critical": critical_count,
            "high": high_count,
            "medium": medium_count,
            "low": low_count,
            "info": info_count
        },
        "issues": sorted(issues, key=lambda x: {"critical": 0, "high": 1, "medium": 2, "low": 3, "info": 4}.get(x.get("severity", "info"), 5)),
        "auto_fixed": auto_fixed,
        "auto_fix_enabled": auto_fix,
        "diagnosis_time": timestamp,
        "new_prc_balance": round(float(user.get("prc_balance", 0) or 0), 2)
    }


@api_router.post("/admin/user/{uid}/fix-issue")
async def admin_fix_user_issue(uid: str, request: Request):
    """
    Fix a specific issue for a user.
    """
    data = await request.json()
    fix_action = data.get("fix_action")
    
    user = await db.users.find_one({"uid": uid})
    if not user:
        raise HTTPException(status_code=404, detail="User not found")
    
    result_message = ""
    
    if fix_action == "reset_kyc":
        await db.users.update_one(
            {"uid": uid},
            {"$set": {"kyc_status": "not_submitted"}}
        )
        result_message = "KYC status reset to 'not_submitted'. User can now re-submit."
    
    elif fix_action == "sync_kyc":
        kyc_doc = await db.kyc_documents.find_one({"user_id": uid})
        if kyc_doc:
            await db.users.update_one(
                {"uid": uid},
                {"$set": {"kyc_status": kyc_doc.get("status", "pending")}}
            )
            result_message = f"KYC status synced to '{kyc_doc.get('status')}'"
        else:
            result_message = "No KYC document found"
    
    elif fix_action == "reset_subscription":
        await db.users.update_one(
            {"uid": uid},
            {"$set": {
                "membership_type": "free",
                "subscription_plan": "explorer",
                "subscription_expiry": None
            }}
        )
        result_message = "Subscription reset to free/explorer"
    
    elif fix_action == "sync_subscription":
        latest_payment = await db.vip_payments.find_one(
            {"$or": [{"user_uid": uid}, {"user_id": uid}], "status": "approved"},
            sort=[("approved_at", -1)]
        )
        if latest_payment:
            await db.users.update_one(
                {"uid": uid},
                {"$set": {
                    "membership_type": latest_payment.get("plan", "vip"),
                    "subscription_plan": latest_payment.get("plan", "vip"),
                    "subscription_expiry": latest_payment.get("expiry")
                }}
            )
            result_message = f"Subscription synced to {latest_payment.get('plan')}"
        else:
            result_message = "No approved payment found"
    
    elif fix_action == "restore_balance":
        suggested_balance = data.get("suggested_balance", 0)
        if suggested_balance > 0:
            await db.users.update_one(
                {"uid": uid},
                {"$set": {"prc_balance": suggested_balance}}
            )
            # Log this action
            await db.transactions.insert_one({
                "user_id": uid,
                "type": "admin_restore",
                "amount": suggested_balance,
                "description": "Balance restored by admin via diagnostics",
                "created_at": datetime.now(timezone.utc).isoformat()
            })
            result_message = f"Balance restored to {suggested_balance} PRC"
        else:
            result_message = "No balance to restore"
    
    elif fix_action == "generate_referral_code":
        import uuid
        new_code = user.get("name", "USER")[:4].upper() + str(uuid.uuid4())[:4].upper()
        await db.users.update_one(
            {"uid": uid},
            {"$set": {"referral_code": new_code}}
        )
        result_message = f"Referral code generated: {new_code}"
    
    elif fix_action == "fix_membership_type":
        # Fix membership_type for paid plan users
        subscription_plan = user.get("subscription_plan", "explorer")
        paid_plans = ["startup", "growth", "elite", "vip", "pro"]
        
        if subscription_plan in paid_plans:
            await db.users.update_one(
                {"uid": uid},
                {"$set": {"membership_type": "vip"}}
            )
            result_message = f"Fixed membership_type to 'vip' for {subscription_plan} plan user"
        else:
            result_message = f"User has {subscription_plan} plan - no fix needed"
    
    elif fix_action == "clear_expired_flag":
        # Clear wrong subscription_expired flag when expiry is still in future
        current_expiry = get_user_expiry(user)
        now = datetime.now(timezone.utc)
        expiry_dt = None
        if current_expiry:
            try:
                if isinstance(current_expiry, str):
                    expiry_dt = datetime.fromisoformat(current_expiry.replace('Z', '+00:00'))
                else:
                    expiry_dt = current_expiry
                if expiry_dt.tzinfo is None:
                    expiry_dt = expiry_dt.replace(tzinfo=timezone.utc)
            except:
                pass
        
        if expiry_dt and expiry_dt > now:
            await db.users.update_one(
                {"uid": uid},
                {"$set": {
                    "subscription_expired": False,
                    "subscription_expired_at": None,
                    "subscription_status": "active"
                }}
            )
            result_message = f"Cleared expired flag. Plan active until {str(expiry_dt)[:10]}"
        else:
            result_message = f"Expiry is in the past ({str(expiry_dt)[:10] if expiry_dt else 'N/A'}) - flag is correct"
    
    elif fix_action == "extend_subscription":
        # Extend subscription expiry by N days (for duplicate payment compensation)
        days = data.get("days", 28)
        current_expiry = get_user_expiry(user)
        if current_expiry:
            try:
                if isinstance(current_expiry, str):
                    expiry_dt = datetime.fromisoformat(current_expiry.replace('Z', '+00:00'))
                else:
                    expiry_dt = current_expiry
                if expiry_dt.tzinfo is None:
                    expiry_dt = expiry_dt.replace(tzinfo=timezone.utc)
                new_expiry = expiry_dt + timedelta(days=days)
                await db.users.update_one(
                    {"uid": uid},
                    {"$set": {
                        "subscription_expiry": new_expiry.isoformat(),
                        "subscription_expired": False,
                        "subscription_status": "active"
                    }}
                )
                result_message = f"Extended by {days} days. Old expiry: {str(expiry_dt)[:10]} → New: {str(new_expiry)[:10]}"
            except Exception as e:
                result_message = f"Failed to extend: {e}"
        else:
            result_message = "No expiry date found to extend"
    
    else:
        result_message = f"Unknown fix action: {fix_action}"
    
    return {
        "success": True,
        "message": result_message,
        "fix_action": fix_action
    }


@api_router.post("/admin/user/{uid}/auto-fix-all")
async def admin_auto_fix_all_issues(uid: str, request: Request):
    """
    Automatically fix ALL issues for a user that can be auto-fixed.
    Runs diagnosis first, then fixes all issues with can_auto_fix=True.
    """
    data = await request.json()
    admin_pin = data.get("admin_pin")
    
    if admin_pin != ADMIN_OPERATION_PIN:
        raise HTTPException(status_code=403, detail="Invalid admin PIN")
    
    user = await db.users.find_one({"uid": uid})
    if not user:
        raise HTTPException(status_code=404, detail="User not found")
    
    fixed_issues = []
    
    # ========== 1. Fix KYC sync issues ==========
    kyc_doc = await db.kyc_documents.find_one({"user_id": uid})
    kyc_status = user.get("kyc_status", "not_submitted")
    
    if kyc_doc and kyc_doc.get("status") == "verified" and kyc_status != "verified":
        await db.users.update_one({"uid": uid}, {"$set": {"kyc_status": "verified"}})
        fixed_issues.append("KYC status synced to 'verified'")
    
    if kyc_status == "pending" and not kyc_doc:
        await db.users.update_one({"uid": uid}, {"$set": {"kyc_status": "not_submitted"}})
        fixed_issues.append("Orphaned KYC status reset")
    
    # ========== 2. Fix expired subscription ==========
    subscription_expiry = get_user_expiry(user)
    subscription_plan = user.get("subscription_plan", "explorer")
    
    if subscription_expiry:
        try:
            if isinstance(subscription_expiry, str):
                expiry_date = datetime.fromisoformat(subscription_expiry.replace('Z', '+00:00'))
            else:
                expiry_date = subscription_expiry
            
            if expiry_date < datetime.now(timezone.utc) and subscription_plan not in ["explorer", "free", ""]:
                await db.users.update_one(
                    {"uid": uid},
                    {"$set": {"membership_type": "free", "subscription_plan": "explorer"}}
                )
                fixed_issues.append(f"Expired subscription ({subscription_plan}) reset to explorer")
        except:
            pass
    
    # ========== 3. Fix membership type mismatch ==========
    paid_plans = ["startup", "growth", "elite", "vip", "pro"]
    if subscription_plan in paid_plans and user.get("membership_type") == "free":
        await db.users.update_one({"uid": uid}, {"$set": {"membership_type": "vip"}})
        fixed_issues.append("Membership type synced to 'vip'")
    
    # ========== 4. Fix subscription not synced from approved payment ==========
    latest_payment = await db.vip_payments.find_one(
        {"uid": uid, "status": "approved"},
        sort=[("approved_at", -1)]
    )
    
    if latest_payment and subscription_plan in ["explorer", "free", ""]:
        plan = latest_payment.get("plan", "startup")
        plan_type = latest_payment.get("plan_type", "monthly")
        approved_at = latest_payment.get("approved_at")
        
        duration_mapping = {"monthly": 28, "quarterly": 84, "half_yearly": 168, "yearly": 336}
        duration_days = duration_mapping.get(plan_type, 28)
        
        if approved_at:
            if isinstance(approved_at, str):
                try:
                    approved_at = datetime.fromisoformat(approved_at.replace('Z', '+00:00'))
                except:
                    approved_at = datetime.now(timezone.utc)
        else:
            approved_at = datetime.now(timezone.utc)
        
        expiry_date = approved_at + timedelta(days=duration_days)
        
        if expiry_date > datetime.now(timezone.utc):
            await db.users.update_one(
                {"uid": uid},
                {
                    "$set": {
                        "subscription_plan": plan,
                        "membership_type": "vip",
                        "subscription_status": "active",
                        "subscription_expiry": expiry_date.isoformat()
                    }
                }
            )
            fixed_issues.append(f"Subscription restored from approved payment: {plan}")
    
    # ========== 4.5. Fix Razorpay subscription not synced ==========
    if subscription_plan in ["explorer", "free", ""] or not subscription_plan:
        razorpay_payment = await db.razorpay_orders.find_one(
            {"user_id": uid, "status": "paid"},
            sort=[("paid_at", -1)]
        )
        
        if razorpay_payment:
            plan = razorpay_payment.get("plan_name", "startup")
            plan_type = razorpay_payment.get("plan_type", "monthly")
            paid_at = razorpay_payment.get("paid_at")
            
            duration_mapping = {"monthly": 28, "quarterly": 84, "half_yearly": 168, "yearly": 336}
            duration_days = duration_mapping.get(plan_type, 28)
            
            if paid_at:
                if isinstance(paid_at, str):
                    try:
                        paid_at = datetime.fromisoformat(paid_at.replace('Z', '+00:00'))
                    except:
                        paid_at = datetime.now(timezone.utc)
            else:
                paid_at = datetime.now(timezone.utc)
            
            expiry_date = paid_at + timedelta(days=duration_days)
            
            if expiry_date > datetime.now(timezone.utc):
                await db.users.update_one(
                    {"uid": uid},
                    {
                        "$set": {
                            "subscription_plan": plan,
                            "subscription_start": paid_at,
                            "subscription_expiry": expiry_date.isoformat(),
                            "membership_type": "vip",
                            "subscription_status": "active"
                        }
                    }
                )
                fixed_issues.append(f"Razorpay subscription restored: {plan} (expires: {expiry_date.date()})")
    
    # ========== 5. Fix PRC balance (recalculate from ALL transactions) ==========
    prc_balance = user.get("prc_balance", 0)
    
    # Credit types (add to balance)
    credit_types = ["mining", "tap_game", "referral", "signup_bonus", "daily_bonus", 
                    "prc_credit", "admin_credit", "adjustment_credit", "bonus", "reward"]
    
    # Debit types (subtract from balance)
    debit_types = ["order", "bill_payment_request", "gift_voucher_request", "prc_burn", 
                   "prc_debit", "adjustment_debit", "deduction", "withdrawal"]
    
    # Calculate credits (positive amounts for credit types OR all positive amounts)
    credit_pipeline = [
        {"$match": {
            "user_id": uid,
            "$or": [
                {"type": {"$in": credit_types}},
                {"type": {"$regex": "credit|bonus|reward", "$options": "i"}},
                {"amount": {"$gt": 0}, "type": {"$nin": debit_types}}
            ]
        }},
        {"$group": {"_id": None, "total": {"$sum": {"$abs": "$amount"}}}}
    ]
    total_credits = await db.transactions.aggregate(credit_pipeline).to_list(1)
    
    # Calculate debits (negative amounts for debit types OR all negative amounts)
    debit_pipeline = [
        {"$match": {
            "user_id": uid,
            "$or": [
                {"type": {"$in": debit_types}},
                {"type": {"$regex": "burn|debit|deduction|order", "$options": "i"}},
                {"amount": {"$lt": 0}}
            ]
        }},
        {"$group": {"_id": None, "total": {"$sum": {"$abs": "$amount"}}}}
    ]
    total_debits = await db.transactions.aggregate(debit_pipeline).to_list(1)
    
    credits = total_credits[0]["total"] if total_credits else 0
    debits = total_debits[0]["total"] if total_debits else 0
    expected_balance = round(credits - debits, 2)
    
    # Fix if balance is significantly different (difference > 10 PRC)
    balance_diff = abs(prc_balance - expected_balance)
    if balance_diff > 10:
        new_balance = max(0, expected_balance)
        await db.users.update_one(
            {"uid": uid},
            {
                "$set": {
                    "prc_balance": new_balance,
                    "prc_balance_recalculated": True,
                    "prc_recalculated_at": datetime.now(timezone.utc).isoformat()
                }
            }
        )
        fixed_issues.append(f"PRC balance corrected: {prc_balance} → {new_balance} (credits: {credits}, debits: {debits})")
    
    # ========== 6. Generate referral code if missing ==========
    if not user.get("referral_code"):
        import secrets
        import string
        new_code = ''.join(secrets.choice(string.ascii_uppercase + string.digits) for _ in range(8))
        await db.users.update_one({"uid": uid}, {"$set": {"referral_code": new_code}})
        fixed_issues.append(f"Generated referral code: {new_code}")
    
    # Log the auto-fix action
    await db.admin_audit_logs.insert_one({
        "action": "auto_fix_user_issues",
        "user_id": uid,
        "user_name": user.get("name"),
        "fixed_issues": fixed_issues,
        "performed_at": datetime.now(timezone.utc).isoformat()
    })
    
    return {
        "success": True,
        "user_id": uid,
        "user_name": user.get("name"),
        "total_fixed": len(fixed_issues),
        "fixed_issues": fixed_issues,
        "message": f"Auto-fixed {len(fixed_issues)} issues" if fixed_issues else "No issues to fix"
    }


@api_router.post("/admin/fix-membership-types")
async def fix_all_membership_types():
    """
    Fix membership_type for ALL users who have paid plans but membership_type = 'free'.
    This is a one-time fix for the PRC reset bug.
    """
    paid_plans = ["startup", "growth", "elite", "vip", "pro"]
    
    # Find all affected users
    affected_users = await db.users.find({
        "subscription_plan": {"$in": paid_plans},
        "membership_type": "free"
    }, {"_id": 0, "uid": 1, "email": 1, "name": 1, "subscription_plan": 1}).to_list(1000)
    
    fixed_count = 0
    fixed_users = []
    
    for user in affected_users:
        result = await db.users.update_one(
            {"uid": user["uid"]},
            {"$set": {"membership_type": "vip"}}
        )
        if result.modified_count > 0:
            fixed_count += 1
            fixed_users.append({
                "uid": user["uid"],
                "email": user.get("email"),
                "name": user.get("name"),
                "plan": user.get("subscription_plan")
            })
    
    return {
        "success": True,
        "message": f"Fixed membership_type for {fixed_count} users",
        "total_affected": len(affected_users),
        "fixed_count": fixed_count,
        "fixed_users": fixed_users[:20]  # Return first 20 for reference
    }



@api_router.get("/admin/prc-affected-users")
async def get_prc_affected_users():
    """
    Find users who may have been affected by the PRC reset bug.
    These are users with:
    - subscription_plan in paid plans (startup, growth, elite)
    - prc_balance = 0
    - But have transaction history showing they earned PRC
    """
    paid_plans = ["startup", "growth", "elite", "vip", "pro"]
    
    # Find paid users with zero balance
    affected_candidates = await db.users.find({
        "subscription_plan": {"$in": paid_plans},
        "prc_balance": 0
    }, {"_id": 0, "uid": 1, "email": 1, "name": 1, "subscription_plan": 1, "prc_balance": 1, "membership_type": 1}).to_list(500)
    
    affected_users = []
    
    for user in affected_candidates:
        uid = user["uid"]
        
        # Calculate expected balance from transactions
        total_credits = await db.transactions.aggregate([
            {"$match": {"user_id": uid, "amount": {"$gt": 0}}},
            {"$group": {"_id": None, "total": {"$sum": "$amount"}}}
        ]).to_list(1)
        
        total_debits = await db.transactions.aggregate([
            {"$match": {"user_id": uid, "amount": {"$lt": 0}}},
            {"$group": {"_id": None, "total": {"$sum": {"$abs": "$amount"}}}}
        ]).to_list(1)
        
        credits = total_credits[0]["total"] if total_credits else 0
        debits = total_debits[0]["total"] if total_debits else 0
        expected_balance = round(credits - debits, 2)
        
        # Only include users who actually had PRC that was lost
        if expected_balance > 0:
            affected_users.append({
                "uid": uid,
                "email": user.get("email"),
                "name": user.get("name"),
                "subscription_plan": user.get("subscription_plan"),
                "membership_type": user.get("membership_type"),
                "current_balance": 0,
                "expected_balance": expected_balance,
                "lost_prc": expected_balance
            })
    
    return {
        "success": True,
        "total_affected": len(affected_users),
        "affected_users": affected_users,
        "message": f"Found {len(affected_users)} users who may have lost PRC due to the bug"
    }


@api_router.post("/admin/restore-prc/{uid}")
async def restore_user_prc(uid: str):
    """
    Restore PRC for a single user based on their transaction history.
    """
    user = await db.users.find_one({"uid": uid})
    if not user:
        raise HTTPException(status_code=404, detail="User not found")
    
    # Calculate expected balance from transactions
    total_credits = await db.transactions.aggregate([
        {"$match": {"user_id": uid, "amount": {"$gt": 0}}},
        {"$group": {"_id": None, "total": {"$sum": "$amount"}}}
    ]).to_list(1)
    
    total_debits = await db.transactions.aggregate([
        {"$match": {"user_id": uid, "amount": {"$lt": 0}}},
        {"$group": {"_id": None, "total": {"$sum": {"$abs": "$amount"}}}}
    ]).to_list(1)
    
    credits = total_credits[0]["total"] if total_credits else 0
    debits = total_debits[0]["total"] if total_debits else 0
    expected_balance = round(credits - debits, 2)
    
    current_balance = user.get("prc_balance", 0)
    
    if expected_balance <= current_balance:
        return {
            "success": False,
            "message": f"No restoration needed. Current: {current_balance} PRC, Expected: {expected_balance} PRC"
        }
    
    # Restore the balance
    await db.users.update_one(
        {"uid": uid},
        {"$set": {"prc_balance": expected_balance}}
    )
    
    # Log the restoration
    await db.transactions.insert_one({
        "user_id": uid,
        "type": "admin_restore",
        "amount": expected_balance - current_balance,
        "balance_before": current_balance,
        "balance_after": expected_balance,
        "description": "PRC restored by admin - fix for balance reset bug",
        "created_at": datetime.now(timezone.utc).isoformat()
    })
    
    return {
        "success": True,
        "user_id": uid,
        "email": user.get("email"),
        "name": user.get("name"),
        "balance_before": current_balance,
        "balance_after": expected_balance,
        "restored_amount": expected_balance - current_balance,
        "message": f"Successfully restored {expected_balance - current_balance} PRC for {user.get('name', user.get('email'))}"
    }


