@api_router.post("/admin/bulk-restore-prc")
async def bulk_restore_prc(request: Request):
    """
    Bulk restore PRC for all affected users.
    Optional: Pass specific user IDs in request body to restore only those.
    """
    data = await request.json() if request.headers.get("content-type") == "application/json" else {}
    specific_uids = data.get("user_ids", [])
    
    paid_plans = ["startup", "growth", "elite", "vip", "pro"]
    
    # Find affected users
    query = {"subscription_plan": {"$in": paid_plans}, "prc_balance": 0}
    if specific_uids:
        query["uid"] = {"$in": specific_uids}
    
    affected_users = await db.users.find(query, {"_id": 0, "uid": 1, "email": 1, "name": 1, "prc_balance": 1}).to_list(500)
    
    restored_users = []
    skipped_users = []
    
    for user in affected_users:
        uid = user["uid"]
        
        # Calculate expected balance
        total_credits = await db.transactions.aggregate([
            {"$match": {"user_id": uid, "amount": {"$gt": 0}}},
            {"$group": {"_id": None, "total": {"$sum": "$amount"}}}
        ]).to_list(1)
        
        total_debits = await db.transactions.aggregate([
            {"$match": {"user_id": uid, "amount": {"$lt": 0}}},
            {"$group": {"_id": None, "total": {"$sum": {"$abs": "$amount"}}}}
        ]).to_list(1)
        
        credits = total_credits[0]["total"] if total_credits else 0
        debits = total_debits[0]["total"] if total_debits else 0
        expected_balance = round(credits - debits, 2)
        
        current_balance = user.get("prc_balance", 0)
        
        if expected_balance <= current_balance or expected_balance <= 0:
            skipped_users.append({
                "uid": uid,
                "email": user.get("email"),
                "reason": "No restoration needed"
            })
            continue
        
        # Restore the balance
        await db.users.update_one(
            {"uid": uid},
            {"$set": {"prc_balance": expected_balance, "membership_type": "vip"}}  # Also fix membership_type
        )
        
        # Log the restoration
        await db.transactions.insert_one({
            "user_id": uid,
            "type": "admin_bulk_restore",
            "amount": expected_balance - current_balance,
            "balance_before": current_balance,
            "balance_after": expected_balance,
            "description": "PRC restored by admin - bulk fix for balance reset bug",
            "created_at": datetime.now(timezone.utc).isoformat()
        })
        
        restored_users.append({
            "uid": uid,
            "email": user.get("email"),
            "name": user.get("name"),
            "restored_amount": expected_balance - current_balance
        })
    
    return {
        "success": True,
        "message": f"Restored PRC for {len(restored_users)} users",
        "total_checked": len(affected_users),
        "restored_count": len(restored_users),
        "skipped_count": len(skipped_users),
        "restored_users": restored_users[:20],  # Return first 20
        "skipped_users": skipped_users[:10]  # Return first 10
    }


@api_router.post("/admin/user-360/action")
async def user_360_quick_action(request: Request):
    """
    Perform quick admin actions on a user from the 360° view.
    Actions: pause_mining, resume_mining, adjust_balance, set_cap, reset_password, send_notification, block_user, unblock_user, save_notes
    """
    data = await request.json()
    user_id = data.get("user_id")
    action = data.get("action")
    admin_id = data.get("admin_id")
    
    if not user_id or not action:
        raise HTTPException(status_code=400, detail="user_id and action are required")
    
    # Get user
    user = await db.users.find_one({"uid": user_id})
    if not user:
        raise HTTPException(status_code=404, detail="User not found")
    
    now = datetime.now(timezone.utc)
    result_message = ""
    
    if action == "pause_mining":
        await db.users.update_one(
            {"uid": user_id},
            {"$set": {"mining_active": False, "updated_at": now.isoformat()}}
        )
        result_message = "Mining paused for user"
        
    elif action == "resume_mining":
        await db.users.update_one(
            {"uid": user_id},
            {"$set": {"mining_active": True, "updated_at": now.isoformat()}}
        )
        result_message = "Mining resumed for user"
        
    elif action == "adjust_balance":
        amount = data.get("amount", 0)
        if amount == 0:
            raise HTTPException(status_code=400, detail="Amount cannot be zero")
        
        current_balance = user.get("prc_balance", 0)
        new_balance = current_balance + amount
        
        if new_balance < 0:
            new_balance = 0
        
        await db.users.update_one(
            {"uid": user_id},
            {"$set": {"prc_balance": new_balance, "updated_at": now.isoformat()}}
        )
        
        # Log the adjustment
        await db.transactions.insert_one({
            "transaction_id": f"TXN-{now.strftime('%Y%m%d')}-{str(uuid.uuid4())[:8].upper()}",
            "user_id": user_id,
            "wallet_type": "prc",
            "type": "admin_credit" if amount > 0 else "admin_debit",
            "amount": amount,
            "balance_before": current_balance,
            "balance_after": new_balance,
            "description": f"Admin adjustment: {'+' if amount > 0 else ''}{amount} PRC",
            "status": "completed",
            "created_at": now.isoformat(),
            "metadata": {"adjusted_by": admin_id}
        })
        
        result_message = f"Balance adjusted by {amount} PRC. New balance: {new_balance} PRC"
        
    elif action in ("add_prc", "deduct_prc"):
        amount = float(data.get("value", 0))
        if amount <= 0:
            raise HTTPException(status_code=400, detail="Amount must be positive")
        
        current_balance = float(user.get("prc_balance", 0) or 0)
        
        if action == "deduct_prc":
            if current_balance < amount:
                raise HTTPException(status_code=400, detail=f"Insufficient balance. Current: {current_balance} PRC")
            new_balance = current_balance - amount
            txn_type = "admin_debit"
            txn_amount = -amount
        else:
            new_balance = current_balance + amount
            txn_type = "admin_credit"
            txn_amount = amount
        
        await db.users.update_one(
            {"uid": user_id},
            {"$set": {"prc_balance": new_balance, "updated_at": now.isoformat()}}
        )
        
        await db.transactions.insert_one({
            "transaction_id": f"TXN-{now.strftime('%Y%m%d')}-{str(uuid.uuid4())[:8].upper()}",
            "user_id": user_id,
            "type": txn_type,
            "amount": txn_amount,
            "balance_before": current_balance,
            "balance_after": new_balance,
            "description": data.get("reason") or f"Admin {'credit' if action == 'add_prc' else 'debit'}",
            "admin_id": admin_id,
            "created_at": now.isoformat()
        })
        
        result_message = f"{'Added' if action == 'add_prc' else 'Deducted'} {amount} PRC. New balance: {new_balance} PRC"
    
    elif action == "set_cap":
        cap = data.get("cap", 0)
        await db.users.update_one(
            {"uid": user_id},
            {"$set": {"daily_prc_cap": cap, "updated_at": now.isoformat()}}
        )
        result_message = f"Daily PRC cap set to {cap}" if cap > 0 else "Daily PRC cap removed (unlimited)"
        
    elif action == "reset_password":
        # Admin can set a temporary password directly
        # For PIN-migrated users, this also resets their PIN
        temp_password = data.get("temp_password", "")
        if not temp_password:
            # Generate a random temporary password
            temp_password = f"Temp{uuid.uuid4().hex[:6].upper()}"
        
        # Hash the temporary password using pwd_context
        hashed_password = pwd_context.hash(temp_password)
        
        # Check if user is PIN-migrated
        is_pin_user = user.get("pin_migrated", False)
        
        update_fields = {
            "password": hashed_password,
            "password_hash": hashed_password,
            "password_reset_required": True,
            "password_reset_at": now.isoformat(),
            "password_reset_by": admin_id,
            "failed_login_attempts": 0,
            "locked_until": None,
            "updated_at": now.isoformat()
        }
        
        # If PIN user, also update PIN hash (password and PIN should be same for consistency)
        if is_pin_user:
            update_fields["pin_hash"] = hashed_password
            update_fields["failed_pin_attempts"] = 0
            update_fields["pin_locked_until"] = None
        
        await db.users.update_one(
            {"uid": user_id},
            {"$set": update_fields}
        )
        
        if is_pin_user:
            result_message = f"Password & PIN reset successful. Temporary credential: {temp_password}. User should use this as their new PIN."
        else:
            result_message = f"Password reset successful. Temporary password: {temp_password}"
    
    elif action == "reset_pin":
        # Admin can reset user's 6-digit PIN
        # This also updates password fields for consistency
        temp_pin = data.get("temp_pin", "")
        if not temp_pin:
            # Generate a random 6-digit PIN
            import secrets
            temp_pin = str(secrets.randbelow(900000) + 100000)
        
        # Validate PIN is 6 digits
        if not temp_pin.isdigit() or len(temp_pin) != 6:
            raise HTTPException(status_code=400, detail="PIN must be exactly 6 digits")
        
        # Hash the PIN using pwd_context
        hashed_pin = pwd_context.hash(temp_pin)
        
        # Update ALL credential fields for consistency
        await db.users.update_one(
            {"uid": user_id},
            {"$set": {
                "pin_hash": hashed_pin,
                "password": hashed_pin,           # Keep in sync
                "password_hash": hashed_pin,      # Keep in sync
                "pin_migrated": True,             # Ensure marked as PIN user
                "pin_reset_required": True,
                "pin_reset_at": now.isoformat(),
                "pin_reset_by": admin_id,
                "failed_pin_attempts": 0,
                "pin_locked_until": None,
                "failed_login_attempts": 0,       # Clear password lockout too
                "locked_until": None,
                "updated_at": now.isoformat()
            }}
        )
        result_message = f"PIN reset successful. New temporary PIN: {temp_pin}"
        # Feb 2026 fix: Frontend Admin User 360 modal reads `new_pin` from the
        # response body to display the freshly generated PIN. Return it in the
        # response so the modal can lock onto the value before closing.
        _generated_pin_to_return = temp_pin
    
    elif action == "update_user_details":
        # Admin can update user profile details
        updates = data.get("updates", {})
        if not updates:
            raise HTTPException(status_code=400, detail="No updates provided")
        
        # Define allowed fields that admin can update
        allowed_fields = {
            "name", "email", "mobile", "address", "city", "state", "pincode",
            "pan_number", "aadhaar_number", "bank_name", "bank_account_number",
            "bank_ifsc", "upi_id", "date_of_birth", "gender", "alternate_mobile",
            "nominee_name", "nominee_relation", "nominee_mobile"
        }
        
        # Filter only allowed fields
        filtered_updates = {}
        for key, value in updates.items():
            if key in allowed_fields:
                # Validate specific fields
                if key == "email" and value:
                    # Check if email already exists for another user
                    existing = await db.users.find_one({"email": value, "uid": {"$ne": user_id}})
                    if existing:
                        raise HTTPException(status_code=400, detail=f"Email '{value}' already registered to another user")
                
                if key == "mobile" and value:
                    # Check if mobile already exists for another user
                    existing = await db.users.find_one({"mobile": value, "uid": {"$ne": user_id}})
                    if existing:
                        raise HTTPException(status_code=400, detail=f"Mobile '{value}' already registered to another user")
                
                if key == "pan_number" and value:
                    # Basic PAN validation (10 chars, format AAAAA0000A)
                    import re
                    if not re.match(r'^[A-Z]{5}[0-9]{4}[A-Z]$', value.upper()):
                        raise HTTPException(status_code=400, detail="Invalid PAN format. Should be like ABCDE1234F")
                    value = value.upper()
                
                if key == "aadhaar_number" and value:
                    # Aadhaar is 12 digits
                    clean_aadhaar = re.sub(r'\s|-', '', str(value))
                    if not clean_aadhaar.isdigit() or len(clean_aadhaar) != 12:
                        raise HTTPException(status_code=400, detail="Invalid Aadhaar. Should be 12 digits")
                    value = clean_aadhaar
                
                filtered_updates[key] = value
        
        if not filtered_updates:
            raise HTTPException(status_code=400, detail="No valid fields to update")
        
        # Add audit trail
        filtered_updates["updated_at"] = now.isoformat()
        filtered_updates["last_updated_by"] = admin_id
        
        await db.users.update_one(
            {"uid": user_id},
            {"$set": filtered_updates}
        )
        
        # Clear user cache after update
        await cache.delete(f"user_data:{user_id}")
        
        updated_fields = ", ".join(filtered_updates.keys())
        result_message = f"User details updated: {updated_fields}"
        
    elif action == "send_notification":
        message = data.get("message", "")
        if not message:
            raise HTTPException(status_code=400, detail="Notification message is required")
        
        await db.notifications.insert_one({
            "notification_id": str(uuid.uuid4()),
            "user_id": user_id,
            "type": "admin",
            "title": "Admin Message",
            "message": message,
            "is_read": False,
            "created_at": now.isoformat()
        })
        result_message = "Notification sent to user"
    
    elif action == "clear_lockout":
        # Clear login attempts lockout
        user_email = user.get("email", "")
        user_mobile = user.get("mobile", "") or user.get("mobile_number", "")
        
        # Delete from login_attempts collection
        delete_result = await db.login_attempts.delete_many({
            "$or": [
                {"identifier": user_email},
                {"identifier": user_mobile},
                {"identifier": user_id}
            ]
        })
        
        # Also clear any user-level lock flags in database
        await db.users.update_one(
            {"uid": user_id},
            {
                "$set": {
                    "failed_login_attempts": 0,
                    "locked_until": None,
                    "failed_pin_attempts": 0,
                    "pin_locked_until": None,
                    "updated_at": now.isoformat()
                }
            }
        )
        
        # CRITICAL: Also clear in-memory lockout storage
        identifiers_to_clear = [user_email, user_mobile, user_id]
        for ident in identifiers_to_clear:
            if ident:
                key = f"login:{ident}"
                if key in login_attempt_storage:
                    login_attempt_storage[key] = {"count": 0, "reset_time": time.time() + RATE_LIMIT_WINDOW_SECONDS, "locked_until": 0, "lockout_level": 0}
        
        result_message = f"Lockout cleared. {delete_result.deleted_count} attempt records removed. User can login now."
        
    elif action == "block_user":
        await db.users.update_one(
            {"uid": user_id},
            {"$set": {
                "is_active": False,
                "is_blocked": True,
                "is_banned": True,  # Auth middleware checks this field (line ~1403) — must be set for login to be blocked
                "banned_at": now.isoformat(),
                "banned_by": admin_id,
                "blocked_at": now.isoformat(),
                "blocked_by": admin_id,
                "updated_at": now.isoformat()
            }}
        )
        # Invalidate session so blocked user can't continue an active session
        try:
            await db.users.update_one(
                {"uid": user_id},
                {"$unset": {"session_token": "", "refresh_token": ""}}
            )
        except Exception:
            pass
        # Clear any caches
        try:
            if cache:
                await cache.delete(f"user_data:{user_id}")
                await cache.delete(f"user:dashboard:{user_id}")
        except Exception:
            pass
        result_message = "User has been blocked"
    
    elif action == "unblock_user":
        await db.users.update_one(
            {"uid": user_id},
            {"$set": {
                "is_active": True,
                "is_blocked": False,
                "is_banned": False,  # Must clear so auth middleware allows login again
                "unblocked_at": now.isoformat(),
                "unblocked_by": admin_id,
                "updated_at": now.isoformat()
            }}
        )
        try:
            if cache:
                await cache.delete(f"user_data:{user_id}")
                await cache.delete(f"user:dashboard:{user_id}")
        except Exception:
            pass
        result_message = "User has been unblocked"
        
    elif action == "save_notes":
        notes = data.get("notes", "")
        await db.users.update_one(
            {"uid": user_id},
            {"$set": {"admin_notes": notes, "updated_at": now.isoformat()}}
        )
        result_message = "Admin notes saved"
    
    elif action == "update_subscription":
        # Admin can update user subscription plan
        plan = data.get("plan", "explorer")
        expiry_date = data.get("expiry_date", "")
        is_free = data.get("is_free", True)
        admin_notes = data.get("admin_notes", "")
        
        if not expiry_date:
            raise HTTPException(status_code=400, detail="Expiry date is required")
        
        # Validate plan
        valid_plans = ["explorer", "startup", "growth", "elite"]
        if plan.lower() not in valid_plans:
            raise HTTPException(status_code=400, detail=f"Invalid plan. Must be one of: {', '.join(valid_plans)}")
        
        plan = plan.lower()
        
        # Convert expiry date
        try:
            expiry_dt = datetime.fromisoformat(expiry_date.replace('Z', '+00:00')) if 'T' in expiry_date else datetime.strptime(expiry_date, "%Y-%m-%d")
            expiry_dt = expiry_dt.replace(hour=23, minute=59, second=59)
        except:
            raise HTTPException(status_code=400, detail="Invalid expiry date format")
        
        # Update user subscription
        old_plan = user.get("subscription_plan", "explorer")
        old_expiry = user.get("subscription_expiry") or user.get("membership_expiry")
        
        await db.users.update_one(
            {"uid": user_id},
            {"$set": {
                "subscription_plan": plan,
                "membership_type": plan,
                "subscription_expiry": expiry_dt.isoformat(),
                "membership_expiry": expiry_dt.isoformat(),
                "subscription_updated_at": now.isoformat(),
                "subscription_updated_by": admin_id,
                "updated_at": now.isoformat()
            }}
        )
        
        # Create subscription record
        subscription_record = {
            "subscription_id": str(uuid.uuid4()),
            "user_id": user_id,
            "plan": plan,
            "subscription_plan": plan,
            "start_date": now.isoformat(),
            "end_date": expiry_dt.isoformat(),
            "expiry": expiry_dt.isoformat(),
            "status": "active",
            "is_free": is_free,
            "payment_status": "free" if is_free else "paid",
            "admin_notes": admin_notes,
            "created_by": admin_id,
            "created_at": now.isoformat(),
            "previous_plan": old_plan,
            "previous_expiry": old_expiry
        }
        await db.subscriptions.insert_one(subscription_record)
        
        # Log the change
        await db.admin_audit_logs.insert_one({
            "log_id": str(uuid.uuid4()),
            "admin_id": admin_id,
            "action": "subscription_update",
            "target_user_id": user_id,
            "details": {
                "old_plan": old_plan,
                "new_plan": plan,
                "expiry": expiry_dt.isoformat(),
                "is_free": is_free,
                "notes": admin_notes
            },
            "timestamp": now.isoformat()
        })
        
        result_message = f"Subscription updated to {plan.capitalize()} plan. Expires: {expiry_date}"
        
        # Assign subscription position for mining network
        if plan in ["elite", "startup", "growth"]:
            try:
                await assign_subscription_position(user_id)
            except Exception as pos_err:
                logging.warning(f"[ADMIN-SUB] Sub position error: {pos_err}")
    
    elif action == "approve_kyc":
        # Admin approves user KYC directly
        current_kyc = user.get("kyc_status", "pending")
        if current_kyc == "verified":
            result_message = "KYC already verified"
        else:
            await db.users.update_one(
                {"uid": user_id},
                {"$set": {
                    "kyc_status": "verified",
                    "kyc_approved_at": now.isoformat(),
                    "kyc_approved_by": admin_id,
                    "updated_at": now.isoformat()
                }}
            )
            # Send notification to user
            await db.notifications.insert_one({
                "notification_id": str(uuid.uuid4()),
                "user_id": user_id,
                "type": "kyc_approved",
                "title": "✅ KYC Verified Successfully!",
                "message": "Congratulations! Your KYC verification is complete. You can now access all features and make withdrawals.",
                "icon": "✅",
                "is_read": False,
                "created_at": now.isoformat()
            })
            result_message = "KYC approved successfully"
    
    elif action == "reject_kyc":
        # Admin rejects user KYC
        reason = data.get("reason", "Documents not valid or incomplete")
        current_kyc = user.get("kyc_status", "pending")
        if current_kyc == "rejected":
            result_message = "KYC already rejected"
        else:
            await db.users.update_one(
                {"uid": user_id},
                {"$set": {
                    "kyc_status": "rejected",
                    "kyc_rejection_reason": reason,
                    "kyc_rejected_at": now.isoformat(),
                    "kyc_rejected_by": admin_id,
                    "updated_at": now.isoformat()
                }}
            )
            # Send notification to user
            await db.notifications.insert_one({
                "notification_id": str(uuid.uuid4()),
                "user_id": user_id,
                "type": "kyc_rejected",
                "title": "❌ KYC Verification Failed",
                "message": f"Your KYC verification was rejected. Reason: {reason}. Please re-submit with correct documents.",
                "icon": "❌",
                "is_read": False,
                "created_at": now.isoformat()
            })
            result_message = f"KYC rejected. Reason: {reason}"
        
    else:
        raise HTTPException(status_code=400, detail=f"Unknown action: {action}")
    
    # Log admin action
    await db.admin_audit_logs.insert_one({
        "log_id": str(uuid.uuid4()),
        "admin_id": admin_id,
        "action": f"user_360_{action}",
        "target_user_id": user_id,
        "details": data,
        "timestamp": now.isoformat()
    })
    
    response = {"success": True, "message": result_message}
    # Feb 2026: Admin User 360 reset_pin flow — include the generated PIN so
    # the frontend modal can display it. Only present when action was reset_pin.
    if action == "reset_pin":
        try:
            response["new_pin"] = _generated_pin_to_return
        except NameError:
            pass  # branch didn't execute (shouldn't happen — defensive)
    return response


