@api_router.post("/vip/payment/submit")
async def submit_vip_payment_new(request: Request):
    """Submit VIP payment proof - new endpoint for VIPMembership page"""
    data = await request.json()
    
    # Validate required fields
    uid = data.get("uid")
    if not uid:
        raise HTTPException(status_code=400, detail="User ID is required")
    
    utr_number = data.get("utr_number")
    if not utr_number:
        raise HTTPException(status_code=400, detail="UTR / Transaction ID is required")
    
    screenshot_url = data.get("screenshot_url")
    if not screenshot_url:
        raise HTTPException(status_code=400, detail="Payment screenshot is required")
    
    # Get user info
    user = await db.users.find_one({"uid": uid}, {"_id": 0})
    if not user:
        raise HTTPException(status_code=404, detail="User not found")
    
    # Check if user already has pending payment
    existing = await db.vip_payments.find_one({
        "user_id": uid,
        "status": "pending"
    })
    
    if existing:
        raise HTTPException(status_code=400, detail="You already have a pending payment request. Please wait for admin verification.")
    
    # Get plan details
    plan_type = data.get("plan_type", "monthly")
    amount = float(data.get("amount", 299))
    
    # Duration mapping based on plan type (28 days per month)
    plan_details = {
        "monthly": {"days": 28, "name": "Monthly VIP"},
        "quarterly": {"days": 84, "name": "Quarterly VIP"},
        "half_yearly": {"days": 168, "name": "Half-Yearly VIP"},
        "yearly": {"days": 336, "name": "Yearly VIP"}
    }
    
    plan_info = plan_details.get(plan_type, plan_details["monthly"])
    
    # Create payment record
    payment_id = str(uuid.uuid4())
    now = datetime.now(timezone.utc)
    
    payment_record = {
        "payment_id": payment_id,
        "user_id": uid,
        "user_email": user.get("email", ""),
        "user_name": user.get("name", ""),
        "user_phone": user.get("phone", user.get("mobile", "")),
        "amount": amount,
        "plan_type": plan_type,
        "plan_name": plan_info["name"],
        "duration_days": plan_info["days"],
        "utr_number": utr_number,
        "screenshot_url": screenshot_url,
        "payment_date": data.get("payment_date", now.strftime("%Y-%m-%d")),
        "payment_time": data.get("payment_time", now.strftime("%H:%M")),
        "payment_method": data.get("payment_method", "UPI"),
        "status": "pending",
        "created_at": now,
        "updated_at": now
    }
    
    await db.vip_payments.insert_one(payment_record)
    
    # Create notification for admin
    await db.notifications.insert_one({
        "notification_id": str(uuid.uuid4()),
        "user_id": "admin",
        "type": "vip_payment_request",
        "title": "New VIP Payment Request",
        "message": f"New VIP payment request from {user.get('name', user.get('email', 'User'))} for {plan_info['name']} (₹{amount})",
        "read": False,
        "created_at": now
    })
    
    return {
        "message": "Payment submitted successfully! Admin will verify your payment within 24 hours.",
        "payment_id": payment_id,
        "status": "pending"
    }

@api_router.post("/membership/submit-payment")
async def submit_vip_payment(request: Request):
    """Submit VIP payment proof"""
    data = await request.json()
    
    # Validate required fields
    required_fields = ["user_id", "amount", "date", "time", "utr_number"]
    for field in required_fields:
        if not data.get(field):
            raise HTTPException(status_code=400, detail=f"{field} is required")
    
    # Get plan type and validate amount
    plan_type = data.get("plan_type", "monthly")
    
    # Duration mapping based on plan type (1 month = 28 days)
    plan_details = {
        "monthly": {"days": 28, "price": 299},
        "quarterly": {"days": 84, "price": 897},
        "half_yearly": {"days": 168, "price": 1794},
        "yearly": {"days": 336, "price": 3588}
    }
    
    if plan_type not in plan_details:
        plan_type = "monthly"
    
    expected_price = plan_details[plan_type]["price"]
    duration_days = plan_details[plan_type]["days"]
    
    # Check if user already has pending payment
    existing = await db.vip_payments.find_one({
        "user_id": data["user_id"],
        "status": "pending"
    })
    
    if existing:
        raise HTTPException(status_code=400, detail="You already have a pending payment request")
    
    # Create payment record with plan details
    payment_id = str(uuid.uuid4())
    now = datetime.now(timezone.utc)
    
    # Plan name mapping
    plan_names = {
        "monthly": "Monthly VIP Plan",
        "quarterly": "Quarterly VIP Plan", 
        "half_yearly": "Half-Yearly VIP Plan",
        "yearly": "Yearly VIP Plan"
    }
    
    payment_record = {
        "payment_id": payment_id,
        "user_id": data["user_id"],
        "amount": float(data["amount"]),
        "plan_type": plan_type,
        "plan_name": plan_names.get(plan_type, "VIP Membership"),
        "duration_days": duration_days,
        "date": data["date"],
        "time": data["time"],
        "utr_number": data["utr_number"],
        "screenshot_url": data.get("screenshot_url", ""),
        "payment_method": data.get("payment_method", "UPI"),
        "status": "pending",
        "submitted_at": now.isoformat(),
        "created_at": now.isoformat(),
        "approved_at": None,
        "approved_by": None,
        "admin_notes": None,
        "validity_start": None,
        "validity_end": None,
        "auto_renew": data.get("auto_renew", False),
        "next_renewal_date": None,
        "invoice_number": f"INV-{now.strftime('%Y%m%d')}-{payment_id[:8].upper()}"
    }
    
    await db.vip_payments.insert_one(payment_record)
    
    return {
        "message": f"Payment submitted successfully for {plan_type} plan ({duration_days} days). Please wait for admin approval.",
        "payment_id": payment_id,
        "status": "pending",
        "plan_type": plan_type,
        "duration_days": duration_days
    }

@api_router.get("/membership/payments")
async def get_vip_payments(
    status: Optional[str] = None,
    page: int = 1,
    limit: int = 50,
):
    """Get VIP payment requests (Admin) — paginated.

    Query: status?, page (1-based), limit (max 100).
    Returns: {payments, total, page, limit, total_pages}
    """
    # Clamp inputs
    page = max(1, page)
    limit = max(1, min(100, limit))
    skip = (page - 1) * limit

    query = {}
    if status:
        query["status"] = status

    total = await db.vip_payments.count_documents(query)
    payments = await db.vip_payments.find(
        query,
        {"_id": 0},  # SECURITY: exclude raw Mongo _id
    ).sort("submitted_at", -1).skip(skip).limit(limit).to_list(length=limit)

    return {
        "payments": payments,
        "total": total,
        "page": page,
        "limit": limit,
        "total_pages": (total + limit - 1) // limit if limit else 0,
    }

@api_router.get("/membership/payment/{user_id}")
async def get_user_payment_status(user_id: str):
    """Get user's VIP payment status"""
    payment = await db.vip_payments.find_one(
        {"user_id": user_id},
        sort=[("submitted_at", -1)]
    )
    
    if payment:
        payment["_id"] = str(payment["_id"])
        return payment
    
    return {"status": "none", "message": "No payment submitted"}

@api_router.post("/membership/payment/{payment_id}/action")
async def handle_payment_action(payment_id: str, request: Request):
    """Approve or reject VIP payment (Admin)"""
    data = await request.json()
    action = data.get("action")  # "approve" or "reject"
    
    if action not in ["approve", "reject"]:
        raise HTTPException(status_code=400, detail="Invalid action")
    
    # Find payment
    payment = await db.vip_payments.find_one({"payment_id": payment_id})
    if not payment:
        raise HTTPException(status_code=404, detail="Payment not found")
    
    if payment["status"] != "pending":
        raise HTTPException(status_code=400, detail="Payment already processed")
    
    now = datetime.now(timezone.utc)
    admin_notes = data.get("admin_notes", "")
    
    if action == "approve":
        # Get plan type from payment - IMPORTANT: default to "monthly" NOT "yearly"
        plan_type = payment.get("plan_type", "monthly")
        
        # Duration mapping based on plan type (28 days per month)
        duration_mapping = {
            "monthly": 28,
            "quarterly": 84,
            "half_yearly": 168,
            "yearly": 336
        }
        
        # Get duration days from payment record first, then from mapping
        # CRITICAL: Always use the correct duration based on what user paid for
        duration_days = payment.get("duration_days")
        if duration_days is None:
            duration_days = duration_mapping.get(plan_type, 28)  # Default to 28 days (monthly)
        
        # Validate duration_days is a valid number
        try:
            duration_days = int(duration_days)
        except (TypeError, ValueError):
            duration_days = duration_mapping.get(plan_type, 28)
        
        # Calculate validity dates
        validity_start = now
        validity_end = now + timedelta(days=duration_days)
        
        # Calculate next renewal date (same as validity end for now)
        next_renewal = validity_end
        
        # Update payment status with all details
        await db.vip_payments.update_one(
            {"payment_id": payment_id},
            {"$set": {
                "status": "approved",
                "approved_at": now.isoformat(),
                "admin_notes": admin_notes or "Payment verified and approved",
                "validity_start": validity_start.isoformat(),
                "validity_end": validity_end.isoformat(),
                "next_renewal_date": next_renewal.isoformat()
            }}
        )
        
        # Update user membership
        await db.users.update_one(
            {"uid": payment["user_id"]},
            {"$set": {
                "membership_type": "vip",
                "membership_expiry": validity_end.isoformat(),
                "vip_plan_type": plan_type,
                "vip_start_date": validity_start.isoformat(),
                "auto_renew": payment.get("auto_renew", False),
                "updated_at": now.isoformat()
            }}
        )
        
        return {
            "message": f"Payment approved. User upgraded to VIP ({plan_type} plan - {duration_days} days).",
            "membership_expiry": validity_end.isoformat(),
            "validity_start": validity_start.isoformat(),
            "validity_end": validity_end.isoformat(),
            "plan_type": plan_type,
            "duration_days": duration_days
        }
    else:
        # Reject payment with admin notes
        await db.vip_payments.update_one(
            {"payment_id": payment_id},
            {"$set": {
                "status": "rejected",
                "rejected_at": now.isoformat(),
                "admin_notes": admin_notes or "Payment rejected"
            }}
        )
        
        return {"message": "Payment rejected", "admin_notes": admin_notes}

