# ========== FINANCIAL REPORTS & ANALYTICS ==========

async def get_revenue_report(
    start_date: Optional[str] = None,
    end_date: Optional[str] = None
):
    """Get revenue report with date filtering (Admin)"""
    query = {"status": "delivered"}
    
    if start_date:
        query["delivered_at"] = {"$gte": start_date}
    if end_date:
        if "delivered_at" not in query:
            query["delivered_at"] = {}
        query["delivered_at"]["$lte"] = end_date
    
    # Total revenue
    revenue_pipeline = [
        {"$match": query},
        {"$group": {
            "_id": None,
            "total_revenue": {"$sum": "$total_cash"},
            "prc_spent": {"$sum": "$total_prc"},
            "delivery_charges": {"$sum": "$delivery_charge"},
            "total_orders": {"$sum": 1}
        }}
    ]
    
    revenue_result = await db.orders.aggregate(revenue_pipeline).to_list(1)
    revenue_data = revenue_result[0] if revenue_result else {
        "total_revenue": 0,
        "prc_spent": 0,
        "delivery_charges": 0,
        "total_orders": 0
    }
    
    # Top products by revenue
    product_pipeline = [
        {"$match": query},
        {"$unwind": "$items"},
        {"$group": {
            "_id": "$items.product_id",
            "product_name": {"$first": "$items.product_name"},
            "total_quantity": {"$sum": "$items.quantity"},
            "total_revenue": {"$sum": {"$multiply": ["$items.quantity", "$items.cash_price"]}}
        }},
        {"$sort": {"total_revenue": -1}},
        {"$limit": 10}
    ]
    
    top_products = await db.orders.aggregate(product_pipeline).to_list(10)
    
    return {
        "total_revenue": revenue_data.get("total_revenue", 0),
        "prc_spent": revenue_data.get("prc_spent", 0),
        "delivery_charges": revenue_data.get("delivery_charges", 0),
        "total_orders": revenue_data.get("total_orders", 0),
        "top_products": top_products
    }

@api_router.get("/admin/reports/commissions")
async def get_commission_report():
    """Get commission distribution report (Admin)"""
    # Total commissions by entity type
    pipeline = [
        {"$group": {
            "_id": "$entity_type",
            "total_amount": {"$sum": "$amount"},
            "count": {"$sum": 1}
        }}
    ]
    
    commissions_by_type = await db.commissions_earned.aggregate(pipeline).to_list(10)
    
    # Top earners
    top_earners_pipeline = [
        {"$group": {
            "_id": "$entity_id",
            "entity_type": {"$first": "$entity_type"},
            "total_earned": {"$sum": "$amount"}
        }},
        {"$sort": {"total_earned": -1}},
        {"$limit": 10}
    ]
    
    top_earners = await db.commissions_earned.aggregate(top_earners_pipeline).to_list(10)
    
    # Get entity names
    for earner in top_earners:
        user = await db.users.find_one({"uid": earner["_id"]})
        if user:
            earner["name"] = user.get("name")
            earner["email"] = user.get("email")
    
    return {
        "commission_distribution": commissions_by_type,
        "top_earners": top_earners
    }


# ========== COMPREHENSIVE ANALYTICS DASHBOARD ==========

@api_router.get("/admin/analytics/comprehensive")
async def get_comprehensive_analytics(
    start_date: Optional[str] = None,
    end_date: Optional[str] = None
):
    """
    Comprehensive Analytics Dashboard API
    Returns: PRC circulation, redemption stats, user stats, and charts
    Supports custom date ranges
    PERF: 60 s cache (key includes range), all charts in parallel.
    """
    from datetime import timedelta

    CACHE_KEY = f"admin:analytics:comprehensive:s={start_date or '-'}:e={end_date or '-'}:v1"
    if cache:
        try:
            cached = await cache.get(CACHE_KEY)
            if cached:
                return cached
        except Exception:
            pass

    now = datetime.now(timezone.utc)
    today_start = now.replace(hour=0, minute=0, second=0, microsecond=0)
    
    # Parse date range or use defaults
    if start_date and end_date:
        try:
            range_start = datetime.fromisoformat(start_date.replace('Z', '+00:00'))
            range_end = datetime.fromisoformat(end_date.replace('Z', '+00:00'))
        except:
            range_start = today_start - timedelta(days=30)
            range_end = now
    else:
        range_start = today_start - timedelta(days=30)
        range_end = now
    
    # Calculate time ranges
    week_start = today_start - timedelta(days=today_start.weekday())
    month_start = today_start.replace(day=1)
    year_start = today_start.replace(month=1, day=1)
    
    # PRC Rate - DYNAMIC from database
    async def get_prc_rate_async():
        try:
            settings = await db.dmt_settings.find_one({"_id": "dmt_config"})
            if settings:
                rate = settings.get("prc_to_inr_rate", 100)
                return 1 / rate  # Convert to INR per PRC (e.g., 100 PRC = 1 INR means 1 PRC = 0.01 INR)
            return 0.01  # Default: 1 PRC = ₹0.01
        except Exception:
            return 0.01
    
    PRC_TO_INR_RATE = await get_prc_rate_async()
    
    # ===== 1. PRC CIRCULATION STATS =====
    prc_circulation = await asyncio.gather(
        # Total PRC in user wallets
        db.users.aggregate([
            {"$group": {"_id": None, "total": {"$sum": {"$ifNull": ["$prc_balance", 0]}}}}
        ]).to_list(1),
        # Total PRC ever mined
        db.users.aggregate([
            {"$group": {"_id": None, "total": {"$sum": {"$ifNull": ["$total_mined", 0]}}}}
        ]).to_list(1),
        # Total PRC from referrals
        db.users.aggregate([
            {"$group": {"_id": None, "total": {"$sum": {"$ifNull": ["$referral_earnings", 0]}}}}
        ]).to_list(1),
    )
    
    total_prc_balance = prc_circulation[0][0]["total"] if prc_circulation[0] else 0
    total_prc_mined = prc_circulation[1][0]["total"] if prc_circulation[1] else 0
    total_prc_referrals = prc_circulation[2][0]["total"] if prc_circulation[2] else 0
    total_prc_circulated = total_prc_balance + total_prc_mined
    
    # ===== 2. PRC REDEMPTION STATS (by time period) =====
    # Helper function for redemption aggregation
    async def get_redemption_stats(date_filter):
        results = await asyncio.gather(
            # Orders
            db.orders.aggregate([
                {"$match": {"status": {"$in": ["completed", "delivered"]}, **date_filter}},
                {"$group": {"_id": None, "total_prc": {"$sum": {"$ifNull": ["$total_prc", 0]}}, "count": {"$sum": 1}}}
            ]).to_list(1),
            # Bill Payments
            db.bill_payment_requests.aggregate([
                {"$match": {"status": {"$in": ["completed", "approved"]}, **date_filter}},
                {"$group": {"_id": None, "total_prc": {"$sum": {"$ifNull": ["$total_prc_deducted", 0]}}, "total_inr": {"$sum": {"$ifNull": ["$amount_inr", 0]}}, "count": {"$sum": 1}}}
            ]).to_list(1),
            # Gift Vouchers
            db.gift_voucher_requests.aggregate([
                {"$match": {"status": {"$in": ["completed", "approved"]}, **date_filter}},
                {"$group": {"_id": None, "total_prc": {"$sum": {"$ifNull": ["$total_prc_deducted", 0]}}, "total_inr": {"$sum": {"$ifNull": ["$amount_inr", 0]}}, "count": {"$sum": 1}}}
            ]).to_list(1),
        )
        
        total_prc = sum([r[0]["total_prc"] if r else 0 for r in results])
        total_inr = sum([r[0].get("total_inr", 0) if r else 0 for r in results[1:]])  # Only bill/gift have INR
        total_count = sum([r[0]["count"] if r else 0 for r in results])
        
        return {
            "total_prc": round(total_prc, 2),
            "total_inr": round(total_inr, 2),
            "prc_value_inr": round(total_prc * PRC_TO_INR_RATE, 2),
            "total_count": total_count,
            "breakdown": {
                "orders": {"prc": results[0][0]["total_prc"] if results[0] else 0, "count": results[0][0]["count"] if results[0] else 0},
                "bill_payments": {"prc": results[1][0]["total_prc"] if results[1] else 0, "inr": results[1][0].get("total_inr", 0) if results[1] else 0, "count": results[1][0]["count"] if results[1] else 0},
                "gift_vouchers": {"prc": results[2][0]["total_prc"] if results[2] else 0, "inr": results[2][0].get("total_inr", 0) if results[2] else 0, "count": results[2][0]["count"] if results[2] else 0}
            }
        }
    
    # Get stats for different periods
    redemption_results = await asyncio.gather(
        get_redemption_stats({}),  # All time
        get_redemption_stats({"created_at": {"$gte": today_start.isoformat()}}),  # Today
        get_redemption_stats({"created_at": {"$gte": week_start.isoformat()}}),  # This week
        get_redemption_stats({"created_at": {"$gte": month_start.isoformat()}}),  # This month
        get_redemption_stats({"created_at": {"$gte": year_start.isoformat()}}),  # This year
        get_redemption_stats({"created_at": {"$gte": range_start.isoformat(), "$lte": range_end.isoformat()}}),  # Custom range
    )
    
    redemption_stats = {
        "all_time": redemption_results[0],
        "today": redemption_results[1],
        "this_week": redemption_results[2],
        "this_month": redemption_results[3],
        "this_year": redemption_results[4],
        "custom_range": {
            **redemption_results[5],
            "start_date": range_start.isoformat(),
            "end_date": range_end.isoformat()
        }
    }
    
    # ===== 3. USER STATS =====
    # Calculate active users (active = logged in within 7 days OR has balance > 0 OR has orders)
    seven_days_ago = now - timedelta(days=7)
    
    user_stats = await asyncio.gather(
        db.users.count_documents({}),  # Total
        db.users.count_documents({"role": {"$ne": "admin"}}),  # Non-admin total
        db.users.count_documents({
            "$or": [
                {"last_login": {"$gte": seven_days_ago.isoformat()}},
                {"prc_balance": {"$gt": 0}},
                {"total_mined": {"$gt": 0}}
            ]
        }),  # Active users
        db.users.count_documents({"subscription_plan": "explorer"}),
        db.users.count_documents({"subscription_plan": "startup"}),
        db.users.count_documents({"subscription_plan": "growth"}),
        db.users.count_documents({"subscription_plan": "elite"}),
        db.users.count_documents({"kyc_status": "verified"}),
        db.users.count_documents({"kyc_status": "pending"}),
        db.users.count_documents({"created_at": {"$gte": today_start.isoformat()}}),  # New today
        db.users.count_documents({"created_at": {"$gte": week_start.isoformat()}}),  # New this week
        db.users.count_documents({"created_at": {"$gte": month_start.isoformat()}}),  # New this month
    )
    
    total_users = user_stats[0]
    non_admin_users = user_stats[1]
    active_users = user_stats[2]
    inactive_users = non_admin_users - active_users
    
    users = {
        "total": total_users,
        "non_admin": non_admin_users,
        "active": active_users,
        "inactive": inactive_users,
        "active_percentage": round((active_users / non_admin_users * 100) if non_admin_users > 0 else 0, 1),
        "by_plan": {
            "explorer": user_stats[3],
            "startup": user_stats[4],
            "growth": user_stats[5],
            "elite": user_stats[6]
        },
        "paid_users": user_stats[4] + user_stats[5] + user_stats[6],
        "free_users": user_stats[3],
        "kyc_verified": user_stats[7],
        "kyc_pending": user_stats[8],
        "new_users": {
            "today": user_stats[9],
            "this_week": user_stats[10],
            "this_month": user_stats[11]
        }
    }
    
    # ===== 4. CHARTS DATA — ALL 5 IN PARALLEL (was sequential) =====
    thirty_days_ago = now - timedelta(days=30)
    thirty_iso = thirty_days_ago.isoformat()
    user_growth_pipe = [
        {"$match": {"created_at": {"$gte": thirty_iso}}},
        {"$addFields": {"date_str": {"$substr": ["$created_at", 0, 10]}}},
        {"$group": {"_id": "$date_str", "count": {"$sum": 1}}},
        {"$sort": {"_id": 1}}
    ]
    redemption_trend_pipe = [
        {"$match": {"created_at": {"$gte": thirty_iso}, "status": {"$in": ["completed", "approved"]}}},
        {"$addFields": {"date_str": {"$substr": ["$created_at", 0, 10]}}},
        {"$group": {
            "_id": "$date_str",
            "total_prc": {"$sum": {"$ifNull": ["$total_prc_deducted", 0]}},
            "total_inr": {"$sum": {"$ifNull": ["$amount_inr", 0]}},
            "count": {"$sum": 1}
        }},
        {"$sort": {"_id": 1}}
    ]
    mining_trend_pipe = [
        {"$match": {"transaction_type": "mining", "timestamp": {"$gte": thirty_iso}}},
        {"$addFields": {"date_str": {"$substr": ["$timestamp", 0, 10]}}},
        {"$group": {
            "_id": "$date_str",
            "total_prc": {"$sum": {"$ifNull": ["$amount", 0]}},
            "count": {"$sum": 1}
        }},
        {"$sort": {"_id": 1}}
    ]
    redeem_trend_ledger_pipe = [
        {"$match": {"type": "redeem", "entry_type": "debit", "created_at": {"$gte": thirty_iso}}},
        {"$addFields": {"date_str": {"$substr": ["$created_at", 0, 10]}}},
        {"$group": {
            "_id": "$date_str",
            "total_prc": {"$sum": {"$abs": "$amount"}},
            "count": {"$sum": 1}
        }},
        {"$sort": {"_id": 1}}
    ]
    bank_redeem_trend_pipe = [
        {"$match": {"status": "paid", "processed_at": {"$gte": thirty_iso}}},
        {"$addFields": {"date_str": {"$substr": ["$processed_at", 0, 10]}}},
        {"$group": {
            "_id": "$date_str",
            "total_prc": {"$sum": {"$ifNull": ["$prc_deducted", 0]}},
            "count": {"$sum": 1}
        }},
        {"$sort": {"_id": 1}}
    ]

    _chart_top = await asyncio.gather(
        db.users.aggregate(user_growth_pipe).to_list(30),
        db.bill_payment_requests.aggregate(redemption_trend_pipe).to_list(30),
        db.transactions.aggregate(mining_trend_pipe).to_list(30),
        db.prc_ledger.aggregate(redeem_trend_ledger_pipe).to_list(30),
        db.bank_transfer_requests.aggregate(bank_redeem_trend_pipe).to_list(30),
        db.users.find(
            {"role": {"$ne": "admin"}},
            {"_id": 0, "uid": 1, "name": 1, "email": 1, "prc_balance": 1, "subscription_plan": 1, "total_mined": 1, "kyc_status": 1, "created_at": 1, "last_login": 1}
        ).sort("prc_balance", -1).limit(10).to_list(10),
        return_exceptions=True,
    )
    user_growth_data    = _chart_top[0] if not isinstance(_chart_top[0], Exception) else []
    redemption_trend    = _chart_top[1] if not isinstance(_chart_top[1], Exception) else []
    mining_trend        = _chart_top[2] if not isinstance(_chart_top[2], Exception) else []
    redeem_trend_ledger = _chart_top[3] if not isinstance(_chart_top[3], Exception) else []
    bank_redeem_trend   = _chart_top[4] if not isinstance(_chart_top[4], Exception) else []
    top_users           = _chart_top[5] if not isinstance(_chart_top[5], Exception) else []

    # Merge redeem trends (ledger + bank transfers)
    redeem_by_date = {}
    for item in redeem_trend_ledger:
        d = item["_id"]
        redeem_by_date[d] = {"_id": d, "total_prc": item["total_prc"], "count": item["count"]}
    for item in bank_redeem_trend:
        d = item["_id"]
        if d in redeem_by_date:
            redeem_by_date[d]["total_prc"] += item["total_prc"]
            redeem_by_date[d]["count"] += item["count"]
        else:
            redeem_by_date[d] = {"_id": d, "total_prc": item["total_prc"], "count": item["count"]}
    daily_redeem_trend = sorted(redeem_by_date.values(), key=lambda x: x["_id"])

    # Plan distribution for pie chart
    plan_distribution = [
        {"name": "Explorer (Free)", "value": user_stats[3], "color": "#6b7280"},
        {"name": "Startup", "value": user_stats[4], "color": "#3b82f6"},
        {"name": "Growth", "value": user_stats[5], "color": "#8b5cf6"},
        {"name": "Elite", "value": user_stats[6], "color": "#f59e0b"}
    ]
    
    # Active vs Inactive pie chart
    activity_distribution = [
        {"name": "Active Users", "value": active_users, "color": "#10b981"},
        {"name": "Inactive Users", "value": inactive_users, "color": "#ef4444"}
    ]
    
    charts = {
        "user_growth": user_growth_data,
        "redemption_trend": redemption_trend,
        "mining_trend": mining_trend,
        "daily_redeem_trend": daily_redeem_trend,
        "plan_distribution": plan_distribution,
        "activity_distribution": activity_distribution
    }

    payload = {
        "prc_circulation": {
            "total_in_wallets": round(total_prc_balance, 2),
            "total_mined": round(total_prc_mined, 2),
            "total_referral_earnings": round(total_prc_referrals, 2),
            "total_circulated": round(total_prc_circulated, 2),
            "inr_value": round(total_prc_balance * PRC_TO_INR_RATE, 2),
            "prc_rate": PRC_TO_INR_RATE
        },
        "redemption": redemption_stats,
        "users": users,
        "charts": charts,
        "top_users": top_users,
        "generated_at": now.isoformat()
    }
    if cache:
        try:
            await cache.set(CACHE_KEY, payload, ttl=60)
        except Exception:
            pass
    return payload


# ========== ANALYTICS ENDPOINTS ==========

@api_router.get("/admin/analytics/revenue-trends")
async def get_revenue_trends(period: str = "daily", days: int = 30):
    """Get revenue trends over time with daily/weekly/monthly aggregation"""
    from datetime import timedelta
    
    # Calculate date range
    end_date = datetime.now(timezone.utc)
    start_date = end_date - timedelta(days=days)
    
    # Determine grouping format
    if period == "daily":
        date_format = "%Y-%m-%d"
    elif period == "weekly":
        date_format = "%Y-W%U"
    elif period == "monthly":
        date_format = "%Y-%m"
    else:
        date_format = "%Y-%m-%d"
    
    # Revenue pipeline
    pipeline = [
        {"$match": {
            "status": "delivered",
            "created_at": {"$gte": start_date.isoformat(), "$lte": end_date.isoformat()}
        }},
        {"$addFields": {
            "date_parsed": {"$dateFromString": {"dateString": "$created_at"}}
        }},
        {"$group": {
            "_id": {"$dateToString": {"format": date_format, "date": "$date_parsed"}},
            "revenue": {"$sum": "$total_cash"},
            "prc_value": {"$sum": "$total_prc"},
            "orders": {"$sum": 1},
            "delivery_charges": {"$sum": "$delivery_charge"}
        }},
        {"$sort": {"_id": 1}}
    ]
    
    trends = await db.orders.aggregate(pipeline).to_list(length=1000)
    
    return {
        "period": period,
        "days": days,
        "data": [
            {
                "date": item["_id"],
                "revenue": round(item["revenue"], 2),
                "prc_value": round(item["prc_value"], 2),
                "orders": item["orders"],
                "delivery_charges": round(item["delivery_charges"], 2)
            }
            for item in trends
        ]
    }

@api_router.get("/admin/analytics/user-growth")
async def get_user_growth(days: int = 30):
    """Get user registration trends"""
    from datetime import timedelta
    
    end_date = datetime.now(timezone.utc)
    start_date = end_date - timedelta(days=days)
    
    pipeline = [
        {"$match": {
            "created_at": {"$gte": start_date.isoformat(), "$lte": end_date.isoformat()}
        }},
        {"$addFields": {
            "date_parsed": {"$dateFromString": {"dateString": "$created_at"}}
        }},
        {"$group": {
            "_id": {
                "date": {"$dateToString": {"format": "%Y-%m-%d", "date": "$date_parsed"}},
                "membership_type": "$membership_type"
            },
            "count": {"$sum": 1}
        }},
        {"$sort": {"_id.date": 1}}
    ]
    
    growth_data = await db.users.aggregate(pipeline).to_list(length=1000)
    
    # Transform data
    date_map = {}
    for item in growth_data:
        date = item["_id"]["date"]
        membership = item["_id"]["membership_type"] or "free"
        
        if date not in date_map:
            date_map[date] = {"date": date, "free": 0, "vip": 0, "total": 0}
        
        date_map[date][membership] = item["count"]
        date_map[date]["total"] += item["count"]
    
    return {
        "days": days,
        "data": list(date_map.values())
    }

# Product Performance Analytics - REMOVED (Marketplace removed)

@api_router.get("/admin/analytics/withdrawal-patterns")
async def get_withdrawal_patterns(days: int = 30):
    """Get withdrawal request patterns over time"""
    from datetime import timedelta
    
    end_date = datetime.now(timezone.utc)
    start_date = end_date - timedelta(days=days)
    
    # Cashback withdrawals
    cashback_pipeline = [
        {"$match": {
            "created_at": {"$gte": start_date.isoformat(), "$lte": end_date.isoformat()}
        }},
        {"$addFields": {
            "date_parsed": {"$dateFromString": {"dateString": "$created_at"}}
        }},
        {"$group": {
            "_id": {
                "date": {"$dateToString": {"format": "%Y-%m-%d", "date": "$date_parsed"}},
                "status": "$status"
            },
            "count": {"$sum": 1},
            "total_amount": {"$sum": "$amount_requested"}
        }},
        {"$sort": {"_id.date": 1}}
    ]
    
    cashback_data = await db.cashback_withdrawals.aggregate(cashback_pipeline).to_list(length=1000)
    
    # Transform data
    date_map = {}
    for item in cashback_data:
        date = item["_id"]["date"]
        status = item["_id"]["status"]
        
        if date not in date_map:
            date_map[date] = {
                "date": date,
                "pending": 0,
                "approved": 0,
                "completed": 0,
                "rejected": 0,
                "total_amount": 0
            }
        
        date_map[date][status] = item["count"]
        date_map[date]["total_amount"] += item["total_amount"]
    
    return {
        "days": days,
        "data": list(date_map.values())
    }


@api_router.get("/admin/performance-report")
async def get_admin_performance_report(date_from: Optional[str] = None, date_to: Optional[str] = None):
    """
    Get admin performance report - which admin approved/rejected how many requests
    OPTIMIZED: Uses aggregation instead of fetching all records
    """
    try:
        # Build date filter
        date_filter = {}
        if date_from:
            date_filter["$gte"] = f"{date_from}T00:00:00+00:00"
        if date_to:
            date_filter["$lte"] = f"{date_to}T23:59:59+00:00"
        
        admin_stats = {}
        category_stats = {}
        
        # Helper to update stats
        def update_from_agg(results, category, admin_field, status_field="status"):
            for r in results:
                admin_uid = r.get("_id")
                if not admin_uid:
                    continue
                
                approved = r.get("approved", 0)
                rejected = r.get("rejected", 0)
                
                if admin_uid not in admin_stats:
                    admin_stats[admin_uid] = {
                        "admin_uid": admin_uid,
                        "admin_name": "Unknown",
                        "approved": 0,
                        "rejected": 0
                    }
                
                admin_stats[admin_uid]["approved"] += approved
                admin_stats[admin_uid]["rejected"] += rejected
                
                if category not in category_stats:
                    category_stats[category] = {"approved": 0, "rejected": 0}
                category_stats[category]["approved"] += approved
                category_stats[category]["rejected"] += rejected
        
        # 1. Bank Withdrawal Requests - Aggregated
        bank_match = {"status": {"$in": ["approved", "rejected"]}}
        if date_filter:
            bank_match["processed_at"] = date_filter
        
        bank_agg = await db.bank_withdrawal_requests.aggregate([
            {"$match": bank_match},
            {"$group": {
                "_id": {"$ifNull": ["$processed_by_uid", "$approved_by"]},
                "approved": {"$sum": {"$cond": [{"$eq": ["$status", "approved"]}, 1, 0]}},
                "rejected": {"$sum": {"$cond": [{"$eq": ["$status", "rejected"]}, 1, 0]}}
            }}
        ]).to_list(100)
        update_from_agg(bank_agg, "bank_redeem", "processed_by_uid")
        
        # 2. VIP/Subscription Payments - Aggregated
        vip_match = {"status": {"$in": ["approved", "rejected"]}}
        if date_filter:
            vip_match["approved_at"] = date_filter
        
        vip_agg = await db.vip_payments.aggregate([
            {"$match": vip_match},
            {"$group": {
                "_id": {"$ifNull": ["$approved_by", "$rejected_by"]},
                "approved": {"$sum": {"$cond": [{"$eq": ["$status", "approved"]}, 1, 0]}},
                "rejected": {"$sum": {"$cond": [{"$eq": ["$status", "rejected"]}, 1, 0]}}
            }}
        ]).to_list(100)
        update_from_agg(vip_agg, "subscription", "approved_by")
        
        # 3. KYC Documents - Aggregated
        kyc_match = {"status": {"$in": ["verified", "rejected"]}}
        if date_filter:
            kyc_match["verified_at"] = date_filter
        
        kyc_agg = await db.kyc_documents.aggregate([
            {"$match": kyc_match},
            {"$group": {
                "_id": {"$ifNull": ["$verified_by", "$rejected_by"]},
                "approved": {"$sum": {"$cond": [{"$eq": ["$status", "verified"]}, 1, 0]}},
                "rejected": {"$sum": {"$cond": [{"$eq": ["$status", "rejected"]}, 1, 0]}}
            }}
        ]).to_list(100)
        update_from_agg(kyc_agg, "kyc", "verified_by")
        
        # 4. Bill Payments - Aggregated
        bill_match = {"status": {"$in": ["completed", "approved", "rejected"]}}
        if date_filter:
            bill_match["processed_at"] = date_filter
        
        bill_agg = await db.bill_payment_requests.aggregate([
            {"$match": bill_match},
            {"$group": {
                "_id": "$processed_by_uid",
                "approved": {"$sum": {"$cond": [{"$in": ["$status", ["completed", "approved"]]}, 1, 0]}},
                "rejected": {"$sum": {"$cond": [{"$eq": ["$status", "rejected"]}, 1, 0]}}
            }}
        ]).to_list(100)
        update_from_agg(bill_agg, "bill_payment", "processed_by_uid")
        
        # 5. Gift Vouchers - Aggregated
        gift_match = {"status": {"$in": ["completed", "approved", "rejected"]}}
        if date_filter:
            gift_match["processed_at"] = date_filter
        
        gift_agg = await db.gift_voucher_requests.aggregate([
            {"$match": gift_match},
            {"$group": {
                "_id": "$processed_by",
                "approved": {"$sum": {"$cond": [{"$in": ["$status", ["completed", "approved"]]}, 1, 0]}},
                "rejected": {"$sum": {"$cond": [{"$eq": ["$status", "rejected"]}, 1, 0]}}
            }}
        ]).to_list(100)
        update_from_agg(gift_agg, "gift_voucher", "processed_by")
        
        # Fetch admin names
        admin_uids = list(admin_stats.keys())
        if admin_uids:
            admin_users = await db.users.find(
                {"uid": {"$in": admin_uids}},
                {"_id": 0, "uid": 1, "name": 1}
            ).to_list(100)
            for u in admin_users:
                if u["uid"] in admin_stats:
                    admin_stats[u["uid"]]["admin_name"] = u.get("name", "Unknown")
        
        # Calculate summary
        total_approved = sum(a["approved"] for a in admin_stats.values())
        total_rejected = sum(a["rejected"] for a in admin_stats.values())
        
        sorted_admins = sorted(
            admin_stats.values(),
            key=lambda x: x["approved"] + x["rejected"],
            reverse=True
        )
        
        return {
            "success": True,
            "summary": {
                "total_admins": len(admin_stats),
                "total_approved": total_approved,
                "total_rejected": total_rejected,
                "total_processed": total_approved + total_rejected
            },
            "admins": sorted_admins,
            "by_category": category_stats,
            "date_range": {"from": date_from, "to": date_to}
        }
        
    except Exception as e:
        logging.error(f"Error generating admin performance report: {e}")
        raise HTTPException(status_code=500, detail=get_user_friendly_error(e))


async def get_analytics_overview():
    """Get comprehensive analytics overview"""
    from datetime import timedelta
    
    now = datetime.now(timezone.utc)
    thirty_days_ago = now - timedelta(days=30)
    seven_days_ago = now - timedelta(days=7)
    
    # Total users
    total_users = await db.users.count_documents({})
    vip_users = await db.users.count_documents({"membership_type": "vip"})
    free_users = total_users - vip_users
    
    # New users (last 30 days)
    new_users_30d = await db.users.count_documents({
        "created_at": {"$gte": thirty_days_ago.isoformat()}
    })
    
    # Revenue stats
    revenue_pipeline = [
        {"$match": {"status": "delivered"}},
        {"$group": {
            "_id": None,
            "total_revenue": {"$sum": "$total_cash"},
            "total_orders": {"$sum": 1}
        }}
    ]
    revenue_result = await db.orders.aggregate(revenue_pipeline).to_list(1)
    revenue_data = revenue_result[0] if revenue_result else {"total_revenue": 0, "total_orders": 0}
    
    # Recent revenue (last 30 days)
    recent_revenue_pipeline = [
        {"$match": {
            "status": "delivered",
            "created_at": {"$gte": thirty_days_ago.isoformat()}
        }},
        {"$group": {
            "_id": None,
            "revenue_30d": {"$sum": "$total_cash"},
            "orders_30d": {"$sum": 1}
        }}
    ]
    recent_revenue_result = await db.orders.aggregate(recent_revenue_pipeline).to_list(1)
    recent_revenue_data = recent_revenue_result[0] if recent_revenue_result else {"revenue_30d": 0, "orders_30d": 0}
    
    # Pending withdrawals
    pending_cashback = await db.cashback_withdrawals.count_documents({"status": "pending"})
    pending_profit = await db.profit_withdrawals.count_documents({"status": "pending"})
    
    # Total withdrawal amount pending
    cashback_amount_pipeline = [
        {"$match": {"status": "pending"}},
        {"$group": {"_id": None, "total": {"$sum": "$amount_requested"}}}
    ]
    cashback_amount_result = await db.cashback_withdrawals.aggregate(cashback_amount_pipeline).to_list(1)
    pending_cashback_amount = cashback_amount_result[0]["total"] if cashback_amount_result else 0
    
    profit_amount_result = await db.profit_withdrawals.aggregate(cashback_amount_pipeline).to_list(1)
    pending_profit_amount = profit_amount_result[0]["total"] if profit_amount_result else 0
    
    return {
        "users": {
            "total": total_users,
            "vip": vip_users,
            "free": free_users,
            "new_30d": new_users_30d
        },
        "revenue": {
            "total": round(revenue_data["total_revenue"], 2),
            "last_30d": round(recent_revenue_data["revenue_30d"], 2)
        },
        "orders": {
            "total": revenue_data["total_orders"],
            "last_30d": recent_revenue_data["orders_30d"]
        },
        "withdrawals": {
            "pending_count": pending_cashback + pending_profit,
            "pending_amount": round(pending_cashback_amount + pending_profit_amount, 2),
            "cashback_pending": pending_cashback,
            "profit_pending": pending_profit
        }
    }


