@api_router.get("/support/tickets/{ticket_id}")
async def get_ticket_details(ticket_id: str):
    """Get ticket details with all replies"""
    ticket = await db.support_tickets.find_one({"ticket_id": ticket_id})
    if not ticket:
        raise HTTPException(status_code=404, detail="Ticket not found")
    
    ticket.pop("_id", None)
    
    # Get all replies for this ticket
    replies = await db.support_ticket_replies.find({"ticket_id": ticket_id}).sort("created_at", 1).to_list(length=1000)
    for reply in replies:
        reply.pop("_id", None)
    
    ticket["replies"] = replies
    
    return ticket

@api_router.post("/support/tickets/{ticket_id}/reply")
async def add_ticket_reply(ticket_id: str, request: TicketReplyRequest):
    """Add a reply to a ticket"""
    # Verify ticket exists
    ticket = await db.support_tickets.find_one({"ticket_id": ticket_id})
    if not ticket:
        raise HTTPException(status_code=404, detail="Ticket not found")
    
    # Get user details
    user = await db.users.find_one({"uid": request.user_id})
    if not user:
        raise HTTPException(status_code=404, detail="User not found")
    
    reply = SupportTicketReply(
        ticket_id=ticket_id,
        user_id=request.user_id,
        user_name=user.get("name", "Unknown"),
        user_role=user.get("role", "user"),
        message=request.message
    )
    
    await db.support_ticket_replies.insert_one(reply.model_dump())
    
    # Update ticket's updated_at timestamp
    await db.support_tickets.update_one(
        {"ticket_id": ticket_id},
        {"$set": {"updated_at": datetime.now(timezone.utc).isoformat()}}
    )
    
    return {
        "message": "Reply added successfully",
        "reply": reply.model_dump()
    }

@api_router.get("/admin/support/tickets")
async def get_all_tickets(status: Optional[str] = None, category: Optional[str] = None, page: int = 1, limit: int = 20):
    """Admin endpoint to get all support tickets with pagination"""
    query = {}
    if status:
        query["status"] = status
    if category:
        query["category"] = category
    
    skip = (page - 1) * limit
    total = await db.support_tickets.count_documents(query)
    total_pages = (total + limit - 1) // limit
    
    tickets = await db.support_tickets.find(query).sort("created_at", -1).skip(skip).limit(limit).to_list(length=limit)
    
    for ticket in tickets:
        ticket.pop("_id", None)
    
    return {
        "tickets": tickets,
        "total": total,
        "page": page,
        "limit": limit,
        "total_pages": total_pages
    }

@api_router.put("/admin/support/tickets/{ticket_id}")
async def update_ticket(ticket_id: str, request: TicketUpdateRequest):
    """Admin endpoint to update ticket status/priority/assignment"""
    ticket = await db.support_tickets.find_one({"ticket_id": ticket_id})
    if not ticket:
        raise HTTPException(status_code=404, detail="Ticket not found")
    
    update_data = {"updated_at": datetime.now(timezone.utc).isoformat()}
    
    if request.status:
        update_data["status"] = request.status
    if request.priority:
        update_data["priority"] = request.priority
    if request.assigned_to is not None:
        update_data["assigned_to"] = request.assigned_to
    if request.resolution_notes is not None:
        update_data["resolution_notes"] = request.resolution_notes
    
    await db.support_tickets.update_one(
        {"ticket_id": ticket_id},
        {"$set": update_data}
    )
    
    return {"message": "Ticket updated successfully", "updates": update_data}


# ========== ADMIN USER MANAGEMENT ROUTES ==========

class UserUpdateRequest(BaseModel):
    name: Optional[str] = None
    email: Optional[str] = None
    mobile: Optional[str] = None
    role: Optional[str] = None
    membership_type: Optional[str] = None
    membership_expiry: Optional[str] = None
    vip_plan_type: Optional[str] = None
    kyc_status: Optional[str] = None
    is_active: Optional[bool] = None

class BalanceAdjustRequest(BaseModel):
    balance_type: str  # prc_balance, cashback_wallet_balance, profit_wallet_balance
    amount: float
    operation: str  # add, deduct, set
    notes: Optional[str] = None

@api_router.put("/admin/users/{uid}/update")
async def update_user_admin(uid: str, request: UserUpdateRequest):
    """Admin updates user details"""
    user = await db.users.find_one({"uid": uid})
    if not user:
        raise HTTPException(status_code=404, detail="User not found")
    
    update_data = {"updated_at": datetime.now(timezone.utc).isoformat()}
    
    if request.name:
        update_data["name"] = request.name
    if request.email:
        # Check if email already exists
        existing = await db.users.find_one({"email": request.email.lower(), "uid": {"$ne": uid}})
        if existing:
            raise HTTPException(status_code=400, detail="Email already exists")
        update_data["email"] = request.email.lower()
    if request.mobile:
        update_data["mobile"] = request.mobile
    if request.role:
        update_data["role"] = request.role
    if request.membership_type:
        update_data["membership_type"] = request.membership_type
    if request.membership_expiry:
        # Convert date string to ISO format datetime
        try:
            expiry_date = datetime.fromisoformat(request.membership_expiry.replace('Z', '+00:00'))
            update_data["membership_expiry"] = expiry_date.isoformat()
        except:
            # If it's a date-only string (YYYY-MM-DD), add time
            update_data["membership_expiry"] = f"{request.membership_expiry}T23:59:59+00:00"
    if request.vip_plan_type:
        update_data["vip_plan_type"] = request.vip_plan_type
    if request.kyc_status:
        update_data["kyc_status"] = request.kyc_status
    if request.is_active is not None:
        update_data["is_active"] = request.is_active
    
    await db.users.update_one({"uid": uid}, {"$set": update_data})
    
    # Log action
    await db.audit_logs.insert_one({
        "log_id": str(uuid.uuid4()),
        "action": "update_user",
        "entity_type": "user",
        "entity_id": uid,
        "performed_by": "admin",
        "changes": update_data,
        "created_at": datetime.now(timezone.utc).isoformat()
    })
    
    return {"message": "User updated successfully", "updates": update_data}

@api_router.get("/admin/duplicate-check")
async def check_duplicate_data():
    """Admin: Check for duplicate Aadhaar, PAN, Mobile, UTR numbers"""
    duplicates = {
        "aadhaar_numbers": [],
        "pan_numbers": [],
        "mobile_numbers": [],
        "utr_numbers": [],
        "summary": {}
    }
    
    # Check duplicate Aadhaar numbers
    pipeline = [
        {"$match": {"aadhaar_number": {"$ne": None, "$ne": ""}}},
        {"$group": {"_id": "$aadhaar_number", "count": {"$sum": 1}, "users": {"$push": {"uid": "$uid", "name": "$name", "email": "$email"}}}},
        {"$match": {"count": {"$gt": 1}}}
    ]
    aadhaar_dups = await db.users.aggregate(pipeline).to_list(100)
    duplicates["aadhaar_numbers"] = [{"aadhaar": d["_id"], "count": d["count"], "users": d["users"]} for d in aadhaar_dups]
    
    # Check duplicate PAN numbers
    pipeline = [
        {"$match": {"pan_number": {"$ne": None, "$ne": ""}}},
        {"$group": {"_id": "$pan_number", "count": {"$sum": 1}, "users": {"$push": {"uid": "$uid", "name": "$name", "email": "$email"}}}},
        {"$match": {"count": {"$gt": 1}}}
    ]
    pan_dups = await db.users.aggregate(pipeline).to_list(100)
    duplicates["pan_numbers"] = [{"pan": d["_id"], "count": d["count"], "users": d["users"]} for d in pan_dups]
    
    # Check duplicate Mobile numbers
    pipeline = [
        {"$match": {"mobile": {"$ne": None, "$ne": ""}}},
        {"$group": {"_id": "$mobile", "count": {"$sum": 1}, "users": {"$push": {"uid": "$uid", "name": "$name", "email": "$email"}}}},
        {"$match": {"count": {"$gt": 1}}}
    ]
    mobile_dups = await db.users.aggregate(pipeline).to_list(100)
    duplicates["mobile_numbers"] = [{"mobile": d["_id"], "count": d["count"], "users": d["users"]} for d in mobile_dups]
    
    # Check duplicate UTR numbers in subscriptions
    pipeline = [
        {"$match": {"utr_number": {"$ne": None, "$ne": ""}}},
        {"$group": {"_id": "$utr_number", "count": {"$sum": 1}, "payments": {"$push": {"payment_id": "$payment_id", "user_id": "$user_id", "amount": "$amount"}}}},
        {"$match": {"count": {"$gt": 1}}}
    ]
    utr_dups_subs = await db.subscriptions.aggregate(pipeline).to_list(100)
    utr_dups_vip = await db.vip_subscriptions.aggregate(pipeline).to_list(100)
    utr_dups_payments = await db.vip_payments.aggregate(pipeline).to_list(100)
    
    all_utr_dups = utr_dups_subs + utr_dups_vip + utr_dups_payments
    duplicates["utr_numbers"] = [{"utr": d["_id"], "count": d["count"], "payments": d["payments"]} for d in all_utr_dups]
    
    # Summary
    duplicates["summary"] = {
        "total_duplicate_aadhaar": len(duplicates["aadhaar_numbers"]),
        "total_duplicate_pan": len(duplicates["pan_numbers"]),
        "total_duplicate_mobile": len(duplicates["mobile_numbers"]),
        "total_duplicate_utr": len(duplicates["utr_numbers"])
    }
    
    return duplicates

async def adjust_user_balance(uid: str, request: BalanceAdjustRequest):
    """Admin adjusts user balance (PRC, cashback, profit)"""
    user = await db.users.find_one({"uid": uid})
    if not user:
        raise HTTPException(status_code=404, detail="User not found")
    
    if request.balance_type not in ["prc_balance", "cashback_wallet_balance", "profit_wallet_balance"]:
        raise HTTPException(status_code=400, detail="Invalid balance type")
    
    current_balance = user.get(request.balance_type, 0)
    
    if request.operation == "add":
        new_balance = current_balance + request.amount
    elif request.operation == "deduct":
        new_balance = current_balance - request.amount
        if new_balance < 0:
            raise HTTPException(status_code=400, detail="Insufficient balance")
    elif request.operation == "set":
        new_balance = request.amount
        if new_balance < 0:
            raise HTTPException(status_code=400, detail="Cannot set negative balance")
    else:
        raise HTTPException(status_code=400, detail="Invalid operation")
    
    await db.users.update_one(
        {"uid": uid},
        {"$set": {
            request.balance_type: new_balance,
            "updated_at": datetime.now(timezone.utc).isoformat()
        }}
    )
    
    # Create wallet transaction record
    wallet_type_map = {
        "prc_balance": "prc",
        "cashback_wallet_balance": "cashback",
        "profit_wallet_balance": "profit"
    }
    
    transaction_type = "credit" if request.operation == "add" or (request.operation == "set" and new_balance > current_balance) else "debit"
    actual_amount = abs(new_balance - current_balance)
    
    await db.wallet_transactions.insert_one({
        "transaction_id": str(uuid.uuid4()),
        "user_id": uid,
        "type": transaction_type,
        "wallet_type": wallet_type_map.get(request.balance_type, "unknown"),
        "amount": actual_amount,
        "description": f"Admin adjustment: {request.operation} - {request.notes or 'Manual adjustment'}",
        "reference_id": "admin_adjustment",
        "balance_after": new_balance,
        "created_at": datetime.now(timezone.utc).isoformat()
    })
    
    # Log action
    await db.audit_logs.insert_one({
        "log_id": str(uuid.uuid4()),
        "action": "adjust_balance",
        "entity_type": "user",
        "entity_id": uid,
        "performed_by": "admin",
        "changes": {
            "balance_type": request.balance_type,
            "operation": request.operation,
            "amount": request.amount,
            "old_balance": current_balance,
            "new_balance": new_balance,
            "notes": request.notes
        },
        "created_at": datetime.now(timezone.utc).isoformat()
    })
    
    return {
        "message": "Balance adjusted successfully",
        "balance_type": request.balance_type,
        "old_balance": current_balance,
        "new_balance": new_balance
    }

@api_router.post("/admin/fix-negative-balances")
async def fix_negative_balances():
    """Admin fixes all negative PRC balances by setting them to 0"""
    # Find all users with negative PRC balance
    negative_users = await db.users.find(
        {"prc_balance": {"$lt": 0}},
        {"uid": 1, "email": 1, "name": 1, "prc_balance": 1, "_id": 0}
    ).to_list(1000)
    
    if not negative_users:
        return {"message": "No users with negative balance found", "fixed_count": 0}
    
    fixed_users = []
    for user in negative_users:
        old_balance = user.get("prc_balance", 0)
        await db.users.update_one(
            {"uid": user["uid"]},
            {"$set": {"prc_balance": 0}}
        )
        
        # Log the fix in transactions (for PRC statement visibility)
        await db.transactions.insert_one({
            "transaction_id": f"NEGFIX-{str(uuid.uuid4())}",
            "user_id": user["uid"],
            "type": "admin_adjustment",
            "amount": -old_balance,
            "description": f"Auto-fix negative PRC balance ({round(old_balance, 2)} → 0)",
            "balance_before": old_balance,
            "balance_after": 0,
            "created_at": datetime.now(timezone.utc).isoformat()
        })
        
        # Log the fix
        await db.audit_logs.insert_one({
            "log_id": str(uuid.uuid4()),
            "action": "fix_negative_balance",
            "entity_type": "user",
            "entity_id": user["uid"],
            "performed_by": "admin",
            "changes": {
                "old_balance": old_balance,
                "new_balance": 0,
                "reason": "Auto-fix negative PRC balance"
            },
            "created_at": datetime.now(timezone.utc).isoformat()
        })
        
        fixed_users.append({
            "uid": user["uid"],
            "email": user.get("email"),
            "name": user.get("name"),
            "old_balance": old_balance,
            "new_balance": 0
        })
    
    return {
        "message": f"Fixed {len(fixed_users)} users with negative balances",
        "fixed_count": len(fixed_users),
        "fixed_users": fixed_users
    }


@api_router.get("/admin/cleanup-retry-failed")
@api_router.post("/admin/cleanup-retry-failed")
async def cleanup_retry_failed_requests(
    dry_run: bool = True,
    limit: int = 500
):
    """
    🧹 CLEANUP: Delete RETRY_FAILED requests and refund PRC to users.
    
    This endpoint:
    1. Finds all requests with status 'RETRY_FAILED' or 'retry_failed'
    2. Refunds the PRC to each user
    3. Deletes the request record (or marks as 'deleted_refunded')
    
    Query Params:
    - dry_run: If True, only preview (default: True)
    - limit: Max records to process (default: 500)
    
    ⚠️ SET dry_run=false TO ACTUALLY DELETE AND REFUND
    """
    from datetime import datetime, timezone
    
    timestamp = datetime.now(timezone.utc).isoformat()
    
    results = {
        "found": 0,
        "refunded": 0,
        "deleted": 0,
        "total_prc_refunded": 0,
        "errors": [],
        "details": []
    }
    
    try:
        # Find all RETRY_FAILED requests
        retry_failed_requests = await db.redeem_requests.find({
            "status": {"$in": ["RETRY_FAILED", "retry_failed", "eko_failed"]}
        }).limit(limit).to_list(limit)
        
        results["found"] = len(retry_failed_requests)
        
        if results["found"] == 0:
            return {
                "success": True,
                "dry_run": dry_run,
                "message": "No RETRY_FAILED requests found",
                "results": results
            }
        
        for req in retry_failed_requests:
            request_id = req.get("request_id", str(req.get("_id", "")))
            user_id = req.get("user_id")
            
            # Get PRC amount to refund
            prc_to_refund = (
                req.get("total_prc_deducted") or 
                req.get("prc_amount") or 
                req.get("prc_used") or 0
            )
            
            # Skip if already refunded
            if req.get("prc_refunded"):
                results["details"].append({
                    "request_id": request_id,
                    "status": "skipped",
                    "reason": "Already refunded"
                })
                continue
            
            detail = {
                "request_id": request_id,
                "user_id": user_id,
                "user_name": req.get("user_name", ""),
                "service_type": req.get("service_type", ""),
                "amount_inr": req.get("amount") or req.get("amount_inr") or 0,
                "prc_to_refund": prc_to_refund,
                "original_status": req.get("status")
            }
            
            if not dry_run:
                try:
                    # 1. Refund PRC to user
                    if prc_to_refund > 0 and user_id:
                        user = await db.users.find_one({"uid": user_id})
                        if user:
                            current_balance = float(user.get("prc_balance", 0) or 0)
                            new_balance = current_balance + prc_to_refund
                            
                            await db.users.update_one(
                                {"uid": user_id},
                                {"$set": {"prc_balance": new_balance}}
                            )
                            
                            # Log the refund in transactions
                            await db.transactions.insert_one({
                                "transaction_id": f"CLEANUP-{request_id}",
                                "user_id": user_id,
                                "type": "cleanup_refund",
                                "amount": prc_to_refund,
                                "balance_before": current_balance,
                                "balance_after": new_balance,
                                "description": f"Cleanup refund for RETRY_FAILED request",
                                "reference": request_id,
                                "timestamp": timestamp
                            })
                            
                            detail["refunded"] = True
                            detail["new_balance"] = new_balance
                            results["refunded"] += 1
                            results["total_prc_refunded"] += prc_to_refund
                    
                    # 2. Delete the request record
                    await db.redeem_requests.delete_one({"_id": req.get("_id")})
                    detail["deleted"] = True
                    results["deleted"] += 1
                    detail["status"] = "refunded_and_deleted"
                    
                except Exception as e:
                    detail["status"] = "error"
                    detail["error"] = str(e)
                    results["errors"].append({"request_id": request_id, "error": str(e)})
            else:
                detail["status"] = "would_refund_and_delete"
            
            results["details"].append(detail)
        
        return {
            "success": True,
            "dry_run": dry_run,
            "timestamp": timestamp,
            "summary": {
                "total_retry_failed_found": results["found"],
                "records_refunded": results["refunded"],
                "records_deleted": results["deleted"],
                "total_prc_refunded": round(results["total_prc_refunded"], 2),
                "errors": len(results["errors"])
            },
            "details": results["details"][:100],
            "errors": results["errors"][:20] if results["errors"] else [],
            "note": "Run with dry_run=false to apply changes" if dry_run else "Cleanup completed successfully"
        }
        
    except Exception as e:
        logging.error(f"[CLEANUP RETRY_FAILED] Error: {e}")
        import traceback
        return {
            "success": False,
            "error": str(e),
            "traceback": traceback.format_exc()
        }


@api_router.post("/admin/prc-auto-correct")
async def prc_auto_correct(
    dry_run: bool = True,
    min_balance: float = 0,
    limit: int = 1000
):
    """
    🔧 AUTO-CORRECT: Fix all PRC balances based on actual transactions.
    
    Formula: Correct Balance = Mining + Referrals + Refunds - All Redemptions
    
    Query Params:
    - dry_run: If True, only preview changes (default: True)
    - min_balance: Only process users with balance > this (default: 0)
    - limit: Max users to process (default: 1000)
    
    IMPORTANT: Run with dry_run=True first to preview changes!
    """
    from utils.prc_fields import get_prc_amount
    
    timestamp = datetime.now(timezone.utc).isoformat()
    
    # Get users
    users = await db.users.find(
        {"prc_balance": {"$gt": min_balance}},
        {"uid": 1, "name": 1, "email": 1, "prc_balance": 1, "total_mined": 1, "total_prc_mined": 1}
    ).sort("prc_balance", -1).limit(limit).to_list(limit)
    
    corrections = []
    errors = []
    
    valid_statuses = ["approved", "success", "completed", "pending", "processing", "paid"]
    skip_statuses = ["refunded", "rejected", "failed", "cancelled"]
    
    for user in users:
        uid = user["uid"]
        current_balance = float(user.get("prc_balance", 0))
        
        try:
            # ============ CREDITS ============
            credits = {}
            
            # 1. Mining
            credits["mining"] = float(user.get("total_prc_mined", 0) or user.get("total_mined", 0) or 0)
            
            # 2. Referral rewards
            ref_txns = await db.transactions.find({
                "$or": [{"user_id": uid}, {"uid": uid}],
                "type": {"$in": ["referral", "referral_bonus", "referral_reward", "referral_commission"]}
            }).to_list(5000)
            credits["referrals"] = sum(abs(float(t.get("amount", 0) or t.get("prc_amount", 0) or t.get("amount_prc", 0) or 0)) for t in ref_txns)
            
            # 3. Signup bonus
            signup_txns = await db.transactions.find({
                "$or": [{"user_id": uid}, {"uid": uid}],
                "type": {"$in": ["signup", "signup_bonus", "welcome_bonus"]}
            }).to_list(100)
            credits["signup"] = sum(abs(float(t.get("amount", 0) or t.get("prc_amount", 0) or 0)) for t in signup_txns)
            
            # 4. Admin credits
            admin_txns = await db.transactions.find({
                "$or": [{"user_id": uid}, {"uid": uid}],
                "type": {"$in": ["admin_credit", "manual_credit", "credit"]}
            }).to_list(1000)
            credits["admin"] = sum(abs(float(t.get("amount", 0) or t.get("prc_amount", 0) or 0)) for t in admin_txns)
            
            # 5. Refunds
            refund_txns = await db.transactions.find({
                "$or": [{"user_id": uid}, {"uid": uid}],
                "type": {"$in": ["refund", "prc_refund"]}
            }).to_list(1000)
            credits["refunds"] = sum(abs(float(t.get("amount", 0) or t.get("prc_amount", 0) or 0)) for t in refund_txns)
            
            # ============ DEBITS ============
            debits = {}
            
            # 1. Bill payments
            bills = await db.bill_payment_requests.find({
                "user_id": uid, "status": {"$in": valid_statuses}
            }).to_list(5000)
            debits["bills"] = sum(get_prc_amount(b) for b in bills if b.get("status") not in skip_statuses)
            
            # 2. Bank withdrawals
            bank_wd = await db.bank_withdrawal_requests.find({
                "user_id": uid, "status": {"$in": valid_statuses}
            }).to_list(5000)
            debits["bank_wd"] = sum(get_prc_amount(b) for b in bank_wd if b.get("status") not in skip_statuses)
            
            # 3. Bank transfers
            bank_tr = await db.bank_transfer_requests.find({
                "user_id": uid, "status": {"$in": valid_statuses}
            }).to_list(5000)
            debits["bank_tr"] = sum(get_prc_amount(b) for b in bank_tr if b.get("status") not in skip_statuses)
            
            # 4. Bank redeems
            bank_rd = await db.bank_redeem_requests.find({
                "user_id": uid, "status": {"$in": valid_statuses}
            }).to_list(5000)
            debits["bank_rd"] = sum(get_prc_amount(b) for b in bank_rd if b.get("status") not in skip_statuses)
            
            # 5. Gift vouchers
            gv = await db.gift_voucher_orders.find({
                "user_id": uid, "status": {"$in": valid_statuses}
            }).to_list(5000)
            gv_req = await db.gift_voucher_requests.find({
                "user_id": uid, "status": {"$in": valid_statuses}
            }).to_list(5000)
            debits["gift_vouchers"] = sum(get_prc_amount(g) for g in gv) + sum(get_prc_amount(g) for g in gv_req)
            
            # 6. Orders
            orders = await db.orders.find({
                "user_id": uid, "status": {"$in": ["completed", "delivered", "paid"]}
            }).to_list(5000)
            debits["orders"] = sum(get_prc_amount(o) for o in orders if o.get("status") not in ["cancelled", "refunded"])
            
            # 7. PRC Subscriptions
            subs = await db.subscription_payments.find({
                "user_id": uid, "payment_method": "prc", "status": {"$in": ["paid", "success", "completed"]}
            }).to_list(1000)
            debits["subscriptions"] = sum(get_prc_amount(s) for s in subs)
            
            # ============ CALCULATE ============
            total_credits = sum(credits.values())
            total_debits = sum(debits.values())
            correct_balance = round(total_credits - total_debits, 2)
            adjustment = round(correct_balance - current_balance, 2)
            
            # Only record if adjustment needed (more than 1 PRC difference)
            if abs(adjustment) > 1:
                correction_record = {
                    "uid": uid,
                    "name": user.get("name"),
                    "email": user.get("email"),
                    "current": current_balance,
                    "correct": correct_balance,
                    "adjustment": adjustment,
                    "credits": credits,
                    "debits": debits
                }
                corrections.append(correction_record)
                
                if not dry_run:
                    # Apply correction
                    await db.users.update_one(
                        {"uid": uid},
                        {
                            "$set": {
                                "prc_balance": max(0, correct_balance),
                                "prc_corrected_at": timestamp,
                                "prc_before_correction": current_balance
                            }
                        }
                    )
                    
                    # Log correction
                    await db.prc_corrections_log.insert_one({
                        "uid": uid,
                        "name": user.get("name"),
                        "email": user.get("email"),
                        "before": current_balance,
                        "after": max(0, correct_balance),
                        "adjustment": adjustment,
                        "credits": credits,
                        "debits": debits,
                        "corrected_at": timestamp
                    })
        
        except Exception as e:
            errors.append({"uid": uid, "error": str(e)})
    
    # Sort by adjustment amount
    corrections.sort(key=lambda x: abs(x["adjustment"]), reverse=True)
    
    total_adjustment = sum(c["adjustment"] for c in corrections)
    
    return {
        "success": True,
        "dry_run": dry_run,
        "timestamp": timestamp,
        "summary": {
            "users_processed": len(users),
            "users_needing_correction": len(corrections),
            "total_adjustment": round(total_adjustment, 2),
            "errors": len(errors)
        },
        "corrections": corrections[:100],
        "errors": errors[:20] if errors else []
    }


@api_router.get("/admin/restore-zero-balance-prc")
@api_router.post("/admin/restore-zero-balance-prc")
async def restore_zero_balance_prc(
    dry_run: bool = True,
    limit: int = 500
):
    """
    🔄 RESTORE PRC: Restore PRC for users whose balance became 0 after subscription expiry.
    
    This endpoint finds users with zero balance and restores their PRC from:
    1. `prc_corrections_log` collection (balance before auto-correction)
    2. `prc_before_correction` field in users collection
    
    Query Params:
    - dry_run: If True, only preview (default: True)
    - limit: Max users to process (default: 500)
    
    ⚠️ SET dry_run=false TO ACTUALLY RESTORE
    """
    timestamp = datetime.now(timezone.utc).isoformat()
    
    results = {
        "found": 0,
        "restored": 0,
        "skipped": 0,
        "errors": [],
        "restorations": []
    }
    
    try:
        # Step 1: Find users with zero or negative balance
        zero_balance_users = await db.users.find(
            {"prc_balance": {"$lte": 0}},
            {"uid": 1, "name": 1, "email": 1, "prc_balance": 1, "prc_before_correction": 1, "subscription_plan": 1}
        ).limit(limit).to_list(limit)
        
        results["found"] = len(zero_balance_users)
        
        for user in zero_balance_users:
            uid = user.get("uid")
            name = user.get("name", "Unknown")
            email = user.get("email", "")
            current_balance = float(user.get("prc_balance", 0) or 0)
            
            restoration_record = {
                "uid": uid,
                "name": name,
                "email": email,
                "current_balance": round(current_balance, 2),
                "subscription_plan": user.get("subscription_plan")
            }
            
            try:
                # Try to find balance from prc_corrections_log (most recent)
                correction_log = await db.prc_corrections_log.find_one(
                    {"uid": uid},
                    sort=[("corrected_at", -1)]  # Get most recent
                )
                
                restore_balance = None
                restore_source = None
                
                if correction_log:
                    # Use the balance BEFORE correction
                    before_balance = float(correction_log.get("before", 0) or 0)
                    if before_balance > 0:
                        restore_balance = before_balance
                        restore_source = "prc_corrections_log"
                
                # Fallback: Check user's prc_before_correction field
                if restore_balance is None or restore_balance <= 0:
                    user_backup = float(user.get("prc_before_correction", 0) or 0)
                    if user_backup > 0:
                        restore_balance = user_backup
                        restore_source = "user.prc_before_correction"
                
                # If no balance to restore, skip
                if restore_balance is None or restore_balance <= 0:
                    restoration_record["status"] = "skipped"
                    restoration_record["reason"] = "No previous balance found to restore"
                    results["skipped"] += 1
                    results["restorations"].append(restoration_record)
                    continue
                
                restoration_record["restore_balance"] = round(restore_balance, 2)
                restoration_record["restore_source"] = restore_source
                
                if not dry_run:
                    # Apply restoration
                    await db.users.update_one(
                        {"uid": uid},
                        {
                            "$set": {
                                "prc_balance": restore_balance,
                                "prc_restored_at": timestamp,
                                "prc_restore_source": restore_source,
                                "prc_balance_before_restore": current_balance
                            }
                        }
                    )
                    
                    # Log restoration
                    await db.prc_restorations_log.insert_one({
                        "uid": uid,
                        "name": name,
                        "email": email,
                        "balance_before": current_balance,
                        "balance_after": restore_balance,
                        "restore_source": restore_source,
                        "restored_at": timestamp,
                        "reason": "Restore after subscription expiry zero-out"
                    })
                    
                    # Also log as transaction
                    await db.transactions.insert_one({
                        "transaction_id": str(uuid.uuid4()),
                        "user_id": uid,
                        "type": "admin_restore",
                        "amount": restore_balance - current_balance,
                        "balance_before": current_balance,
                        "balance_after": restore_balance,
                        "description": f"PRC restored from {restore_source} - subscription expiry fix",
                        "created_at": timestamp
                    })
                    
                    restoration_record["status"] = "restored"
                else:
                    restoration_record["status"] = "would_restore"
                
                results["restored"] += 1
                results["restorations"].append(restoration_record)
                
            except Exception as e:
                restoration_record["status"] = "error"
                restoration_record["error"] = str(e)
                results["errors"].append({"uid": uid, "error": str(e)})
                results["restorations"].append(restoration_record)
        
        # Calculate total PRC to be restored
        total_to_restore = sum(
            r.get("restore_balance", 0) - r.get("current_balance", 0) 
            for r in results["restorations"] 
            if r.get("status") in ["restored", "would_restore"]
        )
        
        return {
            "success": True,
            "dry_run": dry_run,
            "timestamp": timestamp,
            "summary": {
                "users_with_zero_balance": results["found"],
                "users_to_restore": results["restored"],
                "users_skipped": results["skipped"],
                "total_prc_to_restore": round(total_to_restore, 2),
                "errors": len(results["errors"])
            },
            "restorations": results["restorations"][:100],
            "errors": results["errors"][:20] if results["errors"] else [],
            "note": "Run with dry_run=false to apply changes" if dry_run else "Changes applied successfully"
        }
        
    except Exception as e:
        logging.error(f"[PRC RESTORE ZERO] Error: {e}")
        import traceback
        return {
            "success": False,
            "error": str(e),
            "traceback": traceback.format_exc()
        }


@api_router.delete("/admin/users/{uid}/delete")
async def delete_user_admin(uid: str, permanent: bool = False):
    """Admin deletes a user - soft delete by default, permanent if specified"""
    user = await db.users.find_one({"uid": uid})
    if not user:
        raise HTTPException(status_code=404, detail="User not found")
    
    # Prevent deleting admin users
    if user.get("role") == "admin":
        raise HTTPException(status_code=400, detail="Cannot delete admin users")
    
    user_email = user.get("email", "unknown")
    user_name = user.get("name", "unknown")
    
    if permanent:
        # PERMANENT DELETE - Remove from all collections
        await db.users.delete_one({"uid": uid})
        await db.transactions.delete_many({"user_id": uid})
        await db.mining_sessions.delete_many({"user_id": uid})
        await db.notifications.delete_many({"user_id": uid})
        await db.kyc_documents.delete_many({"user_id": uid})
        await db.luxury_savings.delete_many({"user_id": uid})
        await db.activity_logs.delete_many({"user_id": uid})
        
        delete_type = "permanent"
    else:
        # Soft delete - deactivate
        await db.users.update_one(
            {"uid": uid},
            {"$set": {
                "is_active": False,
                "deactivated_at": datetime.now(timezone.utc).isoformat()
            }}
        )
        delete_type = "soft"
    
    # Log action
    await db.audit_logs.insert_one({
        "log_id": str(uuid.uuid4()),
        "action": "delete_user",
        "entity_type": "user",
        "entity_id": uid,
        "performed_by": "admin",
        "changes": {
            "delete_type": delete_type,
            "email": user_email,
            "name": user_name
        },
        "created_at": datetime.now(timezone.utc).isoformat()
    })
    
    return {"message": f"User {delete_type}ly deleted successfully", "email": user_email}


