@api_router.post("/admin/backfill-notifications")
async def backfill_notifications_endpoint(stage: Optional[str] = None, max_iter: int = 5000):
    """
    One-time admin migration to repair the notifications collection.

    Optional query params:
      • stage: run only ONE of "1", "2", "3a", "3b", "4". Default: all.
      • max_iter: hard cap on batches per stage (each batch is 200 docs).

    Implementation (Feb 2026, v4):
      • `_id`-paginated chunks (200 per batch).
      • NO upfront `count_documents()` — those are slow on million-row
        collections and have been causing 10-second MongoDB busy timeouts
        on production before the migration even starts.
      • Each stage is independently try/except wrapped so a Stage 4 failure
        doesn't lose the Stage 1/2/3 progress.
      • Returns the raw exception class+message in the response (the
        normal sanitizer would have masked it).
    """
    from pymongo import UpdateOne

    fixed = {
        "user_id_to_user_uid": 0,
        "user_uid_to_user_id": 0,
        "read_to_is_read": 0,
        "is_read_to_read": 0,
        "bson_date_to_iso_string": 0,
    }
    errors = {}
    BATCH = 200

    async def _paginate_and_apply(stage_name, match_filter, op_builder):
        nonlocal_count = 0
        last_id = None
        iterations = 0
        try:
            while iterations < max_iter:
                iterations += 1
                q = dict(match_filter)
                if last_id is not None:
                    q["_id"] = {"$gt": last_id}
                batch = await db.notifications.find(
                    q,
                    {"_id": 1, "user_id": 1, "user_uid": 1, "read": 1, "is_read": 1, "created_at": 1},
                ).sort("_id", 1).limit(BATCH).to_list(BATCH)
                if not batch:
                    break
                ops = []
                for d in batch:
                    last_id = d["_id"]
                    op = op_builder(d)
                    if op is not None:
                        ops.append(op)
                if ops:
                    await db.notifications.bulk_write(ops, ordered=False)
                    nonlocal_count += len(ops)
                await asyncio.sleep(0)
        except Exception as e:
            errors[stage_name] = f"{type(e).__name__}: {str(e)[:300]}"
            logging.exception("[backfill-notifications] stage=%s last_id=%s iter=%s failed",
                              stage_name, last_id, iterations)
        return nonlocal_count, iterations

    stages_to_run = [stage] if stage else ["1", "2", "3a", "3b", "4"]

    if "1" in stages_to_run:
        cnt, it = await _paginate_and_apply(
            "1",
            {"user_id": {"$exists": True}, "user_uid": {"$exists": False}},
            lambda d: UpdateOne({"_id": d["_id"]}, {"$set": {"user_uid": d["user_id"]}}),
        )
        fixed["user_id_to_user_uid"] = cnt

    if "2" in stages_to_run:
        cnt, _ = await _paginate_and_apply(
            "2",
            {"user_uid": {"$exists": True}, "user_id": {"$exists": False}},
            lambda d: UpdateOne({"_id": d["_id"]}, {"$set": {"user_id": d["user_uid"]}}),
        )
        fixed["user_uid_to_user_id"] = cnt

    if "3a" in stages_to_run:
        cnt, _ = await _paginate_and_apply(
            "3a",
            {"read": {"$exists": True}, "is_read": {"$exists": False}},
            lambda d: UpdateOne({"_id": d["_id"]}, {"$set": {"is_read": d.get("read", False)}}),
        )
        fixed["read_to_is_read"] = cnt

    if "3b" in stages_to_run:
        cnt, _ = await _paginate_and_apply(
            "3b",
            {"is_read": {"$exists": True}, "read": {"$exists": False}},
            lambda d: UpdateOne({"_id": d["_id"]}, {"$set": {"read": d.get("is_read", False)}}),
        )
        fixed["is_read_to_read"] = cnt

    if "4" in stages_to_run:
        def _date_to_iso_op(d):
            ts = d.get("created_at")
            if not isinstance(ts, datetime):
                return None
            if ts.tzinfo is None:
                ts = ts.replace(tzinfo=timezone.utc)
            return UpdateOne({"_id": d["_id"]}, {"$set": {"created_at": ts.isoformat()}})
        cnt, _ = await _paginate_and_apply(
            "4",
            {"created_at": {"$type": "date"}},
            _date_to_iso_op,
        )
        fixed["bson_date_to_iso_string"] = cnt

    return {
        "ok": not errors,
        "stages_run": stages_to_run,
        "fixed": fixed,
        "errors": errors,
    }


@api_router.post("/admin/migrate-subscription-expiry-fields")
async def migrate_subscription_expiry_fields_endpoint():
    """
    One-time admin migration to consolidate 3 legacy subscription expiry
    fields (`subscription_expiry`, `subscription_expires`, `vip_expiry`)
    into the single canonical `subscription_expiry`.

    Strategy:
      • For each user that has ANY of the legacy fields, pick the LATEST
        of the three datetimes (never silently downgrade an active user).
      • Write that latest value back to `subscription_expiry` and `$unset`
        the legacy `subscription_expires` + `vip_expiry` keys.
      • Write an audit row per user to `subscription_expiry_migration_audit`
        so we can roll back if needed.

    Implementation notes (Feb 2026):
    - Uses `_id`-based pagination (NOT a long-held cursor) so each batch is
      independent and we never hold MongoDB locks for >2 seconds.
    - Batches of 200 users per round-trip → bounded memory + Cloudflare safe.
    - Logs the real MongoDB error to backend logs if bulk_write fails so the
      sanitized "Database is busy" message doesn't hide the root cause.
    - Idempotent — safe to re-run.
    """
    from pymongo import UpdateOne, InsertOne
    from bson import ObjectId

    def _parse_dt(v):
        if not v:
            return None
        if isinstance(v, datetime):
            return v if v.tzinfo else v.replace(tzinfo=timezone.utc)
        if isinstance(v, str):
            try:
                dt = datetime.fromisoformat(v.replace("Z", "+00:00"))
                return dt if dt.tzinfo else dt.replace(tzinfo=timezone.utc)
            except Exception:
                return None
        return None

    legacy_query = {
        "$or": [
            {"subscription_expires": {"$exists": True}},
            {"vip_expiry": {"$exists": True}},
        ]
    }
    before_total = await db.users.count_documents(legacy_query)

    touched = 0
    chose_latest = 0
    cleared_only = 0
    now_iso = datetime.now(timezone.utc).isoformat()
    BATCH = 200
    last_id = None
    iterations = 0
    MAX_ITER = 1000  # hard stop — won't process more than 200,000 users in one call

    while iterations < MAX_ITER:
        iterations += 1
        page_query = dict(legacy_query)
        if last_id is not None:
            page_query["_id"] = {"$gt": last_id}

        # Pull ONE batch with a fresh short-lived cursor sorted by _id.
        batch = await db.users.find(
            page_query,
            {
                "_id": 1, "uid": 1, "subscription_expiry": 1,
                "subscription_expires": 1, "vip_expiry": 1, "subscription_plan": 1,
            },
        ).sort("_id", 1).limit(BATCH).to_list(BATCH)

        if not batch:
            break

        user_ops = []
        audit_ops = []
        for u in batch:
            last_id = u["_id"]
            uid = u.get("uid")
            if not uid:
                continue

            dates = {
                "subscription_expiry": _parse_dt(u.get("subscription_expiry")),
                "subscription_expires": _parse_dt(u.get("subscription_expires")),
                "vip_expiry": _parse_dt(u.get("vip_expiry")),
            }
            valid = {k: v for k, v in dates.items() if v}
            canonical = max(valid.values()) if valid else None

            audit_ops.append(InsertOne({
                "uid": uid,
                "subscription_plan": u.get("subscription_plan"),
                "before": {k: (v.isoformat() if v else None) for k, v in dates.items()},
                "chosen": canonical.isoformat() if canonical else None,
                "migrated_at": now_iso,
            }))

            set_ops = {}
            if canonical:
                set_ops["subscription_expiry"] = canonical.isoformat()
                chose_latest += 1
            else:
                cleared_only += 1

            update = {"$unset": {"subscription_expires": "", "vip_expiry": ""}}
            if set_ops:
                update["$set"] = set_ops

            user_ops.append(UpdateOne({"uid": uid}, update))
            touched += 1

        # Flush this page. Log MongoDB errors so the sanitizer can't swallow them.
        try:
            if user_ops:
                await db.users.bulk_write(user_ops, ordered=False)
            if audit_ops:
                await db.subscription_expiry_migration_audit.bulk_write(audit_ops, ordered=False)
        except Exception as bulk_exc:
            logging.exception(
                "[expiry-migration] bulk_write failed on page %s (last_id=%s, touched_so_far=%s): %s",
                iterations, last_id, touched, bulk_exc,
            )
            raise

        # Yield to the event loop so other requests aren't starved
        await asyncio.sleep(0)

    after_remaining = await db.users.count_documents(legacy_query)

    return {
        "ok": True,
        "before": {"users_with_legacy_fields": before_total},
        "after": {"users_with_legacy_fields": after_remaining},
        "fixed": {
            "users_touched": touched,
            "users_with_chosen_latest": chose_latest,
            "users_cleared_only_no_valid_date": cleared_only,
            "audit_rows_written": touched,
            "batches_processed": iterations,
        },
    }

