@api_router.get("/admin/prc-analytics")
async def get_prc_analytics():
    """Get platform-wide PRC statistics for admin dashboard - OPTIMIZED"""
    try:
        # Use aggregation instead of fetching all users
        balance_agg = await db.users.aggregate([
            {"$group": {"_id": None, "total_balance": {"$sum": "$prc_balance"}, "user_count": {"$sum": 1}}}
        ]).to_list(1)
        total_current_balance = balance_agg[0]["total_balance"] if balance_agg else 0
        
        # Get VIP count
        vip_count = await db.users.count_documents({"membership_type": "vip"})
        prc_spent_vip = vip_count * 1000
        
        # Aggregated consumption - Marketplace
        orders_agg = await db.orders.aggregate([
            {"$group": {"_id": None, "total": {"$sum": "$prc_amount"}}}
        ]).to_list(1)
        prc_spent_marketplace = orders_agg[0]["total"] if orders_agg else 0
        
        # Aggregated consumption - Bill Payments  
        bill_agg = await db.bill_payment_requests.aggregate([
            {"$match": {"status": "completed"}},
            {"$group": {"_id": None, "total": {"$sum": "$total_prc_deducted"}}}
        ]).to_list(1)
        prc_spent_bill_payments = bill_agg[0]["total"] if bill_agg else 0
        
        # Aggregated consumption - Gift Vouchers
        gift_agg = await db.gift_voucher_requests.aggregate([
            {"$match": {"status": "completed"}},
            {"$group": {"_id": None, "total": {"$sum": "$total_prc_deducted"}}}
        ]).to_list(1)
        prc_spent_gift_vouchers = gift_agg[0]["total"] if gift_agg else 0
        
        # Calculate totals
        total_prc_consumed = prc_spent_marketplace + prc_spent_bill_payments + prc_spent_gift_vouchers + prc_spent_vip
        total_prc_mined = total_current_balance + total_prc_consumed
        
        # Get daily statistics for last 30 days using aggregation
        thirty_days_ago = datetime.now(timezone.utc) - timedelta(days=30)
        thirty_days_str = thirty_days_ago.isoformat()
        
        # Daily mining - from transactions
        mining_agg = await db.transactions.aggregate([
            {"$match": {"type": {"$in": ["mining", "tap_game"]}, "timestamp": {"$gte": thirty_days_str}}},
            {"$addFields": {"date": {"$substr": ["$timestamp", 0, 10]}}},
            {"$group": {"_id": "$date", "mined": {"$sum": "$amount"}}}
        ]).to_list(100)
        daily_mining = {d["_id"]: abs(d["mined"]) for d in mining_agg if d["_id"]}
        
        # Daily consumption - from transactions
        consume_agg = await db.transactions.aggregate([
            {"$match": {"type": {"$in": ["redeem", "bill_payment", "gift_voucher", "marketplace"]}, "timestamp": {"$gte": thirty_days_str}}},
            {"$addFields": {"date": {"$substr": ["$timestamp", 0, 10]}}},
            {"$group": {"_id": "$date", "consumed": {"$sum": "$amount"}}}
        ]).to_list(100)
        daily_consumption = {d["_id"]: abs(d["consumed"]) for d in consume_agg if d["_id"]}
        
        # Create timeline data
        timeline_data = []
        current_date = thirty_days_ago.date()
        end_date = datetime.now(timezone.utc).date()
        
        while current_date <= end_date:
            date_str = current_date.isoformat()
            timeline_data.append({
                "date": date_str,
                "mined": round(daily_mining.get(date_str, 0), 2),
                "consumed": round(daily_consumption.get(date_str, 0), 2)
            })
            current_date += timedelta(days=1)
        
        consumption_breakdown = {
            "marketplace": round(prc_spent_marketplace, 2),
            "bill_payments": round(prc_spent_bill_payments, 2),
            "gift_vouchers": round(prc_spent_gift_vouchers, 2),
            "vip_memberships": round(prc_spent_vip, 2)
        }
        
        return {
            "total_prc_mined": round(total_prc_mined, 2),
            "total_prc_consumed": round(total_prc_consumed, 2),
            "total_prc_in_circulation": round(total_current_balance, 2),
            "consumption_rate": round((total_prc_consumed / total_prc_mined * 100), 2) if total_prc_mined > 0 else 0,
            "consumption_breakdown": consumption_breakdown,
            "timeline_data": timeline_data[-30:],  # Last 30 days
            "total_users": balance_agg[0]["user_count"] if balance_agg else 0,
            "vip_users": vip_count,
            "avg_prc_per_user": round(total_current_balance / (balance_agg[0]["user_count"] if balance_agg else 1), 2)
        }
        
    except Exception as e:
        raise HTTPException(status_code=500, detail=get_user_friendly_error(e))

@api_router.get("/admin/prc-analytics/detailed")
async def get_detailed_prc_analytics(period: str = "month"):
    """Get detailed PRC analytics with burn data, profit/loss, and time-based breakdown.

    PERF (Phase-3): All 7 independent collection queries (current/prev period
    aggregations on `transactions`, user stats, VIP revenue current/prev,
    chart bucketing, total users) fire in parallel via `asyncio.gather`.
    VIP-revenue uses `$group $sum` server-side instead of pulling 1000 docs.
    60-s in-process cache (period-keyed) makes admin refreshes instant.
    """
    CACHE_KEY = f"admin:prc_analytics:detailed:{period}:v1"
    if cache:
        try:
            cached = await cache.get(CACHE_KEY)
            if cached:
                return cached
        except Exception:
            pass

    try:
        now = datetime.now(timezone.utc)

        # Calculate date ranges based on period
        if period == "day":
            start_date = now - timedelta(days=1)
            prev_start = now - timedelta(days=2)
            prev_end = start_date
        elif period == "week":
            start_date = now - timedelta(weeks=1)
            prev_start = now - timedelta(weeks=2)
            prev_end = start_date
        elif period == "year":
            start_date = now - timedelta(days=365)
            prev_start = now - timedelta(days=730)
            prev_end = start_date
        else:  # month (default)
            start_date = now - timedelta(days=30)
            prev_start = now - timedelta(days=60)
            prev_end = start_date

        start_str = start_date.isoformat()
        prev_start_str = prev_start.isoformat()
        prev_end_str = prev_end.isoformat()

        credit_types = ["mining", "referral_bonus", "cashback", "admin_credit", "vip_bonus", "signup_bonus", "prc_rain_gain"]
        debit_types = ["order", "withdrawal", "bill_payment_request", "gift_voucher_request", "delivery_charge", "prc_rain_loss", "prc_burn"]

        def _build_period_match(start, end=None):
            if end:
                return {"$or": [
                    {"timestamp": {"$gte": start, "$lt": end}},
                    {"created_at": {"$gte": start, "$lt": end}}
                ]}
            return {"$or": [
                {"timestamp": {"$gte": start}},
                {"created_at": {"$gte": start}}
            ]}

        period_group = {
            "_id": "$type",
            "total": {"$sum": {"$ifNull": ["$amount", 0]}},
            "abs_total": {"$sum": {"$abs": {"$ifNull": ["$amount", 0]}}},
            "count": {"$sum": 1}
        }

        # Build chart pipeline (period-specific) — runs in parallel with everything else.
        ts_field = {"$ifNull": ["$timestamp", "$created_at"]}
        ts_as_string = {"$cond": {
            "if": {"$eq": [{"$type": ts_field}, "date"]},
            "then": {"$dateToString": {"format": "%Y-%m-%dT%H:%M:%S", "date": ts_field}},
            "else": {"$toString": ts_field}
        }}
        if period == "day":
            chart_pipeline = [
                {"$match": _build_period_match(start_str)},
                {"$addFields": {"ts_str": ts_as_string}},
                {"$addFields": {"hour_str": {"$substr": ["$ts_str", 11, 2]}}},
                {"$group": {
                    "_id": {"hour": "$hour_str", "type": "$type"},
                    "total": {"$sum": {"$ifNull": ["$amount", 0]}},
                    "abs_total": {"$sum": {"$abs": {"$ifNull": ["$amount", 0]}}}
                }}
            ]
            chart_to_list_limit = 500
        else:
            chart_pipeline = [
                {"$match": _build_period_match(start_str)},
                {"$addFields": {"ts_str": ts_as_string}},
                {"$addFields": {"date_str": {"$substr": ["$ts_str", 0, 10]}}},
                {"$group": {
                    "_id": {"date": "$date_str", "type": "$type"},
                    "total": {"$sum": {"$ifNull": ["$amount", 0]}},
                    "abs_total": {"$sum": {"$abs": {"$ifNull": ["$amount", 0]}}}
                }},
                {"$sort": {"_id.date": 1}}
            ]
            chart_to_list_limit = 5000

        user_stats_pipeline = [
            {"$group": {
                "_id": None,
                "total_prc_balance": {"$sum": {"$ifNull": ["$prc_balance", 0]}},
                "vip_count": {"$sum": {"$cond": [{"$eq": ["$membership_type", "vip"]}, 1, 0]}}
            }}
        ]
        vip_rev_current_pipeline = [
            {"$match": {
                "status": "approved",
                "$or": [
                    {"approved_at": {"$gte": start_str}},
                    {"created_at": {"$gte": start_str}},
                    {"updated_at": {"$gte": start_str}}
                ]
            }},
            {"$group": {"_id": None, "total": {"$sum": {"$ifNull": ["$amount", 0]}}}}
        ]
        vip_rev_prev_pipeline = [
            {"$match": {
                "status": "approved",
                "$or": [
                    {"approved_at": {"$gte": prev_start_str, "$lt": prev_end_str}},
                    {"created_at": {"$gte": prev_start_str, "$lt": prev_end_str}},
                    {"updated_at": {"$gte": prev_start_str, "$lt": prev_end_str}}
                ]
            }},
            {"$group": {"_id": None, "total": {"$sum": {"$ifNull": ["$amount", 0]}}}}
        ]

        # Fire ALL 7 independent queries in parallel — was 7 sequential awaits.
        _r = await asyncio.gather(
            db.transactions.aggregate([{"$match": _build_period_match(start_str)}, {"$group": period_group}]).to_list(100),
            db.transactions.aggregate([{"$match": _build_period_match(prev_start_str, prev_end_str)}, {"$group": period_group}]).to_list(100),
            db.users.aggregate(user_stats_pipeline).to_list(1),
            db.vip_payments.aggregate(vip_rev_current_pipeline).to_list(1),
            db.vip_payments.aggregate(vip_rev_prev_pipeline).to_list(1),
            db.transactions.aggregate(chart_pipeline, allowDiskUse=True).to_list(chart_to_list_limit),
            db.users.count_documents({}),
            return_exceptions=True,
        )
        cur_results       = _r[0] if not isinstance(_r[0], Exception) else []
        prev_results      = _r[1] if not isinstance(_r[1], Exception) else []
        user_stats        = _r[2] if not isinstance(_r[2], Exception) else []
        vip_rev_cur_arr   = _r[3] if not isinstance(_r[3], Exception) else []
        vip_rev_prev_arr  = _r[4] if not isinstance(_r[4], Exception) else []
        chart_data_raw    = _r[5] if not isinstance(_r[5], Exception) else []
        total_user_count  = _r[6] if not isinstance(_r[6], Exception) else 0

        cur_type_map = {r["_id"]: r for r in cur_results if r["_id"]}
        prev_type_map = {r["_id"]: r for r in prev_results if r["_id"]}

        prc_created_current = sum(cur_type_map.get(t, {}).get("total", 0) for t in credit_types)
        prc_created_prev    = sum(prev_type_map.get(t, {}).get("total", 0) for t in credit_types)
        prc_used_current    = sum(cur_type_map.get(t, {}).get("abs_total", 0) for t in debit_types)
        prc_used_prev       = sum(prev_type_map.get(t, {}).get("abs_total", 0) for t in debit_types)
        prc_burned_current  = cur_type_map.get("prc_burn", {}).get("abs_total", 0)
        prc_burned_prev     = prev_type_map.get("prc_burn", {}).get("abs_total", 0)
        current_stats = {"type_map": cur_type_map}

        total_in_circulation = user_stats[0]["total_prc_balance"] if user_stats else 0
        vip_user_count = user_stats[0]["vip_count"] if user_stats else 0

        # Calculate Profit/Loss (Platform perspective)
        # Profit = PRC Used + PRC Burned - PRC Created (ideally should be positive or balanced)
        profit_loss_current = (prc_used_current + prc_burned_current) - prc_created_current
        profit_loss_prev = (prc_used_prev + prc_burned_prev) - prc_created_prev

        vip_revenue_current = vip_rev_cur_arr[0]["total"] if vip_rev_cur_arr else 0
        vip_revenue_prev    = vip_rev_prev_arr[0]["total"] if vip_rev_prev_arr else 0

        # Calculate percentage changes
        def calc_change(current, prev):
            if prev == 0:
                return 100 if current > 0 else 0
            return round(((current - prev) / prev) * 100, 1)

        # Build daily/weekly chart data using the pre-fetched chart_data_raw.
        chart_data = []

        if period == "day":
            hourly_map: dict = {}
            for h in chart_data_raw:
                hr = h["_id"]["hour"]
                t = h["_id"]["type"]
                if hr not in hourly_map:
                    hourly_map[hr] = {}
                hourly_map[hr][t] = h
            for i in range(24):
                hour_label = f"{i:02d}:00"
                hr_key = f"{i:02d}"
                hr_data = hourly_map.get(hr_key, {})
                created = sum(hr_data.get(t, {}).get("total", 0) for t in credit_types)
                used = sum(hr_data.get(t, {}).get("abs_total", 0) for t in debit_types)
                burned = hr_data.get("prc_burn", {}).get("abs_total", 0)
                chart_data.append({"label": hour_label, "created": round(created, 2), "used": round(used, 2), "burned": round(burned, 2)})
        else:
            daily_map: dict = {}
            for d in chart_data_raw:
                dt = d["_id"]["date"]
                t = d["_id"]["type"]
                if dt not in daily_map:
                    daily_map[dt] = {}
                daily_map[dt][t] = d

            days_count = 7 if period == "week" else (365 if period == "year" else 30)
            step = 1 if period in ["day", "week"] else (30 if period == "year" else 1)

            for i in range(0, days_count, step):
                day_start_dt = now - timedelta(days=days_count-i)
                day_str = day_start_dt.isoformat()[:10]
                day_data = daily_map.get(day_str, {})
                created = sum(day_data.get(t, {}).get("total", 0) for t in credit_types)
                used = sum(day_data.get(t, {}).get("abs_total", 0) for t in debit_types)
                burned = day_data.get("prc_burn", {}).get("abs_total", 0)
                label = day_start_dt.strftime("%d %b") if period != "year" else day_start_dt.strftime("%b %Y")
                chart_data.append({"label": label, "created": round(created, 2), "used": round(used, 2), "burned": round(burned, 2)})

        # Usage breakdown by category (from aggregated data)
        usage_breakdown = []
        category_map = {
            "order": "Marketplace Orders",
            "bill_payment_request": "Bill Payments",
            "gift_voucher_request": "Gift Vouchers",
            "withdrawal": "Withdrawals",
            "delivery_charge": "Delivery Charges",
            "prc_rain_loss": "PRC Rain Loss"
        }
        
        for txn_type, label in category_map.items():
            amount = current_stats["type_map"].get(txn_type, {}).get("abs_total", 0)
            if amount > 0:
                usage_breakdown.append({"category": label, "amount": round(amount, 2)})
        
        # Source breakdown (from aggregated data)
        source_breakdown = []
        source_map = {
            "mining": "Mining",
            "referral_bonus": "Referral Bonus",
            "cashback": "Cashback",
            "admin_credit": "Admin Credit",
            "vip_bonus": "VIP Bonus",
            "signup_bonus": "Signup Bonus",
            "prc_rain_gain": "PRC Rain Gain"
        }
        
        for txn_type, label in source_map.items():
            amount = current_stats["type_map"].get(txn_type, {}).get("total", 0)
            if amount > 0:
                source_breakdown.append({"source": label, "amount": round(amount, 2)})

        payload = {
            "period": period,
            "summary": {
                "prc_created": round(prc_created_current, 2),
                "prc_created_change": calc_change(prc_created_current, prc_created_prev),
                "prc_used": round(prc_used_current, 2),
                "prc_used_change": calc_change(prc_used_current, prc_used_prev),
                "prc_burned": round(prc_burned_current, 2),
                "prc_burned_change": calc_change(prc_burned_current, prc_burned_prev),
                "prc_in_circulation": round(total_in_circulation, 2),
                "net_prc_flow": round(prc_created_current - prc_used_current - prc_burned_current, 2),
                "profit_loss": round(profit_loss_current, 2),
                "profit_loss_change": calc_change(profit_loss_current, profit_loss_prev),
                "vip_revenue": round(vip_revenue_current, 2),
                "vip_revenue_change": calc_change(vip_revenue_current, vip_revenue_prev)
            },
            "users": {
                "total": total_user_count,
                "vip": vip_user_count,
                "free": max(0, total_user_count - vip_user_count),
                "avg_balance": round(total_in_circulation / max(1, total_user_count), 2)
            },
            "chart_data": chart_data,
            "usage_breakdown": sorted(usage_breakdown, key=lambda x: x["amount"], reverse=True),
            "source_breakdown": sorted(source_breakdown, key=lambda x: x["amount"], reverse=True),
            "health_score": min(100, max(0, int(50 + (prc_used_current / max(prc_created_current, 1)) * 30 + (prc_burned_current / max(prc_created_current, 1)) * 20)))
        }
        if cache:
            try:
                await cache.set(CACHE_KEY, payload, ttl=60)
            except Exception:
                pass
        return payload
        
    except Exception as e:
        logging.error(f"Error in detailed PRC analytics: {e}")
        import traceback
        logging.error(traceback.format_exc())
        raise HTTPException(status_code=500, detail=f"Analytics error: {str(e)[:200]}")

# ========== END ADMIN PRC ANALYTICS ENDPOINTS ==========


@api_router.post("/admin/migrate-subscription-positions")
async def migrate_subscription_positions():
    """One-time migration: Assign subscription_position to all active subscribers."""
    try:
        now = datetime.now(timezone.utc)
        now_str = now.isoformat()
        
        active_filter = {
            "subscription_plan": {"$in": ["elite", "vip", "startup", "growth", "pro", "Elite", "VIP", "Startup", "Growth", "Pro"]},
            "$or": [
                {"subscription_expiry": {"$gt": now_str}},
                {"subscription_expiry": {"$gt": now}},
            ]
        }
        
        active_users = await db.users.find(
            active_filter,
            {"_id": 0, "uid": 1, "name": 1, "tree_position": 1}
        ).sort("tree_position", 1).to_list(100000)
        
        position = 0
        for user in active_users:
            position += 1
            await db.users.update_one(
                {"uid": user["uid"]},
                {"$set": {"subscription_position": position, "subscription_position_at": now_str}}
            )
        
        await db.app_settings.update_one(
            {"_id": "subscription_position_counter"},
            {"$set": {"counter": position}},
            upsert=True
        )
        
        return {
            "success": True,
            "message": f"Migration complete. Assigned {position} positions.",
            "total_assigned": position
        }
    except Exception as e:
        logging.error(f"Migration error: {e}")
        raise HTTPException(status_code=500, detail=str(e))


@api_router.post("/admin/razorpay/find-double-activations")
async def find_double_activations(request: Request):
    """
    DIAGNOSTIC: Find users whose subscription duration is significantly longer
    than expected (28 days × payment count + carry-over). Caused by the
    bulk-sync-captured dedup hole (fixed May 2026) — same payment_id was
    re-activated when user.last_payment_id was overwritten by a newer order.
    
    Body: {"admin_pin": "153759", "fix": false, "uid": "optional-specific-uid"}
    Returns list of suspect users. Pass fix=true to RESET expiry to the
    correct value: subscription_start + 28 × (payment_count for this user).
    """
    try:
        data = await request.json()
        if data.get("admin_pin") != "153759":
            raise HTTPException(status_code=403, detail="Invalid admin pin")
        do_fix = bool(data.get("fix", False))
        target_uid = data.get("uid")

        # Find Elite users with subscription_start, subscription_expiry set
        query = {
            "subscription_plan": "elite",
            "subscription_start": {"$exists": True, "$ne": None},
            "subscription_expiry": {"$exists": True, "$ne": None},
        }
        if target_uid:
            query["uid"] = target_uid

        users = await db.users.find(
            query,
            {
                "_id": 0, "uid": 1, "name": 1, "mobile": 1,
                "subscription_start": 1,
                "subscription_expiry": 1, "subscription_type": 1,
                "previous_remaining_days_added": 1,
                "last_payment_id": 1, "activated_via": 1,
            }
        ).to_list(20000)

        suspects = []
        fixed = []
        ok_count = 0

        for u in users:
            uid = u["uid"]
            start = u.get("subscription_start")
            expires = u.get("subscription_expiry")
            sub_type = u.get("subscription_type") or "monthly"

            # Parse dates
            def to_dt(x):
                if isinstance(x, datetime):
                    return x if x.tzinfo else x.replace(tzinfo=timezone.utc)
                if isinstance(x, str):
                    try:
                        d = datetime.fromisoformat(x.replace("Z", "+00:00"))
                        return d if d.tzinfo else d.replace(tzinfo=timezone.utc)
                    except Exception:
                        return None
                return None

            start_dt = to_dt(start)
            expires_dt = to_dt(expires)
            if not start_dt or not expires_dt:
                continue

            actual_days = (expires_dt - start_dt).total_seconds() / 86400.0

            # Count how many CASH payments this user has on record (each = 28 days)
            payment_count = await db.vip_payments.count_documents({
                "user_id": uid, "status": "approved", "payment_method": "razorpay"
            })
            if payment_count == 0:
                payment_count = await db.razorpay_orders.count_documents({
                    "user_id": uid, "status": "paid", "payment_captured": True
                })

            duration_days_per_payment = {"monthly": 28, "quarterly": 84, "half_yearly": 168, "yearly": 336}.get(sub_type, 28)
            expected_days = duration_days_per_payment * max(1, payment_count) + (u.get("previous_remaining_days_added") or 0)

            # Suspect if actual > expected + 2 days tolerance
            if actual_days > expected_days + 2:
                expected_expiry = start_dt + timedelta(days=expected_days)
                suspects.append({
                    "uid": uid,
                    "name": u.get("name"),
                    "mobile": u.get("mobile"),
                    "start": start_dt.isoformat(),
                    "current_expires": expires_dt.isoformat(),
                    "expected_expires": expected_expiry.isoformat(),
                    "actual_days": round(actual_days, 1),
                    "expected_days": expected_days,
                    "extra_days": round(actual_days - expected_days, 1),
                    "payment_count": payment_count,
                    "activated_via": u.get("activated_via"),
                })

                if do_fix:
                    await db.users.update_one(
                        {"uid": uid},
                        {"$set": {
                            "subscription_expiry": expected_expiry.isoformat(),
                            "double_activation_fixed_at": datetime.now(timezone.utc).isoformat(),
                            "double_activation_old_expires": expires_dt.isoformat(),
                        }}
                    )
                    fixed.append(uid)
            else:
                ok_count += 1

        return {
            "success": True,
            "fix_applied": do_fix,
            "total_scanned": len(users),
            "suspects": len(suspects),
            "ok": ok_count,
            "fixed": len(fixed),
            "suspect_users": suspects[:200],  # cap for response size
        }
    except HTTPException:
        raise
    except Exception as e:
        logging.error(f"[FIND-DOUBLE-ACTIVATION] error: {e}")
        raise HTTPException(status_code=500, detail=str(e))


@api_router.post("/admin/razorpay/backfill-missing-hooks")
async def backfill_razorpay_missing_hooks(request: Request):
    """
    BACKFILL: For every Razorpay-paid user whose verify-payment ran BEFORE the
    May 2026 fix (which adds assign_subscription_position + community post hook),
    retroactively:
      1. Assign subscription_position if missing.
      2. Create Community Forum Success Story post (idempotent via ref_id).
    
    Body: {"admin_pin": "153759", "dry_run": true, "uid": "optional-specific-uid"}
    """
    try:
        data = await request.json()
        admin_pin = data.get("admin_pin", "")
        dry_run = bool(data.get("dry_run", True))
        target_uid = data.get("uid")  # optional: backfill a single user
        if admin_pin != "153759":
            raise HTTPException(status_code=403, detail="Invalid admin pin")

        # Find candidates: paid razorpay_orders with payment_captured=True,
        # whose user has subscription_plan set but is missing subscription_position
        # OR is missing community post for that payment.
        # CHRONOLOGICAL ORDER: process oldest paid_at first so subscription_position
        # numbers preserve actual purchase chronology. Otherwise late-paid users
        # would get LATER positions than their earlier-paid referrals, breaking
        # the position-based network calculation (Network = users with position
        # GREATER than yours).
        query = {"status": "paid", "payment_captured": True}
        if target_uid:
            query["user_id"] = target_uid
        orders = await db.razorpay_orders.find(
            query,
            {"_id": 0, "order_id": 1, "user_id": 1, "payment_id": 1, "amount": 1,
             "plan_name": 1, "paid_at": 1, "razorpay_payment_time": 1,
             "synced_at": 1, "created_at": 1}
        ).sort([("paid_at", 1), ("razorpay_payment_time", 1), ("created_at", 1)]).to_list(10000)

        position_fixed = 0
        posts_created = 0
        already_ok = 0
        skipped = []

        from routes.mining import assign_subscription_position
        from routes.community import create_success_story_post

        for o in orders:
            uid = o.get("user_id")
            pid = o.get("payment_id")
            if not uid or not pid:
                continue
            user = await db.users.find_one(
                {"uid": uid},
                {"_id": 0, "uid": 1, "subscription_position": 1, "subscription_plan": 1}
            )
            if not user:
                skipped.append({"uid": uid, "reason": "user_not_found"})
                continue

            did_anything = False

            # 1. Fix subscription_position if missing
            if not user.get("subscription_position"):
                if not dry_run:
                    try:
                        await assign_subscription_position(uid)
                    except Exception as _e:
                        logging.warning(f"[BACKFILL] position assign failed for {uid}: {_e}")
                position_fixed += 1
                did_anything = True

            # 2. Create community post if missing (back-dated to actual paid_at
            # so the Community Feed retains chronological order — backfill posts
            # won't all bunch up at the top with "just now" timestamps).
            ref_id = f"sub_{pid}"
            existing_post = await db.community_posts.find_one(
                {"metadata.ref_id": ref_id, "is_success_story": True},
                {"_id": 1}
            )
            if not existing_post:
                # Pick the best available historical timestamp
                paid_ts = (o.get("paid_at") or o.get("razorpay_payment_time")
                           or o.get("synced_at") or o.get("created_at"))
                if isinstance(paid_ts, datetime):
                    paid_ts_iso = paid_ts.isoformat()
                elif isinstance(paid_ts, str):
                    paid_ts_iso = paid_ts
                else:
                    paid_ts_iso = None
                if not dry_run:
                    try:
                        await create_success_story_post(
                            user_id=uid,
                            service_type="subscription",
                            amount_inr=float(o.get("amount") or 0),
                            plan_name=o.get("plan_name", "elite"),
                            ref_id=ref_id,
                            created_at_override=paid_ts_iso,
                        )
                    except Exception as _e:
                        logging.warning(f"[BACKFILL] post create failed for {uid}: {_e}")
                posts_created += 1
                did_anything = True

            if not did_anything:
                already_ok += 1

        return {
            "success": True,
            "dry_run": dry_run,
            "scanned": len(orders),
            "position_fixed": position_fixed,
            "posts_created": posts_created,
            "already_ok": already_ok,
            "skipped": skipped[:50],
        }
    except HTTPException:
        raise
    except Exception as e:
        logging.error(f"[BACKFILL] error: {e}")
        raise HTTPException(status_code=500, detail=str(e))


