# ==================== COMPANY MASTER WALLETS ====================

async def get_company_wallets():
    """Get all company master wallets"""
    try:
        # Define wallet types - UPDATED 1 April 2026
        wallet_types = [
            {"type": "ads_revenue", "name": "Ads Revenue Wallet", "description": "Income from AdMob & Unity Ads"},
            {"type": "subscription", "name": "Subscription Wallet", "description": "VIP Membership payments"},
            {"type": "redeem_reserve", "name": "Redeem Reserve Wallet", "description": "Reserved for user redemptions"},
            {"type": "charity", "name": "Charity Wallet", "description": "Social responsibility fund"},
            {"type": "profit", "name": "Profit Wallet", "description": "Net company profit"},
            # NEW WALLETS - 1 April 2026
            {"type": "processing_fees", "name": "Processing Fees Wallet", "description": "₹10 processing fee collection"},
            {"type": "admin_charges", "name": "Admin Charges Wallet", "description": "20% admin charges collection"},
            {"type": "gst_collection", "name": "GST Collection Wallet", "description": "18% GST collected"}
        ]
        
        wallets = []
        for wt in wallet_types:
            wallet = await db.company_wallets.find_one({"wallet_type": wt["type"]}, {"_id": 0})
            if not wallet:
                # Initialize wallet if not exists
                wallet = {
                    "wallet_id": str(uuid.uuid4()),
                    "wallet_type": wt["type"],
                    "wallet_name": wt["name"],
                    "description": wt["description"],
                    "balance": 0.0,
                    "total_credit": 0.0,
                    "total_debit": 0.0,
                    "created_at": datetime.now(timezone.utc).isoformat(),
                    "last_updated": datetime.now(timezone.utc).isoformat()
                }
                await db.company_wallets.insert_one(wallet)
            wallets.append(wallet)
        
        # Get recent transactions
        recent_txns = await db.company_wallet_transactions.find(
            {}, {"_id": 0}
        ).sort("timestamp", -1).limit(20).to_list(20)
        
        return {
            "wallets": wallets,
            "recent_transactions": recent_txns,
            "total_balance": sum(w.get("balance", 0) for w in wallets)
        }
    except Exception as e:
        raise HTTPException(status_code=500, detail=get_user_friendly_error(e))

async def transfer_company_wallet(request: Request):
    """Transfer amount between company wallets"""
    try:
        data = await request.json()
        from_wallet = data.get("from_wallet")
        to_wallet = data.get("to_wallet")
        amount = float(data.get("amount", 0))
        description = data.get("description", "Inter-wallet transfer")
        admin_id = data.get("admin_id")
        
        if amount <= 0:
            raise HTTPException(status_code=400, detail="Amount must be positive")
        
        # Get source wallet
        source = await db.company_wallets.find_one({"wallet_type": from_wallet})
        if not source or source.get("balance", 0) < amount:
            raise HTTPException(status_code=400, detail="Insufficient balance in source wallet")
        
        now = datetime.now(timezone.utc).isoformat()
        
        # Debit from source
        await db.company_wallets.update_one(
            {"wallet_type": from_wallet},
            {"$inc": {"balance": -amount, "total_debit": amount}, "$set": {"last_updated": now}}
        )
        
        # Credit to destination
        await db.company_wallets.update_one(
            {"wallet_type": to_wallet},
            {"$inc": {"balance": amount, "total_credit": amount}, "$set": {"last_updated": now}}
        )
        
        # Log transaction
        txn = {
            "txn_id": str(uuid.uuid4()),
            "from_wallet": from_wallet,
            "to_wallet": to_wallet,
            "amount": amount,
            "description": description,
            "admin_id": admin_id,
            "timestamp": now
        }
        await db.company_wallet_transactions.insert_one(txn)
        
        return {"success": True, "transaction_id": txn["txn_id"]}
    except HTTPException:
        raise
    except Exception as e:
        raise HTTPException(status_code=500, detail=get_user_friendly_error(e))

async def adjust_company_wallet(request: Request):
    """Manual credit/debit to company wallet"""
    try:
        data = await request.json()
        wallet_type = data.get("wallet_type")
        amount = float(data.get("amount", 0))
        txn_type = data.get("type")  # credit or debit
        description = data.get("description")
        admin_id = data.get("admin_id")
        
        if txn_type == "debit":
            wallet = await db.company_wallets.find_one({"wallet_type": wallet_type})
            if wallet.get("balance", 0) < amount:
                raise HTTPException(status_code=400, detail="Insufficient balance")
            amount = -amount
        
        now = datetime.now(timezone.utc).isoformat()
        
        update_field = "total_credit" if txn_type == "credit" else "total_debit"
        await db.company_wallets.update_one(
            {"wallet_type": wallet_type},
            {
                "$inc": {"balance": amount, update_field: abs(amount)},
                "$set": {"last_updated": now}
            }
        )
        
        # Log transaction
        txn = {
            "txn_id": str(uuid.uuid4()),
            "wallet_type": wallet_type,
            "amount": abs(amount),
            "type": txn_type,
            "description": description,
            "admin_id": admin_id,
            "timestamp": now
        }
        await db.company_wallet_transactions.insert_one(txn)
        
        return {"success": True}
    except HTTPException:
        raise
    except Exception as e:
        raise HTTPException(status_code=500, detail=get_user_friendly_error(e))

# ==================== GST COLLECTION SUMMARY ====================

@api_router.get("/admin/gst-summary")
async def get_gst_collection_summary():
    """
    Get GST Collection Summary for Admin Dashboard
    Shows total GST collected, trends, and source breakdown

    Cached 5 min — runs 6+ aggregations against company_wallet_transactions
    (4s on production); admin can hit "refresh" if real-time value needed.
    """
    # ---- Cache (300s TTL) ----
    gst_cache_key = "admin:gst_summary"
    if cache:
        try:
            cached_gst = await cache.get(gst_cache_key)
            if cached_gst:
                return cached_gst
        except Exception:
            pass

    try:
        now = datetime.now(timezone.utc)
        
        # Get GST wallet balance
        gst_wallet = await db.company_wallets.find_one(
            {"wallet_type": "gst_collection"}, 
            {"_id": 0}
        )
        
        total_gst = gst_wallet.get("balance", 0) if gst_wallet else 0
        total_credited = gst_wallet.get("total_credit", 0) if gst_wallet else 0
        
        # Get GST transactions for trends
        # Today
        today_start = now.replace(hour=0, minute=0, second=0, microsecond=0)
        today_txns = await db.company_wallet_transactions.find({
            "wallet_type": "gst_collection",
            "type": "credit",
            "timestamp": {"$gte": today_start.isoformat()}
        }).to_list(1000)
        today_gst = sum(t.get("amount", 0) for t in today_txns)
        
        # This Week
        week_start = today_start - timedelta(days=today_start.weekday())
        week_txns = await db.company_wallet_transactions.find({
            "wallet_type": "gst_collection",
            "type": "credit",
            "timestamp": {"$gte": week_start.isoformat()}
        }).to_list(1000)
        week_gst = sum(t.get("amount", 0) for t in week_txns)
        
        # This Month
        month_start = today_start.replace(day=1)
        month_txns = await db.company_wallet_transactions.find({
            "wallet_type": "gst_collection",
            "type": "credit",
            "timestamp": {"$gte": month_start.isoformat()}
        }).to_list(1000)
        month_gst = sum(t.get("amount", 0) for t in month_txns)
        
        # Last 30 days trend (daily breakdown)
        thirty_days_ago = today_start - timedelta(days=30)
        trend_pipeline = [
            {
                "$match": {
                    "wallet_type": "gst_collection",
                    "type": "credit",
                    "timestamp": {"$gte": thirty_days_ago.isoformat()}
                }
            },
            {
                "$addFields": {
                    "date": {"$substr": ["$timestamp", 0, 10]}
                }
            },
            {
                "$group": {
                    "_id": "$date",
                    "amount": {"$sum": "$amount"},
                    "count": {"$sum": 1}
                }
            },
            {"$sort": {"_id": 1}}
        ]
        daily_trend = await db.company_wallet_transactions.aggregate(trend_pipeline).to_list(31)
        
        # Source breakdown (PRC vs Manual subscriptions)
        source_pipeline = [
            {
                "$match": {
                    "wallet_type": "gst_collection",
                    "type": "credit"
                }
            },
            {
                "$group": {
                    "_id": "$source",
                    "total": {"$sum": "$amount"},
                    "count": {"$sum": 1}
                }
            }
        ]
        source_breakdown = await db.company_wallet_transactions.aggregate(source_pipeline).to_list(10)
        
        # Format source breakdown
        sources = {}
        for s in source_breakdown:
            source_name = s.get("_id", "unknown")
            if source_name == "prc_subscription":
                sources["PRC Subscriptions"] = {"amount": round(s["total"], 2), "count": s["count"]}
            elif source_name == "manual_subscription":
                sources["Manual Subscriptions"] = {"amount": round(s["total"], 2), "count": s["count"]}
            else:
                sources[source_name or "Other"] = {"amount": round(s["total"], 2), "count": s["count"]}
        
        # Recent GST transactions
        recent_txns = await db.company_wallet_transactions.find(
            {"wallet_type": "gst_collection", "type": "credit"},
            {"_id": 0}
        ).sort("timestamp", -1).limit(10).to_list(10)
        
        gst_result = {
            "success": True,
            "summary": {
                "total_gst_collected": round(total_credited, 2),
                "current_balance": round(total_gst, 2),
                "today": round(today_gst, 2),
                "this_week": round(week_gst, 2),
                "this_month": round(month_gst, 2)
            },
            "trend": {
                "daily": [{"date": d["_id"], "amount": round(d["amount"], 2), "count": d["count"]} for d in daily_trend]
            },
            "source_breakdown": sources,
            "recent_transactions": recent_txns,
            "gst_rate": "18%",
            "formula": "GST = Base Price × 18%"
        }
        if cache:
            try:
                await cache.set(gst_cache_key, gst_result, ttl=300)
            except Exception:
                pass
        return gst_result
    except Exception as e:
        logging.error(f"GST Summary Error: {e}")
        raise HTTPException(status_code=500, detail=get_user_friendly_error(e))


