@api_router.get("/admin/bill-payment/requests")
async def get_all_bill_payment_requests(
    status: Optional[str] = None,
    request_type: Optional[str] = None,
    payment_type: Optional[str] = None,
    search: Optional[str] = None,
    limit: int = 500
):
    """Get all bill payment requests (Admin only) with enriched user data"""
    query = {}
    
    if status:
        query["status"] = status
    if request_type:
        query["request_type"] = request_type
    
    # Filter by payment_type (for EMI requests)
    if payment_type:
        if payment_type.lower() in ['emi', 'loan_emi']:
            query["$or"] = [
                {"payment_type": {"$regex": "emi", "$options": "i"}},
                {"request_type": "loan_emi"}
            ]
        else:
            query["payment_type"] = payment_type
    
    # Search by user_id, mobile, name, email or request_id
    if search:
        search_query = [
            {"user_id": {"$regex": search, "$options": "i"}},
            {"user_mobile": {"$regex": search, "$options": "i"}},
            {"user_email": {"$regex": search, "$options": "i"}},
            {"user_name": {"$regex": search, "$options": "i"}},
            {"request_id": {"$regex": search, "$options": "i"}}
        ]
        if "$or" in query:
            # Combine with existing $or
            query = {"$and": [{"$or": query["$or"]}, {"$or": search_query}]}
        else:
            query["$or"] = search_query
    
    requests = await db.bill_payment_requests.find(query, {"_id": 0}).sort("created_at", -1).to_list(limit)
    
    # Batch fetch all unique user IDs to avoid N+1 queries
    user_ids = list(set(req.get("user_id") for req in requests if req.get("user_id")))
    users_data = {}
    if user_ids:
        users_cursor = db.users.find(
            {"uid": {"$in": user_ids}}, 
            {"_id": 0, "uid": 1, "name": 1, "email": 1, "mobile": 1, 
             "subscription_plan": 1, "membership_type": 1,
             "prc_balance": 1, "kyc_status": 1}
        )
        # FIX: Use to_list() instead of async for to prevent cursor leak
        users_list = await users_cursor.to_list(length=1000)
        for user in users_list:
            users_data[user.get("uid")] = user
    
    # Enrich requests with cached user data and flatten service details
    for req in requests:
        user_id = req.get("user_id")
        if user_id and user_id in users_data:
            user = users_data[user_id]
            # Add/update user details in request
            req["user_name"] = user.get("name") or req.get("user_name")
            req["user_email"] = user.get("email") or req.get("user_email")
            req["user_mobile"] = user.get("mobile") or req.get("user_mobile")
            req["user_subscription"] = user.get("subscription_plan") or (
                "vip" if user.get("membership_type") == "vip" else "explorer"
            )
            req["user_prc_balance"] = user.get("prc_balance", 0)
            req["user_kyc_status"] = user.get("kyc_status", "pending")
        
        # Flatten service details from nested 'details' object
        details = req.get("details", {})
        if isinstance(details, dict):
            # Mobile Recharge details
            req["phone_number"] = details.get("phone_number") or details.get("mobile_number")
            req["operator"] = details.get("operator")
            
            # DTH details
            req["subscriber_id"] = details.get("subscriber_id") or details.get("customer_id")
            req["dth_operator"] = details.get("dth_operator") or details.get("operator")
            
            # Electricity Bill details
            req["consumer_number"] = details.get("consumer_number")
            req["account_number"] = details.get("account_number")
            req["biller_name"] = details.get("biller_name") or details.get("provider")
            
            # Credit Card details
            req["card_last4"] = details.get("card_last4")
            req["cardholder_name"] = details.get("cardholder_name")
            req["card_type"] = details.get("card_type")
            req["bank_name"] = details.get("bank_name")
            
            # Loan/EMI details - handle both old (loan_account_number) and new (loan_account) field names
            req["loan_account"] = details.get("loan_account") or details.get("loan_account_number")
            req["borrower_name"] = details.get("borrower_name")
            req["loan_type"] = details.get("loan_type")
            req["ifsc_code"] = details.get("ifsc_code")
            req["registered_mobile"] = details.get("registered_mobile")
            req["emi_amount"] = details.get("emi_amount")
            req["emi_due_date"] = details.get("emi_due_date")
            req["customer_id"] = details.get("customer_id")
            req["loan_tenure"] = details.get("loan_tenure")
    
    # Get statistics
    total_pending = await db.bill_payment_requests.count_documents({"status": "pending"})
    total_completed = await db.bill_payment_requests.count_documents({"status": "completed"})
    total_rejected = await db.bill_payment_requests.count_documents({"status": "rejected"})
    
    return {
        "requests": requests,
        "count": len(requests),
        "stats": {
            "pending": total_pending,
            "completed": total_completed,
            "rejected": total_rejected
        }
    }

@api_router.post("/admin/bill-payment/process")
async def process_bill_payment_request(request: Request):
    """Process a bill payment request - approve, reject, retry, or complete manually (Admin only).
    
    Actions:
    - approve: Try Eko API (3 retries). Success=completed, Fail=eko_failed (pending for admin)
    - retry: Retry Eko API for eko_failed requests
    - complete: Manually mark as completed (admin processed offline)
    - reject: Reject with PRC refund (admin decision only)
    """
    data = await request.json()
    request_id = data.get("request_id")
    action = data.get("action")  # approve, reject, retry, complete
    admin_notes = data.get("admin_notes", "")
    admin_uid = data.get("admin_uid")
    reject_reason = data.get("reject_reason", "")
    txn_reference = data.get("txn_reference", "")  # For manual completion
    
    valid_actions = ["approve", "reject", "retry", "complete"]
    if action not in valid_actions:
        raise HTTPException(status_code=400, detail=f"Invalid action. Must be one of: {', '.join(valid_actions)}")
    
    # Get admin name
    admin_name = "Admin"
    if admin_uid:
        admin_user = await db.users.find_one({"uid": admin_uid}, {"name": 1})
        if admin_user:
            admin_name = admin_user.get("name", "Admin")
    
    # Get request
    bill_request = await db.bill_payment_requests.find_one({"request_id": request_id})
    if not bill_request:
        raise HTTPException(status_code=404, detail="Request not found")
    
    current_status = bill_request.get("status")
    user_id = bill_request.get("user_id")
    total_prc = bill_request.get("total_prc_deducted")
    
    # Handle actions
    if action == "reject":
        if current_status == "completed":
            raise HTTPException(status_code=400, detail="Cannot reject completed request")
        
        # Require reject reason
        if not reject_reason:
            raise HTTPException(status_code=400, detail="Reject reason is required")
        
        # Refund PRC to user - RECORD BEFORE/AFTER for transparency
        user = await db.users.find_one({"uid": user_id}, {"_id": 0})
        if not user:
            print(f"⚠️ WARNING: User {user_id} not found for bill payment refund")
            raise HTTPException(status_code=404, detail="User not found for refund")
        
        balance_before = user.get("prc_balance", 0)
        balance_after = balance_before + total_prc
        
        await db.users.update_one(
            {"uid": user_id},
            {"$set": {"prc_balance": balance_after}}
        )
        
        print(f"✅ Refunded {total_prc} PRC to user {user_id}. Balance: {balance_before} → {balance_after}")
        
        # Log refund transaction with before/after details
        await log_transaction(
            user_id=user_id,
            wallet_type="prc",
            transaction_type="bill_payment_refund",
            amount=total_prc,
            description="Bill payment rejected - PRC Refunded",
            metadata={
                "request_id": request_id, 
                "reason": reject_reason,
                "balance_before": balance_before,
                "balance_after": balance_after,
                "service_type": bill_request.get('request_type', ''),
                "amount_inr": bill_request.get('amount_inr', 0)
            }
        )
        
        # Update request status with refund details
        await db.bill_payment_requests.update_one(
            {"request_id": request_id},
            {"$set": {
                "status": "rejected",
                "reject_reason": reject_reason,
                "processed_at": datetime.now(timezone.utc).isoformat(),
                "admin_notes": admin_notes or reject_reason,
                "processed_by": admin_name,
                "processed_by_uid": admin_uid,
                "refund_details": {
                    "prc_refunded": total_prc,
                    "balance_before": balance_before,
                    "balance_after": balance_after,
                    "refunded_at": datetime.now(timezone.utc).isoformat()
                }
            }}
        )
        
        # Notify user about rejection WITH BALANCE DETAILS
        await create_notification(
            user_id=user_id,
            title="❌ Bill Payment Rejected - PRC Refunded",
            message=f"Your ₹{bill_request.get('amount_inr')} {bill_request.get('request_type', '').replace('_', ' ')} request was rejected.\n\n💰 PRC Refund: {total_prc:.2f} PRC returned to your wallet.\n\n❌ Reason: {reject_reason}",
            notification_type="bill_payment_rejected",
            related_id=request_id,
            icon="❌",
            action_url="/bill-payments"
        )
        
        return {
            "message": "Request rejected and PRC refunded", 
            "status": "rejected", 
            "reject_reason": reject_reason,
            "refund_details": {
                "prc_refunded": total_prc,
                "balance_before": balance_before,
                "balance_after": balance_after
            }
        }
    
    elif action == "approve":
        # APPROVE = AUTOMATIC EKO PAYMENT with RETRY and AUTO-REJECT on failure
        if current_status != "pending":
            raise HTTPException(status_code=400, detail=f"Cannot approve request with status: {current_status}")
        
        now = datetime.now(timezone.utc)
        request_type = bill_request.get("request_type", "")
        details = bill_request.get("details", {})
        amount_inr = bill_request.get("amount_inr", 0)
        
        # =====================================================
