@api_router.get("/admin/gift-voucher/requests")
async def get_all_gift_voucher_requests(status: Optional[str] = None, search: Optional[str] = None):
    """[DISCONTINUED] Admin gift voucher list — feature removed May 2026."""
    raise HTTPException(status_code=410, detail=_GIFT_VOUCHER_DISCONTINUED_MSG)


async def _legacy_admin_gift_voucher_list(status: Optional[str] = None, search: Optional[str] = None):
    """Old implementation — kept inlined for historical reference."""
    query = {}
    if status:
        query["status"] = status
    
    # Search by user info or request ID
    if search:
        query["$or"] = [
            {"user_id": {"$regex": search, "$options": "i"}},
            {"user_email": {"$regex": search, "$options": "i"}},
            {"user_name": {"$regex": search, "$options": "i"}},
            {"request_id": {"$regex": search, "$options": "i"}}
        ]
    
    requests = await db.gift_voucher_requests.find(query, {"_id": 0}).sort("created_at", -1).to_list(500)
    
    # Use aggregation pipeline for efficient stats calculation
    stats_pipeline = [
        {"$group": {
            "_id": "$status",
            "count": {"$sum": 1},
            "total_value": {"$sum": "$denomination"}
        }}
    ]
    stats_result = await db.gift_voucher_requests.aggregate(stats_pipeline).to_list(10)
    
    # Parse aggregation results
    stats_by_status = {s["_id"]: {"count": s["count"], "value": s["total_value"]} for s in stats_result}
    
    return {
        "requests": requests,
        "count": len(requests),
        "stats": {
            "pending": stats_by_status.get("pending", {}).get("count", 0),
            "completed": stats_by_status.get("completed", {}).get("count", 0),
            "rejected": stats_by_status.get("rejected", {}).get("count", 0),
            "total_value_pending": stats_by_status.get("pending", {}).get("value", 0),
            "total_value_completed": stats_by_status.get("completed", {}).get("value", 0)
        }
    }

@api_router.post("/admin/gift-voucher/process")
async def process_gift_voucher_request(request: Request):
    """[DISCONTINUED] Gift voucher admin process — feature removed May 2026."""
    raise HTTPException(status_code=410, detail=_GIFT_VOUCHER_DISCONTINUED_MSG)


async def _legacy_admin_gift_voucher_process(request: Request):
    """Old implementation — kept inlined for historical reference."""
    data = await request.json()
    request_id = data.get("request_id")
    action = data.get("action")  # approve, reject
    voucher_code = data.get("voucher_code")
    voucher_details = data.get("voucher_details", {})
    admin_notes = data.get("admin_notes", "")
    admin_uid = data.get("admin_uid")
    reject_reason = data.get("reject_reason", "")
    
    if action not in ["approve", "reject"]:
        raise HTTPException(status_code=400, detail="Invalid action. Must be: approve or reject")
    
    # Get request
    voucher_request = await db.gift_voucher_requests.find_one({"request_id": request_id})
    if not voucher_request:
        raise HTTPException(status_code=404, detail="Request not found")
    
    current_status = voucher_request.get("status")
    user_id = voucher_request.get("user_id")
    total_prc = voucher_request.get("total_prc_deducted")
    
    if action == "reject":
        if current_status == "completed":
            raise HTTPException(status_code=400, detail="Cannot reject completed request")
        
        # Require reject reason
        if not reject_reason:
            raise HTTPException(status_code=400, detail="Reject reason is required")
        
        # Refund PRC to user - RECORD BEFORE/AFTER for transparency
        user = await db.users.find_one({"uid": user_id}, {"_id": 0})
        if not user:
            print(f"⚠️ WARNING: User {user_id} not found for gift voucher refund")
            raise HTTPException(status_code=404, detail="User not found for refund")
        
        balance_before = user.get("prc_balance", 0)
        balance_after = balance_before + total_prc
        
        await db.users.update_one(
            {"uid": user_id},
            {"$set": {"prc_balance": balance_after}}
        )
        
        print(f"✅ Refunded {total_prc} PRC to user {user_id}. Balance: {balance_before} → {balance_after}")
        
        # Log refund transaction with before/after details
        await log_transaction(
            user_id=user_id,
            wallet_type="prc",
            transaction_type="gift_voucher_refund",
            amount=total_prc,
            description="Gift voucher rejected - PRC Refunded",
            metadata={
                "request_id": request_id, 
                "reason": reject_reason,
                "balance_before": balance_before,
                "balance_after": balance_after,
                "denomination": voucher_request.get('denomination', 0)
            }
        )
        
        # Update request status with refund details
        await db.gift_voucher_requests.update_one(
            {"request_id": request_id},
            {"$set": {
                "status": "rejected",
                "reject_reason": reject_reason,
                "processed_at": datetime.now(timezone.utc).isoformat(),
                "admin_notes": admin_notes or reject_reason,
                "processed_by": admin_uid,
                "refund_details": {
                    "prc_refunded": total_prc,
                    "balance_before": balance_before,
                    "balance_after": balance_after,
                    "refunded_at": datetime.now(timezone.utc).isoformat()
                }
            }}
        )
        
        # Notify user about rejection WITH BALANCE DETAILS
        await create_notification(
            user_id=user_id,
            title="❌ Gift Voucher Rejected - PRC Refunded",
            message=f"Your ₹{voucher_request.get('denomination')} gift voucher request was rejected.\n\n💰 PRC Refund Details:\n• Refunded: {total_prc:.2f} PRC\n• Balance Before: {balance_before:.2f} PRC\n• Balance After: {balance_after:.2f} PRC\n\n❓ Reason: {reject_reason}",
            notification_type="gift_voucher_refund",
            related_id=request_id,
            icon="💰"
        )
        
        return {
            "message": "Request rejected and PRC refunded", 
            "status": "rejected", 
            "reject_reason": reject_reason,
            "refund_details": {
                "prc_refunded": total_prc,
                "balance_before": balance_before,
                "balance_after": balance_after
            }
        }
    
    elif action == "approve":
        if current_status != "pending":
            raise HTTPException(status_code=400, detail=f"Cannot approve request with status: {current_status}")
        
        if not voucher_code:
            raise HTTPException(status_code=400, detail="Voucher code is required for approval")
        
        # Generate TXN number
        txn_number = f"GV{datetime.now(timezone.utc).strftime('%Y%m%d%H%M%S')}{uuid.uuid4().hex[:6].upper()}"
        
        # Update request status
        await db.gift_voucher_requests.update_one(
            {"request_id": request_id},
            {"$set": {
                "status": "completed",
                "txn_number": txn_number,
                "voucher_code": voucher_code,
                "voucher_details": voucher_details,
                "processed_at": datetime.now(timezone.utc).isoformat(),
                "admin_notes": admin_notes,
                "processed_by": admin_uid
            }}
        )
        
        # Notify user
        await create_notification(
            user_id=user_id,
            title="🎁 Gift Voucher Ready!",
            message=f"Your ₹{voucher_request.get('denomination')} gift voucher is ready. TXN: {txn_number}",
            notification_type="gift_voucher",
            related_id=request_id,
            icon="🎁"
        )
        
        return {
            "message": "Gift voucher approved and provided to user",
            "status": "completed",
            "txn_number": txn_number,
            "voucher_code": voucher_code
        }

