@api_router.get("/user/security-info/{user_id}")
async def get_user_security_info(user_id: str):
    """Get user's security information including last login and login history"""
    user = await db.users.find_one(
        {"uid": user_id},
        {"_id": 0, "last_login": 1, "last_login_ip": 1, "last_login_device": 1, "created_at": 1}
    )
    
    if not user:
        raise HTTPException(status_code=404, detail="User not found")
    
    # Get recent login history
    login_history = await db.login_history.find(
        {"user_id": user_id},
        {"_id": 0}
    ).sort("login_time", -1).limit(10).to_list(10)
    
    # Format login history
    formatted_history = []
    for login in login_history:
        device_info = login.get("device_info", {})
        formatted_history.append({
            "login_time": login.get("login_time"),
            "ip_address": login.get("ip_address", "Unknown"),
            "device": device_info.get("device", "Unknown"),
            "os": device_info.get("os", "Unknown"),
            "browser": device_info.get("browser", "Unknown"),
            "device_id": login.get("device_id", "")[:8] if login.get("device_id") else ""
        })
    
    return {
        "last_login": user.get("last_login"),
        "last_login_ip": user.get("last_login_ip"),
        "last_login_device": user.get("last_login_device"),
        "account_created": user.get("created_at"),
        "login_history": formatted_history,
        "total_logins": len(login_history)
    }

@api_router.get("/public/contact-info")
async def get_public_contact_info():
    """Get contact information for public display (Landing page, Contact Us, Footer).

    Cached 5 min — contact info is essentially static configuration; the
    earlier 830ms latency on this hot endpoint (called on every public
    page mount + footer load) was pure waste."""
    # ---- Cache (300s TTL) ----
    contact_cache_key = "public:contact_info"
    if cache:
        try:
            cached_contact = await cache.get(contact_cache_key)
            if cached_contact:
                return cached_contact
        except Exception:
            pass

    settings = await db.settings.find_one({}, {"_id": 0, "contact_settings": 1})
    
    default_settings = {
        "company_name": "PARAS REWARD",
        "address_line1": "",
        "address_line2": "",
        "city": "",
        "state": "",
        "pincode": "",
        "country": "India",
        "phone_primary": "",
        "phone_secondary": "",
        "email_support": "",
        "email_business": "",
        "working_hours": "9:00 AM - 6:00 PM (Mon-Sat)"
    }
    
    if settings and settings.get("contact_settings"):
        contact = {**default_settings, **settings["contact_settings"]}
    else:
        contact = default_settings
    
    # Format full address
    address_parts = [contact.get("address_line1"), contact.get("address_line2")]
    city_state = f"{contact.get('city', '')}, {contact.get('state', '')} - {contact.get('pincode', '')}"
    address_parts.append(city_state)
    address_parts.append(contact.get("country", "India"))
    
    full_address = ", ".join([p for p in address_parts if p and p.strip() and p != ", , - "])
    
    result = {
        "company_name": contact.get("company_name"),
        "address": full_address,
        "address_line1": contact.get("address_line1"),
        "address_line2": contact.get("address_line2"),
        "city": contact.get("city"),
        "state": contact.get("state"),
        "pincode": contact.get("pincode"),
        "country": contact.get("country"),
        "phone": contact.get("phone_primary"),
        "phone_secondary": contact.get("phone_secondary"),
        "email": contact.get("email_support"),
        "email_business": contact.get("email_business"),
        "working_hours": contact.get("working_hours")
    }
    if cache:
        try:
            await cache.set(contact_cache_key, result, ttl=300)
        except Exception:
            pass
    return result

