async def _background_db_init():
    """Background: indexes and warmup after DB is connected"""
    try:
        await create_performance_indexes(db)
        print("✅ Performance indexes created")
    except Exception as e:
        print(f"⚠️ Performance indexes (non-critical): {e}")
    try:
        await initialize_database_indexes()
        print("✅ Database indexes initialized")
    except Exception as e:
        print(f"⚠️ Database indexes (non-critical): {e}")
    try:
        video_ads_count = await db.video_ads.count_documents({})
        if video_ads_count == 0:
            print("No video ads found, database ready for admin to create videos")
    except Exception as e:
        print(f"Video ads check (non-critical): {e}")
    
    # Single Leg Tree: auto-migrate users without tree_position
    try:
        users_without_tree = await db.users.count_documents({"tree_position": {"$exists": False}})
        if users_without_tree > 0:
            print(f"Single Leg Tree: {users_without_tree} users need tree_position, migrating...")
            # Get all users without tree_position, sorted by created_at
            users_to_migrate = await db.users.find(
                {"tree_position": {"$exists": False}},
                {"_id": 0, "uid": 1, "created_at": 1}
            ).sort("created_at", 1).to_list(None)
            
            # Get current max tree_position
            last_positioned = await db.users.find_one(
                {"tree_position": {"$exists": True}},
                {"_id": 0, "uid": 1, "tree_position": 1},
                sort=[("tree_position", -1)]
            )
            
            current_pos = last_positioned["tree_position"] if last_positioned else 0
            prev_uid = last_positioned["uid"] if last_positioned else None
            
            from pymongo import UpdateOne
            bulk_ops = []
            for u in users_to_migrate:
                current_pos += 1
                bulk_ops.append(UpdateOne(
                    {"uid": u["uid"]},
                    {"$set": {"tree_position": current_pos, "network_parent": prev_uid}}
                ))
                prev_uid = u["uid"]
            
            if bulk_ops:
                result = await db.users.bulk_write(bulk_ops)
                print(f"Single Leg Tree: Migrated {result.modified_count} users")
            
            # Ensure indexes
            await db.users.create_index("tree_position")
            await db.users.create_index("network_parent")
            print("Single Leg Tree: Indexes ready")
        else:
            print("Single Leg Tree: All users have tree_position")
    except Exception as e:
        print(f"Single Leg Tree migration (non-critical): {e}")
    
    # Seed Holiday Calendar
    try:
        await seed_holidays()
        print("Holiday calendar seeded")
    except Exception as e:
        print(f"Holiday seed (non-critical): {e}")
    
    # Community Success Story auto-backfill (fire-and-forget, idempotent, rolling 1000 cap)
    try:
        import asyncio
        asyncio.create_task(auto_backfill_success_stories(limit=1000))
        print("Community Success Story auto-backfill scheduled")
    except Exception as e:
        print(f"Success story backfill (non-critical): {e}")

    # Pool Wallet — auto-repair legacy Core Team Bonus balance_after=0 entries
    try:
        import asyncio
        asyncio.create_task(pool_auto_repair_balance_after())
        print("Pool Wallet balance_after auto-repair scheduled")
    except Exception as e:
        print(f"Pool balance_after repair (non-critical): {e}")

    print("Background DB init complete!")

@app.on_event("startup")
async def startup_db():
    """Initialize database - NON-BLOCKING so server starts immediately"""
    import asyncio
    global db_ready
    print("🚀 Starting server (non-blocking startup)...")
    
    # Initialize cache manager (quick)
    try:
        print("📦 Initializing cache system...")
        await cache.initialize()
    except Exception as e:
        print(f"⚠️ Cache init failed (non-critical): {e}")
    
    # Single quick DB check - if fails, move to background
    try:
        await asyncio.wait_for(client.admin.command('ping'), timeout=5.0)
        print("✅ MongoDB connected!")
        db_ready = True
        # Complete init in background
        asyncio.create_task(_background_db_init())
    except Exception as e:
        print(f"⚠️ MongoDB not ready: {str(e)[:100]}")
        print("   → Background retry started. Server will serve requests immediately.")
        asyncio.create_task(retry_db_connection())
        
    # Start Task Queue Worker (Phase 4 - Background Tasks)
    print("🔄 Starting background task worker...")
    try:
        from app.services import TaskQueue
        asyncio.create_task(TaskQueue.start_worker(interval=10.0))
        print("✅ Task queue worker started (10s interval)")
    except Exception as e:
        print(f"⚠️ Task worker start failed (non-critical): {e}")

    # Daily inactive-user cleanup background loop (May 11, 2026)
    try:
        asyncio.create_task(daily_inactive_cleanup_task())
        print("🧹 Daily inactive-user cleanup task scheduled (24h interval, opt-in)")
    except Exception as e:
        print(f"⚠️ Inactive cleanup scheduler start failed (non-critical): {e}")

    # Daily PRC auto-unlock background loop (Jun 9, 2026 — 25k lock vault)
    try:
        asyncio.create_task(prc_auto_unlock_task())
        print("🔓 Daily PRC auto-unlock task scheduled (24h interval)")
    except Exception as e:
        print(f"⚠️ PRC auto-unlock scheduler start failed (non-critical): {e}")

    
    # Start scheduler for automated tasks
    print("⏰ Starting scheduled tasks...")
    
    try:
        # ========== PRC BURN JOBS REMOVED - MARCH 2026 ==========
        # Burning functionality has been completely removed
        
        # Schedule daily wallet reconciliation - runs at 3 AM
        scheduler.add_job(
            daily_wallet_reconciliation,
            CronTrigger(hour=3, minute=0),  # Daily at 3 AM
            id='daily_wallet_reconciliation',
            name='Daily wallet reconciliation and profit calculation',
            replace_existing=True
        )
        
        # Schedule daily system summary generation - runs at 12:05 AM
        scheduler.add_job(
            generate_daily_summary,
            CronTrigger(hour=0, minute=5),  # Daily at 12:05 AM
            id='daily_system_summary',
            name='Generate daily accounting summary',
            replace_existing=True
        )
        
        # Schedule hard deletion of expired accounts - runs daily at 3:30 AM
        scheduler.add_job(
            hard_delete_expired_accounts,
            CronTrigger(hour=3, minute=30),  # Daily at 3:30 AM
            id='hard_delete_expired_accounts',
            name='Permanently delete accounts after 30-day grace period',
            replace_existing=True
        )
        
        # Auto clear all lockouts at 12 PM (noon)
        scheduler.add_job(
            auto_clear_all_lockouts,
            CronTrigger(hour=12, minute=0),  # Daily at 12:00 PM
            id='auto_clear_lockouts_noon',
            name='Auto clear all user lockouts at noon',
            replace_existing=True
        )
        
        # Auto clear all lockouts at 12 AM (midnight)
        scheduler.add_job(
            auto_clear_all_lockouts,
            CronTrigger(hour=0, minute=0),  # Daily at 12:00 AM
            id='auto_clear_lockouts_midnight',
            name='Auto clear all user lockouts at midnight',
            replace_existing=True
        )
        
        # Auto-expire subscriptions - check every 30 minutes
        scheduler.add_job(
            auto_expire_subscriptions,
            'interval',
            minutes=30,
            id='auto_expire_subscriptions',
            name='Auto expire and downgrade subscriptions to explorer',
            replace_existing=True
        )
        
        # Upcoming subscription reminders - daily at 10:00 AM IST (4:30 UTC)
        scheduler.add_job(
            notify_upcoming_subscription_starts,
            CronTrigger(hour=4, minute=30),
            id='notify_upcoming_subscription_starts',
            name='Send 3-day and 1-day reminders for queued upcoming plans',
            replace_existing=True
        )
        
        # Auto-sync Razorpay payments every 1 minute for faster activation
        scheduler.add_job(
            auto_sync_razorpay_payments,
            'interval',
            minutes=1,
            id='auto_sync_razorpay',
            name='Auto sync Razorpay payments every 1 minute',
            replace_existing=True
        )

        # Unified Spend Sync (2026-06-30 migration) — keeps redeem_requests in sync
        # with the legacy bank/utility collections so the admin's
        # /api/admin/unified-spend/* always reflects the latest activity.
        # Idempotent (uses _legacy_request_id to skip already-synced rows).
        scheduler.add_job(
            sync_legacy_to_unified_redeem,
            'interval',
            minutes=15,
            id='sync_legacy_to_unified_redeem',
            name='Mirror legacy redeem/recharge collections into redeem_requests',
            replace_existing=True
        )
        
        # DISABLED: Captured payments sync - CAUSING DOUBLE ACTIVATION BUG
        # This was running in parallel with auto_sync_razorpay_payments
        # and causing users to get double subscription days (28 → 55 days)
        # Keeping auto_sync_razorpay_payments only - it already handles captured payments
        # 
        # scheduler.add_job(
        #     auto_sync_captured_from_razorpay,
        #     'interval',
        #     minutes=2,
        #     id='auto_sync_captured',
        #     name='Sync captured payments from Razorpay API',
        #     replace_existing=True
        # )
        
        # Eko transaction status update every 5 minutes
        scheduler.add_job(
            eko_update_pending_transactions,
            'interval',
            minutes=5,
            id='eko_status_update',
            name='Update Eko pending transaction statuses',
            replace_existing=True
        )
        
        # Database keep-alive ping every 2 minutes
        # This keeps MongoDB connection pool warm and prevents cold start delays
        scheduler.add_job(
            database_keep_alive_ping,
            'interval',
            minutes=2,
            id='db_keep_alive',
            name='Database connection keep-alive ping',
            replace_existing=True
        )
        
        # Emergency Auto-Pause Check (REMOVED June 2026 - fixed rate cleanup)
        
        # Pool Wallet Daily Distribution at midnight
        async def pool_wallet_daily_distribute():
            try:
                result = await distribute_pool_to_core_team(triggered_by="daily_cron")
                logging.info(f"[POOL WALLET CRON] Distribution result: {result}")
            except Exception as e:
                logging.error(f"[POOL WALLET CRON] Distribution error: {e}")
        
        scheduler.add_job(
            pool_wallet_daily_distribute,
            'cron',
            hour=18,
            minute=30,
            id='pool_wallet_daily_distribute',
            name='Pool Wallet Daily Distribution (Midnight IST)',
            replace_existing=True,
            misfire_grace_time=3600,
            coalesce=True
        )
        
        # Employee Pool Daily Distribution (Midnight IST = 18:30 UTC)
        async def employee_pool_daily_distribute():
            try:
                await distribute_employee_pool()
            except Exception as e:
                logging.error(f"Employee pool distribution error: {e}")
        
        scheduler.add_job(
            employee_pool_daily_distribute,
            'cron',
            hour=18,
            minute=35,
            id='employee_pool_daily_distribute',
            name='Employee Pool Daily Distribution (Midnight IST)',
            replace_existing=True,
            misfire_grace_time=3600,
            coalesce=True
        )
        
        # STARTUP CATCH-UP: If last distribution > 24h ago, run once at boot
        # This guards against deployments that restart backend after 18:30 UTC
        # and would otherwise skip that day's distribution entirely.
        async def catch_up_pool_distributions():
            try:
                await asyncio.sleep(45)  # wait for app fully initialized
                now = datetime.now(timezone.utc)
                one_day_ago = now - timedelta(hours=24)
                
                # Pool Wallet catch-up
                pool_wallet = await db.pool_wallet.find_one(
                    {"wallet_id": "main"}, {"_id": 0, "last_distributed": 1, "balance": 1}
                )
                if pool_wallet:
                    last = pool_wallet.get("last_distributed")
                    balance = float(pool_wallet.get("balance", 0))
                    needs_run = False
                    if balance > 0:
                        if not last:
                            needs_run = True
                        else:
                            try:
                                last_dt = datetime.fromisoformat(last.replace('Z', '+00:00'))
                                if last_dt < one_day_ago:
                                    needs_run = True
                            except Exception:
                                needs_run = True
                    if needs_run:
                        logging.warning(f"[POOL WALLET CATCH-UP] Last run: {last}, balance: {balance} - running NOW")
                        result = await distribute_pool_to_core_team(triggered_by="startup_catchup")
                        logging.info(f"[POOL WALLET CATCH-UP] Result: {result}")
                
                # Employee Pool catch-up
                emp_settings = await db.employee_pool_settings.find_one({}, {"_id": 0})
                if emp_settings:
                    last = emp_settings.get("last_distributed")
                    balance = float(emp_settings.get("pool_balance", 0))
                    needs_run = False
                    if balance > 0:
                        if not last:
                            needs_run = True
                        else:
                            try:
                                last_dt = datetime.fromisoformat(last.replace('Z', '+00:00'))
                                if last_dt < one_day_ago:
                                    needs_run = True
                            except Exception:
                                needs_run = True
                    if needs_run:
                        logging.warning(f"[EMPLOYEE POOL CATCH-UP] Last run: {last}, balance: {balance} - running NOW")
                        await distribute_employee_pool()
                        logging.info("[EMPLOYEE POOL CATCH-UP] Completed")
            except Exception as e:
                logging.error(f"[POOL CATCH-UP] Error: {e}", exc_info=True)
        
        asyncio.create_task(catch_up_pool_distributions())
        
        # ========== SUBSCRIPTION AUTO-EXPIRE CATCH-UP ==========
        # Critical fix (Apr 2026): If server was down when a user's subscription
        # expired, upcoming plans may not have auto-activated. Run immediately on
        # startup + again after a short delay to catch anything missed.
        async def subscription_catch_up():
            try:
                await asyncio.sleep(15)  # Let DB + indexes warm up
                logging.info("[SUBSCRIPTION CATCH-UP] Running immediate auto-expire sweep on startup")
                await auto_expire_subscriptions()
                logging.info("[SUBSCRIPTION CATCH-UP] Completed")
            except Exception as e:
                logging.error(f"[SUBSCRIPTION CATCH-UP] Error: {e}", exc_info=True)
        
        asyncio.create_task(subscription_catch_up())
        
        # Start the scheduler
        scheduler.start()
        print("✅ Scheduled tasks started:")
        print("   - 💰 Wallet reconciliation: Daily at 3 AM")
        print("   - 📊 Daily system summary: Daily at 12:05 AM")
        print("   - 🗑️ Account hard delete: Daily at 3:30 AM")
        print("   - 🔓 Auto lockout clear: Daily at 12 PM & 12 AM")
        print("   - ⏰ Subscription auto-expire: Every 30 minutes")
        print("   - 🔄 Razorpay auto-sync: Every 1 minute (faster activation)")
        print("   - 💳 Razorpay captured-sync: Every 2 minutes")
        print("   - 🏦 Eko status update: Every 5 minutes")
        print("   - 💓 DB keep-alive ping: Every 2 minutes (prevents cold start)")
        print("   - 🚨 Emergency auto-pause: Every 5 minutes (200% spike detection)")
        print("   - 👥 Employee pool distribution: Daily at midnight IST")
        
        # Trigger initial Razorpay sync 30 seconds after startup
        import asyncio
        asyncio.create_task(delayed_initial_sync())
    except Exception as e:
        print(f"⚠️ Error starting scheduler (non-critical): {e}")

async def delayed_initial_sync():
    """Run initial Razorpay sync after startup delay"""
    await asyncio.sleep(30)  # Wait 30 seconds for full startup
    print("[INITIAL-SYNC] 🚀 Running initial Razorpay sync after startup...")
    await auto_sync_razorpay_payments()

@app.on_event("shutdown")
async def shutdown_db_client():
    """Shutdown database client and scheduler"""
    # Shutdown scheduler
    if scheduler.running:
        scheduler.shutdown()
        print("⏰ Scheduler shut down")
    
    # Close database client
    client.close()
